if ($Fixture -eq 'canary-harness') {
  $fixtureRoot = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-canary-harness-$PID"
  try {
    New-Item -ItemType Directory -Force $fixtureRoot | Out-Null
    $ledgerPath = Join-Path $fixtureRoot 'effectiveness-ledger.jsonl'
    '{"gate":"scope","result":"block"}' | Set-Content -LiteralPath $ledgerPath -Encoding utf8
    $sensitive = 'CANARY-' + 'PRIVATE'
    $nestedOutput = @((1..30 | ForEach-Object { "noise-line-$_" }) + "Authorization: Bearer $sensitive" + 'exact-inner-failure')
    $diagnostic = Get-SelftestNestedShipDiagnostic -ExitCode 23 -Output $nestedOutput -LedgerPath $ledgerPath
    if ($diagnostic -notmatch '^\[SELFTEST-15B-SHIP\] exit=23 gate=scope tail=' -or
        $diagnostic -notmatch 'exact-inner-failure' -or $diagnostic.Contains($sensitive) -or $diagnostic.Length -gt 3600) {
      throw "canary-harness nested ship diagnostic contract failed: $diagnostic"
    }

    $coldAndroidRoot = Join-Path $fixtureRoot 'cold-android'
    New-Item -ItemType Directory -Force (Join-Path $coldAndroidRoot 'gradle/wrapper') | Out-Null
    Set-Content -LiteralPath (Join-Path $coldAndroidRoot 'gradle/wrapper/gradle-wrapper.properties') `
      -Value 'distributionUrl=https\://services.gradle.org/distributions/gradle-9.7.0-bin.zip' -Encoding utf8
    $coldCalls = 0
    $cold = Invoke-SelftestGradleMigrationGate -AndroidRoot $coldAndroidRoot -GradleUserHome (Join-Path $fixtureRoot 'cold-gradle-home') `
      -RunCases { $script:coldCalls++ }
    if (-not $cold.Skipped -or $cold.Reason -cne 'GRADLE-WRAPPER-OFFLINE' -or $coldCalls -ne 0) {
      throw "canary-harness cold Gradle gate invoked wrapper or lost stable reason: calls=$coldCalls result=$cold"
    }
    $readyCalls = 0
    $ready = Invoke-SelftestGradleMigrationGate -AndroidRoot $fixtureRoot -GradleUserHome $fixtureRoot `
      -StateProbe { param($androidRoot, $gradleHome) [pscustomobject]@{ Ready = $true; Detail = 'ready-fixture' } } `
      -RunCases { $script:readyCalls++ }
    if ($ready.Skipped -or $readyCalls -ne 1) {
      throw "canary-harness ready Gradle gate did not execute real cases exactly once: calls=$readyCalls result=$ready"
    }

    $baselineRepo = Join-Path $fixtureRoot 'baseline-repo'
    New-Item -ItemType Directory -Force (Join-Path $baselineRepo 'ignored') | Out-Null
    & git -C $baselineRepo init -q
    Set-Content -LiteralPath (Join-Path $baselineRepo '.gitignore') -Value '*.db' -Encoding utf8
    Set-Content -LiteralPath (Join-Path $baselineRepo 'normal.txt') -Value 'normal' -Encoding utf8
    $reviewedBaselines = @('ignored/1.db', 'ignored/2.db')
    $assertReviewedBaselinesTracked = {
      param([string]$Repo, [string[]]$Paths)
      foreach ($path in $Paths) {
        $trackedBaseline = "$(& git -C $Repo ls-files --error-unmatch -- $path 2>$null)".Trim()
        if ($LASTEXITCODE -ne 0 -or $trackedBaseline -cne $path) {
          throw "canary-harness E2E baseline did not force-add reviewed ignored file: $path"
        }
      }
    }
    Set-Content -LiteralPath (Join-Path $baselineRepo $reviewedBaselines[0]) -Value 'single reviewed baseline' -Encoding utf8
    Add-SelftestE2eBaseline -RepoRoot $baselineRepo -TrackedSensitivePaths $reviewedBaselines[0]
    & $assertReviewedBaselinesTracked $baselineRepo $reviewedBaselines[0]

    Set-Content -LiteralPath (Join-Path $baselineRepo $reviewedBaselines[1]) -Value 'second reviewed baseline' -Encoding utf8
    Add-SelftestE2eBaseline -RepoRoot $baselineRepo -TrackedSensitivePaths $reviewedBaselines
    & $assertReviewedBaselinesTracked $baselineRepo $reviewedBaselines
    $missingBaselineRejected = $false
    try {
      Add-SelftestE2eBaseline -RepoRoot $baselineRepo -TrackedSensitivePaths @($reviewedBaselines[0], 'ignored/missing.db')
    } catch {
      $missingBaselineRejected = $_.Exception.Message -match 'reviewed sensitive baseline is missing: ignored[/\\]missing\.db'
    }
    if (-not $missingBaselineRejected) {
      throw 'canary-harness E2E baseline did not reject one missing path in a reviewed collection.'
    }

    $firstOnlyMutantRepo = Join-Path $fixtureRoot 'baseline-first-only-mutant'
    New-Item -ItemType Directory -Force (Join-Path $firstOnlyMutantRepo 'ignored') | Out-Null
    & git -C $firstOnlyMutantRepo init -q
    Set-Content -LiteralPath (Join-Path $firstOnlyMutantRepo '.gitignore') -Value '*.db' -Encoding utf8
    foreach ($reviewedBaseline in $reviewedBaselines) {
      Set-Content -LiteralPath (Join-Path $firstOnlyMutantRepo $reviewedBaseline) -Value "mutant baseline $reviewedBaseline" -Encoding utf8
    }
    Add-SelftestE2eBaseline -RepoRoot $firstOnlyMutantRepo -TrackedSensitivePaths $reviewedBaselines[0]
    $firstOnlyMutantRejected = $false
    try {
      & $assertReviewedBaselinesTracked $firstOnlyMutantRepo $reviewedBaselines
    } catch {
      $firstOnlyMutantRejected = $_.Exception.Message -match 'reviewed ignored file: ignored[/\\]2\.db'
    }
    if (-not $firstOnlyMutantRejected) {
      throw 'canary-harness first-only executable mutant survived the two-path tracking oracle.'
    }

    $source = [System.IO.File]::ReadAllText((Join-Path $RepoRoot 'scripts/selftest.ps1'))
    $contractFailures = @(Get-SelftestCanarySourceContractFailures -Source $source)
    $migrationContinuePattern = '(?m)^\s+(?:if \(\$IsWindows\) \{ \$output = & cmd /c android\\gradlew\.bat|else \{ \$output = & sh android/gradlew) -p android --offline --no-daemon --con' + 'tinue -q :core:check 2>&1 \| Out-String \}\r?$'
    if ($contractFailures.Count -ne 0 -or
        [regex]::Matches($source, $migrationContinuePattern).Count -ne 2 -or
        (Get-SelftestGradleContinueInvocationCount -Source $source) -ne 2 -or
        [regex]::Matches($source, '(?m)^\s+\$(?:cold|ready|td4MigrationGate) = Invoke-SelftestGradleMigrationGate -AndroidRoot').Count -ne 3 -or
        [regex]::Matches($source, '(?m)^\s+Add-SelftestE2eBaseline -RepoRoot \$e2e ').Count -ne 1 -or
        $source.Contains("-TaskId T0-SMOKE -Phase ship -Local -SkipRed *> `$null`n      `$shipExit")) {
      throw "canary-harness production wiring is absent, duplicated, or weakened: $($contractFailures -join ',')"
    }
    foreach ($contract in @(Get-SelftestCanarySourceContracts)) {
      $mutatedSource = $source.Replace($contract.Text, '')
      $mutationFailures = @(Get-SelftestCanarySourceContractFailures -Source $mutatedSource)
      if ($mutationFailures.Count -ne 1 -or $mutationFailures[0] -cne $contract.Code) {
        throw "canary-harness source mutation did not isolate $($contract.Code): $($mutationFailures -join ',')"
      }
      $scopeProperty = $contract.PSObject.Properties['Scope']
      if ($scopeProperty -and $scopeProperty.Value -ceq 'MIGRATION-CORE-CHECK') {
        $relocatedSource = $mutatedSource + [Environment]::NewLine + $contract.Text + [Environment]::NewLine
        $relocationFailures = @(Get-SelftestCanarySourceContractFailures -Source $relocatedSource)
        if ($relocationFailures.Count -ne 1 -or $relocationFailures[0] -cne $contract.Code -or [regex]::Matches($relocatedSource, $migrationContinuePattern).Count -ne 2) {
          throw "canary-harness source relocation mutation did not isolate $($contract.Code): $($relocationFailures -join ',')"
        }
        $diffusedSource = $source + [Environment]::NewLine + $contract.Text + [Environment]::NewLine
        if ([regex]::Matches($diffusedSource, $migrationContinuePattern).Count -ne 3 -or (Get-SelftestGradleContinueInvocationCount -Source $diffusedSource) -ne 3) {
          throw "canary-harness source diffusion mutation did not widen the invocation surface for $($contract.Code)."
        }
      }
    }
    $otherRouteMutant = $source + [Environment]::NewLine +
      ('              if ($IsWindows) { $output = & cmd /c android\gradlew.bat -p android --offline --no-daemon --con' + 'tinue -q :app:check 2>&1 | Out-String }') + [Environment]::NewLine +
      ('              else { $output = & sh android/gradlew -p android --offline --no-daemon --con' + 'tinue -q :app:check 2>&1 | Out-String }') + [Environment]::NewLine
    if ((Get-SelftestGradleContinueInvocationCount -Source $otherRouteMutant) -ne 4 -or [regex]::Matches($otherRouteMutant, $migrationContinuePattern).Count -ne 2) {
      throw 'canary-harness other-route diffusion mutation survived generic Gradle --continue cardinality or polluted the exact migration-task count.'
    }
    Write-Host '[SELFTEST-FIXTURE] canary-harness PASS'
    exit 0
  } finally {
    Remove-Item -LiteralPath $fixtureRoot -Recurse -Force -ErrorAction SilentlyContinue
  }
}

if (-not $Fixture -and $Shard -eq 'seeded') {
  $sourceCanaryOutput = & pwsh -NoProfile -File $PSCommandPath -Shard seeded -Fixture canary-harness 2>&1 | Out-String
  $sourceCanaryExit = $LASTEXITCODE
  if ($sourceCanaryExit -ne 0 -or $sourceCanaryOutput -notmatch '\[SELFTEST-FIXTURE\] canary-harness PASS') {
    throw "seeded source-contract canary failed or was not reached (exit=$sourceCanaryExit): $sourceCanaryOutput"
  }
  Write-Host '  seeded source-contract canary：两平台删除/移位/扩散变异均被 scoped production block 精确击杀 OK' -ForegroundColor Green
}

function Test-SelftestGateIdContract {
  param(
    [Parameter(Mandatory)][string]$Source,
    [Parameter(Mandatory)][string]$InsertionAnchor
  )

  $tokens = $null
  $parseErrors = $null
  $parseFixturePath = Join-Path ([System.IO.Path]::GetTempPath()) ("selftest-gate-id-" + [guid]::NewGuid().ToString('N') + '.ps1')
  try {
    [System.IO.File]::WriteAllText($parseFixturePath, $Source, [System.Text.UTF8Encoding]::new($false))
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($parseFixturePath, [ref]$tokens, [ref]$parseErrors)
  } finally {
    [System.IO.File]::Delete($parseFixturePath)
  }
  if ($parseErrors -and $parseErrors.Count -gt 0) { return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-PARSE-ERROR'; Id = ''; Locations = @($parseErrors[0].Extent.StartLineNumber); Detail = $parseErrors[0].Message } } # GATE-ID-GUARD-PARSE

  # This is deliberately raw text, matching the actual anchor-based edit mechanism. A marker inside
  # a string or a longer comment is just as ambiguous to a text inserter as a standalone comment.
  $anchorLocations = @([regex]::Matches($Source, [regex]::Escape($InsertionAnchor)) | ForEach-Object {
      [regex]::Matches($Source.Substring(0, $_.Index), "`n").Count + 1
    })
  if ($anchorLocations.Count -ne 1) { return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-ANCHOR-NONUNIQUE'; Id = ''; Locations = $anchorLocations; Detail = "anchor count=$($anchorLocations.Count)" } } # GATE-ID-GUARD-ANCHOR

  $declarations = @(
    foreach ($token in $tokens) {
      if ($token.Kind -ne [System.Management.Automation.Language.TokenKind]::Comment) { continue }
      # Exactly one space after # distinguishes a gate heading from indented prose such as "#   15j:".
      # The lookahead prevents "8.0c" from backtracking to a false "8." declaration.
      $heading = [regex]::Match($token.Text, '^# (?:--- )?(?<id>[0-9A-Za-z.]+)(?<separator>[.:：])(?=\s|[^\w.]|$)')
      if (-not $heading.Success) { continue }
      $id = $heading.Groups['id'].Value
      if ($id -notmatch '^\d+(?:\.\d+)?[a-z]*\d*$') { continue }
      [pscustomobject]@{ Id = $id; Line = $token.Extent.StartLineNumber }
    }
  )
  $gateContexts = @(
    foreach ($token in $tokens) {
      if ($token.Kind -ne [System.Management.Automation.Language.TokenKind]::Comment) { continue }
      $context = [regex]::Match($token.Text,
        '^#\s+(?:---\s+)?(?<id>\d+(?:\.\d+)?[a-z]*\d*)(?:(?:[.:：])|(?:\([^)]*\)[.:：]?)|(?:（[^）]*）[.:：]?)|(?:/(?:\d+(?:\.\d+)?[a-z]*\d*)[.:：]))')
      if (-not $context.Success) { continue }
      $contextId = $context.Groups['id'].Value
      $isCanonical = @($declarations | Where-Object { $_.Line -eq $token.Extent.StartLineNumber -and $_.Id -ceq $contextId }).Count -eq 1
      [pscustomobject]@{ Id = $contextId; Line = $token.Extent.StartLineNumber; IsCanonical = $isCanonical }
    }
  )
  $isMessageOwnedBy = {
    param([string]$MessageId, [string]$OwnerId)
    if ($MessageId -ceq $OwnerId) { return $true }
    if (-not $MessageId.StartsWith($OwnerId, [System.StringComparison]::Ordinal)) { return $false }
    $suffix = $MessageId.Substring($OwnerId.Length)
    if (-not $suffix) { return $false }
    return $(if ($OwnerId -match '[a-z]$') { $suffix[0] -match '[0-9]' } else { $suffix[0] -match '[a-z]' })
  }

  $failCommands = @($ast.FindAll({
        param($node)
        $node -is [System.Management.Automation.Language.CommandAst] -and $node.GetCommandName() -ceq 'Fail'
      }, $true) | Sort-Object { $_.Extent.StartLineNumber })
  $failMessageByOffset = @{}
  $failMessages = @(
    foreach ($command in $failCommands) {
      if ($command.CommandElements.Count -lt 2) { continue }
      # Read the first argument AST rather than the command's raw prefix. This covers both
      # Fail '闸17t:...' and expression forms such as Fail ('闸17t(doc):...' + $detail).
      $messageId = [regex]::Match($command.CommandElements[1].Extent.Text,
        '^\s*\(*\s*["'']闸(?<id>\d+(?:\.\d+)?[a-z]*\d*)')
      if ($messageId.Success) {
        $message = [pscustomobject]@{ Id = $messageId.Groups['id'].Value; Line = $command.Extent.StartLineNumber }
        $failMessageByOffset[[string]$command.Extent.StartOffset] = $message
        $message
      }
    }
  )
  if ($failMessages.Count -eq 0) { return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-SCAN-EMPTY'; Id = ''; Locations = @(); Detail = 'no 闸<id> failure messages found' } } # GATE-ID-GUARD-SCAN-EMPTY

  $duplicate = @($declarations | Group-Object Id | Where-Object Count -gt 1 | Sort-Object Name | Select-Object -First 1)
  if ($duplicate.Count -gt 0) { return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-DUPLICATE'; Id = $duplicate[0].Name; Locations = @($duplicate[0].Group.Line | Sort-Object); Detail = "[GATE-ID-DUPLICATE] id=$($duplicate[0].Name) locations=$(@($duplicate[0].Group.Line | Sort-Object) -join ',')" } } # GATE-ID-GUARD-DUPLICATE

  # Build the report side from actual Fail ownership. An explicit 闸<id> contributes only its
  # preceding lexical heading owners; an unnumbered Fail owns headings opened since the previous
  # Fail. Write-Warning is deliberately excluded because it is not a failure-message report.
  $reportedMessageIds = [System.Collections.Generic.List[string]]::new()
  $previousFailLine = 0
  $previousExplicitFailLine = 0
  $activeCanonicalOwnerId = ''
  foreach ($failCommand in $failCommands) {
    $messageKey = [string]$failCommand.Extent.StartOffset
    if ($failMessageByOffset.ContainsKey($messageKey)) {
      $message = $failMessageByOffset[$messageKey]
      $newContexts = @($gateContexts | Where-Object {
          $_.Line -gt $previousExplicitFailLine -and $_.Line -lt $message.Line
        } | Sort-Object Line)
      if ($newContexts.Count -gt 0) {
        $latestContext = $newContexts[-1]
        $activeCanonicalOwnerId = if ($latestContext.IsCanonical -and (& $isMessageOwnedBy $message.Id $latestContext.Id)) { $latestContext.Id } else { '' }
      }
      if ($newContexts.Count -eq 0 -and $activeCanonicalOwnerId -and -not (& $isMessageOwnedBy $message.Id $activeCanonicalOwnerId)) { return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = $message.Id; Locations = @($message.Line); Detail = "failure message id=$($message.Id) is under active gate=$activeCanonicalOwnerId" } } # GATE-ID-GUARD-ACTIVE-OWNER
      $previousExplicitFailLine = $message.Line
      $owners = @(
        foreach ($declaration in $declarations | Where-Object Line -lt $message.Line) {
          if (& $isMessageOwnedBy $message.Id $declaration.Id) { $declaration }
        }
      )
      if ($owners.Count -eq 0) {
        return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = $message.Id; Locations = @($message.Line); Detail = "failure message id=$($message.Id) has no preceding gate heading" }
      }
      foreach ($owner in $owners) { [void]$reportedMessageIds.Add($owner.Id) }
    } else {
      foreach ($declaration in $declarations | Where-Object {
          $_.Line -gt $previousFailLine -and $_.Line -lt $failCommand.Extent.StartLineNumber
        }) {
        [void]$reportedMessageIds.Add($declaration.Id)
      }
    }
    $previousFailLine = $failCommand.Extent.StartLineNumber
  }
  $reportedHeadingIdSet = @($declarations | ForEach-Object { $_.Id } | Sort-Object -Unique)
  $reportedMessageIdSet = @($reportedMessageIds | Sort-Object -Unique)
  if ([string]::Join([char]0, $reportedHeadingIdSet) -cne [string]::Join([char]0, $reportedMessageIdSet)) { $firstMismatch = @($reportedHeadingIdSet + $reportedMessageIdSet | Group-Object | Where-Object Count -eq 1 | Sort-Object Name | Select-Object -First 1); return [pscustomobject]@{ Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = if ($firstMismatch) { $firstMismatch[0].Name } else { '' }; Locations = @(); Detail = "heading ids=$($reportedHeadingIdSet -join ','); failure-owner ids=$($reportedMessageIdSet -join ',')" } } # GATE-ID-GUARD-MESSAGE-SET

  return [pscustomobject]@{ Ok = $true; Code = 'OK'; Id = ''; Locations = @(); Detail = "gate headings=$($declarations.Count); failure-owner ids=$($reportedMessageIdSet.Count); explicit messages=$($failMessages.Count)" }
}

if ($Fixture -eq 'gate-id-mutant') {
  if (-not $GateIdMutation) { throw '[GATE-ID-MUTATION-SETUP] -GateIdMutation is required.' }
  $gateIdMutantSource = Get-Content -LiteralPath $PSCommandPath -Raw
  $gateIdMutantTokens = $null
  $gateIdMutantParseErrors = $null
  $gateIdMutantAst = [System.Management.Automation.Language.Parser]::ParseInput(
    $gateIdMutantSource, [ref]$gateIdMutantTokens, [ref]$gateIdMutantParseErrors)
  $gateIdMutantFunctions = @($gateIdMutantAst.FindAll({
        param($node)
        $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and
          $node.Name -ceq 'Test-SelftestGateIdContract'
      }, $true))
  if ($gateIdMutantParseErrors -or $gateIdMutantFunctions.Count -ne 1) {
    throw "[GATE-ID-MUTATION-SETUP] contract function parse/count invalid: parseErrors=$(@($gateIdMutantParseErrors).Count) functions=$($gateIdMutantFunctions.Count)."
  }
  $gateIdMutantFunctionLines = @($gateIdMutantFunctions[0].Extent.Text -split "`r?`n")
  $gateIdMutantMarker = 'GATE-ID-GUARD-' + $GateIdMutation
  $gateIdMutantGuardIndexes = @(for ($lineIndex = 0; $lineIndex -lt $gateIdMutantFunctionLines.Count; $lineIndex++) {
      if ($gateIdMutantFunctionLines[$lineIndex].Contains($gateIdMutantMarker)) { $lineIndex }
    })
  if ($gateIdMutantGuardIndexes.Count -ne 1) {
    throw "[GATE-ID-MUTATION-SETUP] expected one $gateIdMutantMarker sentence, found $($gateIdMutantGuardIndexes.Count)."
  }
  $gateIdMutatedFunctionLines = @(for ($lineIndex = 0; $lineIndex -lt $gateIdMutantFunctionLines.Count; $lineIndex++) {
      if ($lineIndex -ne $gateIdMutantGuardIndexes[0]) { $gateIdMutantFunctionLines[$lineIndex] }
    })
  if ($gateIdMutatedFunctionLines.Count -ne ($gateIdMutantFunctionLines.Count - 1)) {
    throw '[GATE-ID-MUTATION-SETUP] mutation did not delete exactly one sentence.'
  }
  $gateIdMutantName = 'Test-SelftestGateIdContractMutant' + ($GateIdMutation -replace '-', '')
  $gateIdMutatedFunctionSource = $gateIdMutatedFunctionLines -join "`n"
  $gateIdMutatedFunctionSource = ([regex]::new('function Test-SelftestGateIdContract\b')).Replace(
    $gateIdMutatedFunctionSource, "function $gateIdMutantName", 1)
  . ([scriptblock]::Create($gateIdMutatedFunctionSource))

  $gateIdMutantAnchor = '# GATE-ID-' + 'CONTRACT-INSERTION-ANCHOR'
  $gateIdMutantValidSource = @(
    '# --- 2. root gate ---',
    '# 2d. child gate',
    "if (`$false) { Fail '闸2d：reported' }",
    $gateIdMutantAnchor
  ) -join "`n"
  $gateIdMutantCases = @(switch ($GateIdMutation) {
    'DUPLICATE' {
      [pscustomobject]@{ Name = 'duplicate'; Code = 'GATE-ID-DUPLICATE'; Source = $gateIdMutantValidSource.Replace("# 2d. child gate", "# 2d. first gate`nif (`$false) { Fail '闸2d：first' }`n# 2d. second gate") }
    }
    'SCAN-EMPTY' {
      [pscustomobject]@{ Name = 'empty'; Code = 'GATE-ID-SCAN-EMPTY'; Source = "$gateIdMutantAnchor`n" }
    }
    'ANCHOR' {
      [pscustomobject]@{ Name = 'anchor'; Code = 'GATE-ID-ANCHOR-NONUNIQUE'; Source = $gateIdMutantValidSource + "`n$gateIdMutantAnchor`n" }
    }
    'PARSE' {
      [pscustomobject]@{ Name = 'parse'; Code = 'GATE-ID-PARSE-ERROR'; Source = $gateIdMutantValidSource + "`nif (`n" }
    }
    'MESSAGE-SET' {
      [pscustomobject]@{ Name = 'message-owner'; Code = 'GATE-ID-MESSAGE-MISMATCH'; Source = $gateIdMutantValidSource.Replace($gateIdMutantAnchor, "# 2e. wrong owner`nif (`$false) { Fail '闸2d：does not own 2e' }`n$gateIdMutantAnchor") }
      [pscustomobject]@{ Name = 'warning-only'; Code = 'GATE-ID-MESSAGE-MISMATCH'; Source = $gateIdMutantValidSource.Replace($gateIdMutantAnchor, "# 2e. warning is not a failure`nWrite-Warning 'unnumbered warning'`n$gateIdMutantAnchor") }
      [pscustomobject]@{ Name = 'heading-only'; Code = 'GATE-ID-MESSAGE-MISMATCH'; Source = $gateIdMutantValidSource + "`n# 2e. declaration without a failure`n" }
    }
    'ACTIVE-OWNER' {
      [pscustomobject]@{ Name = 'stale-copy'; Code = 'GATE-ID-MESSAGE-MISMATCH'; Source = $gateIdMutantValidSource.Replace($gateIdMutantAnchor, "# 2e. next gate`nif (`$false) { Fail '闸2e：valid next gate' }`nif (`$false) { Fail '闸2d：stale copied label' }`n$gateIdMutantAnchor") }
    }
  })
  $gateIdMutationSurvived = $false
  $gateIdMutationFailures = [System.Collections.Generic.List[string]]::new()
  foreach ($gateIdMutantCase in $gateIdMutantCases) {
    $gateIdMutantResult = & $gateIdMutantName -Source $gateIdMutantCase.Source -InsertionAnchor $gateIdMutantAnchor
    if ($gateIdMutantResult.Code -ceq $gateIdMutantCase.Code) {
      Write-Host "[GATE-ID-MUTATION-SURVIVED-$GateIdMutation] deleted guard still returned $($gateIdMutantCase.Code) for $($gateIdMutantCase.Name)."
      $gateIdMutationSurvived = $true
    } else {
      [void]$gateIdMutationFailures.Add("[GATE-ID-FIXTURE-$($gateIdMutantCase.Name)] expected code=$($gateIdMutantCase.Code); actual code=$($gateIdMutantResult.Code).")
    }
  }
  if ($gateIdMutationSurvived) { exit 0 }
  Write-Error ($gateIdMutationFailures -join ' ')
  exit 1
}

# 每个显式分片都先判 CI 接线，避免 core 组合被删时守卫也随 core 一起消失。
if ($Shard -ne 'all') {
  $preflightWorkflow = Get-Content (Join-Path $RepoRoot '.github/workflows/scaffold-selftest.yml') -Raw
  $withoutCoreMutation = [regex]::Replace($preflightWorkflow, '(?m)^\s{10}- os: (windows-latest|ubuntu-latest)\s*\r?\n\s{12}shard: core\s*\r?\n?', '')
  if (-not (Test-SelftestCiWiringContract $preflightWorkflow)) { throw 'selftest CI 分片接线契约不完整。' }
  if (Test-SelftestCiWiringContract $withoutCoreMutation) { throw 'selftest CI 接线契约未检出“删除全部 core 组合”变异。' }
}

if ($Shard -eq 'all') {
  $aggregateExit = Invoke-SelftestAll -SourceRoot $RepoRoot -ForwardStrictLint:$PSBoundParameters.ContainsKey('StrictLint') -StrictLintValue:$StrictLint.IsPresent
  exit $aggregateExit
}
# TD15：本脚本随下游保留（不再被 init -Cleanup/-Retrofit 删除），因约 12/17 闸测的是会下发的生产脚本
# （task.ps1/review.ps1/check-cards.ps1/check-secrets.ps1/lessons.ps1/triage.ps1/guard-frozen.ps1...）。
# 少数闸只测「从模板生成下游」这条元仓专属路径（模板哨兵/占位符/token 覆盖/init 干跑冒烟），已初始化的
# 下游（CLAUDE.template.md 已被改名删除）跑到这些子检查即自动跳过、不当失败。
$isPostInit = -not (Test-Path (Join-Path $RepoRoot 'CLAUDE.template.md'))
# TD77-STRICTLINT-DEFAULT：CI 从不显式传 -StrictLint，警告存量因此掩盖新增告警、严格档形同虚设。只在
#   元仓自身（$isPostInit 为假）默认打开，用户未显式传参时生效；已初始化的下游项目仍保持 opt-in——
#   不对下游自有脚本施加新的告警严格性（同 scaffold-selftest.yml 头注的既有设计意图，故不改该 CI 调用行）。
# 抽成纯函数（而非内联 if）是为了让下方 TD77 回归断言能直接调用三态，不必派子进程模拟三种运行环境。
function Resolve-StrictLintDefault([bool]$IsPostInit, [bool]$ParamBound, [bool]$Requested) {
  if (-not $ParamBound -and -not $IsPostInit) { return $true }
  return $Requested
}
$StrictLint = Resolve-StrictLintDefault -IsPostInit $isPostInit -ParamBound $PSBoundParameters.ContainsKey('StrictLint') -Requested $StrictLint

function Resolve-SelftestGateId([string]$Message, [string]$Fallback) {
  $match = [regex]::Match($Message, '^(?:闸)?(?<id>[^:：\s]+)(?:\s|[:：])')
  if ($match.Success) {
    $gateId = ConvertTo-SelftestAsciiGateId $match.Groups['id'].Value
    if (Test-SelftestGateId $gateId) { return $gateId }
  }
  if ($Fallback) { return $Fallback }
  return 'UNKNOWN'
}
function Step($m) {
  $stepMatch = [regex]::Match([string]$m, '^(?<id>[0-9]+(?:\.[0-9]+)?[a-z]*)/17\b')
  if ($stepMatch.Success) { $script:currentSelftestGateId = $stepMatch.Groups['id'].Value }
  Write-Host "`n=== $m ===" -ForegroundColor Cyan
}
$fail = $false
$currentSelftestGateId = ''
$failedSelftestGateIds = [System.Collections.Generic.List[string]]::new()
$skippedSelftestChecks = [System.Collections.Generic.List[string]]::new()
function Fail($m) {
  [void](Add-SelftestFailedGateId -GateIds $script:failedSelftestGateIds -Message ([string]$m) -Fallback $script:currentSelftestGateId)
  Write-Warning $m
  $script:fail = $true
}
$RootIgnore = @('.git', 'node_modules', '.venv', '.review', '.secrets', 'runtime', '.pytest_cache', '.ruff_cache', '.mypy_cache')  # 运行时/工具产物：存在即忽略，非交付物
$executedGateGroups = [System.Collections.Generic.List[string]]::new()

# A1's original false-green was a workflow run. Enforce the repository contract in the two dynamic
# gate shards named by the card; workflow also owns the full Gate 1i fixture/mutation matrix below.
if ($Shard -ceq 'workflow' -or $Shard -like 'seeded*') {
  $gateIdPreflightAnchor = '# GATE-ID-' + 'CONTRACT-INSERTION-ANCHOR'
  $gateIdPreflightSource = Get-Content -LiteralPath $PSCommandPath -Raw
  $gateIdPreflightResult = Test-SelftestGateIdContract -Source $gateIdPreflightSource -InsertionAnchor $gateIdPreflightAnchor
  if (-not $gateIdPreflightResult.Ok) {
    if ($gateIdPreflightResult.Code -ceq 'GATE-ID-DUPLICATE') {
      Fail "[GATE-ID-DUPLICATE] id=$($gateIdPreflightResult.Id) locations=$(@($gateIdPreflightResult.Locations) -join ',') detail=$($gateIdPreflightResult.Detail)"
    } else {
      Fail "[GATE-ID-PREFLIGHT-$($gateIdPreflightResult.Code)] id=$($gateIdPreflightResult.Id) locations=$(@($gateIdPreflightResult.Locations) -join ',') detail=$($gateIdPreflightResult.Detail)"
    }
    exit 1
  }
}

function Test-SelftestGateGroupCompletion([string[]]$Actual, [string[]]$Expected) {
  return ([string]::Join([char]0, $Actual) -ceq [string]::Join([char]0, $Expected))
}

function Test-SeededShardRegionSelected([ValidateSet('git','remote','scanner')][string]$Region) {
  if ($Shard -eq 'seeded') { return $true }
  return ($Shard -ceq "seeded-$Region")
}

function Get-AcMoveGitWrapperBody([string]$ShimScript, [bool]$UseWindows) {
  if ($UseWindows) {
    return (@('& "$PSScriptRoot/git-shim.ps1" @args', 'exit $LASTEXITCODE') -join "`n")
  }
  $quotedShimScript = "'" + $ShimScript.Replace("'", "''") + "'"
  return (@('#!/usr/bin/env pwsh', "& $quotedShimScript @args", 'exit $LASTEXITCODE') -join "`n")
}

# T44-W6FIXTURES
function New-InitSmokeCopy([string]$LeafName) {
  $copyRoot = Join-Path ([System.IO.Path]::GetTempPath()) $LeafName
  if (Test-Path $copyRoot) { Remove-Item -Recurse -Force $copyRoot }
  New-Item -ItemType Directory -Force $copyRoot | Out-Null
  $skip = $RootIgnore + @('_local', 'CLAUDE.md')
  Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $skip } |
    Copy-Item -Destination $copyRoot -Recurse -Force
  return $copyRoot
}

# T44-W6FIXTURES
function New-ReviewFixtureRepo([string]$RepoPath, [string]$Branch) {
  & git -C $RepoPath init -q
  & git -C $RepoPath symbolic-ref HEAD refs/heads/master
  & git -C $RepoPath -c user.email='s@l' -c user.name='s' add -A 2>$null
  & git -C $RepoPath -c user.email='s@l' -c user.name='s' commit -q -m base *> $null
  & git -C $RepoPath -c user.email='s@l' -c user.name='s' checkout -q -b $Branch
}

# T45-W7SHIPCARD
function New-ShipFixtureCard([string]$Root, [string]$Id, [string]$Title, [string]$DodLine) {
  @('---', "id: $Id", "title: $Title", 'status: todo',
    $DodLine, 'allow_paths:', '  - README.md', '---') -join "`n" |
    Set-Content (Join-Path $Root "specs/tasks/$Id.md") -Encoding utf8
  & git -C $Root add specs/tasks/$Id.md *> $null
  & git -C $Root commit -q -m "fixture card $Id" *> $null
  & pwsh -NoProfile -File (Join-Path $Root 'scripts/task.ps1') -TaskId $Id -Phase start *> $null
  return (Join-Path $Root "wt/$Id")
}

if ($Shard -eq 'core') {
[void]$executedGateGroups.Add('core:1-14')
# --- 1. PowerShell 语法 ---
Step '1/17 PowerShell 语法（ParseFile）'
$ps1 = @(Get-ChildItem -Path (Join-Path $RepoRoot 'scripts') -Filter *.ps1 -Recurse) +
       @(Get-ChildItem -Path (Join-Path $RepoRoot '.claude/hooks') -Filter *.ps1 -Recurse -ErrorAction SilentlyContinue) +
       @(Get-Item (Join-Path $RepoRoot 'init-scaffold.ps1'))
foreach ($f in $ps1) {
  $errs = $null
  [void][System.Management.Automation.Language.Parser]::ParseFile($f.FullName, [ref]$null, [ref]$errs)
  if ($errs -and $errs.Count) { Fail "语法错误 $($f.Name): $($errs[0].Message)" }
}
if (-not $fail) { Write-Host "  $($ps1.Count) 个 .ps1 语法 OK" }
# .mjs：workflow 脚本在 harness 包的 async 上下文里跑（顶层 return/await/export const meta 是 harness 特性、
# 非独立模块），故用「剥 export + 包 async 函数」喂 node --check 验语法；node 缺失则跳过（保持离线，仿闸 ⑦）。
$mjs = @(Get-ChildItem -Path (Join-Path $RepoRoot '.claude/workflows') -Filter *.mjs -Recurse -ErrorAction SilentlyContinue)
if ($mjs.Count -eq 0) {
  Skip-SelftestCheck -GateId '1(mjs)' -Reason 'FILE-MISSING' -Message '  无 .claude/workflows/*.mjs，跳过 mjs 语法检。'
} else {
  if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    Skip-SelftestCheck -GateId '1(mjs)' -Reason 'TOOL-NODE-MISSING' -Message "  node 未安装，跳过 $($mjs.Count) 个 .mjs 语法检（离线环境正常）。"
  } else {
    $mjsOk = 0
    foreach ($m in $mjs) {
      $wrapped = "async function __wf(){`n" + ((Get-Content $m.FullName -Raw) -replace '(?m)^export\s+', '') + "`n}"
      $tmpMjs = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-mjs-$PID-$($m.BaseName).mjs"
      Set-Content -Path $tmpMjs -Value $wrapped -Encoding utf8
      $mjsErr = $true
      try { & node --check $tmpMjs 2>$null; if ($LASTEXITCODE -eq 0) { $mjsErr = $false } } catch { $mjsErr = $true }
      Remove-Item $tmpMjs -ErrorAction SilentlyContinue
      if ($mjsErr) { Fail ".mjs 语法错误 $($m.Name)（剥 export+包 async 后 node --check 仍失败）。" } else { $mjsOk++ }
    }
    if ($mjsOk) { Write-Host "  $mjsOk 个 .mjs 语法 OK（node --check：剥 export+包 async）" }
  }
}

# 1a. TD52：plan-forge.mjs 尾 agent() 结果裸解引用无 null 守卫，单个 skip/终态错的 agent 返回 null 即崩整轮
#     （lens/verify 段已防 :249 `(review && review.findings) || []`、:263 `votes.filter(Boolean)`，耗时尾 agent
#     synth/decomp 曾未防）。纯字符串静态断言（离线、不依赖 node）：定位「赋值 -> 首次解引用」之间的源码切片，
#     断言切片内含守卫写法（`if (!x)` / `if (x === null)` / `x?.` / `.filter(Boolean)`）——修前该切片不含任何守卫
#     写法故必红；修后守卫语句位于切片内故转绿。
Step '1a/17 尾 agent() null 守卫（plan-forge.mjs，TD52）'
$pfGuardPath = Join-Path $RepoRoot '.claude/workflows/plan-forge.mjs'
if (-not (Test-Path $pfGuardPath)) { Fail 'plan-forge.mjs 不存在（TD52 尾 agent null 守卫检查目标缺失）。' }
else {
  $pfGuardSrc = Get-Content $pfGuardPath -Raw
  $tailGuardPattern = 'if\s*\(\s*!\s*(synth|decomp)\s*\)|if\s*\(\s*(synth|decomp)\s*===?\s*null\s*\)|(synth|decomp)\s*\?\.|\.filter\(\s*Boolean\s*\)'
  function Test-TdPfTailGuard([string]$assignMarker, [string]$derefMarker) {
    $aIdx = $pfGuardSrc.IndexOf($assignMarker)
    if ($aIdx -lt 0) { return $null }   # 赋值点被重构掉——本闸断言范围外，不误判
    $dIdx = $pfGuardSrc.IndexOf($derefMarker, $aIdx + $assignMarker.Length)
    if ($dIdx -lt 0) { return $null }   # 解引用点消失——同上
    $between = $pfGuardSrc.Substring($aIdx, $dIdx - $aIdx)
    return [bool]($between -match $tailGuardPattern)
  }
  $synthGuarded = Test-TdPfTailGuard 'const synth = await agent(' 'synth.verdict'
  $decompGuarded = Test-TdPfTailGuard 'const decomp = await agent(' 'decomp.freeze_point'
  if ($synthGuarded -eq $false) { Fail 'plan-forge.mjs: 尾 agent 结果 synth 在首次解引用（synth.verdict）前无 null 守卫（TD52：agent() 被跳过/终态错时返回 null，裸解引用即 TypeError 崩整轮——需仿 :249/:263 加 if (!synth) 守卫）。' }
  if ($decompGuarded -eq $false) { Fail 'plan-forge.mjs: 尾 agent 结果 decomp 在首次解引用（decomp.freeze_point）前无 null 守卫（TD52，同上）。' }
  if ($synthGuarded -ne $false -and $decompGuarded -ne $false) { Write-Host '  synth / decomp 尾 agent 结果均在首次解引用前 null 守卫 OK' -ForegroundColor Green }
}

# 1b. TD53/TD-116：scout-options.mjs 的 BRIEF 用「无条件字符串默认值」`A.briefPath || '_local/1-brief.md'`，
#     致 BRIEF 恒真——:22 的无参守卫 `if (!BRIEF && !IDEA)` 永不可达，:26 的 SOURCE 三元恒走 brief 分支，
#     `args.idea`（docs/SCOUT-OPTIONS.md:16 记录的「无 brief 时用一句话兜底」通道）从未真正生效：idea-only
#     调用会让下游 fan-out agent 去 Read 一个不存在的 `_local/1-brief.md`（评审已核验 S3）。
#     夹具：不重新实现该逻辑，而是从源码里用正则**原样抠出** BRIEF/IDEA 赋值行、无参守卫条件、SOURCE 三元
#     这几处的**真实表达式**，拼进一段临时 node 脚本，对 {idea-only, brief-only, neither} 三种 args 形状真跑
#     求值——跑的是仓库这份源码当下的逻辑本身，实现一变、断言就贴着新表达式走，不会像纯字符串正则那样随
#     改法漂移（同 1a 的「静态定位再断言」手法，这里换成「抽取表达式再求值」）。
#     种子非真空：改前 idea-only 的 SOURCE 恒引用 `_local/1-brief.md`（不含 idea 文本）——本闸必红；
#     TD53 修复后 idea-only 的 BRIEF 变假、SOURCE 转引 idea 文本——本闸转绿。
#     neither 形状留作文档化夹具而非「必触发守卫」断言：无条件默认值决定了「两者皆无」时 BRIEF 仍退到常规
#     路径（这是刻意保留的「零参即假设 shape-idea 已产出常规 brief」既有约定，不在 TD53 范围内改变），
#     故只锁「未回归」+ 守卫真正的必要条件（触发即两者皆假，用跨形状通用循环核验），不断言其在此形状下触发。
Step '1b/17 scout-options BRIEF/IDEA 兜底表达式（TD53/TD-116）'
$soExprPath = Join-Path $RepoRoot '.claude/workflows/scout-options.mjs'
if (-not (Test-Path $soExprPath)) {
  Skip-SelftestCheck -GateId '1b' -Reason 'FILE-MISSING' -Message '  1b 跳过（无 scout-options.mjs——下游裁剪后正常）。'
} elseif (-not (Get-Command node -ErrorAction SilentlyContinue)) {
  Skip-SelftestCheck -GateId '1b' -Reason 'TOOL-NODE-MISSING' -Message '  1b 跳过（node 未安装，离线环境正常，同 mjs 语法检）。'
} else {
  $soSrc = Get-Content $soExprPath -Raw
  $briefM = [regex]::Match($soSrc, '(?m)^const BRIEF = (.+)$')
  $ideaM = [regex]::Match($soSrc, '(?m)^const IDEA = (.+)$')
  $guardM = [regex]::Match($soSrc, 'if\s*\(([^)]*)\)\s*\{\s*\r?\n\s*return \{ error:')
  $sourceM = [regex]::Match($soSrc, 'const SOURCE = ([\s\S]+?)\r?\n\r?\n')
  if (-not ($briefM.Success -and $ideaM.Success -and $guardM.Success -and $sourceM.Success)) {
    Fail '1b：scout-options.mjs 里 BRIEF/IDEA/守卫/SOURCE 这几行的形状已变，正则抠不出表达式——需同步本闸的抽取正则（检查目标漂移，TD53）。'
  } else {
    $briefExpr = ($briefM.Groups[1].Value -replace '\s*//.*$', '').Trim()
    $ideaExpr = ($ideaM.Groups[1].Value -replace '\s*//.*$', '').Trim()
    $guardExpr = $guardM.Groups[1].Value.Trim()
    $sourceExpr = $sourceM.Groups[1].Value.Trim()
    $node1bTpl = @'
const cases = {
  ideaOnly: { idea: "IDEA_TEXT_X" },
  briefOnly: { briefPath: "_local/custom-brief.md" },
  neither: {},
}
const out = {}
for (const [k, A] of Object.entries(cases)) {
  const BRIEF = __BRIEF_EXPR__
  const IDEA = __IDEA_EXPR__
  let guardFired = false
  if (__GUARD_EXPR__) { guardFired = true }
  let SOURCE = null
  if (!guardFired) { SOURCE = (__SOURCE_EXPR__) }
  out[k] = { BRIEF, IDEA, guardFired, SOURCE }
}
console.log(JSON.stringify(out))
'@
    $node1b = $node1bTpl.Replace('__BRIEF_EXPR__', $briefExpr).Replace('__IDEA_EXPR__', $ideaExpr).Replace('__GUARD_EXPR__', $guardExpr).Replace('__SOURCE_EXPR__', $sourceExpr)
    $tmp1b = Join-Path ([System.IO.Path]::GetTempPath()) "selftest-1b-$PID.mjs"
    Set-Content -Path $tmp1b -Value $node1b -Encoding utf8
    $node1bOut = $null
    try { $node1bOut = (& node $tmp1b 2>&1 | Out-String) } catch { $node1bOut = $_.Exception.Message }
    Remove-Item $tmp1b -ErrorAction SilentlyContinue
    $parsed1b = $null
    try { $parsed1b = $node1bOut | ConvertFrom-Json } catch {}
    if (-not $parsed1b) {
      Fail "1b：node 求值 BRIEF/IDEA/SOURCE 表达式失败或输出非 JSON（抽取的表达式可能已不是合法 JS 片段）。输出=$(($node1bOut -replace '\s+',' ').Trim())"
    } else {
      if ($parsed1b.ideaOnly.SOURCE -match [regex]::Escape('_local/1-brief.md')) {
        Fail '1b：只给 args.idea（无 briefPath）时，SOURCE 仍引用 `_local/1-brief.md`——BRIEF 的字符串默认值把 idea-only 形状也导去读一个不存在的 brief 文件（TD53/TD-116 核心缺陷，已核验 S3）。'
      }
      if ($parsed1b.ideaOnly.SOURCE -notmatch 'IDEA_TEXT_X') {
        Fail '1b：只给 args.idea 时，SOURCE 未引用 idea 文本——idea-only 兜底通道（docs/SCOUT-OPTIONS.md:16 记录的约定）未生效。'
      }
      if ($parsed1b.ideaOnly.guardFired) {
        Fail '1b：只给 args.idea 时，无参守卫误触发——idea 已提供，不应被当「两者皆无」拦截。'
      }
      if ($parsed1b.briefOnly.SOURCE -notmatch [regex]::Escape('_local/custom-brief.md')) {
        Fail '1b：只给 args.briefPath 时，SOURCE 未指向该路径——brief-only 既有行为被本次改动意外破坏（验收要求「brief-only 行为不变」）。'
      }
      foreach ($shape in @('ideaOnly', 'briefOnly', 'neither')) {
        $c = $parsed1b.$shape
        if ($c.guardFired -and ($c.BRIEF -or $c.IDEA)) {
          Fail "1b：$shape 形状下守卫触发但 BRIEF/IDEA 并非皆假——守卫「触发即两者皆无」的必要条件被破坏。"
        }
      }
      if (-not $fail) { Write-Host '  scout-options BRIEF/IDEA 兜底：idea-only 用 idea 且不误触发守卫、brief-only 不变、守卫必要条件成立 OK' -ForegroundColor Green }
    }
  }
}

# --- 1c–1f. TD54/TD-117：编码 + 原生错误纪律收敛为共享前奏（散落点修 → 对称覆盖）---
# 归在闸①下（静态/hermetic、无网络），不新增顶层闸号（避免触发闸⑭计数一致）。
# 1c：_encoding.ps1 形态——设 OutputEncoding + 关 native 非零抛，但**不**全局设 InputEncoding（L4/L69：破坏嵌套/重定向 stdin）。
$encPath = Join-Path $PSScriptRoot '_encoding.ps1'
if (-not (Test-Path $encPath)) { Fail '1c TD54：scripts\_encoding.ps1 缺失（共享编码/native-error 前奏未建）。' }
else {
  $encRaw = Get-Content -LiteralPath $encPath -Raw
  if ($encRaw -notmatch '\[Console\]::OutputEncoding') { Fail '1c TD54：_encoding.ps1 未设 [Console]::OutputEncoding。' }
  elseif ($encRaw -notmatch 'PSNativeCommandUseErrorActionPreference\s*=\s*\$false') { Fail '1c TD54：_encoding.ps1 未关 $PSNativeCommandUseErrorActionPreference。' }
  elseif ($encRaw -match '\[Console\]::InputEncoding\s*=') { Fail '1c TD54：_encoding.ps1 不得全局设 [Console]::InputEncoding（L4/L69：破坏嵌套/重定向 stdin；InputEncoding pin 须就地就读端）。' }
  else { Write-Host '  1c _encoding.ps1 形态 OK（OutputEncoding + native pin，无全局 InputEncoding）' -ForegroundColor Green }
}
# 1d：覆盖对称——曾缺 native pin 的 gap 脚本 dot-source 前奏；_guard 函数域 pin；_scope/review 的 git diff 带 -c core.quotepath=false。
$td54cov = $true
foreach ($s in @('check-secrets.ps1', 'verify.ps1')) {
  $sr = Get-Content -LiteralPath (Join-Path $PSScriptRoot $s) -Raw
  if ($sr -notmatch '_encoding\.ps1') { Fail "1d TD54：$s 未 dot-source _encoding.ps1（native-error/OutputEncoding 覆盖缺口）。"; $td54cov = $false }
}
$guardRaw = Get-Content -LiteralPath (Join-Path $PSScriptRoot '_guard.ps1') -Raw
if ($guardRaw -notmatch '(?s)function Assert-PersonalAccount[\s\S]{0,2000}PSNativeCommandUseErrorActionPreference\s*=\s*\$false') {
  Fail '1d TD54：_guard.ps1 Assert-PersonalAccount 缺函数域 native pin（hostile profile 下 gh/git 非零会抛、崩账号守卫）。'; $td54cov = $false
}
# 范围闸那句 --name-only diff 已随判定核抽进 _scope.ps1（TD93 item①，task.ps1 与 check-scope.ps1 共用），
# 故本断言跟着核走——覆盖面不变（仍是「范围闸的 diff 必带 quotepath 旗标」），只是不再钉在搬走前的宿主文件上。
# (?: -c \S+)* 容许 core.quotepath=false 与 diff --name-only 之间夹别的 git -c 配置旗标（TD-202 加了 -c diff.renames=false），
# 仍断言 quotepath 旗标作用于范围闸那句 --name-only diff——不收窄 TD54 覆盖，只容忍相邻 -c 旗标。
$scopeRawEnc = Get-Content -LiteralPath (Join-Path $PSScriptRoot '_scope.ps1') -Raw
if ($scopeRawEnc -notmatch 'core\.quotepath=false(?: -c \S+)* diff --name-only') {
  Fail '1d TD54：_scope.ps1 范围闸 git diff --name-only 未带 -c core.quotepath=false（CJK allow_paths 文件会被 C-quote → 假越界 BLOCK）。'; $td54cov = $false
}
# 反向（TD93）：task.ps1 不得再自带**第二句** --name-only diff。抽核后它只应经 Get-ScaffoldChangedPath 打同一枚核；
# 留一份「等价的」内联求值就是 TD68 式双实现（一处修、一处漏）。只认真正的调用形态 `& git … diff --name-only`，
# 故 throw 文案里那句人类可读的 `git diff --name-only …` 不会误伤。
$taskRawEnc = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'task.ps1') -Raw
if ($taskRawEnc -match '&\s*git[^\r\n]*diff --name-only') {
  Fail '1d TD93：task.ps1 仍自带 git diff --name-only 调用——范围闸判定核已收敛到 _scope.ps1，第二份内联求值即双实现漂移面（TD68）。'; $td54cov = $false
}
$revRawEnc = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'review.ps1') -Raw
if ($revRawEnc -notmatch 'core\.quotepath=false') {
  Fail '1d TD54：review.ps1 评审 diff 未带 -c core.quotepath=false（CJK 路径 C-quote 混淆评审者）。'; $td54cov = $false
}
if ($td54cov) { Write-Host '  1d 编码/native-error 覆盖对称 OK（gap 脚本 dot-source 前奏 · _guard 函数域 pin · _scope/review quotepath · task.ps1 无第二份内联 diff）' -ForegroundColor Green }
# 1e：行为——脚本设 $ErrorActionPreference='Stop'（本仓入口脚本都设）下，即便调用方 profile 把
#     $PSNativeCommandUseErrorActionPreference 设 $true（敌意），dot-source _encoding 后「预期非零」的原生命令仍不抛终止错
#     （check-secrets 非 git / verify 缺料优雅路径靠此不崩）。Stop+pin=$true 才有牙——两者都设方能复现，故探针必须都设。跨平台用 pwsh 自身产非零退出码。
$encAbs = Join-Path $PSScriptRoot '_encoding.ps1'
$probeBody = "`$ErrorActionPreference = 'Stop'; `$PSNativeCommandUseErrorActionPreference = `$true; . '$encAbs'; & pwsh -NoProfile -Command 'exit 7'; if (`$LASTEXITCODE -eq 7) { 'NATIVE-PIN-OK' } else { 'BAD:' + `$LASTEXITCODE }"
$probeOut = (& pwsh -NoProfile -Command $probeBody 2>&1 | Out-String).Trim()
if ($probeOut -notmatch 'NATIVE-PIN-OK') { Fail "1e TD54：_encoding.ps1 未在敌意 profile 下抑制 native 非零抛错（应按退出码判、得: $probeOut）。" }
else { Write-Host '  1e _encoding.ps1 敌意 profile 下 native 非零按退出码判、不抛 OK' -ForegroundColor Green }
# 1f：行为（acceptance #4）——-c core.quotepath=false 令 git 原样输出 CJK 路径（不 C-quote 成 "docs/\346..."），
#     task.ps1 范围闸据此能把 CJK-名文件匹配进 allow_paths。只断言 ASCII 可观测属性（docs/ 前缀 / 无引号），避开跨进程 CJK 捕获的编码坑（TD31/L66）。
$cjkTmp = Join-Path ([System.IO.Path]::GetTempPath()) ("td54cjk-" + [guid]::NewGuid().ToString('N'))
try {
  New-Item -ItemType Directory -Force -Path (Join-Path $cjkTmp 'docs') | Out-Null
  Push-Location $cjkTmp
  try {
    & git init -q *> $null
    & git -c user.email='t@t.t' -c user.name='t' commit -q --allow-empty -m base *> $null
    Set-Content -LiteralPath (Join-Path $cjkTmp 'docs/测试.md') -Value 'x' -Encoding utf8
    & git add -A *> $null
    & git -c user.email='t@t.t' -c user.name='t' commit -q -m cjk *> $null
    $rawLine = (& git -c core.quotepath=false diff --name-only 'HEAD~1...HEAD' | Select-Object -First 1)
    if (-not $rawLine) { Fail '1f TD54：CJK 探针 git diff 无输出（临时仓构造失败）。' }
    elseif ($rawLine -notmatch '^docs/') { Fail "1f TD54：-c core.quotepath=false 下 CJK 路径未以未引用的 docs/ 开头（得: $rawLine）——仍被 C-quote，范围闸会假越界。" }
    elseif ($rawLine -match '"') { Fail "1f TD54：quotepath=false 输出仍含引号（C-quote 未关）：$rawLine" }
    else { Write-Host '  1f CJK 路径经 -c core.quotepath=false 原样输出（docs/ 前缀 · 无引号）OK' -ForegroundColor Green }
  } finally { Pop-Location }
} finally { Remove-Item -Recurse -Force $cjkTmp -ErrorAction SilentlyContinue }
# 1g：OutputEncoding 覆盖对称（TD54/TD-117 breadth）——所有写中文 stdout 的入口脚本 dot-source _encoding.ps1（前奏统一设 UTF-8 输出）；
#     所有写 stdout 的钩子就地设 [Console]::OutputEncoding（钩子保持自包含 fail-open、不跨目录 dot-source 前奏，与其既有 InputEncoding pin 同风格）。
#     selftest.ps1 的 all 子进程会捕获中文输出，也必须在入口 dot-source 前奏，避免 Windows OEM 解码假红。
$encScripts = @('selftest.ps1', 'task.ps1', 'review.ps1', 'check-secrets.ps1', 'verify.ps1', 'gh-bootstrap.ps1', 'handoff.ps1', 'lessons.ps1', 'triage.ps1', 'check-cards.ps1', 'check-scope.ps1', 'check-licenses.ps1', 'license-scanner-check.ps1', 'init-scaffold.ps1')
$g1ok = $true
foreach ($s in $encScripts) {
  # init-scaffold.ps1 在仓库根（非 scripts/，见 $RootAllow / 闸①的 $RepoRoot 解析），其余在 scripts/。
  $sp = if ($s -eq 'init-scaffold.ps1') { Join-Path $RepoRoot $s } else { Join-Path $PSScriptRoot $s }
  if (-not (Test-Path $sp)) { Fail "1g TD54：$s 不存在。"; $g1ok = $false; continue }
  $spRaw = Get-Content -LiteralPath $sp -Raw
  $hasPrelude = if ($s -eq 'selftest.ps1') {
    $spRaw -match "(?m)^try \{ \. \(Join-Path \`$PSScriptRoot '_encoding\.ps1'\) \} catch \{ \}\s*$"
  } elseif ($s -eq 'license-scanner-check.ps1') {
    $spRaw -match "(?m)^\. \(Join-Path \`$PSScriptRoot '_encoding\.ps1'\)(?:\s*#.*)?$"
  } else { $spRaw -match '_encoding\.ps1' }
  if (-not $hasPrelude) { Fail "1g TD54：$s 未 dot-source _encoding.ps1（OutputEncoding 覆盖缺口）。"; $g1ok = $false }
}
$encodingFailClosedRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("selftest-encoding-failclosed-" + [guid]::NewGuid().ToString('N'))
try {
  New-Item -ItemType Directory -Force -Path $encodingFailClosedRoot | Out-Null
  $encodingFailClosedScript = Join-Path $encodingFailClosedRoot 'license-scanner-check.ps1'
  Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'license-scanner-check.ps1') -Destination $encodingFailClosedScript
  $encodingFailClosedOutput = (& pwsh -NoProfile -File $encodingFailClosedScript -Suite graph 2>&1 | Out-String)
  $encodingFailClosedExit = $LASTEXITCODE
  if ($encodingFailClosedExit -eq 0 -or $encodingFailClosedOutput -notmatch '_encoding\.ps1') {
    Fail "1g TD54：license-scanner-check.ps1 缺失必需 _encoding.ps1 时未 fail-closed（exit=$encodingFailClosedExit）：$encodingFailClosedOutput"
    $g1ok = $false
  }
} finally {
  if (Test-Path -LiteralPath $encodingFailClosedRoot) { Remove-Item -LiteralPath $encodingFailClosedRoot -Recurse -Force }
}
$encHookDir = Join-Path (Split-Path $PSScriptRoot -Parent) '.claude/hooks'
$encHooks = @('route-new-work.ps1', 'guard-frozen.ps1', 'handoff-resume.ps1', 'handoff-reminder.ps1', 'lessons-reminder.ps1')
foreach ($h in $encHooks) {
  $hp = Join-Path $encHookDir $h
  if (-not (Test-Path $hp)) { Fail "1g TD54：钩子 $h 不存在。"; $g1ok = $false; continue }
  if ((Get-Content -LiteralPath $hp -Raw) -notmatch '\[Console\]::OutputEncoding\s*=') { Fail "1g TD54：钩子 $h 未就地设 [Console]::OutputEncoding（中文 stdout 注入/提醒在非 UTF-8 主机 mojibake）。"; $g1ok = $false }
}
# 计数**从清单派生**，不写字面量：字面量与清单会各自漂移（本行此前写 12、清单实为 11 项，codex R3 r3 抓出）。
if ($g1ok) { Write-Host "  1g OutputEncoding 覆盖对称 OK（$($encScripts.Count) 入口脚本 dot-source 前奏 + $($encHooks.Count) 钩子就地 OutputEncoding）" -ForegroundColor Green }

# 1h（TD157 / L190）：.NET regex classifies UTF-16 code units, so supplementary-plane Cf scalars
# appear as two Cs code units and evade `\p{Cc}|\p{Cf}`. Exercise the real shared helper:
# enumerate the complete Unicode scalar space in bounded batches, require every Cc/Cf target to
# become one ASCII space, preserve every other scalar exactly, and reject malformed UTF-16 instead
# of silently converting it into trusted text.
Step '1h/17 Unicode scalar control/format text helper (TD157)'
$unicodeScalarHelper = Join-Path $PSScriptRoot '_unicode.ps1'
if (-not (Test-Path -LiteralPath $unicodeScalarHelper -PathType Leaf)) {
  Fail '[UNICODE-SCALAR-MISSING] scripts/_unicode.ps1 is absent.'
} else {
  $unicodeHelperText = Get-Content -LiteralPath $unicodeScalarHelper -Raw
  $unicodeHelperShapeOk = $true
  if ($unicodeHelperText -notmatch '(?m)^\s*\$offset \+= \$rune\.Utf16SequenceLength\s*$') {
    Fail '[UNICODE-SCALAR-ADVANCE] scalar iteration does not advance by the decoded rune width.'
    $unicodeHelperShapeOk = $false
  }
  if ($unicodeHelperText -notmatch '(?m)^\s*\$category = \[System\.Text\.Rune\]::GetUnicodeCategory\(\$rune\)\s*$') {
    Fail '[UNICODE-SCALAR-CATEGORY] scalar category is not derived from the decoded rune.'
    $unicodeHelperShapeOk = $false
  }
  if ($unicodeHelperText -notmatch '(?m)^\s*throw \[System\.ArgumentException\]::new\($' -or
      $unicodeHelperText -notmatch '\[UNICODE-SCALAR-MALFORMED\] malformed UTF-16') {
    Fail '[UNICODE-SCALAR-MALFORMED-GUARD] malformed UTF-16 does not reach the stable fail-closed guard.'
    $unicodeHelperShapeOk = $false
  }
  . $unicodeScalarHelper
  $unicodeScalarOk = $unicodeHelperShapeOk
  if (-not $unicodeHelperShapeOk) {
    # A deleted advance statement would otherwise hang the semantic oracle.
  } elseif (-not (Get-Command ConvertTo-ScaffoldControlFormatSpaces -CommandType Function -ErrorAction SilentlyContinue)) {
    Fail '[UNICODE-SCALAR-API] ConvertTo-ScaffoldControlFormatSpaces is absent.'
    $unicodeScalarOk = $false
  } else {
    function Test-UnicodeScalarTransform([Parameter(Mandatory)][string]$CommandName) {
      $visited = 0
      $targets = 0
      $inputBuffer = [System.Text.StringBuilder]::new(16384)
      $expected = [System.Text.StringBuilder]::new(16384)
      $batchPoints = [System.Collections.Generic.List[int]]::new(4096)

      for ($codePoint = 0; $codePoint -le 0x10FFFF; $codePoint++) {
        if ($codePoint -ge 0xD800 -and $codePoint -le 0xDFFF) { continue }
        $visited++
        $rune = [System.Text.Rune]::new($codePoint)
        $runeText = $rune.ToString()
        $category = [System.Text.Rune]::GetUnicodeCategory($rune)
        $isTarget = $category -in @(
          [System.Globalization.UnicodeCategory]::Control,
          [System.Globalization.UnicodeCategory]::Format
        )
        if ($isTarget) { $targets++ }
        [void]$inputBuffer.Append($runeText)
        [void]$expected.Append($(if ($isTarget) { ' ' } else { $runeText }))
        [void]$batchPoints.Add($codePoint)

        if ($batchPoints.Count -lt 4096 -and $codePoint -lt 0x10FFFF) { continue }
        try { [string]$actual = & $CommandName $inputBuffer.ToString() }
        catch {
          return [PSCustomObject]@{ Ok = $false; Code = 'THREW'; Point = $batchPoints[0]; Category = ''; Detail = $_.Exception.Message; Visited = $visited; Targets = $targets }
        }
        if ($actual -cne $expected.ToString()) {
          foreach ($point in $batchPoints) {
            $pointRune = [System.Text.Rune]::new($point)
            $pointText = $pointRune.ToString()
            $pointCategory = [System.Text.Rune]::GetUnicodeCategory($pointRune)
            $pointIsTarget = $pointCategory -in @(
              [System.Globalization.UnicodeCategory]::Control,
              [System.Globalization.UnicodeCategory]::Format
            )
            [string]$pointActual = & $CommandName $pointText
            $pointExpected = if ($pointIsTarget) { ' ' } else { $pointText }
            if ($pointActual -cne $pointExpected) {
              return [PSCustomObject]@{ Ok = $false; Code = $(if ($pointIsTarget) { 'TARGET' } else { 'PRESERVE' }); Point = $point; Category = $pointCategory; Detail = ''; Visited = $visited; Targets = $targets }
            }
          }
          return [PSCustomObject]@{ Ok = $false; Code = 'BATCH'; Point = $batchPoints[0]; Category = ''; Detail = 'batch output differed but per-scalar replay did not'; Visited = $visited; Targets = $targets }
        }
        [void]$inputBuffer.Clear()
        [void]$expected.Clear()
        $batchPoints.Clear()
      }
      return [PSCustomObject]@{ Ok = $true; Code = ''; Point = -1; Category = ''; Detail = ''; Visited = $visited; Targets = $targets }
    }

    $unicodeOracle = Test-UnicodeScalarTransform -CommandName 'ConvertTo-ScaffoldControlFormatSpaces'
    if (-not $unicodeOracle.Ok) {
      $unicodeOracleCode = if ($unicodeOracle.Code -eq 'TARGET') { 'UNICODE-SCALAR-TARGET' } elseif ($unicodeOracle.Code -eq 'PRESERVE') { 'UNICODE-SCALAR-PRESERVE' } else { 'UNICODE-SCALAR-ORACLE' }
      Fail ('[{0}] U+{1:X} category={2} failed the complete scalar oracle ({3}).' -f $unicodeOracleCode, $unicodeOracle.Point, $unicodeOracle.Category, $unicodeOracle.Detail)
      $unicodeScalarOk = $false
    }
    if ($unicodeOracle.Visited -ne (0x110000 - 0x800) -or $unicodeOracle.Targets -le 0) {
      Fail "[UNICODE-SCALAR-ORACLE] scalar enumeration was incomplete (visited=$($unicodeOracle.Visited) targets=$($unicodeOracle.Targets))."
      $unicodeScalarOk = $false
    }

    # Mutation proof: broaden the production predicate to DecimalDigitNumber. The same complete oracle
    # must kill that over-replacement at U+0030 as PRESERVE, proving non-target coverage is not sampled.
    $unicodeMutantName = 'ConvertTo-ScaffoldControlFormatSpacesOverReplacementMutant'
    $unicodeMutantText = $unicodeHelperText.Replace(
      'function ConvertTo-ScaffoldControlFormatSpaces {',
      "function $unicodeMutantName {"
    ).Replace(
      '$category -eq [System.Globalization.UnicodeCategory]::Format) {',
      '$category -eq [System.Globalization.UnicodeCategory]::Format -or' + "`n" +
      '        $category -eq [System.Globalization.UnicodeCategory]::DecimalDigitNumber) {'
    )
    try {
      if ($unicodeMutantText -ceq $unicodeHelperText) { throw 'over-replacement mutation did not change helper source' }
      . ([scriptblock]::Create($unicodeMutantText))
      $unicodeMutantOracle = Test-UnicodeScalarTransform -CommandName $unicodeMutantName
      if ($unicodeMutantOracle.Ok -or $unicodeMutantOracle.Code -ne 'PRESERVE' -or $unicodeMutantOracle.Point -ne 0x30) {
        Fail "[UNICODE-SCALAR-MUTATION-OVERREPLACE] DecimalDigitNumber mutant was not killed at U+0030 as PRESERVE (ok=$($unicodeMutantOracle.Ok) code=$($unicodeMutantOracle.Code) point=$($unicodeMutantOracle.Point))."
        $unicodeScalarOk = $false
      }
    }
    catch {
      Fail "[UNICODE-SCALAR-MUTATION-SETUP] over-replacement mutation could not run: $($_.Exception.Message)"
      $unicodeScalarOk = $false
    }
    finally { Remove-Item -LiteralPath "Function:\$unicodeMutantName" -ErrorAction SilentlyContinue }

    foreach ($unicodeMalformed in @([string][char]0xD800, [string][char]0xDC00)) {
      $unicodeRejected = $false
      try { [void](ConvertTo-ScaffoldControlFormatSpaces $unicodeMalformed) }
      catch { $unicodeRejected = $_.Exception.Message -match '\[UNICODE-SCALAR-MALFORMED\]' }
      if (-not $unicodeRejected) {
        Fail '[UNICODE-SCALAR-MALFORMED] lone surrogate was not rejected with the stable sentinel.'
        $unicodeScalarOk = $false
      }
    }
  }
  if ($unicodeScalarOk) { Write-Host '  1h Unicode scalar control/format helper OK' -ForegroundColor Green }
}
}

# 1i. Gate identifiers are coordination keys: a duplicate declaration makes concurrent additions
# indistinguishable in logs even though both blocks still execute. Exercise one source parser against
# synthetic blocks and this file; failure-message repetition and child labels remain legal.
if ($Shard -ceq 'workflow') {
Step '1i/17 gate identifier uniqueness and insertion-anchor contract'
$gateIdInsertionAnchor = '# GATE-ID-' + 'CONTRACT-INSERTION-ANCHOR'
$gateIdContractCommand = Get-Command Test-SelftestGateIdContract -CommandType Function -ErrorAction SilentlyContinue
if (-not $gateIdContractCommand) {
  Fail '[GATE-ID-CONTRACT-MISSING] Test-SelftestGateIdContract is absent.'
} else {
  $gateIdFixtureOk = $true
  # Retained real RED receipt (2026-08-27): command=pwsh -NoProfile -File
  # scripts\selftest.ps1 -Shard workflow; sourceSha256=689290A8A48A164006A60CFC582C022A2025AFCABAA515B12E714DF54E0DA3AF;
  # exit=0; tail="selftest(workflow): PASS | selftest: PASS". Re-run the same pre-guard
  # behavior hermetically so A1 remains executable rather than relying only on the historical receipt.
  $a1DuplicateSource = @(
    '$ErrorActionPreference = ''Stop''',
    '$script:a1Failed = $false',
    'function Fail { param([string]$Message) $script:a1Failed = $true; Write-Error $Message }',
    '# 15q. first declaration', "if (`$false) { Fail '闸15q：first block' }",
    '# 15q. second declaration', "if (`$false) { Fail '闸15q：second block' }",
    $gateIdInsertionAnchor,
    'if ($script:a1Failed) { exit 1 }',
    "Write-Output 'selftest(workflow): PASS'", "Write-Output 'selftest: PASS'", 'exit 0'
  ) -join "`n"
  $a1HarnessPath = Join-Path ([System.IO.Path]::GetTempPath()) ("selftest-gate-id-a1-" + [guid]::NewGuid().ToString('N') + '.ps1')
  try {
    [System.IO.File]::WriteAllText($a1HarnessPath, $a1DuplicateSource, [System.Text.UTF8Encoding]::new($false))
    $a1HarnessOutput = (& pwsh -NoProfile -File $a1HarnessPath 2>&1 | Out-String)
    $a1HarnessExit = $LASTEXITCODE
  } finally {
    [System.IO.File]::Delete($a1HarnessPath)
  }
  $a1PostGuardResult = Test-SelftestGateIdContract -Source $a1DuplicateSource -InsertionAnchor $gateIdInsertionAnchor
  if ($a1HarnessExit -ne 0 -or $a1HarnessOutput -notmatch 'selftest\(workflow\): PASS' -or
      $a1HarnessOutput -notmatch 'selftest: PASS') {
    Fail "[GATE-ID-A1-BASELINE] expected pre-guard workflow harness exit=0 plus both PASS tails; exit=$a1HarnessExit output=$(($a1HarnessOutput -replace '\s+', ' ').Trim())"
    $gateIdFixtureOk = $false
  } elseif ($a1PostGuardResult.Code -cne 'GATE-ID-DUPLICATE' -or $a1PostGuardResult.Id -cne '15q') {
    Fail "[GATE-ID-A2-POSTGUARD] the same duplicate source was not rejected; code=$($a1PostGuardResult.Code) id=$($a1PostGuardResult.Id)."
    $gateIdFixtureOk = $false
  } else {
    Write-Host '  1i A1/A2 paired regression OK (pre-guard workflow harness exit 0 + PASS tails; same source post-guard GATE-ID-DUPLICATE id=15q)' -ForegroundColor Green
  }
  $validGateIdSource = @(
    '# --- 2. root gate ---', '# 2d. child gate',
    "if (`$false) { Fail '闸2d：first failure path' }",
    "if (`$false) { Fail '闸2d(a)：second failure path in the same gate' }",
    $gateIdInsertionAnchor
  ) -join "`n"
  $duplicateGateIdSource = @(
    '# --- 2. root gate ---', '# 2d. first declaration',
    "if (`$false) { Fail '闸2d：first block' }", '# 2d. second declaration',
    "if (`$false) { Fail '闸2d：second block' }", $gateIdInsertionAnchor
  ) -join "`n"
  $childGateIdSource = @(
    '# --- 2. root gate ---', '# 2d. parenthesized child owner',
    "if (`$false) { Fail '闸2d(a)：parenthesized child' }",
    '# --- 15. workflow root ---', '# 15b. digit child owner',
    "if (`$false) { Fail '闸15b5：digit child' }",
    '# --- 16. lesson root ---', "if (`$false) { Fail '闸16a：letter child' }",
    $gateIdInsertionAnchor
  ) -join "`n"
  $parenthesizedGateIdSource = @(
    '# --- 17. seeded root ---', '# 17t. parenthesized expression owner',
    "if (`$false) { Fail (`"闸17t(t18)：format {0}`" -f 'x') }",
    "if (`$false) { Fail ('闸17t(doc)：concat ' + 'x') }",
    $gateIdInsertionAnchor
  ) -join "`n"
  $emptyGateIdSource = "$gateIdInsertionAnchor`n"
  $mismatchedGateIdSource = @(
    '# 2d. declared gate', "if (`$false) { Fail '闸2e：message has no corresponding heading' }",
    $gateIdInsertionAnchor
  ) -join "`n"
  $wrongOwnerGateIdSource = $validGateIdSource.Replace($gateIdInsertionAnchor,
    "# 2e. heading owned by neither following message`nif (`$false) { Fail '闸2d：still reports 2d' }`n$gateIdInsertionAnchor")
  $warningOnlyGateIdSource = $validGateIdSource.Replace($gateIdInsertionAnchor,
    "# 2e. warning is not a failure message`nWrite-Warning 'unnumbered warning'`n$gateIdInsertionAnchor")
  $staleCopiedGateIdSource = $validGateIdSource.Replace($gateIdInsertionAnchor,
    "# 2e. next gate`nif (`$false) { Fail '闸2e：valid next gate' }`nif (`$false) { Fail '闸2d：stale copied label' }`n$gateIdInsertionAnchor")
  $headingOnlyGateIdSource = $validGateIdSource + "`n# 2e. declared after the last failure without a message`n"
  $embeddedStringAnchorSource = $validGateIdSource + "`n`$embedded = '$gateIdInsertionAnchor'`n"
  $embeddedCommentAnchorSource = $validGateIdSource + "`n# summary repeats $gateIdInsertionAnchor and is ambiguous`n"
  $duplicateAnchorGateIdSource = $validGateIdSource + "`n$gateIdInsertionAnchor`n"
  $invalidSyntaxGateIdSource = $validGateIdSource + "`nif (`n"
  $gateIdCases = @(
    [pscustomobject]@{ Name = 'valid'; Source = $validGateIdSource; Ok = $true; Code = 'OK'; Id = ''; Locations = '' },
    [pscustomobject]@{ Name = 'duplicate'; Source = $duplicateGateIdSource; Ok = $false; Code = 'GATE-ID-DUPLICATE'; Id = '2d'; Locations = '2,4' },
    [pscustomobject]@{ Name = 'children'; Source = $childGateIdSource; Ok = $true; Code = 'OK'; Id = ''; Locations = '' },
    [pscustomobject]@{ Name = 'parenthesized'; Source = $parenthesizedGateIdSource; Ok = $true; Code = 'OK'; Id = ''; Locations = '' },
    [pscustomobject]@{ Name = 'empty'; Source = $emptyGateIdSource; Ok = $false; Code = 'GATE-ID-SCAN-EMPTY'; Id = ''; Locations = '' },
    [pscustomobject]@{ Name = 'message-set'; Source = $mismatchedGateIdSource; Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = '2e'; Locations = '2' },
    [pscustomobject]@{ Name = 'message-owner'; Source = $wrongOwnerGateIdSource; Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = '2e'; Locations = '' },
    [pscustomobject]@{ Name = 'warning-only'; Source = $warningOnlyGateIdSource; Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = '2e'; Locations = '' },
    [pscustomobject]@{ Name = 'heading-only'; Source = $headingOnlyGateIdSource; Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = '2e'; Locations = '' },
    [pscustomobject]@{ Name = 'stale-copy'; Source = $staleCopiedGateIdSource; Ok = $false; Code = 'GATE-ID-MESSAGE-MISMATCH'; Id = '2d'; Locations = '7' },
    [pscustomobject]@{ Name = 'anchor'; Source = $duplicateAnchorGateIdSource; Ok = $false; Code = 'GATE-ID-ANCHOR-NONUNIQUE'; Id = ''; Locations = '5,6' },
    [pscustomobject]@{ Name = 'anchor-string'; Source = $embeddedStringAnchorSource; Ok = $false; Code = 'GATE-ID-ANCHOR-NONUNIQUE'; Id = ''; Locations = '5,6' },
    [pscustomobject]@{ Name = 'anchor-comment'; Source = $embeddedCommentAnchorSource; Ok = $false; Code = 'GATE-ID-ANCHOR-NONUNIQUE'; Id = ''; Locations = '5,6' },
    [pscustomobject]@{ Name = 'parse'; Source = $invalidSyntaxGateIdSource; Ok = $false; Code = 'GATE-ID-PARSE-ERROR'; Id = ''; Locations = '6' }
  )
  foreach ($gateIdCase in $gateIdCases) {
    $gateIdResult = Test-SelftestGateIdContract -Source $gateIdCase.Source -InsertionAnchor $gateIdInsertionAnchor
    $gateIdLocations = @($gateIdResult.Locations) -join ','
    if ($gateIdResult.Ok -ne $gateIdCase.Ok -or $gateIdResult.Code -cne $gateIdCase.Code -or
        $gateIdResult.Id -cne $gateIdCase.Id -or $gateIdLocations -cne $gateIdCase.Locations) {
      Fail "[GATE-ID-FIXTURE-$($gateIdCase.Name)] expected ok=$($gateIdCase.Ok) code=$($gateIdCase.Code) id=$($gateIdCase.Id) locations=$($gateIdCase.Locations); actual ok=$($gateIdResult.Ok) code=$($gateIdResult.Code) id=$($gateIdResult.Id) locations=$gateIdLocations."
      $gateIdFixtureOk = $false
    }
  }
  $repositoryGateIdSource = Get-Content -LiteralPath $PSCommandPath -Raw
  $gateIdMutationAssertions = @(
    [pscustomobject]@{ Suffix = 'DUPLICATE'; Assertions = @('[GATE-ID-FIXTURE-duplicate]') },
    [pscustomobject]@{ Suffix = 'SCAN-EMPTY'; Assertions = @('[GATE-ID-FIXTURE-empty]') },
    [pscustomobject]@{ Suffix = 'ANCHOR'; Assertions = @('[GATE-ID-FIXTURE-anchor]') },
    [pscustomobject]@{ Suffix = 'PARSE'; Assertions = @('[GATE-ID-FIXTURE-parse]') },
    [pscustomobject]@{ Suffix = 'MESSAGE-SET'; Assertions = @('[GATE-ID-FIXTURE-message-owner]', '[GATE-ID-FIXTURE-warning-only]', '[GATE-ID-FIXTURE-heading-only]') },
    [pscustomobject]@{ Suffix = 'ACTIVE-OWNER'; Assertions = @('[GATE-ID-FIXTURE-stale-copy]') }
  )
  foreach ($mutationAssertion in $gateIdMutationAssertions) {
    $mutationOutput = (& pwsh -NoProfile -File $PSCommandPath -Fixture gate-id-mutant -GateIdMutation $mutationAssertion.Suffix 2>&1 | Out-String)
    $mutationExit = $LASTEXITCODE
    $missingMutationAssertions = @($mutationAssertion.Assertions | Where-Object { $mutationOutput -notmatch [regex]::Escape($_) })
    if ($mutationExit -eq 0 -or $missingMutationAssertions.Count -gt 0) {
      Fail "[GATE-ID-MUTATION-$($mutationAssertion.Suffix)] expected nonzero plus $($mutationAssertion.Assertions -join ','); missing=$($missingMutationAssertions -join ',') exit=$mutationExit output=$(($mutationOutput -replace '\s+', ' ').Trim())"
      $gateIdFixtureOk = $false
    }
  }
  $repositoryGateIdResult = Test-SelftestGateIdContract -Source $repositoryGateIdSource -InsertionAnchor $gateIdInsertionAnchor
  if (-not $repositoryGateIdResult.Ok) {
    if ($repositoryGateIdResult.Code -ceq 'GATE-ID-DUPLICATE') {
      Fail "[GATE-ID-DUPLICATE] id=$($repositoryGateIdResult.Id) locations=$(@($repositoryGateIdResult.Locations) -join ',') detail=$($repositoryGateIdResult.Detail)"
    } else {
      Fail "[GATE-ID-REPOSITORY-$($repositoryGateIdResult.Code)] id=$($repositoryGateIdResult.Id) locations=$(@($repositoryGateIdResult.Locations) -join ',') detail=$($repositoryGateIdResult.Detail)"
    }
    $gateIdFixtureOk = $false
  }
  if ($gateIdFixtureOk) { Write-Host '  1i gate identifier contract fixtures OK' -ForegroundColor Green }
}
# GATE-ID-CONTRACT-INSERTION-ANCHOR
}

if ($Shard -eq 'core') {
# --- 2. 经验系统自检 ---
Step '2/17 经验系统（lessons.ps1 check）'
$lessonsCheckOut = (& pwsh -NoProfile -File (Join-Path $PSScriptRoot 'lessons.ps1') check 2>&1 | Out-String)
$lessonsCheckExit = $LASTEXITCODE
Write-Host $lessonsCheckOut
if ($lessonsCheckExit -ne 0) { Fail '经验系统 check 未过（见上）。' }
# 2a. 计量单位钉在**生产路径**上（本仓真实 CLAUDE.md，非夹具）：驻留经验 id 数与承载它们的条目数
#   **两个数各断言精确值**。只断言其一证不出「单位换了」——两个数必须**不相等**，那正是「合并条目」
#   这条静默失效路径的形状；相等时旧口径（数 bullet）与新口径（数 id）不可分辨。
#   数字变了就该在这里红：加/减铁律、或把两条并进一条 bullet，都要求作者回来同步这两个期望值。
$expectedResidentIds = 9    # CLAUDE.md「经验铁律」小节当前驻留的经验 id 数（上限 LessonsMustCap=10）
$expectedBullets = 7        # 承载它们的 markdown 条目数——比 id 少，因为有两条是合并条目
if ($lessonsCheckOut -notmatch "驻留 id=$expectedResidentIds（承载于 $expectedBullets 条目）") {
  Fail "闸2a：lessons.ps1 check 未在生产 CLAUDE.md 上报出「驻留 id=$expectedResidentIds（承载于 $expectedBullets 条目）」——要么铁律增删了（同步本闸的两个期望值），要么封顶又退回按 markdown 条目计量。实际输出：$(($lessonsCheckOut -split "`r?`n" | Where-Object { $_ -match '必须层：' }) -join ' ')"
} elseif ($expectedResidentIds -eq $expectedBullets) {
  Fail '闸2a：期望的 id 数与条目数相等——此时两种口径不可分辨，本闸证不了单位是 id。请让夹具/生产数据保留至少一条合并条目。'
} else { Write-Host "  2a 计量单位 OK（生产路径：驻留 id=$expectedResidentIds ≠ 条目数 $expectedBullets，两个数各自精确断言）" -ForegroundColor Green }

# 2b. TD39/TD-102：lessons.ps1 在【空 / 零-must LEDGER】下 StrictMode 崩溃（TD24 标 paid 实为未真修）。
#   根因：add 走【裸】Next-Id（默认绑定 = (Get-Lessons)）。空 LEDGER 时 Get-Lessons 返回 @()，经 [array] 默认参数
#   绑定 unroll 成 $null → @($null).Count==1 → 绕过 Count-eq-0 守卫 → $ls.id 抛 PropertyNotFoundStrict；
#   check 的 (…|Where tier -eq 'must').Count 在零匹配（AutomationNull）上取 .Count 亦抛。
#   为何 TD24（PR#47）漏修：in-file 自检调 Next-Id -Lessons @()【显式】绑定（空数组保真 → Count 0 → L1），
#   测的路径 ≠ 生产【裸】调用的默认绑定路径，故一直假绿。本闸【真跑】lessons.ps1 add / check（生产入口）覆盖。
#   夹具：忠实拷 scripts/ 到临时仓（无 git 依赖），写 header-only / zero-must LEDGER；断言 exit 0 —— 旧码崩溃即非零 → RED。
$l2Repo = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2b-$PID"
if (Test-Path $l2Repo) { Remove-Item -Recurse -Force $l2Repo }
New-Item -ItemType Directory -Force $l2Repo | Out-Null
try {
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2Repo -Recurse -Force   # lessons.ps1 dot-source _config/_config·check-secrets，整目录拷免隐式漏依赖（同 15i/17k）
  $l2Lessons = Join-Path $l2Repo 'scripts/lessons.ps1'
  $l2Ledger = Join-Path $l2Repo 'docs/lessons/LEDGER.md'
  New-Item -ItemType Directory -Force (Split-Path $l2Ledger) | Out-Null

  # (a) header-only（空）LEDGER 上【真跑】add → 生产裸 Next-Id 路径。旧码崩溃、不写；新码 exit 0 且 mint L1。
  Set-Content $l2Ledger "# 经验总账（header-only fixture，无 ## L<n> 块）`n" -Encoding utf8
  $a2Out = (& pwsh -NoProfile -File $l2Lessons add -Severity minor -Symptom 'seed 2b 空账本' -Rule 'seed 2b rule' 2>&1 | Out-String)
  $a2Exit = $LASTEXITCODE
  $a2Tail = ($a2Out -replace '\s+', ' ').Trim(); if ($a2Tail.Length -gt 200) { $a2Tail = $a2Tail.Substring($a2Tail.Length - 200) }
  if ($a2Exit -ne 0) { Fail "闸2b(a)：空 LEDGER 上 lessons.ps1 add 非零退出（$a2Exit）——裸 Next-Id 默认绑定 StrictMode 崩（TD24/TD39：空数组 unroll→`$null，@(`$null).Count==1 绕过守卫、`$ls.id 抛）。下游首条经验即崩、TD24 实为未修。输出尾段=$a2Tail" }
  elseif ((Get-Content $l2Ledger -Raw) -notmatch '(?m)^##[ \t]+L1[ \t]*\r?$') { Fail '闸2b(a)：add 退出 0 但未在空 LEDGER mint L1——Next-Id 未正确返回 L1（空账本递增回归）。' }

  # (b) zero-tier:must LEDGER 上【真跑】check → 零匹配 Where-Object 取 .Count。旧码崩溃；新码 exit 0（真 PASS）。
  #   构造【合法】zero-must 账本（条目齐全、无一 must）——修好后 check 应真 PASS，令 RED/GREEN 以退出码判别（locale 无关，免中文 mojibake 假 FAIL）。
  $l2Entry = @(
    '# 经验总账（zero-must fixture）', '',
    '## L1',
    '- date: 2026-01-01 ｜ tags: seed ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1',
    '- symptom: seed', '- root_cause: seed', '- rule: seed rule one', '- enforced_by: none（seed）', '- refs:'
  ) -join "`n"
  Set-Content $l2Ledger $l2Entry -Encoding utf8
  # A present resident section with zero lesson ids is distinct from a missing CLAUDE.md; both must be legal.
  Set-Content (Join-Path $l2Repo 'CLAUDE.md') "## 经验铁律（必须加载）`n当前无驻留经验。`n`n## 下一节" -Encoding utf8
  $c2Out = (& pwsh -NoProfile -File $l2Lessons check 2>&1 | Out-String)
  $c2Exit = $LASTEXITCODE
  if ($c2Exit -ne 0) { Fail "闸2b(b)：zero-must LEDGER + 在场但零 resident-id 的 CLAUDE.md 上 lessons.ps1 check 非零退出（$c2Exit）——(…|Where tier -eq 'must').Count 在零匹配 AutomationNull 上取 .Count 抛（TD39 Claim B）。删净示例 must 经验是合法下游态、却令 selftest 闸② 整挂。" }
  elseif ($c2Out -notmatch 'check: PASS') { Fail '闸2b(b)：check 退出 0 但输出无「check: PASS」——zero-must fixture 未正常通过（可能崩在别处或断言点漂移）。' }
  else {
    $l2Archive = Join-Path $l2Repo 'specs/archive/lessons-archive.md'
    New-Item -ItemType Directory -Force (Split-Path $l2Archive) | Out-Null
    Set-Content $l2Archive (@('# archive', '', '## L500', '- date: 2025-12-31 ｜ tags: cold ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1', '- symptom: cold max', '- root_cause: seed', '- rule: archived ids remain reserved', '- enforced_by: none（seed）', '- refs:') -join "`n") -Encoding utf8
    $coldAddOut = (& pwsh -NoProfile -File $l2Lessons add -Severity minor -Symptom 'cold max add' -Rule 'mint after archived maximum' 2>&1 | Out-String)
    $coldAddExit = $LASTEXITCODE
    $coldAddText = Get-Content $l2Ledger -Raw
    if ($coldAddExit -ne 0 -or $coldAddText -notmatch '(?m)^##[ \t]+L501[ \t]*\r?$' -or $coldAddText -match '(?m)^##[ \t]+L2[ \t]*\r?$') {
      Fail "闸2b(c)：真实 add 未以冷库最大 L500 的下一号 L501 入账，归档 id 被复用。exit=$coldAddExit output=[$coldAddOut]"
    } else { Write-Host '  2b lessons.ps1 空账本、zero-must 与 cold-max add 生产路径 OK' -ForegroundColor Green }
  }

  $invalidEntries = @(
    @{ id = 'L1'; value = 'TODO' }, @{ id = 'L2'; value = 'N/A' }, @{ id = 'L3'; value = '待补' }
  ) | ForEach-Object {
    @("## $($_.id)", '- date: 2026-01-01 ｜ tags: seed ｜ tier: ledger ｜ kind: pitfall ｜ severity: blocking ｜ recurrence: 1', '- symptom: seed', '- root_cause: seed', '- rule: seed', "- enforced_by: $($_.value)", '- refs:', '') -join "`n"
  }
  Set-Content $l2Ledger (('# invalid enforced_by fixture', '') + $invalidEntries -join "`n") -Encoding utf8
  Set-Content (Join-Path $l2Repo 'CLAUDE.md') "## 经验铁律（必须加载）`n- zero resident ids`n`n## 下一节" -Encoding utf8
  $invalidOut = (& pwsh -NoProfile -File $l2Lessons check 2>&1 | Out-String); $invalidExit = $LASTEXITCODE
  if ($invalidExit -eq 0 -or $invalidOut -notmatch '\[LESSONS-ENFORCED-BY-INVALID\]' -or $invalidOut -notmatch 'L1=TODO' -or $invalidOut -notmatch 'L2=N/A' -or $invalidOut -notmatch 'L3=待补') {
    Fail "闸2b(c)：真实 lessons.ps1 check 未逐项拒绝 TODO/N/A/待补 enforced_by。exit=$invalidExit output=[$invalidOut]"
  } else { Write-Host '  2b lessons.ps1 空/zero-must 与 invalid enforced_by 生产路径 OK' -ForegroundColor Green }
} finally {
  Remove-Item -Recurse -Force $l2Repo -ErrorAction SilentlyContinue
}

# 2c. TD51/TD-114：lessons.ps1 bump 用错 [regex]::Replace 静态重载——4 参数写法里第 4 个 int 实参会被隐式
#   转成 RegexOptions（1=IgnoreCase），并不存在「替换次数」这个重载，故等价于「大小写不敏感、替换块内全部
#   匹配」。若某条经验的 body 文本恰好引用了字面量 `recurrence: <digits>`（如讨论 bump/recurrence 本身的经验），
#   该 body 行会被 bump 静默篡改——单一真相源账本被写坏且不报错（exit 0，肉眼难发现）。
#   夹具：忠实拷 scripts/ 到临时仓（同 2b），造一条 body 含字面 `recurrence: 7` 的经验、meta recurrence=3，
#   真跑 bump L1（new=4），断言：meta 行变 4，且 body 的 `recurrence: 7` 原样保留（未被覆盖为 4）。
$l2cRepo = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2c-$PID"
if (Test-Path $l2cRepo) { Remove-Item -Recurse -Force $l2cRepo }
New-Item -ItemType Directory -Force $l2cRepo | Out-Null
try {
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2cRepo -Recurse -Force   # lessons.ps1 dot-source _config/check-secrets，整目录拷免隐式漏依赖（同 2b/15i/17k）
  $l2cLessons = Join-Path $l2cRepo 'scripts/lessons.ps1'
  $l2cLedger = Join-Path $l2cRepo 'docs/lessons/LEDGER.md'
  New-Item -ItemType Directory -Force (Split-Path $l2cLedger) | Out-Null
  # L2 的 meta 行破折号后是**两个空格**——合法（Get-LessonMeta 认 `^-\s+date:`），但它把「读 meta 行的锚定形态」
  # 与「写 meta 行的锚定形态」是否同源变成可观测：若把 bump 的 Replace 锚定收窄成 `^(- date:`（恰一个空格），
  # 替换将一处也匹配不上、块字节原样写回，旧码会照样打印绿字并 exit 0。此夹具令那条路径必须现形。
  $l2cEntry = @(
    '# 经验总账（TD51 fixture）', '',
    '## L1',
    '- date: 2026-01-01 ｜ tags: seed recurrence: 99 ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 3',
    '- symptom: seed，body 里引用示例文本 recurrence: 7（不应被 bump 覆盖）',
    '- root_cause: seed', '- rule: seed rule one', '- enforced_by: none（seed）', '- refs:',
    '',
    '## L2',
    '-',
    'date: prose recurrence: 99',
    '-  date: 2026-01-01 ｜ tags: seed ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 5',
    '- symptom: META_LINE_WITH_TWO_SPACES', '- root_cause: seed', '- rule: seed rule two',
    '- enforced_by: none（seed）', '- refs:'
  ) -join "`n"
  Set-Content $l2cLedger $l2cEntry -Encoding utf8
  $before = Get-Content $l2cLedger -Raw
  $expected = $before.Replace('severity: minor ｜ recurrence: 3', 'severity: minor ｜ recurrence: 4')
  $b2cOut = (& pwsh -NoProfile -File $l2cLessons bump L1 2>&1 | Out-String)
  $b2cExit = $LASTEXITCODE
  $after = Get-Content $l2cLedger -Raw
  $metaOk = $after -match '(?m)^- date:.*?recurrence:\s*4\b'
  $bodyIntact = $after -match 'symptom:.*recurrence:\s*7'
  $afterTail = ($after -replace '\s+', ' ').Trim()
  if ($b2cExit -ne 0) { Fail "闸2c：bump 对合法 fixture 非零退出（$b2cExit）——不应发生。输出=$(($b2cOut -replace '\s+',' ').Trim())" }
  elseif (-not $metaOk) { Fail "闸2c：bump 后 meta 行 recurrence 未变为 4（计数未正确递增）。after=$afterTail" }
  elseif (-not $bodyIntact -or $after -cne $expected) { Fail "闸2c：bump 未逐字只改 delimiter-bounded recurrence 字段；tags/body bait 被改。after=$afterTail" }
  else {
    # 读侧与写侧的 meta 行锚定形态必须同源：L2 的 meta 行破折号后两个空格，读侧照收，写侧若收窄成恰一个空格
    # 就会「一处也没改却报成功」。断言退出 0 + 计数器真的到 6 + 文件字节真的变了，三者缺一都能让那条路径隐身。
    $hash2cBefore = (Get-FileHash $l2cLedger -Algorithm SHA256).Hash
    $before2 = Get-Content $l2cLedger -Raw
    $expected2 = $before2.Replace('severity: minor ｜ recurrence: 5', 'severity: minor ｜ recurrence: 6')
    $b2cOut2 = (& pwsh -NoProfile -File $l2cLessons bump L2 2>&1 | Out-String)
    $b2cExit2 = $LASTEXITCODE
    $after2 = Get-Content $l2cLedger -Raw
    if ($b2cExit2 -ne 0) { Fail "闸2c(b)：bump 对「破折号后两个空格」的合法 meta 行非零退出（$b2cExit2）——写侧锚定比读侧窄。output=[$b2cOut2]" }
    elseif ($after2 -notmatch '(?m)^-\s+date:.*?recurrence:\s*6\b' -or $after2 -cne $expected2) { Fail "闸2c(b)：跨行 bait 被写入，或 L2 canonical recurrence 未逐字单改。after=$(($after2 -replace '\s+',' ').Trim())" }
    elseif ((Get-FileHash $l2cLedger -Algorithm SHA256).Hash -eq $hash2cBefore) { Fail '闸2c(b)：bump 报告成功却一个字节都没写（假绿写入——正是「读到了正文里的数字、锚定的写却打空」那条路径）。' }
    else { Write-Host '  2c lessons.ps1 bump 只改 meta 计数器、body 文本保真、读写锚定同源（TD51）OK' -ForegroundColor Green }
  }
} finally {
  Remove-Item -Recurse -Force $l2cRepo -ErrorAction SilentlyContinue
}

# 2h. 分节解析 fail-closed：CLAUDE.md **在**、但「经验铁律」小节标题漂移时，旧码返回 0 条 bullet，
#   与「小节在、零驻留」逐字不可分辨——于是 check 打印「驻留 id=0」、`-gt $MustCap` 判否、**exit 0 放行**，
#   而此刻真实驻留数其实远超上限（实测旧码：标题改一个字 → 11 个 id 的夹具报 0，封顶静默通过）。
#   本闸种同一个坏输入：夹具仓的 CLAUDE.md 带一条 11 个 id 的铁律、标题写成别的，断言 check
#   **非零退出**且打出 ASCII 哨兵 [LESSONS-SECTION-NOT-FOUND]（机检认哨兵，本地化文案只给人读，L165）。
$l2hRepo = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2h-$PID"
if (Test-Path $l2hRepo) { Remove-Item -Recurse -Force $l2hRepo }
New-Item -ItemType Directory -Force $l2hRepo | Out-Null
try {
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2hRepo -Recurse -Force   # 同 2b/2c：整目录拷免隐式漏依赖（lessons.ps1 dot-source _config/_lessons/check-secrets）
  $l2hLessons = Join-Path $l2hRepo 'scripts/lessons.ps1'
  $l2hLedger = Join-Path $l2hRepo 'docs/lessons/LEDGER.md'
  New-Item -ItemType Directory -Force (Split-Path $l2hLedger) | Out-Null
  Set-Content $l2hLedger (@(
    '# 经验总账（2h fixture）', '',
    '## L1',
    '- date: 2026-01-01 ｜ tags: seed ｜ tier: must ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1',
    '- symptom: seed', '- root_cause: seed', '- rule: seed rule one', '- enforced_by: none（seed）', '- refs:'
  ) -join "`n") -Encoding utf8
  Set-Content (Join-Path $l2hRepo 'CLAUDE.md') (@(
    '## 经验铁律（必须加载 · fixture）',
    '- **[L1]** resident fixture', '', '## 下一节') -join "`n") -Encoding utf8
  Set-Content (Join-Path $l2hRepo 'CLAUDE.template.md') (@(
    '## 经验铁律（必须加载 · fixture）',
    '- **[L1]** resident fixture', '', '## 下一节') -join "`n") -Encoding utf8
  $okOut = (& pwsh -NoProfile -File $l2hLessons check 2>&1 | Out-String); $okExit = $LASTEXITCODE
  # 负例：只把标题换掉，其余一字不动
  Set-Content (Join-Path $l2hRepo 'CLAUDE.md') (@(
    '## 必载经验（标题已漂移）',
    '- **[L901][L902][L903][L904][L905][L906][L907][L908][L909][L910][L911]** 11 个驻留 id，远超上限', '', '## 下一节') -join "`n") -Encoding utf8
  $driftOut = (& pwsh -NoProfile -File $l2hLessons check 2>&1 | Out-String); $driftExit = $LASTEXITCODE
  Set-Content (Join-Path $l2hRepo 'CLAUDE.md') (@('## 经验铁律（必须加载 · fixture）', '- **[L1]** resident fixture', '', '## 下一节') -join "`n") -Encoding utf8
  Set-Content (Join-Path $l2hRepo 'CLAUDE.template.md') (@('## 模板铁律标题已漂移', '- **[L1]** resident fixture', '', '## 下一节') -join "`n") -Encoding utf8
  $tplDriftOut = (& pwsh -NoProfile -File $l2hLessons check 2>&1 | Out-String); $tplDriftExit = $LASTEXITCODE
  $validResident = @('## 经验铁律（必须加载 · fixture）', '- **[L1]** resident fixture', '', '## 下一节') -join "`n"
  $duplicateResident = @('## 经验铁律（必须加载 · fixture）', '- **[L1]** first occurrence', '+ **[L1]** duplicate occurrence', '', '## 下一节') -join "`n"
  Set-Content (Join-Path $l2hRepo 'CLAUDE.md') $duplicateResident -Encoding utf8
  Set-Content (Join-Path $l2hRepo 'CLAUDE.template.md') $validResident -Encoding utf8
  $dupOut = (& pwsh -NoProfile -File $l2hLessons check 2>&1 | Out-String); $dupExit = $LASTEXITCODE
  Set-Content (Join-Path $l2hRepo 'CLAUDE.md') $validResident -Encoding utf8
  Set-Content (Join-Path $l2hRepo 'CLAUDE.template.md') $duplicateResident -Encoding utf8
  $tplDupOut = (& pwsh -NoProfile -File $l2hLessons check 2>&1 | Out-String); $tplDupExit = $LASTEXITCODE
  if ($okExit -ne 0) { Fail "闸2h(正例)：小节在场时 check 反而非零退出（$okExit）——fail-closed 写过头，把正常仓也拦了：$okOut" }
  elseif ($driftExit -eq 0) { Fail "闸2h：CLAUDE.md 在、但「经验铁律」小节标题漂移时 check 仍 exit 0——分节解析静默返回 0 条，封顶遂恒绿（夹具真实驻留 11 个 id，上限 10）：$driftOut" }
  elseif ($driftOut -notmatch '\[LESSONS-SECTION-NOT-FOUND\]') { Fail "闸2h：check 确实非零，但没打出 ASCII 哨兵 [LESSONS-SECTION-NOT-FOUND]——机检面必须是哨兵而非本地化文案（L165），且非零可能来自别的原因：$driftOut" }
  elseif ($tplDriftExit -eq 0 -or $tplDriftOut -notmatch '\[LESSONS-SECTION-NOT-FOUND\]') { Fail "闸2h(template)：CLAUDE.template.md 标题漂移未非零并给稳定哨兵。exit=$tplDriftExit output=[$tplDriftOut]" }
  elseif ($dupExit -eq 0 -or $dupOut -notmatch '\[LESSONS-DUPLICATE-RESIDENT-ID\].*CLAUDE\.md.*L1') { Fail "闸2h(duplicate)：CLAUDE.md 重复驻留 L1 未非零并给稳定哨兵/明细。exit=$dupExit output=[$dupOut]" }
  elseif ($tplDupExit -eq 0 -or $tplDupOut -notmatch '\[LESSONS-DUPLICATE-RESIDENT-ID\].*CLAUDE\.template\.md.*L1') { Fail "闸2h(template duplicate)：CLAUDE.template.md 重复驻留 L1 未非零并给稳定哨兵/明细。exit=$tplDupExit output=[$tplDupOut]" }
  else { Write-Host '  2h CLAUDE.md/template resident-id 分节漂移与重复 id 均 fail-closed OK' -ForegroundColor Green }
} finally {
  Remove-Item -Recurse -Force $l2hRepo -ErrorAction SilentlyContinue
}

# 2h2. 共享 resident parser 遵守受限 CommonMark：三种无序列表标记都计项；空行后的仓外段落/
# blockquote 不续进前一项；围栏代码里的标题、列表与 id 都只是正文诱饵。
$l2h2File = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2h2-$PID.md"
try {
  . (Join-Path $RepoRoot 'scripts/_lessons.ps1')
  $l2h2Text = @(
    '```markdown', '## 经验铁律（必须加载）', '- **[L900]** fenced decoy', '```',
    '## 经验铁律（必须加载 · fixture）',
    '* **[L901]** star item', '  lazy continuation [L902]',
    '+ **[L903]** plus item', '', 'outside paragraph [L904]', '> outside quote [L905]',
    '- **[L906]** dash item', '~~~text', '## fake heading', '- **[L907]** fenced decoy', '~~~',
    'outside after fence [L908]', '', '## 下一节'
  ) -join "`n"
  Set-Content $l2h2File $l2h2Text -Encoding utf8
  $l2h2 = Get-ScaffoldMustLayerSection -Path $l2h2File
  $l2h2Ids = @($l2h2.Ids) -join ','
  if (-not $l2h2.Found -or $l2h2.Bullets.Count -ne 3 -or $l2h2Ids -ne 'L901,L902,L903,L906') {
    Fail "闸2h2：resident parser 未守 CommonMark marker/boundary/fence；Found=$($l2h2.Found) Bullets=$($l2h2.Bullets.Count) Ids=$l2h2Ids"
  } else { Write-Host '  2h2 resident parser CommonMark marker/boundary/fence OK' -ForegroundColor Green }
} finally {
  Remove-Item $l2h2File -Force -ErrorAction SilentlyContinue
}

# 2g. T0-LESSONS-COLD-RECALL：选择器只把一次性 ledger 经验交给既有 archive.ps1；冷项仍可召回，
#     check 以热/冷 ID 并集判引用，bump/promote 对冷项只给移回热区指引。全程真跑生产 CLI，不复制搬运逻辑。
#     排除面逐条可杀：复发≥2 / tier=ondemand / tier=must / 当前最大 id / 被常驻 CLAUDE 文件引用（**三种形态**：
#     方括号 [L5]、裸写 L6、范围端点 L7–L8、模板侧裸写 L11）各配一条夹具，候选集按逐字相等断言；
#     两种「看着像引用但按契约不算」的否定形态（路径行号 x.ps1:L9、ASCII 行段 L10-13）另各配一条，
#     令判定式的两个否定组件也各自可被单点变异杀死。(g) 另证「引用判据本身缺席」时 fail-closed（卡片 A16）。
$l2gRepo = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2g-$PID"
if (Test-Path $l2gRepo) { Remove-Item -Recurse -Force $l2gRepo }
New-Item -ItemType Directory -Force $l2gRepo | Out-Null
try {
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2gRepo -Recurse -Force
  $l2gLessons = Join-Path $l2gRepo 'scripts/lessons.ps1'
  $l2gLedger = Join-Path $l2gRepo 'docs/lessons/LEDGER.md'
  $l2gArchive = Join-Path $l2gRepo 'specs/archive/lessons-archive.md'
  New-Item -ItemType Directory -Force (Split-Path $l2gLedger), (Split-Path $l2gArchive) | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $l2gRepo 'specs/tasks') | Out-Null
  $l2gTracker = Join-Path $l2gRepo 'specs/tech-debt-tracker.md'
  $l2gCard = Join-Path $l2gRepo 'specs/tasks/T-FIXTURE-MERGED.md'
  Set-Content $l2gTracker "| id | 状态 |`n|---|---|`n| TD-FIXTURE | paid |" -Encoding utf8
  Set-Content $l2gCard "---`nid: T-FIXTURE-MERGED`ntitle: unrelated merged card`nstatus: merged`n---" -Encoding utf8
  $entry2g = {
    param([string]$Id, [string]$Tier, [int]$Recurrence, [string]$Token)
    @(
      "## $Id",
      "- date: 2026-08-21 ｜ tags: fixture ｜ tier: $Tier ｜ kind: pitfall ｜ severity: minor ｜ recurrence: $Recurrence",
      "- symptom: $Token", "- rule: rule-$Token"
    ) -join "`n"
  }
  $getLessonBlock2g = {
    param([string]$Text, [string]$Id)
    $match = [regex]::Match($Text, "(?ms)^##[ \t]+$([regex]::Escape($Id))[ \t]*\r?$.*?(?=^##[ \t]+|\z)")
    if (-not $match.Success) { return '' }
    return (($match.Value -replace "`r`n", "`n").TrimEnd("`r", "`n"))
  }
  $l2gLedgerText = @(
    '# fixture ledger',
    (& $entry2g L1 ledger 1 'COLD_RECALL_ONLY'),
    (& $entry2g L2 ledger 2 'RECURRENT_EXCLUDED'),
    (& $entry2g L3 ondemand 1 'ONDEMAND_EXCLUDED'),
    (& $entry2g L4 must 1 'MUST_EXCLUDED'),
    (& $entry2g L5 ledger 1 'CLAUDE_BRACKET_REF_EXCLUDED'),
    (& $entry2g L6 ledger 1 'CLAUDE_BARE_REF_EXCLUDED'),
    (& $entry2g L7 ledger 1 'CLAUDE_RANGE_LEFT_EXCLUDED'),
    (& $entry2g L8 ledger 1 'CLAUDE_RANGE_RIGHT_EXCLUDED'),
    (& $entry2g L9 ledger 1 'PATH_LINE_NUMBER_NOT_A_REF'),
    (& $entry2g L10 ledger 1 'ASCII_HYPHEN_RANGE_NOT_A_REF'),
    (& $entry2g L11 ledger 1 'TEMPLATE_BARE_REF_EXCLUDED'),
    (& $entry2g L12 ledger 1 'MAX_ID_EXCLUDED')
  ) -join "`n`n"
  Set-Content $l2gLedger $l2gLedgerText -Encoding utf8
  # 常驻引用的**三种真实形态**都要在夹具里（F1 的病根正是实现只认第一种，而本仓 CLAUDE.md 绝大多数是第二种）：
  #   ① 方括号 [L5]  ② 裸写「按 L6 之理」  ③ 范围简写 L7–L8。EN DASH 按 L193 用码位拼出、不直接敲——它与
  # ASCII 连字符肉眼几乎一样，而在引用正则里行为相反（`L52-71` 是行段须排除，`L7–L8` 两端点须保护）。
  # 范围简写不保护中间 id，该限制写在 docs/LESSONS.md §3，不靠这里的沉默表达。
  # 另有**两种「看着像引用、按契约不算」**的形态（L9 / L10），它们让判定式的另两个组件各自可被单点变异杀死：
  #   ④ `scripts/x.ps1:L9` 冒号前缀 = 代码行号 → 删掉 `(?<![A-Za-z0-9:])` 后 L9 会被误判为受保护、退出候选集；
  #   ⑤ `L10-13` ASCII 连字符 = 行段 → 删掉 `(?!-\d)` 后 L10 同样会被误判受保护。
  # 判定式如今全仓只有一份字面量（在 lessons.ps1），故两边不会分歧——但「组件是否还在」仍须由这里的候选集变红来证明。
  $enDash2g = [string][char]0x2013
  $tier1Head2g = "## 经验铁律（必须加载）`n- **[L4] must fixture**`n`n## refs`n"
  # `${名}` 包裹不是洁癖：CJK 在 PowerShell 里是合法变量名字符，`"$tier1Head2g模板侧…"` 会被当成一个变量名。
  Set-Content (Join-Path $l2gRepo 'CLAUDE.md') "${tier1Head2g}[L5] 方括号引用`n按 L6 之理（裸引用，本仓最常见）`n范围简写 L7${enDash2g}L8（两端点均须受保护）`n行号写法 scripts/x.ps1:L9（冒号前缀=源码行号，不算引用）`n行段写法 L10-13（ASCII 连字符=行段，不算引用）" -Encoding utf8
  Set-Content (Join-Path $l2gRepo 'CLAUDE.template.md') "${tier1Head2g}模板侧裸引用 L11" -Encoding utf8

  # Fail 只置位不中断，故绿字必须挂在**本闸自己的**失败位上（独立的 $g2Fail）：否则 (a)–(e) 全红、
  # (f) 恰好绿时，最后一句 if/else 的 else 分支照样打印「2g … OK」。
  $g2Fail = $false

  # Duplicate hot IDs destroy block identity when the selector sends only an ID to archive.ps1. Cover all
  # ambiguous shapes: excluded+eligible, byte-identical eligible blocks, and different eligible blocks.
  $duplicateCases2g = @(
    @{ Name='mixed'; Blocks=@((& $entry2g L1 ondemand 1 'EXCLUDED-FIRST'), (& $entry2g L1 ledger 1 'ELIGIBLE-SECOND')) },
    @{ Name='identical'; Blocks=@((& $entry2g L1 ledger 1 'SAME'), (& $entry2g L1 ledger 1 'SAME')) },
    @{ Name='different'; Blocks=@((& $entry2g L1 ledger 1 'FIRST'), (& $entry2g L1 ledger 1 'SECOND')) }
  )
  foreach ($duplicateCase2g in $duplicateCases2g) {
    $dupRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2g-dup-$($duplicateCase2g.Name)-$PID"
    if (Test-Path $dupRepo2g) { Remove-Item -Recurse -Force -LiteralPath $dupRepo2g }
    New-Item -ItemType Directory -Force (Join-Path $dupRepo2g 'docs/lessons'), (Join-Path $dupRepo2g 'specs/archive') | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $dupRepo2g -Recurse -Force
    $dupLedger2g = Join-Path $dupRepo2g 'docs/lessons/LEDGER.md'
    $dupArchive2g = Join-Path $dupRepo2g 'specs/archive/lessons-archive.md'
    Set-Content (Join-Path $dupRepo2g 'CLAUDE.md') 'resident source present; no lesson references' -Encoding utf8
    Set-Content $dupLedger2g ((@('# fixture ledger') + $duplicateCase2g.Blocks + @((& $entry2g L2 ledger 1 'MAX'))) -join "`n`n") -Encoding utf8
    Set-Content $dupArchive2g '# archive' -Encoding utf8
    $dupHotHash2g = (Get-FileHash $dupLedger2g -Algorithm SHA256).Hash
    $dupColdHash2g = (Get-FileHash $dupArchive2g -Algorithm SHA256).Hash
    $dupOut2g = (& pwsh -NoProfile -File (Join-Path $dupRepo2g 'scripts/lessons.ps1') archive -RepoRoot $dupRepo2g 2>&1 | Out-String)
    $dupExit2g = $LASTEXITCODE
    if ($dupExit2g -eq 0 -or $dupOut2g -notmatch '\[LSN-DUPLICATE-HOT-ID\]' -or $dupOut2g -match 'candidates=') {
      Fail "闸2g(duplicate/$($duplicateCase2g.Name))：重复热 id 未在选择候选前 fail-closed。output=[$dupOut2g]"; $g2Fail = $true
    }
    if ((Get-FileHash $dupLedger2g -Algorithm SHA256).Hash -ne $dupHotHash2g -or
        (Get-FileHash $dupArchive2g -Algorithm SHA256).Hash -ne $dupColdHash2g) {
      Fail "闸2g(duplicate/$($duplicateCase2g.Name))：重复热 id 拒绝路径改写了热账本或冷库。"; $g2Fail = $true
    }
    Remove-Item -Recurse -Force -LiteralPath $dupRepo2g -ErrorAction SilentlyContinue
  }

  $ledgerHash2g = (Get-FileHash $l2gLedger -Algorithm SHA256).Hash
  $trackerHash2g = (Get-FileHash $l2gTracker -Algorithm SHA256).Hash
  $cardHash2g = (Get-FileHash $l2gCard -Algorithm SHA256).Hash
  $dry2g = (& pwsh -NoProfile -File $l2gLessons archive -RepoRoot $l2gRepo -DryRun 2>&1 | Out-String)
  $dryExit2g = $LASTEXITCODE
  # 候选集**逐字相等**，不是「整份 stdout 里出现过 L1」：后者被任何一行无关告警满足，而这里判的是「哪些条目
  # 会被移出热账本」——数据搬运面上，宽于契约的断言等于没有断言（L165）。逐字相等同时钉住两个方向：
  # 排除面（L2/L3/L4/L5/L6/L7/L8/L11/L12）一个都不许进候选，而「看着像引用但不算」的 L9/L10 一个都不许被漏掉。
  $cand2g = ([regex]::Match($dry2g, '\[LSN-ARCHIVE-DRYRUN\]\s*candidates=(?<c>\S+)')).Groups['c'].Value
  if ($dryExit2g -ne 0) { Fail "闸2g(a)：archive -DryRun 对合法夹具非零退出（$dryExit2g）。output=[$dry2g]"; $g2Fail = $true }
  elseif ($cand2g -ne 'L1,L9,L10') { Fail "闸2g(a)：候选集应恰为 L1,L9,L10，实得『$cand2g』——tier/复发/最大 id/常驻引用四类排除面之一失效，或引用判定式的「路径行号」「ASCII 行段」两个否定组件之一被删（那会把 L9/L10 误判成受保护）。output=[$dry2g]"; $g2Fail = $true }
  if ((Get-FileHash $l2gLedger -Algorithm SHA256).Hash -ne $ledgerHash2g -or (Test-Path $l2gArchive) -or
      (Get-FileHash $l2gTracker -Algorithm SHA256).Hash -ne $trackerHash2g -or (Get-FileHash $l2gCard -Algorithm SHA256).Hash -ne $cardHash2g) {
    Fail '闸2g(a)：archive -DryRun 写了 lesson 或旁域 tracker/card（预览必须零写入）。'; $g2Fail = $true
  }

  # (a2) 单一真相源的**接线**证明：判定式本身如今只有一份字面量（lessons.ps1 的 $LessonRefRegex，闸 16 从其源码
  #   抽取复用），所以这里测的不再是「两份副本是否一致」，而是「选择器的排除面真的走了那份判定式」——
  #   若 Get-ResidentLessonRefs 里改回内联 `'\[(L\d+)\]'`，裸引用与范围端点会掉进候选集，而闸 16 侧不变 → 分歧 → 红。
  #   比较范围收敛到「只可能因被引用而落选」的那组（tier=ledger、recurrence=1、非最大 id），把另三类排除面剔干净。
  $refEligible2g = @('L1','L5','L6','L7','L8','L9','L10','L11')
  $residentText2g = (Get-Content (Join-Path $l2gRepo 'CLAUDE.md') -Raw) + "`n" + (Get-Content (Join-Path $l2gRepo 'CLAUDE.template.md') -Raw)
  $gate16Refs2g = Get-LessonReferenceIdSet $residentText2g
  $gate16Set2g = (@($refEligible2g | Where-Object { $gate16Refs2g.ContainsKey($_) }) -join ',')
  $selectorSet2g = (@($refEligible2g | Where-Object { @($cand2g -split ',') -notcontains $_ }) -join ',')
  if ($gate16Set2g -ne $selectorSet2g) {
    Fail "闸2g(a2)：常驻引用判定出现第二套权威——闸16 判定被引用=[$gate16Set2g]，lessons.ps1 选择器判定被引用=[$selectorSet2g]。两者须逐条相等（本仓引用多为裸写，只认 [Lnn] 会把常驻文件正在引用的条目搬进冷库）。"; $g2Fail = $true
  }

  $run2g = (& pwsh -NoProfile -File $l2gLessons archive -RepoRoot $l2gRepo 2>&1 | Out-String)
  $runExit2g = $LASTEXITCODE
  $ledgerAfter2g = Get-Content $l2gLedger -Raw
  $archiveAfter2g = if (Test-Path $l2gArchive) { Get-Content $l2gArchive -Raw } else { '' }
  $movedExpect2g = @('L1', 'L9', 'L10')
  $moveFail2g = ($runExit2g -ne 0)
  foreach ($moved2g in $movedExpect2g) {
    if ($ledgerAfter2g -match "(?m)^##[ \t]+$moved2g[ \t]*\r?$" -or $archiveAfter2g -notmatch "(?m)^##[ \t]+$moved2g[ \t]*\r?$") { $moveFail2g = $true }
  }
  if ($moveFail2g) {
    Fail "闸2g(b)：实际 archive 未经既有搬运器把 $($movedExpect2g -join ',') 全部从热账本移入冷库。exit=$runExit2g output=[$run2g]"; $g2Fail = $true
  }
  foreach ($kept2g in @('L2','L3','L4','L5','L6','L7','L8','L11','L12')) {
    if ($ledgerAfter2g -notmatch "(?m)^##[ \t]+$kept2g[ \t]*\r?$") { Fail "闸2g(b)：排除项 $kept2g 被误搬（实跑后已不在 LEDGER）。"; $g2Fail = $true }
  }
  if ((Get-FileHash $l2gTracker -Algorithm SHA256).Hash -ne $trackerHash2g -or
      (Get-FileHash $l2gCard -Algorithm SHA256).Hash -ne $cardHash2g -or
      (Test-Path (Join-Path $l2gRepo 'specs/archive/tasks/T-FIXTURE-MERGED.md'))) {
    Fail '闸2g(b)：lesson 实际归档越界改写了 tracker/card；必须使用 archive.ps1 的 lesson-only 模式。'; $g2Fail = $true
  }

  $search2g = (& pwsh -NoProfile -File $l2gLessons search COLD_RECALL_ONLY -RepoRoot $l2gRepo 2>&1 | Out-String)
  if ($LASTEXITCODE -ne 0 -or $search2g -notmatch '\[archived\].*L1') { Fail "闸2g(c)：冷项 search 未以 [archived] 标记召回 L1。output=[$search2g]"; $g2Fail = $true }
  Add-Content (Join-Path $l2gRepo 'CLAUDE.md') "`n归档后新增引用 [L1]" -Encoding utf8
  $check2g = (& pwsh -NoProfile -File $l2gLessons check -RepoRoot $l2gRepo 2>&1 | Out-String)
  if ($LASTEXITCODE -ne 0 -or $check2g -notmatch 'check: PASS') { Fail "闸2g(d)：check 未以热/冷 ID 并集接受 CLAUDE 对已归档 L1 的定义。output=[$check2g]"; $g2Fail = $true }

  foreach ($writeCommand2g in @('bump','promote')) {
    $write2g = (& pwsh -NoProfile -File $l2gLessons $writeCommand2g L1 -RepoRoot $l2gRepo 2>&1 | Out-String)
    if ($LASTEXITCODE -eq 0 -or $write2g -notmatch '\[LSN-ARCHIVED-READONLY\]' -or $write2g -notmatch 'RestoreLessonIds') {
      Fail "闸2g(e)：$writeCommand2g 冷项 L1 未 fail-closed 并给出可执行的 -RestoreLessonIds 修法。output=[$write2g]"; $g2Fail = $true
    }
  }

  # (e1) 提示里的恢复命令必须真的完成冷→热移动，而不是复制后留下冷热重复、令 bump/promote 继续拒绝。
  $expectedRestoreBlock2g = (& $entry2g L1 ledger 1 'COLD_RECALL_ONLY')
  $tokenCountBeforeRestore2g = ([regex]::Matches("$(Get-Content $l2gLedger -Raw)`n$(Get-Content $l2gArchive -Raw)", 'COLD_RECALL_ONLY')).Count
  $restore2g = (& pwsh -NoProfile -File (Join-Path $l2gRepo 'scripts/archive.ps1') -RepoRoot $l2gRepo -LessonsOnly -RestoreLessonIds L1 2>&1 | Out-String)
  $restoreExit2g = $LASTEXITCODE
  $hotAfterRestore2g = Get-Content $l2gLedger -Raw
  $coldAfterRestore2g = Get-Content $l2gArchive -Raw
  $tokenCount2g = ([regex]::Matches("$hotAfterRestore2g`n$coldAfterRestore2g", 'COLD_RECALL_ONLY')).Count
  $actualRestoreBlock2g = & $getLessonBlock2g $hotAfterRestore2g L1
  if ($restoreExit2g -ne 0 -or ([regex]::Matches($hotAfterRestore2g, '(?m)^##[ \t]+L1[ \t]*\r?$')).Count -ne 1 -or
      $coldAfterRestore2g -match '(?m)^##[ \t]+L1[ \t]*\r?$' -or $tokenCount2g -ne $tokenCountBeforeRestore2g) {
    Fail "闸2g(e1)：-RestoreLessonIds L1 未完成无损冷→热移动（exit=$restoreExit2g，token-count=$tokenCount2g，before=$tokenCountBeforeRestore2g）。output=[$restore2g]"; $g2Fail = $true
  }
  if ($actualRestoreBlock2g -cne $expectedRestoreBlock2g) {
    Fail "闸2g(e1)：恢复后的 L1 整块与归档前字节内容不相等（完整块断言失败）。actual=[$actualRestoreBlock2g] expected=[$expectedRestoreBlock2g]"; $g2Fail = $true
  }
  foreach ($usableCommand2g in @('bump','promote')) {
    $usable2g = (& pwsh -NoProfile -File $l2gLessons $usableCommand2g L1 -RepoRoot $l2gRepo 2>&1 | Out-String)
    if ($LASTEXITCODE -ne 0 -or $usable2g -match '\[LSN-ARCHIVED-READONLY\]') {
      Fail "闸2g(e1)：按提示恢复后 $usableCommand2g L1 仍不可用。output=[$usable2g]"; $g2Fail = $true
    }
  }

  # (e2) 恢复态可能暂时冷热两侧同时存在同一条目。promote 是只读决策，但仍不得优先采用热副本、
  # 把「已归冷」事实藏掉后给出晋升建议；两侧任一命中冷库就必须先要求人工移回并消歧。
  $bothRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2ge2-$PID"
  if (Test-Path $bothRepo2g) { Remove-Item -Recurse -Force -LiteralPath $bothRepo2g }
  New-Item -ItemType Directory -Force (Join-Path $bothRepo2g 'docs/lessons'), (Join-Path $bothRepo2g 'specs/archive') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $bothRepo2g -Recurse -Force
  $bothBlock2g = @('## L1', '- date: 2026-08-24 ｜ tags: t ｜ tier: ledger ｜ severity: minor ｜ recurrence: 1', '- symptom: s', '- root_cause: rc', '- rule: r', '- refs:') -join [Environment]::NewLine
  $bothLedger2g = Join-Path $bothRepo2g 'docs/lessons/LEDGER.md'
  $bothArchive2g = Join-Path $bothRepo2g 'specs/archive/lessons-archive.md'
  Set-Content $bothLedger2g (@('# LEDGER', '', $bothBlock2g) -join [Environment]::NewLine) -Encoding utf8
  Set-Content $bothArchive2g (@('# archive', '', $bothBlock2g) -join [Environment]::NewLine) -Encoding utf8
  $bothHotHash2g = (Get-FileHash $bothLedger2g -Algorithm SHA256).Hash
  $bothColdHash2g = (Get-FileHash $bothArchive2g -Algorithm SHA256).Hash
  $bothOut2g = (& pwsh -NoProfile -File (Join-Path $bothRepo2g 'scripts/lessons.ps1') promote L1 -RepoRoot $bothRepo2g 2>&1 | Out-String)
  $bothExit2g = $LASTEXITCODE
  if ($bothExit2g -eq 0 -or $bothOut2g -notmatch '\[LSN-ARCHIVED-READONLY\]') {
    Fail "闸2g(e2)：冷热两侧同时存在 L1 时 promote 仍采用热副本并退出 0。output=[$bothOut2g]"; $g2Fail = $true
  }
  if ((Get-FileHash $bothLedger2g -Algorithm SHA256).Hash -ne $bothHotHash2g -or
      (Get-FileHash $bothArchive2g -Algorithm SHA256).Hash -ne $bothColdHash2g) {
    Fail '闸2g(e2)：promote 的冷热并存拒绝路径改写了热账本或冷库。'; $g2Fail = $true
  }
  Remove-Item -Recurse -Force -LiteralPath $bothRepo2g -ErrorAction SilentlyContinue

  # (e3) 恢复器按 id 移动，任一侧重复 id 都让块身份不唯一。必须在取 [0] 之前拒绝，且双侧零写入。
  $restoreDupBlock2g = (& $entry2g L1 ledger 1 'RESTORE_DUPLICATE')
  $restoreDupCases2g = @(
    @{ Name = 'hot'; Hot = @($restoreDupBlock2g, $restoreDupBlock2g); Cold = @($restoreDupBlock2g) },
    @{ Name = 'cold'; Hot = @(); Cold = @($restoreDupBlock2g, $restoreDupBlock2g) }
  )
  foreach ($restoreDupCase2g in $restoreDupCases2g) {
    $restoreDupRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2ge3-$($restoreDupCase2g.Name)-$PID"
    if (Test-Path $restoreDupRepo2g) { Remove-Item -Recurse -Force -LiteralPath $restoreDupRepo2g }
    New-Item -ItemType Directory -Force (Join-Path $restoreDupRepo2g 'docs/lessons'), (Join-Path $restoreDupRepo2g 'specs/archive') | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $restoreDupRepo2g -Recurse -Force
    $restoreDupLedger2g = Join-Path $restoreDupRepo2g 'docs/lessons/LEDGER.md'
    $restoreDupArchive2g = Join-Path $restoreDupRepo2g 'specs/archive/lessons-archive.md'
    Set-Content $restoreDupLedger2g ((@('# ledger') + $restoreDupCase2g.Hot) -join "`n`n") -Encoding utf8
    Set-Content $restoreDupArchive2g ((@('# archive') + $restoreDupCase2g.Cold) -join "`n`n") -Encoding utf8
    $restoreDupHotHash2g = (Get-FileHash $restoreDupLedger2g -Algorithm SHA256).Hash
    $restoreDupColdHash2g = (Get-FileHash $restoreDupArchive2g -Algorithm SHA256).Hash
    $restoreDupOut2g = (& pwsh -NoProfile -File (Join-Path $restoreDupRepo2g 'scripts/archive.ps1') -RepoRoot $restoreDupRepo2g -LessonsOnly -RestoreLessonIds L1 2>&1 | Out-String)
    $restoreDupExit2g = $LASTEXITCODE
    if ($restoreDupExit2g -eq 0 -or $restoreDupOut2g -notmatch '\[ARCHIVE-LESSON-REJECT-DUPLICATE\]') {
      Fail "闸2g(e3/$($restoreDupCase2g.Name))：恢复器未拒绝重复 id。output=[$restoreDupOut2g]"; $g2Fail = $true
    }
    if ((Get-FileHash $restoreDupLedger2g -Algorithm SHA256).Hash -ne $restoreDupHotHash2g -or
        (Get-FileHash $restoreDupArchive2g -Algorithm SHA256).Hash -ne $restoreDupColdHash2g) {
      Fail "闸2g(e3/$($restoreDupCase2g.Name))：重复 id 拒绝路径改写了热账本或冷库。"; $g2Fail = $true
    }
    Remove-Item -Recurse -Force -LiteralPath $restoreDupRepo2g -ErrorAction SilentlyContinue
  }

  # (e4) 恢复方向的两个原子写失败分支：热侧暂存失败须双侧不变；冷侧暂存失败须留下逐字一致的
  # 双侧态，清除注入后重跑只删除冷副本，热侧完整块与失败后 hash 均保持不变。
  foreach ($restoreFailureSide2g in @('ledger', 'archive')) {
    $restoreFailRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2ge4-$restoreFailureSide2g-$PID"
    if (Test-Path $restoreFailRepo2g) { Remove-Item -Recurse -Force -LiteralPath $restoreFailRepo2g }
    New-Item -ItemType Directory -Force (Join-Path $restoreFailRepo2g 'docs/lessons'), (Join-Path $restoreFailRepo2g 'specs/archive') | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $restoreFailRepo2g -Recurse -Force
    $restoreFailLedger2g = Join-Path $restoreFailRepo2g 'docs/lessons/LEDGER.md'
    $restoreFailArchive2g = Join-Path $restoreFailRepo2g 'specs/archive/lessons-archive.md'
    $restoreFailBlock2g = (& $entry2g L1 ledger 1 "RESTORE_FAILURE_$($restoreFailureSide2g.ToUpperInvariant())")
    Set-Content $restoreFailLedger2g '# ledger' -Encoding utf8
    Set-Content $restoreFailArchive2g (@('# archive', '', $restoreFailBlock2g) -join "`n") -Encoding utf8
    $restoreFailHotBefore2g = (Get-FileHash $restoreFailLedger2g -Algorithm SHA256).Hash
    $restoreFailColdBefore2g = (Get-FileHash $restoreFailArchive2g -Algorithm SHA256).Hash
    $blockedTmp2g = if ($restoreFailureSide2g -eq 'ledger') { "$restoreFailLedger2g.tmp" } else { "$restoreFailArchive2g.tmp" }
    New-Item -ItemType Directory -Force $blockedTmp2g | Out-Null
    $restoreFailOut2g = (& pwsh -NoProfile -File (Join-Path $restoreFailRepo2g 'scripts/archive.ps1') -RepoRoot $restoreFailRepo2g -LessonsOnly -RestoreLessonIds L1 2>&1 | Out-String)
    $restoreFailExit2g = $LASTEXITCODE
    Remove-Item -Recurse -Force -LiteralPath $blockedTmp2g -ErrorAction SilentlyContinue
    $restoreFailHotAfter2g = (Get-FileHash $restoreFailLedger2g -Algorithm SHA256).Hash
    $restoreFailColdAfter2g = (Get-FileHash $restoreFailArchive2g -Algorithm SHA256).Hash
    if ($restoreFailExit2g -eq 0) { Fail "闸2g(e4/$restoreFailureSide2g)：恢复暂存写失败仍 exit 0。output=[$restoreFailOut2g]"; $g2Fail = $true }
    if ($restoreFailColdAfter2g -ne $restoreFailColdBefore2g) { Fail "闸2g(e4/$restoreFailureSide2g)：失败路径改写了冷库。"; $g2Fail = $true }
    if ($restoreFailureSide2g -eq 'ledger') {
      if ($restoreFailHotAfter2g -ne $restoreFailHotBefore2g) { Fail '闸2g(e4/ledger)：热账本暂存失败仍改写了热账本。'; $g2Fail = $true }
    } else {
      $restoreFailHotBlock2g = & $getLessonBlock2g (Get-Content $restoreFailLedger2g -Raw) L1
      $restoreFailColdBlock2g = & $getLessonBlock2g (Get-Content $restoreFailArchive2g -Raw) L1
      if ($restoreFailHotAfter2g -eq $restoreFailHotBefore2g -or $restoreFailHotBlock2g -cne $restoreFailBlock2g -or $restoreFailColdBlock2g -cne $restoreFailBlock2g) {
        Fail '闸2g(e4/archive)：冷侧暂存失败后未留下两侧逐字一致的完整块。'; $g2Fail = $true
      }
      $restoreHealOut2g = (& pwsh -NoProfile -File (Join-Path $restoreFailRepo2g 'scripts/archive.ps1') -RepoRoot $restoreFailRepo2g -LessonsOnly -RestoreLessonIds L1 2>&1 | Out-String)
      $restoreHealExit2g = $LASTEXITCODE
      if ($restoreHealExit2g -ne 0 -or (Get-FileHash $restoreFailLedger2g -Algorithm SHA256).Hash -ne $restoreFailHotAfter2g -or
          (Get-Content $restoreFailArchive2g -Raw) -match '(?m)^##[ \t]+L1[ \t]*\r?$' -or
          (& $getLessonBlock2g (Get-Content $restoreFailLedger2g -Raw) L1) -cne $restoreFailBlock2g) {
        Fail "闸2g(e4/archive)：清除故障注入后重跑未从两侧一致态自愈。output=[$restoreHealOut2g]"; $g2Fail = $true
      }
    }
    Remove-Item -Recurse -Force -LiteralPath $restoreFailRepo2g -ErrorAction SilentlyContinue
  }

  # (e5) 双侧自愈只接受逐字一致。PowerShell 的 -ne 默认不区分大小写，TrimEnd() 又会吞掉正文尾空格；
  # 两者都会把真实冲突误判成相同并删除一侧。归档/恢复两个方向、case-only/trailing-space 两类都须拒绝且零写入。
  foreach ($exactDirection2g in @('archive', 'restore')) {
    foreach ($exactVariant2g in @('case-only', 'trailing-space')) {
      $exactRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2ge5-$exactDirection2g-$exactVariant2g-$PID"
      if (Test-Path $exactRepo2g) { Remove-Item -Recurse -Force -LiteralPath $exactRepo2g }
      New-Item -ItemType Directory -Force (Join-Path $exactRepo2g 'docs/lessons'), (Join-Path $exactRepo2g 'specs/archive') | Out-Null
      Copy-Item (Join-Path $RepoRoot 'scripts') $exactRepo2g -Recurse -Force
      $exactLedger2g = Join-Path $exactRepo2g 'docs/lessons/LEDGER.md'
      $exactArchive2g = Join-Path $exactRepo2g 'specs/archive/lessons-archive.md'
      $exactMeta2g = '- date: 2026-08-24 ｜ tags: t ｜ tier: ledger ｜ severity: minor ｜ recurrence: 1'
      $exactHotRule2g = if ($exactVariant2g -eq 'case-only') { '- rule: CaseSensitiveRule' } else { '- rule: trailing-sensitive' }
      $exactColdRule2g = if ($exactVariant2g -eq 'case-only') { '- rule: casesensitiverule' } else { '- rule: trailing-sensitive' }
      $exactHotRefs2g = '- refs:'
      $exactColdRefs2g = if ($exactVariant2g -eq 'trailing-space') { '- refs: ' } else { '- refs:' }
      $exactHotBlock2g = @('## L1', $exactMeta2g, '- symptom: s', '- root_cause: rc', $exactHotRule2g, $exactHotRefs2g)
      $exactColdBlock2g = @('## L1', $exactMeta2g, '- symptom: s', '- root_cause: rc', $exactColdRule2g, $exactColdRefs2g)
      # L2 keeps L1 eligible for the archive direction; it is outside the compared L1 block.
      $exactSentinel2g = @('## L2', $exactMeta2g, '- symptom: sentinel', '- root_cause: rc', '- rule: highest-id', '- refs:')
      Set-Content $exactLedger2g ((@('# ledger', '') + $exactHotBlock2g + @('') + $exactSentinel2g) -join "`n") -Encoding utf8
      Set-Content $exactArchive2g ((@('# archive', '') + $exactColdBlock2g) -join "`n") -Encoding utf8
      $exactHotHash2g = (Get-FileHash $exactLedger2g -Algorithm SHA256).Hash
      $exactColdHash2g = (Get-FileHash $exactArchive2g -Algorithm SHA256).Hash
      $exactArgs2g = if ($exactDirection2g -eq 'restore') { @('-RestoreLessonIds', 'L1') } else { @('-LessonIds', 'L1') }
      $exactOut2g = (& pwsh -NoProfile -File (Join-Path $exactRepo2g 'scripts/archive.ps1') -RepoRoot $exactRepo2g -LessonsOnly @exactArgs2g 2>&1 | Out-String)
      $exactExit2g = $LASTEXITCODE
      if ($exactExit2g -eq 0 -or $exactOut2g -notmatch '\[ARCHIVE-LESSON-REJECT-CONFLICT\]') {
        Fail "闸2g(e5/$exactDirection2g/$exactVariant2g)：逐字冲突未以 [ARCHIVE-LESSON-REJECT-CONFLICT] fail-closed。output=[$exactOut2g]"; $g2Fail = $true
      }
      if ((Get-FileHash $exactLedger2g -Algorithm SHA256).Hash -ne $exactHotHash2g -or
          (Get-FileHash $exactArchive2g -Algorithm SHA256).Hash -ne $exactColdHash2g) {
        Fail "闸2g(e5/$exactDirection2g/$exactVariant2g)：冲突拒绝路径改写了热账本或冷库。"; $g2Fail = $true
      }
      Remove-Item -Recurse -Force -LiteralPath $exactRepo2g -ErrorAction SilentlyContinue
    }
  }

  # (e6) 多 id 的恢复顺序必须由源文件决定，而不是由调用者的参数顺序决定。反向传 L2,L1，并让第二个
  # 原子替换失败，先制造两侧并存；清除注入后用同一反向参数重试，归档/恢复两个方向都必须自愈。
  foreach ($batchDirection2g in @('archive', 'restore')) {
    $batchRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2ge6-$batchDirection2g-$PID"
    if (Test-Path $batchRepo2g) { Remove-Item -Recurse -Force -LiteralPath $batchRepo2g }
    New-Item -ItemType Directory -Force (Join-Path $batchRepo2g 'docs/lessons'), (Join-Path $batchRepo2g 'specs/archive') | Out-Null
    Copy-Item (Join-Path $RepoRoot 'scripts') $batchRepo2g -Recurse -Force
    $batchLedger2g = Join-Path $batchRepo2g 'docs/lessons/LEDGER.md'
    $batchArchive2g = Join-Path $batchRepo2g 'specs/archive/lessons-archive.md'
    $batchL12g = (& $entry2g L1 ledger 1 'BATCH_FIRST')
    $batchL22g = (& $entry2g L2 ledger 1 'BATCH_SECOND')
    $batchL32g = (& $entry2g L3 ledger 1 'BATCH_MAX_SENTINEL')
    if ($batchDirection2g -eq 'archive') {
      Set-Content $batchLedger2g ((@('# ledger', $batchL12g, $batchL22g, $batchL32g)) -join "`n`n") -Encoding utf8
      Set-Content $batchArchive2g '# archive' -Encoding utf8
      $batchArgs2g = @('-LessonIds', 'L2,L1')
      $batchBlockedTmp2g = "$batchLedger2g.tmp"
    } else {
      Set-Content $batchLedger2g '# ledger' -Encoding utf8
      Set-Content $batchArchive2g ((@('# archive', $batchL12g, $batchL22g)) -join "`n`n") -Encoding utf8
      $batchArgs2g = @('-RestoreLessonIds', 'L2,L1')
      $batchBlockedTmp2g = "$batchArchive2g.tmp"
    }
    New-Item -ItemType Directory -Force $batchBlockedTmp2g | Out-Null
    $batchFailOut2g = (& pwsh -NoProfile -File (Join-Path $batchRepo2g 'scripts/archive.ps1') -RepoRoot $batchRepo2g -LessonsOnly @batchArgs2g 2>&1 | Out-String)
    $batchFailExit2g = $LASTEXITCODE
    Remove-Item -Recurse -Force -LiteralPath $batchBlockedTmp2g -ErrorAction SilentlyContinue
    if ($batchFailExit2g -eq 0) {
      Fail "闸2g(e6/$batchDirection2g)：第二个原子替换失败仍 exit 0。output=[$batchFailOut2g]"; $g2Fail = $true
    }
    $batchHealOut2g = (& pwsh -NoProfile -File (Join-Path $batchRepo2g 'scripts/archive.ps1') -RepoRoot $batchRepo2g -LessonsOnly @batchArgs2g 2>&1 | Out-String)
    $batchHealExit2g = $LASTEXITCODE
    $batchHotText2g = Get-Content $batchLedger2g -Raw
    $batchColdText2g = Get-Content $batchArchive2g -Raw
    $batchDestinationText2g = if ($batchDirection2g -eq 'archive') { $batchColdText2g } else { $batchHotText2g }
    $batchSourceText2g = if ($batchDirection2g -eq 'archive') { $batchHotText2g } else { $batchColdText2g }
    $batchL1Pos2g = $batchDestinationText2g.IndexOf('## L1', [System.StringComparison]::Ordinal)
    $batchL2Pos2g = $batchDestinationText2g.IndexOf('## L2', [System.StringComparison]::Ordinal)
    if ($batchHealExit2g -ne 0 -or $batchHealOut2g -match '\[ARCHIVE-LESSON-REJECT-CONFLICT\]' -or
        $batchSourceText2g -match '(?m)^##[ \t]+L[12][ \t]*\r?$' -or
        $batchL1Pos2g -lt 0 -or $batchL2Pos2g -le $batchL1Pos2g -or
        (& $getLessonBlock2g $batchDestinationText2g L1) -cne $batchL12g -or
        (& $getLessonBlock2g $batchDestinationText2g L2) -cne $batchL22g) {
      Fail "闸2g(e6/$batchDirection2g)：反向双 id 的失败重试未按源顺序自愈。output=[$batchHealOut2g]"; $g2Fail = $true
    }
    Remove-Item -Recurse -Force -LiteralPath $batchRepo2g -ErrorAction SilentlyContinue
  }

  # 闸2g(f)：A11 的**生产路径**回归——真实 linked worktree，而不是非 git 临时目录。
  # 2g(e) 的夹具不是 git 仓库，Resolve-BumpLedger 因此回落到本地账本，冷项在本地热账本里本就不存在，
  # 于是命中「块没找到」分支顺带触发只读提示——**它测的根本不是 bump 会不会改主检出**。真实形态是：
  # 主检出的 LEDGER 里 Lx 仍是热的、本工作树已把它归冷；旧序的 bump 会命中块、照常改写、exit 0。
  # 修复前实测：exit 0、无哨兵、主检出 recurrence 3→4。
  $wtRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2gf-$PID"
  if (Test-Path $wtRepo2g) { Remove-Item -Recurse -Force -LiteralPath $wtRepo2g }
  $wtMain2g = Join-Path $wtRepo2g 'main'
  $wtLink2g = Join-Path $wtRepo2g 'wt'
  New-Item -ItemType Directory -Force (Join-Path $wtMain2g 'docs/lessons'), (Join-Path $wtMain2g 'specs/archive') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $wtMain2g -Recurse -Force
  $hotBlock2g = @('# LEDGER', '', '## L900', '- date: 2026-08-24 ｜ tags: t ｜ tier: ledger ｜ severity: minor ｜ recurrence: 3', '- symptom: s', '- root_cause: rc', '- rule: r', '- refs:') -join [Environment]::NewLine
  Set-Content (Join-Path $wtMain2g 'docs/lessons/LEDGER.md') $hotBlock2g -Encoding utf8
  Set-Content (Join-Path $wtMain2g 'specs/archive/lessons-archive.md') '# archive' -Encoding utf8
  Push-Location $wtMain2g
  & git init -q 2>&1 | Out-Null
  & git config user.email 'selftest@example.invalid' 2>&1 | Out-Null
  & git config user.name 'selftest' 2>&1 | Out-Null
  & git add -A 2>&1 | Out-Null
  & git -c commit.gpgsign=false commit -q -m fixture 2>&1 | Out-Null
  & git worktree add -q -b lessons2gf $wtLink2g 2>&1 | Out-Null
  $wtAddOk2g = ($LASTEXITCODE -eq 0)
  Pop-Location
  if (-not $wtAddOk2g) {
    Fail '闸2g(f)：无法建立 linked worktree 夹具——本闸判的就是 linked worktree 下的行为，建不起来即中止而非跳过。'
    $g2Fail = $true
  }
  else {
    Set-Content (Join-Path $wtLink2g 'docs/lessons/LEDGER.md') '# LEDGER' -Encoding utf8
    Set-Content (Join-Path $wtLink2g 'specs/archive/lessons-archive.md') ($hotBlock2g -replace '# LEDGER', '# archive') -Encoding utf8
    $mainLedger2g = Join-Path $wtMain2g 'docs/lessons/LEDGER.md'
    $hashBefore2g = (Get-FileHash $mainLedger2g -Algorithm SHA256).Hash
    Push-Location $wtLink2g
    $wtOut2g = (& pwsh -NoProfile -File (Join-Path $wtLink2g 'scripts/lessons.ps1') bump L900 2>&1 | Out-String)
    $wtExit2g = $LASTEXITCODE
    Pop-Location
    $hashAfter2g = (Get-FileHash $mainLedger2g -Algorithm SHA256).Hash
    if ($wtExit2g -eq 0) { Fail "闸2g(f)：linked worktree 里 bump 已归冷的 L900 退出 0（主检出该 id 仍热）——A11 的闸没拦住生产路径。output=[$wtOut2g]"; $g2Fail = $true }
    if ($wtOut2g -notmatch '\[LSN-ARCHIVED-READONLY\]') { Fail "闸2g(f)：未打出 [LSN-ARCHIVED-READONLY]——写入面与判据面分家（写主检出的账本，却只判本工作树的冷库）。output=[$wtOut2g]"; $g2Fail = $true }
    if ($hashBefore2g -ne $hashAfter2g) { Fail '闸2g(f)：主检出的 LEDGER 被改写——冷项 bump 必须零写入。'; $g2Fail = $true }
    Push-Location $wtMain2g
    & git worktree remove --force $wtLink2g 2>&1 | Out-Null
    Pop-Location
  }
  if (Test-Path $wtRepo2g) { Remove-Item -Recurse -Force -LiteralPath $wtRepo2g -ErrorAction SilentlyContinue }

  # 闸2g(g)：Int32 范围判据（旧写法用「位数 \d{1,9}」当范围代理，两头都错）。
  # ① 1000000000 是合法 Int32（10 位）却被位数上界拒；② bump 能把 999999999 加成 1000000000 写进去，
  # 下一次读又判它非法——写路径造出读路径拒绝的值。判据改为 [int]::TryParse，即范围本身。
  $intRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2gg-$PID"
  if (Test-Path $intRepo2g) { Remove-Item -Recurse -Force -LiteralPath $intRepo2g }
  New-Item -ItemType Directory -Force (Join-Path $intRepo2g 'docs/lessons'), (Join-Path $intRepo2g 'specs/archive') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $intRepo2g -Recurse -Force
  $intLessons2g = Join-Path $intRepo2g 'scripts/lessons.ps1'
  $intLedger2g = Join-Path $intRepo2g 'docs/lessons/LEDGER.md'
  Set-Content (Join-Path $intRepo2g 'specs/archive/lessons-archive.md') '# archive' -Encoding utf8
  $mk2g = {
    param([string]$Id, [string]$Rec)
    @("## $Id", "- date: 2026-08-24 ｜ tags: t ｜ tier: ledger ｜ severity: minor ｜ recurrence: $Rec", '- symptom: s', '- root_cause: rc', '- rule: r', '- refs:') -join [Environment]::NewLine
  }
  # (g1) 合法的 10 位 Int32 必须被接受——位数上界会误杀它
  Set-Content $intLedger2g (@('# LEDGER', '', (& $mk2g 'L1000000000' '1')) -join [Environment]::NewLine) -Encoding utf8
  $g1Out = (& pwsh -NoProfile -File $intLessons2g check -RepoRoot $intRepo2g 2>&1 | Out-String)
  if ($LASTEXITCODE -ne 0 -or $g1Out -notmatch 'check: PASS') { Fail "闸2g(g1)：合法 Int32 值 L1000000000（10 位）被判非法——位数不是范围判据。output=[$g1Out]"; $g2Fail = $true }
  # (g2) Int32.MaxValue+1 必须被拒（读路径 fail-closed）
  Set-Content $intLedger2g (@('# LEDGER', '', (& $mk2g 'L901' '2147483648')) -join [Environment]::NewLine) -Encoding utf8
  $g2Out = (& pwsh -NoProfile -File $intLessons2g check -RepoRoot $intRepo2g 2>&1 | Out-String)
  if ($LASTEXITCODE -eq 0) { Fail "闸2g(g2)：recurrence 2147483648 超 Int32 却被接受——溢出会让下游 [int] 抛裸异常。output=[$g2Out]"; $g2Fail = $true }
  # (g3) bump 到 Int32 上限必须 fail-closed 且零写入（否则写出读路径拒绝的值）
  Set-Content $intLedger2g (@('# LEDGER', '', (& $mk2g 'L902' '2147483647')) -join [Environment]::NewLine) -Encoding utf8
  $g3Hash = (Get-FileHash $intLedger2g -Algorithm SHA256).Hash
  $g3Out = (& pwsh -NoProfile -File $intLessons2g bump L902 -RepoRoot $intRepo2g 2>&1 | Out-String)
  $g3Exit = $LASTEXITCODE
  if ($g3Exit -eq 0) { Fail "闸2g(g3)：recurrence 已是 Int32.MaxValue，bump 仍退出 0——PowerShell 的 + 会静默升宽到 [long]，写出的值下一次读就判非法。output=[$g3Out]"; $g2Fail = $true }
  if ((Get-FileHash $intLedger2g -Algorithm SHA256).Hash -ne $g3Hash) { Fail '闸2g(g3)：到顶的 bump 改写了账本——必须零写入。'; $g2Fail = $true }
  # (g4) Next-Id 也必须守同一个 Int32 域；冷库最大 id 到顶时 add 不得写出下一次读取必拒的 L2147483648。
  Set-Content $intLedger2g '# LEDGER' -Encoding utf8
  Set-Content (Join-Path $intRepo2g 'specs/archive/lessons-archive.md') (@('# archive', '', (& $mk2g 'L2147483647' '1')) -join [Environment]::NewLine) -Encoding utf8
  $g4LedgerHash = (Get-FileHash $intLedger2g -Algorithm SHA256).Hash
  $g4ArchiveHash = (Get-FileHash (Join-Path $intRepo2g 'specs/archive/lessons-archive.md') -Algorithm SHA256).Hash
  $g4Out = (& pwsh -NoProfile -File $intLessons2g add -RepoRoot $intRepo2g -Symptom s -Rule r 2>&1 | Out-String)
  $g4Exit = $LASTEXITCODE
  if ($g4Exit -eq 0 -or $g4Out -notmatch '\[LSN-ID-EXHAUSTED\]') { Fail "闸2g(g4)：冷库最大 id 已达 Int32.MaxValue，add 未以 [LSN-ID-EXHAUSTED] fail-closed。output=[$g4Out]"; $g2Fail = $true }
  if ((Get-FileHash $intLedger2g -Algorithm SHA256).Hash -ne $g4LedgerHash -or
      (Get-FileHash (Join-Path $intRepo2g 'specs/archive/lessons-archive.md') -Algorithm SHA256).Hash -ne $g4ArchiveHash) {
    Fail '闸2g(g4)：Next-Id 域耗尽后的 add 改写了热账本或冷库。'; $g2Fail = $true
  }
  if (Test-Path $intRepo2g) { Remove-Item -Recurse -Force -LiteralPath $intRepo2g -ErrorAction SilentlyContinue }

  # 闸2g(h)：A13 的第二类搬运器拒绝——热/冷内容不一致，须经 wrapper 的 -DryRun 打出**搬运器自己的 ASCII 哨兵**。
  # 原先这条分支只有本地化中文 Write-Warning，且唯一的测试直接调搬运器、按中文文案匹配——本地化文案一变即
  # 静默失效（L165：机检只认 ASCII 哨兵）。现补 [ARCHIVE-LESSON-REJECT-CONFLICT] 并从 wrapper 预览侧断言。
  $cfRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2gh-$PID"
  if (Test-Path $cfRepo2g) { Remove-Item -Recurse -Force -LiteralPath $cfRepo2g }
  New-Item -ItemType Directory -Force (Join-Path $cfRepo2g 'docs/lessons'), (Join-Path $cfRepo2g 'specs/archive') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $cfRepo2g -Recurse -Force
  $cfLessons2g = Join-Path $cfRepo2g 'scripts/lessons.ps1'
  $cfLedger2g = Join-Path $cfRepo2g 'docs/lessons/LEDGER.md'
  $cfArchive2g = Join-Path $cfRepo2g 'specs/archive/lessons-archive.md'
  $cfMeta2g = '- date: 2026-08-24 ｜ tags: t ｜ tier: ledger ｜ severity: minor ｜ recurrence: 1'
  # 两侧并存但正文**不一致**：rule 行不同 → 自愈路径必须拒绝（盲删 LEDGER 侧会毁掉较新的在册内容）
  # 选择器把**最高 id** 列为排除面之一，所以夹具必须另有一条更高的 id，否则 L905 自己就是最高、
  # candidates=none，搬运器一次都不会被调用——本闸会因为「没候选」而红，而不是因为它要测的冲突分支。
  Set-Content $cfLedger2g (@('# LEDGER', '',
    '## L905', $cfMeta2g, '- symptom: s', '- root_cause: rc', '- rule: HOT-VERSION', '- refs:', '',
    '## L950', $cfMeta2g, '- symptom: s', '- root_cause: rc', '- rule: highest-id sentinel (excluded by design)', '- refs:') -join [Environment]::NewLine) -Encoding utf8
  Set-Content $cfArchive2g (@('# archive', '', '## L905', $cfMeta2g, '- symptom: s', '- root_cause: rc', '- rule: COLD-VERSION-DIFFERS', '- refs:') -join [Environment]::NewLine) -Encoding utf8
  # 常驻真相源必须在场：CLAUDE.md 缺席时 lessons.ps1 先以 [LSN-RESIDENT-SOURCE-MISSING] 拒绝归档，
  # 根本走不到冲突分支——那样本闸会因为**另一个**原因变红，测不到它声称要测的东西。
  Set-Content (Join-Path $cfRepo2g 'CLAUDE.md') '常驻引用：无' -Encoding utf8
  New-Item -ItemType Directory -Force (Join-Path $cfRepo2g 'specs/tasks') | Out-Null
  Set-Content (Join-Path $cfRepo2g 'specs/tech-debt-tracker.md') "| id | 状态 |`n|---|---|`n| TD-FIXTURE | paid |" -Encoding utf8
  $cfHotHash2g = (Get-FileHash $cfLedger2g -Algorithm SHA256).Hash
  $cfColdHash2g = (Get-FileHash $cfArchive2g -Algorithm SHA256).Hash
  $cfOut2g = (& pwsh -NoProfile -File $cfLessons2g archive -DryRun -RepoRoot $cfRepo2g 2>&1 | Out-String)
  $cfExit2g = $LASTEXITCODE
  if ($cfExit2g -eq 0) { Fail "闸2g(h)：两侧并存且内容不一致，archive -DryRun 仍退出 0——预览把「拒绝」伪装成绿。output=[$cfOut2g]"; $g2Fail = $true }
  if ($cfOut2g -notmatch '\[ARCHIVE-LESSON-REJECT-CONFLICT\]') { Fail "闸2g(h)：预览输出里没有搬运器自己的 ASCII 哨兵 [ARCHIVE-LESSON-REJECT-CONFLICT]——要么哨兵没加，要么 -DryRun 没把搬运器的拒绝透传上来（只按中文文案判会在文案一变时静默失效）。output=[$cfOut2g]"; $g2Fail = $true }
  if ((Get-FileHash $cfLedger2g -Algorithm SHA256).Hash -ne $cfHotHash2g) { Fail '闸2g(h)：拒绝路径改写了热账本——必须双侧零写入。'; $g2Fail = $true }
  if ((Get-FileHash $cfArchive2g -Algorithm SHA256).Hash -ne $cfColdHash2g) { Fail '闸2g(h)：拒绝路径改写了冷库——必须双侧零写入。'; $g2Fail = $true }
  if (Test-Path $cfRepo2g) { Remove-Item -Recurse -Force -LiteralPath $cfRepo2g -ErrorAction SilentlyContinue }

  # 闸2g(i)：**镜像**用例——冷项只在**主检出**的冷库里，本工作树的冷库没有它。
  # 只有「按 BumpLedger 推出的主检出冷库」那条守卫能拦住它；2g(f) 拦不住，因为 2g(f) 会被
  # 本工作树自己的冷库先满足（断言被另一条路径满足＝没在测它声称测的东西，L165）。
  # 早先 $BumpArchive 只上溯两级父目录，算出 <root>/docs/specs/archive/... 这个永不存在的路径，
  # Test-Path 恒 false ⇒ 这条守卫一次都没跑过，而 2g(f) 照样绿。本闸把这条路径钉死。
  $mrRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2gi-$PID"
  if (Test-Path $mrRepo2g) { Remove-Item -Recurse -Force -LiteralPath $mrRepo2g }
  $mrMain2g = Join-Path $mrRepo2g 'main'
  $mrLink2g = Join-Path $mrRepo2g 'wt'
  New-Item -ItemType Directory -Force (Join-Path $mrMain2g 'docs/lessons'), (Join-Path $mrMain2g 'specs/archive') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $mrMain2g -Recurse -Force
  $mrBlock2g = @('## L906', '- date: 2026-08-24 ｜ tags: t ｜ tier: ledger ｜ severity: minor ｜ recurrence: 7', '- symptom: s', '- root_cause: rc', '- rule: r', '- refs:') -join [Environment]::NewLine
  Set-Content (Join-Path $mrMain2g 'docs/lessons/LEDGER.md') (@('# LEDGER', '', $mrBlock2g) -join [Environment]::NewLine) -Encoding utf8
  Set-Content (Join-Path $mrMain2g 'specs/archive/lessons-archive.md') (@('# archive', '', $mrBlock2g) -join [Environment]::NewLine) -Encoding utf8
  Push-Location $mrMain2g
  & git init -q 2>&1 | Out-Null
  & git config user.email 'selftest@example.invalid' 2>&1 | Out-Null
  & git config user.name 'selftest' 2>&1 | Out-Null
  & git add -A 2>&1 | Out-Null
  & git -c commit.gpgsign=false commit -q -m fixture 2>&1 | Out-Null
  & git worktree add -q -b lessons2gi $mrLink2g 2>&1 | Out-Null
  $mrAddOk2g = ($LASTEXITCODE -eq 0)
  Pop-Location
  if (-not $mrAddOk2g) {
    Fail '闸2g(i)：无法建立 linked worktree 夹具——本闸判的就是主检出冷库那条守卫，建不起来即中止而非跳过。'
    $g2Fail = $true
  }
  else {
    # 关键：本工作树的冷库**空**（不含 L906），主检出的冷库含 L906 且主检出 LEDGER 里它仍是热的
    Set-Content (Join-Path $mrLink2g 'specs/archive/lessons-archive.md') '# archive' -Encoding utf8
    Set-Content (Join-Path $mrLink2g 'docs/lessons/LEDGER.md') '# LEDGER' -Encoding utf8
    $mrMainLedger2g = Join-Path $mrMain2g 'docs/lessons/LEDGER.md'
    $mrHash2g = (Get-FileHash $mrMainLedger2g -Algorithm SHA256).Hash
    Push-Location $mrLink2g
    $mrOut2g = (& pwsh -NoProfile -File (Join-Path $mrLink2g 'scripts/lessons.ps1') bump L906 2>&1 | Out-String)
    $mrExit2g = $LASTEXITCODE
    Pop-Location
    if ($mrExit2g -eq 0) { Fail "闸2g(i)：L906 只在主检出的冷库里（本工作树冷库为空），bump 仍退出 0——按 BumpLedger 推出主检出冷库的那条守卫没生效（早先的两级父目录 bug 会让它永远 Test-Path 失败）。output=[$mrOut2g]"; $g2Fail = $true }
    if ($mrOut2g -notmatch '\[LSN-ARCHIVED-READONLY\]') { Fail "闸2g(i)：未打出 [LSN-ARCHIVED-READONLY]——主检出冷库未被查看。output=[$mrOut2g]"; $g2Fail = $true }
    if ((Get-FileHash $mrMainLedger2g -Algorithm SHA256).Hash -ne $mrHash2g) { Fail '闸2g(i)：主检出 LEDGER 被改写——冷项 bump 必须零写入。'; $g2Fail = $true }
    Push-Location $mrMain2g
    & git worktree remove --force $mrLink2g 2>&1 | Out-Null
    Pop-Location
  }
  if (Test-Path $mrRepo2g) { Remove-Item -Recurse -Force -LiteralPath $mrRepo2g -ErrorAction SilentlyContinue }

  $ledgerStableHash2g = (Get-FileHash $l2gLedger -Algorithm SHA256).Hash
  $archiveHash2g = (Get-FileHash $l2gArchive -Algorithm SHA256).Hash
  $rerun2g = (& pwsh -NoProfile -File $l2gLessons archive -RepoRoot $l2gRepo 2>&1 | Out-String)
  if ($LASTEXITCODE -ne 0 -or (Get-FileHash $l2gLedger -Algorithm SHA256).Hash -ne $ledgerStableHash2g -or
      (Get-FileHash $l2gArchive -Algorithm SHA256).Hash -ne $archiveHash2g) {
    Fail "闸2g(j)：无新候选时 archive 重跑不幂等。output=[$rerun2g]"; $g2Fail = $true
  }
  # (k) A16：定义「受保护集合」的常驻 CLAUDE.md 缺席时必须 fail-closed（模板文件只在元仓存在，故夹具把两个
  #   都删掉——这正是「有 LEDGER 却没有 CLAUDE.md」那棵树的真实形态）。此刻 L5/L6/L7/L8/L11 之所以还留在
  #   热账本，唯一原因就是被这两个文件引用；把它们删掉再跑，fail-open 的实现会把这 5 条**真的**搬进冷库，
  #   exit 0、无告警，事后闸 16 也不会红（它按热∪冷判）——与「只认方括号引用」同一后果、不同入口。
  #   断言预览与实跑同口径：非零退出 + 点名 [LSN-RESIDENT-SOURCE-MISSING] + 连 candidates= 都不该印出来
  #   （读不到判据就不该有「候选」这个结论）+ 两侧字节零变化。
  Remove-Item (Join-Path $l2gRepo 'CLAUDE.md'), (Join-Path $l2gRepo 'CLAUDE.template.md') -Force
  $ledgerHashG2g = (Get-FileHash $l2gLedger -Algorithm SHA256).Hash
  $archiveHashG2g = (Get-FileHash $l2gArchive -Algorithm SHA256).Hash
  foreach ($modeG2g in @('预览', '实跑')) {
    # 逐元素拼参数数组再 splat：`$x = if (…) { @('-DryRun') }` 会被 PowerShell 把单元素数组拆成**字符串**，
    # 而 splat 一个字符串是按字符散开的（实测报 “positional parameter … 'D'”），预览分支遂根本没带上 -DryRun。
    $argsG2g = @('-NoProfile', '-File', $l2gLessons, 'archive', '-RepoRoot', $l2gRepo)
    if ($modeG2g -eq '预览') { $argsG2g += '-DryRun' }
    $noRef2g = (& pwsh @argsG2g 2>&1 | Out-String)
    $noRefExit2g = $LASTEXITCODE
    if ($noRefExit2g -eq 0) { Fail "闸2g(k)：常驻 CLAUDE 文件全部缺席时 archive($modeG2g) 仍退出 0——「读不到受保护集合」被当成了「没有条目被引用」，整批 ledger 条目遂静默进候选。output=[$noRef2g]"; $g2Fail = $true }
    if ($noRef2g -notmatch '\[LSN-RESIDENT-SOURCE-MISSING\]') { Fail "闸2g(k)：archive($modeG2g) 未给 [LSN-RESIDENT-SOURCE-MISSING] 哨兵——告警文本不算诊断，按退出码判断的调用方看不见原因。output=[$noRef2g]"; $g2Fail = $true }
    if ($noRef2g -match 'candidates=') { Fail "闸2g(k)：引用判据缺席时仍印出了 candidates=——判据都没有，就不该给出「候选」这个结论。output=[$noRef2g]"; $g2Fail = $true }
    if ((Get-FileHash $l2gLedger -Algorithm SHA256).Hash -ne $ledgerHashG2g -or (Get-FileHash $l2gArchive -Algorithm SHA256).Hash -ne $archiveHashG2g) {
      Fail "闸2g(k)：引用判据缺席时 archive($modeG2g) 仍动了数据（L5/L6/L7/L8/L11 正是靠常驻引用才留热）。"; $g2Fail = $true
    }
  }

  # (l) 源 LEDGER 缺席不等于空账本。选择器若继续，会打印 candidates=none 并 exit 0，掩盖错误 RepoRoot。
  $noLedgerRepo2g = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2gl-$PID"
  if (Test-Path $noLedgerRepo2g) { Remove-Item -Recurse -Force -LiteralPath $noLedgerRepo2g }
  New-Item -ItemType Directory -Force (Join-Path $noLedgerRepo2g 'specs/archive') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $noLedgerRepo2g -Recurse -Force
  Set-Content (Join-Path $noLedgerRepo2g 'CLAUDE.md') '常驻引用：无' -Encoding utf8
  $noLedgerArchive2g = Join-Path $noLedgerRepo2g 'specs/archive/lessons-archive.md'
  Set-Content $noLedgerArchive2g '# archive sentinel' -Encoding utf8
  $noLedgerColdHash2g = (Get-FileHash $noLedgerArchive2g -Algorithm SHA256).Hash
  $noLedgerOut2g = (& pwsh -NoProfile -File (Join-Path $noLedgerRepo2g 'scripts/lessons.ps1') archive -RepoRoot $noLedgerRepo2g 2>&1 | Out-String)
  if ($LASTEXITCODE -eq 0 -or $noLedgerOut2g -notmatch '\[LSN-LEDGER-SOURCE-MISSING\]' -or
      (Get-FileHash $noLedgerArchive2g -Algorithm SHA256).Hash -ne $noLedgerColdHash2g -or
      (Test-Path (Join-Path $noLedgerRepo2g 'docs/lessons/LEDGER.md'))) {
    Fail "闸2g(l)：源 LEDGER 缺席未以 [LSN-LEDGER-SOURCE-MISSING] fail-closed 且零写入。output=[$noLedgerOut2g]"; $g2Fail = $true
  }
  Remove-Item -Recurse -Force -LiteralPath $noLedgerRepo2g -ErrorAction SilentlyContinue

  if (-not $g2Fail) {
    Write-Host '  2g lessons 选择性冷存/零写预览/三形态引用排除 + 两种否定形态/引用判据缺席即 fail-closed/热冷召回/ID 并集/冷项只读/幂等 OK' -ForegroundColor Green
  }
} finally {
  Remove-Item -Recurse -Force $l2gRepo -ErrorAction SilentlyContinue
}

# 2i. T0-LESSONS-COLD-RECALL（R3 收口）：规范 meta 行是元数据的**唯一出生点**——为什么必须如此，见
#     scripts/lessons.ps1 中 Get-LessonMeta 的头注（单一处论述，此处不复述）。本闸只负责把它钉死：
#     用一条夹具一个病灶的敌意账本，断言读侧（archive 选择器 / check / list / search）与写侧（bump / promote）
#     一律 [LSN-META-INVALID] 留热区、零写入、非零退出，而合法条目行为不变。
#     把 Get-LessonMeta 换回不锚定正则、或去掉任一枚值校验，都有对应的一条夹具让它变红。
$l2iRepo = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2i-$PID"
if (Test-Path $l2iRepo) { Remove-Item -Recurse -Force $l2iRepo }
New-Item -ItemType Directory -Force $l2iRepo | Out-Null
try {
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2iRepo -Recurse -Force
  $l2iLessons = Join-Path $l2iRepo 'scripts/lessons.ps1'
  $l2iLedger = Join-Path $l2iRepo 'docs/lessons/LEDGER.md'
  New-Item -ItemType Directory -Force (Split-Path $l2iLedger), (Join-Path $l2iRepo 'specs/archive') | Out-Null
  Set-Content (Join-Path $l2iRepo 'CLAUDE.md') "## 经验铁律（必须加载）`n`n## refs`n" -Encoding utf8

  # 一条夹具一个病灶——每道守卫都要有一枚**只**打它的夹具，共用一条会让两道守卫互相打掩护（L165）。
  # 每条只在合法基线 meta 行上改一处，正文形状不变，于是「哪里不合法」在下面一眼可见。
  # L20 值得单说：它的 meta 行**整个没有** recurrence 字段（不是值写错）。这才是 bump 假绿写入的确切触发形状——
  # meta 行通常是块内第二行，不锚定的 `recurrence:\s*(\d+)` 会先命中它，只有该字段根本不在时才掉到正文诱饵上，
  # 于是读出 7、算出 8、锚定的写一处也匹配不到、原样写回，却打印绿字「7 → 8」、exit 0、还建议 promote 进必须层。
  # **闸 2c 抓不到它**（2c 的夹具 meta 行有该字段，读永远落在 meta 行上），故必须在此单列。
  $ok2i = '- date: 2026-08-21 ｜ tags: fixture ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1'
  $entry2i = {
    param([string]$Heading, [string]$Meta, [string]$Token, [string]$Bait = '')
    @("## $Heading", $Meta, "- symptom: $Token", "- rule: rule-$Token$Bait") -join "`n"
  }
  $l2iLedgerText = @(
    '# fixture ledger', '',
    (& $entry2i 'L1'  $ok2i 'LEGIT_COLD_CANDIDATE'),
    (& $entry2i 'L2'  ($ok2i -replace ' ｜ tier: ledger','') 'BAIT_TIER_ONLY' '，正文诱饵 tier: ledger'),
    (& $entry2i 'L20' ($ok2i -replace ' ｜ recurrence: 1','') 'BAIT_RECURRENCE_ONLY' '，正文诱饵 recurrence: 7'),
    (& $entry2i 'L3'  ($ok2i + "`n" + $ok2i) 'DUPLICATE_META_LINE'),
    (& $entry2i 'L4'  ($ok2i -replace 'tier: ledger','tier: bogus') 'INVALID_TIER_VALUE'),
    (& $entry2i 'L5'  '- note: 本块无规范 meta 行' 'NO_META_LINE_AT_ALL'),
    (& $entry2i 'L6'  ('  ' + $ok2i) 'INDENTED_META_LINE'),
    (& $entry2i 'L7'  ($ok2i -replace 'tier: ledger','tier: ledger ｜ tier: must') 'DUPLICATE_FIELD_NAME'),
    (& $entry2i 'L8'  ($ok2i -replace 'date: 2026-08-21','date: 2026-8-1') 'NON_ISO_DATE'),
    (& $entry2i 'L10' ($ok2i -replace 'severity: minor','severity: fatal') 'INVALID_SEVERITY'),
    (& $entry2i 'L13' ($ok2i -replace 'kind: pitfall','kind: bogus') 'INVALID_KIND'),
    (& $entry2i 'L14' ($ok2i -replace 'recurrence: 1','recurrence: many') 'NON_NUMERIC_RECURRENCE'),
    (& $entry2i 'L15' ($ok2i -replace 'recurrence: 1','recurrence: 99999999999999999999') 'RECURRENCE_OVERFLOWS_INT32'),
    (& $entry2i 'L16' ($ok2i -replace ' ｜ tags: fixture','') 'MISSING_TAGS_FIELD'),
    # L17 与 L10 是**两枚**夹具、打的是两道不同守卫：L10 的 severity 有值但值非法（走值校验那一行），
    # L17 的 meta 行整个没有 severity 字段（走必填字段表那一行）。少了 L17，把 'severity' 从必填表里删掉
    # 后没有任何输入能变红——缺失键在 StrictMode 下取值为 $null，会被下游的值校验降级成「值非法」照样报错。
    (& $entry2i 'L17' ($ok2i -replace ' ｜ severity: minor','') 'MISSING_SEVERITY_FIELD'),
    ((& $entry2i 'L18' $ok2i 'MISSING_RULE_LINE') -replace '(?m)^- rule:.*(?:\r?\n|$)', ''),
    (& $entry2i 'L19' ($ok2i -replace 'severity: minor','severity: blocking') 'BLOCKING_WITHOUT_ENFORCED_BY'),
    ((& $entry2i 'L21' $ok2i 'EMPTY_RULE_VALUE') -replace '(?m)^- rule:.*$', "- rule:`n- refs:"),
    ((& $entry2i 'L22' ($ok2i -replace 'severity: minor','severity: blocking') 'EMPTY_ENFORCED_BY_VALUE') + "`n- enforced_by:`n- refs:"),
    (& $entry2i 'L99999999999999999999' $ok2i 'ID_OVERFLOWS_INT32'),
    (& $entry2i 'L30' $ok2i 'MAX_ID_EXCLUDED')
  ) -join "`n`n"
  Set-Content $l2iLedger $l2iLedgerText -Encoding utf8
  $hostile2iIds = @('L2', 'L20', 'L3', 'L4', 'L5', 'L6', 'L7', 'L8', 'L10', 'L13', 'L14', 'L15', 'L16', 'L17', 'L99999999999999999999')
  $invalidEntry2iIds = @('L18', 'L19', 'L21', 'L22')

  $dry2i = (& pwsh -NoProfile -File $l2iLessons archive -RepoRoot $l2iRepo -DryRun 2>&1 | Out-String)
  $dryExit2i = $LASTEXITCODE
  $cand2i = ([regex]::Match($dry2i, '\[LSN-ARCHIVE-DRYRUN\]\s*candidates=(?<c>\S+)')).Groups['c'].Value
  $e2Fail = $false
  # 有不可解析条目时预览必须**非零**退出：同一份账本不能 check 报 1 而 archive 报 0，那正是 archive.ps1 自己
  # 早已否掉的 fail-open（闸 12e⑥）。告警文本不算诊断——`-Quiet`、折叠的 CI 日志、按退出码判断的调用方都看不见。
  if ($dryExit2i -eq 0) { Fail "闸2i(a)：夹具含不可解析条目，archive -DryRun 却退出 0——预览把「无效」伪装成绿。output=[$dry2i]"; $e2Fail = $true }
  if ($cand2i -ne 'L1') { Fail "闸2i(a)：候选集应恰为 L1，实得『$cand2i』——有条目的正文诱饵/非法值被当成了合法元数据，或合法条目被误伤。output=[$dry2i]"; $e2Fail = $true }
  foreach ($hostile2i in $hostile2iIds) {
    if ($dry2i -notmatch "\[LSN-META-INVALID\][^`n]*\b$hostile2i\b") { Fail "闸2i(b)：$hostile2i 的非法 meta 未被点名报告 [LSN-META-INVALID]——静默留热区等于没有诊断。output=[$dry2i]"; $e2Fail = $true }
  }
  foreach ($invalidEntry2i in $invalidEntry2iIds) {
    if ($dry2i -notmatch "\[LSN-ENTRY-INVALID\][^`n]*\b$invalidEntry2i\b") { Fail "闸2i(b3)：$invalidEntry2i 违反 check 共用正文不变量，却未被 [LSN-ENTRY-INVALID] 点名并排除。output=[$dry2i]"; $e2Fail = $true }
  }
  # (b2) 「字段缺失」须报成缺失、而非降级成「值非法」。StrictMode 下缺失键取值为 $null，下游枚举/正则校验照样
  #   判非法，于是必填字段表的每一项都能被删掉而整批仍绿（本卡变异实测：删 'tier' 后闸 2 全绿）。断言 ASCII
  #   哨兵 missing-field=<名>，本表才真有人在测；不断言中文正文——本地化文案一变即假红/假绿（L165）。
  #   本循环须与 lessons.ps1 的必填表**逐项等长**（今为 tags/tier/severity/recurrence 四项，各配一枚只缺该
  #   字段的夹具：L16/L2/L17/L20）——漏掉哪一项，哪一项就重新变回「删了没人红」。
  foreach ($missing2i in @('tier', 'recurrence', 'tags', 'severity')) {
    if ($dry2i -notmatch "missing-field=$missing2i") { Fail "闸2i(b2)：缺 $missing2i 字段的条目未报 missing-field=$missing2i，而是被降级成「值非法」——必填字段表遂无一项可被变异杀死。output=[$dry2i]"; $e2Fail = $true }
  }

  $check2i = (& pwsh -NoProfile -File $l2iLessons check -RepoRoot $l2iRepo 2>&1 | Out-String)
  $checkExit2i = $LASTEXITCODE
  if ($checkExit2i -eq 0 -or $check2i -notmatch '\[LSN-META-INVALID\]' -or $check2i -notmatch '\[LSN-ENTRY-INVALID\]') {
    Fail "闸2i(c)：check 对缺字段/重复/非法 meta 未 fail-closed（exit=$checkExit2i）——校验器放行的形状，选择器迟早会当真。output=[$check2i]"; $e2Fail = $true
  }

  # (c2) 一条坏条目不得废掉整个 CLI：recurrence / id 越 Int32 时 `[int]` 在 $ErrorActionPreference='Stop' 下是终止性
  #   异常，会让 list/search/check 一起抛裸 .NET 消息——连「遇到问题先 search」这个召回入口都没了。越界须与其它
  #   非法值走同一条 [LSN-META-INVALID] 路。判据用 ASCII 哨兵 + 退出码，不认本地化异常文案。
  $list2i = (& pwsh -NoProfile -File $l2iLessons list -RepoRoot $l2iRepo 2>&1 | Out-String); $listExit2i = $LASTEXITCODE
  $srch2i = (& pwsh -NoProfile -File $l2iLessons search RECURRENCE_OVERFLOWS_INT32 -RepoRoot $l2iRepo 2>&1 | Out-String); $srchExit2i = $LASTEXITCODE
  if ($listExit2i -ne 0 -or $srchExit2i -ne 0) { Fail "闸2i(c2)：list/search 因越界条目非零退出（$listExit2i/$srchExit2i）——一条坏 meta 不该废掉只读召回面。output=[$list2i$srch2i]"; $e2Fail = $true }
  elseif ("$list2i$srch2i" -match 'Cannot convert|OverflowException') { Fail "闸2i(c2)：list/search 抛出了裸 .NET 转换异常（越界未走 [LSN-META-INVALID]）。output=[$list2i$srch2i]"; $e2Fail = $true }
  elseif ($list2i -notmatch 'L15[^`n]*\[LSN-META-INVALID\]') { Fail "闸2i(c2)：list 未把不可解析条目标成 [LSN-META-INVALID]，而是渲染了猜出来的默认值（空 tier / rec=0 会被当事实读）。output=[$list2i]"; $e2Fail = $true }

  # (e) 写侧：bump 只信规范 meta 行。三个靶各打一处：L20 = 假绿写入（旧码读正文的 7、印「7 → 8」、exit 0、零写入）；
  #   L3 = 一次改两行；L15 = 唯一能证明 **Get-LessonMeta 那道闸本身**在起作用的靶——L20/L3 即使摘掉它也会被
  #   「块字节一个都没变」兜住，而 L15 的计数器是合法数字串，摘掉闸后 bump 会把 20 位计数器静默改写成 1 并 exit 0。
  #   三者都要求：非零退出 + 点名 [LSN-META-INVALID] + LEDGER 字节不变。
  foreach ($bumpTarget2i in @('L20', 'L3', 'L15')) {
    $hashBefore2i = (Get-FileHash $l2iLedger -Algorithm SHA256).Hash
    $bumpOut2i = (& pwsh -NoProfile -File $l2iLessons bump $bumpTarget2i -RepoRoot $l2iRepo 2>&1 | Out-String)
    $bumpExit2i = $LASTEXITCODE
    $hashAfter2i = (Get-FileHash $l2iLedger -Algorithm SHA256).Hash
    if ($bumpExit2i -eq 0) { Fail "闸2i(e)：bump $bumpTarget2i 的 meta 行不合法却退出 0——写路径把「读不出元数据」当成了「元数据说可以写」。output=[$bumpOut2i]"; $e2Fail = $true }
    if ($bumpOut2i -notmatch '\[LSN-META-INVALID\]') { Fail "闸2i(e)：bump $bumpTarget2i 拒绝时未给 [LSN-META-INVALID] 哨兵。output=[$bumpOut2i]"; $e2Fail = $true }
    if ($hashAfter2i -ne $hashBefore2i) { Fail "闸2i(e)：bump $bumpTarget2i 被拒却改动了 LEDGER 字节（应零写入）。"; $e2Fail = $true }
  }
  # promote 是决策面：同样不得对不可解析条目渲染默认值并给出「暂不够必须层」这种结论。
  $promote2i = (& pwsh -NoProfile -File $l2iLessons promote L20 -RepoRoot $l2iRepo 2>&1 | Out-String)
  if ($LASTEXITCODE -eq 0 -or $promote2i -notmatch '\[LSN-META-INVALID\]') {
    Fail "闸2i(e)：promote 对不可解析条目未 fail-closed，而是拿空 tier / rec=0 当事实给了晋升结论。output=[$promote2i]"; $e2Fail = $true
  }

  $ledgerHash2i = (Get-FileHash $l2iLedger -Algorithm SHA256).Hash
  $run2i = (& pwsh -NoProfile -File $l2iLessons archive -RepoRoot $l2iRepo 2>&1 | Out-String)
  $runExit2i = $LASTEXITCODE
  $ledgerAfter2i = Get-Content $l2iLedger -Raw
  if ($runExit2i -eq 0) { Fail "闸2i(d)：夹具含不可解析条目，archive 实跑却退出 0——预览与实跑须同口径 fail-closed。output=[$run2i]"; $e2Fail = $true }
  foreach ($stayHot2i in @($hostile2iIds + $invalidEntry2iIds)) {
    if ($ledgerAfter2i -notmatch "(?m)^##[ \t]+$stayHot2i[ \t]*\r?$") { Fail "闸2i(d)：$stayHot2i 元数据不可解析却被真的搬出热账本——fail-closed 应是「留下」，不是「搬走」。output=[$run2i]"; $e2Fail = $true }
  }
  if ($ledgerAfter2i -match '(?m)^##[ \t]+L1[ \t]*\r?$') { Fail "闸2i(d)：合法一次性条目 L1 未被搬走——新校验误伤了正常路径。output=[$run2i]"; $e2Fail = $true }
  if ($ledgerHash2i -eq (Get-FileHash $l2iLedger -Algorithm SHA256).Hash) { Fail '闸2i(d)：archive 实跑后热账本毫无变化——本例没有真正施压。'; $e2Fail = $true }

  if (-not $e2Fail) { Write-Host '  2i lessons 规范 meta + 共用正文不变量 OK（非法条目均点名留热、预览与实跑非零；bump/promote 零写入拒绝；list/search 仍可用；合法条目照常冷存）' -ForegroundColor Green }
} finally {
  Remove-Item -Recurse -Force $l2iRepo -ErrorAction SilentlyContinue
}

# 2f. T0-LESSONS-COLD-RECALL（R3 收口·预览诚实性与幂等的非平凡分支）：
#   (a) 预览必须走搬运器自己那条路——选择器只回答「选出了谁」，archive.ps1 的四类拒绝都在这之后；只印候选就
#       break 会让预览报绿、实跑搬走一部分后才非零退出，落差压在一次数据移动上。
#   (b) 归档暂存写失败（注入同名 .tmp 目录）须非零退出、两侧字节零变化——wrapper 不得把搬运器的失败吞成 0
#       （12e⑦ 只证明了 archive.ps1 本身，证明不了这层透传）。
#   (c) 幂等的**非平凡**分支：把已归档条目粘回 LEDGER 造两侧并存态，重跑须自愈补齐且归档字节不变
#       （只测「无新候选时零写入」会漏掉这条自愈路径）。
#   (d) 带后缀的标题（`## L45 (deprecated)`）两侧须同样不当它是条目 id，否则诊断会指向与真因无关的「未知 id」。
$l2fRepo = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2f-$PID"
if (Test-Path $l2fRepo) { Remove-Item -Recurse -Force $l2fRepo }
New-Item -ItemType Directory -Force $l2fRepo | Out-Null
try {
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2fRepo -Recurse -Force
  $l2fLessons = Join-Path $l2fRepo 'scripts/lessons.ps1'
  $l2fLedger = Join-Path $l2fRepo 'docs/lessons/LEDGER.md'
  $l2fArchive = Join-Path $l2fRepo 'specs/archive/lessons-archive.md'
  New-Item -ItemType Directory -Force (Split-Path $l2fLedger), (Split-Path $l2fArchive) | Out-Null
  Set-Content (Join-Path $l2fRepo 'CLAUDE.md') "## 经验铁律（必须加载）`n`n## refs`n" -Encoding utf8
  $entry2f = {
    param([string]$Heading, [string]$Token)
    @(
      "## $Heading",
      '- date: 2026-08-21 ｜ tags: fixture ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1',
      "- symptom: $Token", "- rule: rule-$Token"
    ) -join "`n"
  }
  $f2Fail = $false

  # (a) 预览与实跑同口径：L02 是**非规范别名**（前导零），选择器会把它当普通候选交出去，
  #   而搬运器按 `^L[1-9]\d*$` 拒收（别名经数值匹配会撞上 L2 的块）。预览若不透传给搬运器，这条拒绝
  #   在预览里完全看不见、还 exit 0。断言：非零退出 + 预览输出里出现搬运器自己的拒绝文案 + 零写入。
  Set-Content $l2fLedger (@('# fixture ledger', '', (& $entry2f 'L1' 'ALIAS_CASE_LEGIT'), '', (& $entry2f 'L02' 'ALIAS_ID_REJECTED_BY_MOVER'), '', (& $entry2f 'L30' 'MAX_ID_EXCLUDED')) -join "`n") -Encoding utf8
  $hashA2f = (Get-FileHash $l2fLedger -Algorithm SHA256).Hash
  $dryA2f = (& pwsh -NoProfile -File $l2fLessons archive -RepoRoot $l2fRepo -DryRun 2>&1 | Out-String)
  $dryExitA2f = $LASTEXITCODE
  if ($dryExitA2f -eq 0) { Fail "闸2f(a)：候选里含搬运器会拒收的别名 id L02，archive -DryRun 却退出 0——预览没走搬运器那条路（去掉 -DryRun 才会现形，而那时已经在搬数据了）。output=[$dryA2f]"; $f2Fail = $true }
  # 判据是 archive.ps1 自己发的 ASCII 哨兵，不是中文文案：本地化正文一改（或编码链一变）就假红/假绿（L165）。
  if ($dryA2f -notmatch '\[ARCHIVE-LESSON-REJECT-ALIAS\]') { Fail "闸2f(a)：预览输出里没有搬运器自己的拒绝哨兵 [ARCHIVE-LESSON-REJECT-ALIAS]——说明 -DryRun 未透传到 archive.ps1。output=[$dryA2f]"; $f2Fail = $true }
  if ((Get-FileHash $l2fLedger -Algorithm SHA256).Hash -ne $hashA2f -or (Test-Path $l2fArchive)) { Fail '闸2f(a)：预览写了文件（透传后仍须零写入）。'; $f2Fail = $true }

  # (b) 归档暂存写失败：在 `<归档>.tmp` 预置同名**目录**令 Set-Content 确定性失败（跨平台一致）。
  Set-Content $l2fLedger (@('# fixture ledger', '', (& $entry2f 'L1' 'MOVE_TARGET'), '', (& $entry2f 'L30' 'MAX_ID_EXCLUDED')) -join "`n") -Encoding utf8
  $hashB2f = (Get-FileHash $l2fLedger -Algorithm SHA256).Hash
  $tmpBlock2f = "$l2fArchive.tmp"
  New-Item -ItemType Directory -Force $tmpBlock2f | Out-Null
  $runB2f = (& pwsh -NoProfile -File $l2fLessons archive -RepoRoot $l2fRepo 2>&1 | Out-String)
  $runExitB2f = $LASTEXITCODE
  Remove-Item $tmpBlock2f -Recurse -Force -ErrorAction SilentlyContinue
  if ($runExitB2f -eq 0) { Fail "闸2f(b)：归档暂存写失败时 lessons.ps1 archive 仍退出 0——wrapper 吞掉了搬运器的非零码。output=[$runB2f]"; $f2Fail = $true }
  if ((Get-FileHash $l2fLedger -Algorithm SHA256).Hash -ne $hashB2f) { Fail '闸2f(b)：归档暂存写失败时 LEDGER 不该有任何变化（数据丢失窗口）。'; $f2Fail = $true }
  if (Test-Path $l2fArchive) { Fail '闸2f(b)：归档暂存写失败却留下了归档件（原子替换未生效）。'; $f2Fail = $true }

  # (c) 正常搬运 → 造两侧并存 → 重跑自愈。
  $runC2f = (& pwsh -NoProfile -File $l2fLessons archive -RepoRoot $l2fRepo 2>&1 | Out-String)
  if ($LASTEXITCODE -ne 0 -or -not (Test-Path $l2fArchive) -or (Get-Content $l2fLedger -Raw) -match '(?m)^##[ \t]+L1[ \t]*\r?$') {
    Fail "闸2f(c)：清掉注入后正常搬运未把 L1 移入冷库。output=[$runC2f]"; $f2Fail = $true
  } else {
    $archLines2f = @(Get-Content $l2fArchive)
    $idx2f = -1
    for ($i = 0; $i -lt $archLines2f.Count; $i++) { if ($archLines2f[$i] -match '^##[ \t]+L1[ \t]*$') { $idx2f = $i; break } }
    if ($idx2f -lt 0) { Fail '闸2f(c)：归档件里找不到「## L1」标题，无法构造两侧并存态。'; $f2Fail = $true }
    else {
      # 把归档侧那一整块**逐字**粘回 LEDGER：archive.ps1 的自愈只在两侧内容逐字一致时才补完移动，
      # 不一致时会拒绝自动处理（防归档陈旧时盲删在册的较新内容）——此处测的是一致那一支。
      Add-Content $l2fLedger (@('') + @($archLines2f[$idx2f..($archLines2f.Count - 1)])) -Encoding utf8
      $archHashC2f = (Get-FileHash $l2fArchive -Algorithm SHA256).Hash
      $healC2f = (& pwsh -NoProfile -File $l2fLessons archive -RepoRoot $l2fRepo 2>&1 | Out-String)
      $healExitC2f = $LASTEXITCODE
      $ledgerAfterC2f = Get-Content $l2fLedger -Raw
      $headCountC2f = ([regex]::Matches((Get-Content $l2fArchive -Raw), '(?m)^##[ \t]+L1[ \t]*\r?$')).Count
      if ($healExitC2f -ne 0) { Fail "闸2f(c)：两侧并存态重跑非零退出（$healExitC2f）——自愈分支未走通。output=[$healC2f]"; $f2Fail = $true }
      if ($ledgerAfterC2f -match '(?m)^##[ \t]+L1[ \t]*\r?$') { Fail "闸2f(c)：两侧并存态重跑后 LEDGER 仍留着 L1 残留副本（移动未补完）。output=[$healC2f]"; $f2Fail = $true }
      if ($headCountC2f -ne 1) { Fail "闸2f(c)：自愈后归档侧「## L1」标题出现 $headCountC2f 次（应恰 1 次——重复追加即非幂等）。"; $f2Fail = $true }
      if ((Get-FileHash $l2fArchive -Algorithm SHA256).Hash -ne $archHashC2f) { Fail '闸2f(c)：自愈补齐改动了归档字节（该分支只该清除 LEDGER 残留，不该重写归档内容）。'; $f2Fail = $true }
    }
  }

  # (d) 条目起点只认规范 `## L<n>`，但块终点是下一个任意 `## ` 标题。Appendix 下的 meta/rule
  # 不得补全 L42，也不得被 bump L42 改写；带后缀/拆行标题仍不成为 lesson id。
  Set-Content $l2fLedger (@(
    '# fixture ledger', '',
    (& $entry2f 'L41' 'SUFFIX_CASE_LEGIT'), '',
    '## L42',
    '- symptom: OWN_METADATA_AND_RULE_MISSING',
    '## Appendix',
    '- date: 2026-08-21 ｜ tags: appendix ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 7',
    '- rule: APPENDIX_RULE_MUST_NOT_QUALIFY_L42', '',
    (& $entry2f 'L50' 'MAX_ID_EXCLUDED'), '',
    (& $entry2f 'L45 (deprecated)' 'SUFFIXED_HEADING_NOT_AN_ENTRY'), '',
    '##', 'L46',
    '- date: 2026-08-21 ｜ tags: fixture ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 1',
    '- symptom: SPLIT_HEADING_NOT_AN_ENTRY', '- rule: split-heading-rule'
  ) -join "`n") -Encoding utf8
  $hashD2f = (Get-FileHash $l2fLedger -Algorithm SHA256).Hash
  $dryD2f = (& pwsh -NoProfile -File $l2fLessons archive -RepoRoot $l2fRepo -DryRun 2>&1 | Out-String)
  $dryExitD2f = $LASTEXITCODE
  $candD2f = ([regex]::Match($dryD2f, '\[LSN-ARCHIVE-DRYRUN\]\s*candidates=(?<c>\S+)')).Groups['c'].Value
  if ($candD2f -ne 'L41') { Fail "闸2f(d)：候选集应恰为 L41，实得『$candD2f』——Appendix 正文补全了 L42，或非规范标题被当成条目 id。output=[$dryD2f]"; $f2Fail = $true }
  if ($dryD2f -notmatch "\[LSN-META-INVALID\][^`n]*\bL42\b" -or $dryD2f -notmatch "\[LSN-ENTRY-INVALID\][^`n]*\bL42\b") {
    Fail "闸2f(d)：L42 自身缺 meta/rule，却未被两个共享不变量点名；Appendix 内容可能越界补全了它。output=[$dryD2f]"; $f2Fail = $true
  }
  if ($dryD2f -match "\[LSN-META-INVALID\][^`n]*\bL50\b") { Fail "闸2f(d)：后缀标题越过通用 ## 边界并入 L50，令合法 L50 被误判。output=[$dryD2f]"; $f2Fail = $true }
  if ($dryExitD2f -eq 0) { Fail "闸2f(d)：存在不可解析条目却退出 0。output=[$dryD2f]"; $f2Fail = $true }
  foreach ($malformedId2f in @('L42', 'L45', 'L46')) {
    $bumpD2f = (& pwsh -NoProfile -File $l2fLessons bump $malformedId2f -RepoRoot $l2fRepo 2>&1 | Out-String)
    if ($LASTEXITCODE -eq 0) { Fail "闸2f(d)：不可写目标 $malformedId2f 被 bump 成功修改。output=[$bumpD2f]"; $f2Fail = $true }
    if ((Get-FileHash $l2fLedger -Algorithm SHA256).Hash -ne $hashD2f) { Fail "闸2f(d)：bump 拒绝 $malformedId2f 后仍改写了 LEDGER。"; $f2Fail = $true }
  }
  if ((Get-Content $l2fLedger -Raw) -notmatch 'tags: appendix.*recurrence: 7') { Fail '闸2f(d)：bump L42 改写了 Appendix 的 recurrence。'; $f2Fail = $true }
  $definedD2f = Get-LessonDefinitionIdSet -LedgerPath $l2fLedger -ArchivePath $l2fArchive
  $danglingD2f = @((Get-LessonReferenceIdSet 'resident refs L45 and [L46]').Keys | Where-Object { -not $definedD2f.ContainsKey($_) } | Sort-Object)
  if (($danglingD2f -join ',') -ne 'L45,L46') {
    Fail "闸2f(d)：闸16 未把后缀/拆行标题引用同时判为悬空，实得 [$($danglingD2f -join ',')]。"; $f2Fail = $true
  }

  # (e) 冷库从第一行就出现不可解析的 lesson-like 标题时必须整次拒绝。旧实现把它当“无条目头注”，
  # 随后写入合法 L1 时会重建冷库并静默丢掉原块。溢出和带后缀各打一枚，双侧字节必须完全不变。
  $l2fMover = Join-Path $l2fRepo 'scripts/archive.ps1'
  foreach ($badColdHeading2f in @('L2147483648', 'L45 (deprecated)')) {
    Set-Content $l2fLedger (@('# fixture ledger', '', (& $entry2f 'L1' 'VALID_MOVE_MUST_NOT_RUN'), '', (& $entry2f 'L30' 'MAX_ID_EXCLUDED')) -join "`n") -Encoding utf8
    Set-Content $l2fArchive (@("## $badColdHeading2f", '- data: COLD_BLOCK_MUST_SURVIVE') -join "`n") -Encoding utf8
    $hotHashE2f = (Get-FileHash $l2fLedger -Algorithm SHA256).Hash
    $coldHashE2f = (Get-FileHash $l2fArchive -Algorithm SHA256).Hash
    $badColdOut2f = (& pwsh -NoProfile -File $l2fMover -RepoRoot $l2fRepo -LessonsOnly -LessonIds L1 2>&1 | Out-String)
    if ($LASTEXITCODE -eq 0 -or $badColdOut2f -notmatch '\[ARCHIVE-LESSON-INVALID-HEADING\]' -or
        (Get-FileHash $l2fLedger -Algorithm SHA256).Hash -ne $hotHashE2f -or
        (Get-FileHash $l2fArchive -Algorithm SHA256).Hash -ne $coldHashE2f) {
      Fail "闸2f(e)：冷库首条非法标题 ## $badColdHeading2f 未 fail-closed 且双侧零写入。output=[$badColdOut2f]"; $f2Fail = $true
    }
  }

  if (-not $f2Fail) { Write-Host '  2f lessons 预览透传搬运器拒绝/写失败非零透传/两侧并存自愈幂等/标题口径两侧一致 OK' -ForegroundColor Green }
} finally {
  Remove-Item -Recurse -Force $l2fRepo -ErrorAction SilentlyContinue
}

# 2d. bump 的写入平面（T0-LESSONS-BUMP-PLANE）：recurrence 是**仓库级元数据**，与任何卡片无关。
#   旧实现把 $Ledger 绑到 $PSScriptRoot/..，于是在 linked worktree 里跑 bump 就写进了**卡片分支**的
#   LEDGER.md，被范围闸与 R3 #7（夹带无关改动）正确拦下——计数遂无处可去。丢失是**结构性**的：
#   卡片工作全在 worktree 里做，所以「工作中发现的复发」几乎必然记不上，晋升门槛被系统性低估。
#   夹具 LSN-PLANE-WORKTREE：真 git 仓 + 一棵 linked worktree，三条断言——
#   当前 2d：普通仓取 worktree 首条；首条为 common-dir 时取唯一 local core.worktree，再反向验证 top/common 同仓。
#     (a) 从 worktree 跑 bump → 主检出账本 +1，且 worktree 账本**逐字节不变**；
#     (e) 继承的 GIT_COMMON_DIR 不得劫持写入平面；(c) 主检出账本缺失 → 非零退出 + [LSN-PLANE-UNRESOLVED]（fail-closed，禁止回落到当前检出）。
$l2dRoot = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-lessons2d-$PID"
if (Test-Path $l2dRoot) { Remove-Item -Recurse -Force $l2dRoot }
New-Item -ItemType Directory -Force $l2dRoot | Out-Null
try {
  $l2dMain = Join-Path $l2dRoot 'main'
  $l2dWt = Join-Path $l2dRoot 'wt'
  New-Item -ItemType Directory -Force $l2dMain | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2dMain -Recurse -Force   # 同 2b/2c：整目录拷，免隐式漏 dot-source 依赖
  $l2dMainLedger = Join-Path $l2dMain 'docs/lessons/LEDGER.md'
  New-Item -ItemType Directory -Force (Split-Path $l2dMainLedger) | Out-Null
  $l2dEntry = @(
    '# 经验总账（LSN-PLANE-WORKTREE fixture）', '',
    '## L1',
    '- date: 2026-01-01 ｜ tags: seed ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 3',
    '- symptom: seed', '- root_cause: seed', '- rule: seed rule one', '- enforced_by: none（seed）', '- refs:'
  ) -join "`n"
  Set-Content $l2dMainLedger $l2dEntry -Encoding utf8
  $l2dGit = @('-c', 'user.name=selftest', '-c', 'user.email=selftest@example.invalid', '-c', 'commit.gpgsign=false')
  & git -C $l2dMain init -q 2>&1 | Out-Null
  & git -C $l2dMain @l2dGit add -A 2>&1 | Out-Null
  & git -C $l2dMain @l2dGit commit -qm 'lsn-plane fixture' 2>&1 | Out-Null
  & git -C $l2dMain @l2dGit worktree add -q --detach $l2dWt 2>&1 | Out-Null
  $l2dWtLedger = Join-Path $l2dWt 'docs/lessons/LEDGER.md'
  $l2dWtLessons = Join-Path $l2dWt 'scripts/lessons.ps1'
  if (-not (Test-Path $l2dWtLedger) -or -not (Test-Path $l2dWtLessons)) {
    Fail '闸2d 夹具：linked worktree 未检出 LEDGER/lessons.ps1（夹具自身坏了，非被测行为）。'
  }
  else {
    # (a) 从 worktree 跑 —— 账本必须落在主检出，worktree 那份一个字节都不许动。
    $l2dWtHashBefore = (Get-FileHash $l2dWtLedger -Algorithm SHA256).Hash
    $l2dOutA = (& pwsh -NoProfile -File $l2dWtLessons bump L1 2>&1 | Out-String)
    $l2dExitA = $LASTEXITCODE
    $l2dMainA = Get-Content $l2dMainLedger -Raw
    $l2dWtHashAfter = (Get-FileHash $l2dWtLedger -Algorithm SHA256).Hash
    $l2dTailA = ($l2dOutA -replace '\s+', ' ').Trim()
    if ($l2dExitA -ne 0) { Fail "闸2d(a)：从 linked worktree 跑 bump 非零退出（$l2dExitA）——不应发生。输出=$l2dTailA" }
    elseif ($l2dMainA -notmatch '(?m)^- date:.*?recurrence:\s*4\b') {
      Fail "闸2d(a)：从 linked worktree 跑 bump 后**主检出**账本 recurrence 未变为 4——写入平面仍绑在脚本所在检出（`$Ledger = `$PSScriptRoot/..），复发计数会随卡片分支走、被范围闸/R3 #7 当夹带改动拦掉而永久丢失。输出=$l2dTailA"
    }
    elseif ($l2dWtHashAfter -ne $l2dWtHashBefore) {
      Fail "闸2d(a)：bump 改动了 **worktree** 那份 LEDGER（SHA256 $l2dWtHashBefore -> $l2dWtHashAfter）——仓库级元数据不得进入卡片分支 diff。"
    }
    else {
      $l2dOutB = (& pwsh -NoProfile -File (Join-Path $l2dMain 'scripts/lessons.ps1') bump L1 2>&1 | Out-String)
      $l2dExitB = $LASTEXITCODE
      $l2dMainB = Get-Content $l2dMainLedger -Raw
      $l2dTailB = ($l2dOutB -replace '\s+', ' ').Trim()
      if ($l2dExitB -ne 0 -or $l2dMainB -notmatch '(?m)^- date:.*?recurrence:\s*5\b') {
        Fail "闸2d(b)：primary bump exit=$l2dExitB output=$l2dTailB"
      }
      else {
        # (d) git 失败但**往 stdout 吐了看似路径的东西** —— 只判空会当成解析成功、把账本指到一个不存在的
        #   检出上（R3 r2 #9）。_encoding.ps1 置 $PSNativeCommandUseErrorActionPreference = $false，原生非零
        #   **不抛**，try/catch 兜不住，必须显式取退出码。注入手法用 git shim（同本仓「diff 命令失败只信 git
        #   自身实现、须 shim 注入」的既有立场），不改被测代码。
        $l2dShim = Join-Path $l2dRoot 'shim'
        New-Item -ItemType Directory -Force $l2dShim | Out-Null
        $l2dMark = Join-Path $l2dShim 'invoked.txt'
        # 两个平台各备一份 shim：Windows 靠 PATHEXT 认 git.cmd，Unix 认**无扩展名且可执行**的 git。
        # 两份都落 marker，下面据此断言「shim 真被调用过」——否则在没被覆盖的平台上真 git 会成功、
        # recurrence 照样 5→6，本用例整个假绿（R3 r3 #6：此闸原先只在 Windows 上真跑到过回落路径）。
        Set-Content (Join-Path $l2dShim 'git.cmd') "@echo off`r`n> `"%~dp0invoked.txt`" echo invoked`r`necho C:\definitely\not\a\checkout\.git`r`nexit /b 1" -Encoding ascii
        $l2dSh = "#!/bin/sh`necho invoked > `"`$(dirname `"`$0`")/invoked.txt`"`necho /definitely/not/a/checkout/.git`nexit 1`n"
        [System.IO.File]::WriteAllText((Join-Path $l2dShim 'git'), $l2dSh, (New-Object System.Text.UTF8Encoding($false)))
        if (-not $IsWindows) { & chmod +x (Join-Path $l2dShim 'git') 2>&1 | Out-Null }
        $l2dPathOld = $env:PATH
        try {
          $env:PATH = "$l2dShim$([System.IO.Path]::PathSeparator)$l2dPathOld"
          $l2dOutD = (& pwsh -NoProfile -File (Join-Path $l2dMain 'scripts/lessons.ps1') bump L1 2>&1 | Out-String)
          $l2dExitD = $LASTEXITCODE
        }
        finally { $env:PATH = $l2dPathOld }
        $l2dMainD = Get-Content $l2dMainLedger -Raw
        $l2dTailD = ($l2dOutD -replace '\s+', ' ').Trim()
        if (-not (Test-Path $l2dMark)) {
          Fail "闸2d(d)：git shim 从未被调用（marker 缺席）——本用例在当前平台根本没跑到回落路径，recurrence 5→6 是**真 git 成功**的结果，断言假绿（R3 r3 #6）。Windows 需 git.cmd、Unix 需无扩展名且 chmod +x 的 git，且 shim 目录须在 PATH 首位（分隔符按 [System.IO.Path]::PathSeparator）。"
        }
        elseif ($l2dExitD -ne 0 -or $l2dMainD -notmatch '(?m)^- date:.*?recurrence:\s*6\b') {
          Fail "闸2d(d)：initial-probe fallback exit=$l2dExitD output=$l2dTailD"
        }
        else {
        $l2dHeadF = "$(& git -C $l2dMain rev-parse HEAD 2>$null)".Trim()
        foreach ($l2dCaseF in @(
          @{ Name = 'empty'; Outputs = @() },
          @{ Name = 'invalid-first'; Outputs = @('HEAD deadbeef') },
          @{ Name = 'contradictory-state'; Outputs = @("worktree $l2dMain", "HEAD $l2dHeadF", 'branch refs/heads/master', 'detached', '') }
        )) {
          $l2dCommonF = Join-Path $l2dMain '.git'
          $l2dCmdOutputF = (@($l2dCaseF.Outputs) | ForEach-Object { if ($_ -eq '') { "echo.`r`n" } else { "echo $_`r`n" } }) -join ''
          $l2dShOutputF = (@($l2dCaseF.Outputs) | ForEach-Object { "printf '%s\n' '$_'`n" }) -join ''
          $l2dCmdF = "@echo off`r`n> `"%~dp0invoked.txt`" echo invoked`r`necho %* | findstr /C:`"--git-common-dir`" >nul`r`nif not errorlevel 1 goto common`r`necho %* | findstr /C:`"worktree list --porcelain`" >nul`r`nif not errorlevel 1 goto worktree`r`nexit /b 2`r`n:common`r`necho $l2dCommonF`r`nexit /b 0`r`n:worktree`r`n${l2dCmdOutputF}exit /b 0`r`n"
          Set-Content (Join-Path $l2dShim 'git.cmd') $l2dCmdF -Encoding ascii
          $l2dSh = "#!/bin/sh`necho invoked > `"`$(dirname `"`$0`")/invoked.txt`"`ncase `"`$*`" in *`"--git-common-dir`"*) printf '%s\n' '$l2dCommonF'; exit 0;; *`"worktree list --porcelain`"*) ${l2dShOutputF}exit 0;; *) exit 2;; esac`n"
          [System.IO.File]::WriteAllText((Join-Path $l2dShim 'git'), $l2dSh, (New-Object System.Text.UTF8Encoding($false)))
          if (-not $IsWindows) { & chmod +x (Join-Path $l2dShim 'git') 2>&1 | Out-Null }
          Remove-Item -Force $l2dMark -ErrorAction SilentlyContinue
          $l2dMainHashPreF = (Get-FileHash $l2dMainLedger -Algorithm SHA256).Hash
          $l2dPathOld = $env:PATH
          try {
            $env:PATH = "$l2dShim$([System.IO.Path]::PathSeparator)$l2dPathOld"
            $l2dOutF = (& pwsh -NoProfile -File (Join-Path $l2dMain 'scripts/lessons.ps1') bump L1 2>&1 | Out-String)
            $l2dExitF = $LASTEXITCODE
          }
          finally { $env:PATH = $l2dPathOld }
          $l2dMainHashPostF = (Get-FileHash $l2dMainLedger -Algorithm SHA256).Hash
          $l2dTailF = ($l2dOutF -replace '\s+', ' ').Trim()
          if (-not (Test-Path $l2dMark)) {
            Fail "[LSN-PLANE-SUBMODULE] 闸2d(f/shim-$($l2dCaseF.Name))：git malformed-success shim 未被调用。"
          }
          elseif ($l2dExitF -eq 0 -or $l2dTailF -notmatch [regex]::Escape('[LSN-PLANE-UNRESOLVED]') -or $l2dMainHashPostF -ne $l2dMainHashPreF) {
            Fail "[LSN-PLANE-SUBMODULE] 闸2d(f/$($l2dCaseF.Name)) fail-closed/zero-write exit=$l2dExitF"
          }
        }

        $l2dCommonG = Join-Path $l2dMain '.git'
        $l2dCmdG = "@echo off`r`n> `"%~dp0invoked.txt`" echo invoked`r`necho %* | findstr /C:`"worktree list --porcelain`" >nul`r`nif not errorlevel 1 exit /b 2`r`necho $l2dCommonG`r`nexit /b 0`r`n"
        Set-Content (Join-Path $l2dShim 'git.cmd') $l2dCmdG -Encoding ascii
        $l2dSh = "#!/bin/sh`necho invoked > `"`$(dirname `"`$0`")/invoked.txt`"`ncase `"`$*`" in *`"worktree list --porcelain`"*) exit 2;; esac`nprintf '%s\n' '$l2dCommonG'`nexit 0`n"
        [System.IO.File]::WriteAllText((Join-Path $l2dShim 'git'), $l2dSh, (New-Object System.Text.UTF8Encoding($false)))
        if (-not $IsWindows) { & chmod +x (Join-Path $l2dShim 'git') 2>&1 | Out-Null }
        Remove-Item -Force $l2dMark -ErrorAction SilentlyContinue
        $l2dMainHashPreG = (Get-FileHash $l2dMainLedger -Algorithm SHA256).Hash
        $l2dPathOld = $env:PATH
        try {
          $env:PATH = "$l2dShim$([System.IO.Path]::PathSeparator)$l2dPathOld"
          $l2dOutG = (& pwsh -NoProfile -File (Join-Path $l2dMain 'scripts/lessons.ps1') bump L1 2>&1 | Out-String)
          $l2dExitG = $LASTEXITCODE
        }
        finally { $env:PATH = $l2dPathOld }
        $l2dMainHashPostG = (Get-FileHash $l2dMainLedger -Algorithm SHA256).Hash
        $l2dTailG = ($l2dOutG -replace '\s+', ' ').Trim()
        if (-not (Test-Path $l2dMark) -or $l2dExitG -eq 0 -or
            $l2dTailG -notmatch [regex]::Escape('[LSN-PLANE-UNRESOLVED]') -or $l2dMainHashPostG -ne $l2dMainHashPreG) {
          Fail "[LSN-PLANE-SUBMODULE] 闸2d(g/later-command) fail-closed/zero-write exit=$l2dExitG"
        }

        $l2dHeadH = "$(& git -C $l2dMain rev-parse HEAD 2>$null)".Trim()
        $l2dConfigMarkH = Join-Path $l2dShim 'config-invoked.txt'
        foreach ($l2dCaseH in @(
          @{ Name = 'empty-config'; Outputs = @() },
          @{ Name = 'duplicate-config'; Outputs = @($l2dMain, $l2dWt) }
        )) {
          $l2dCmdConfigH = (@($l2dCaseH.Outputs) | ForEach-Object { "echo $_`r`n" }) -join ''
          $l2dShConfigH = (@($l2dCaseH.Outputs) | ForEach-Object { "printf '%s\n' '$_'`n" }) -join ''
          $l2dCmdH = "@echo off`r`n> `"%~dp0invoked.txt`" echo invoked`r`necho %* | findstr /C:`"--git-common-dir`" >nul`r`nif not errorlevel 1 goto common`r`necho %* | findstr /C:`"worktree list --porcelain`" >nul`r`nif not errorlevel 1 goto worktree`r`necho %* | findstr /C:`"config --local --get-all core.worktree`" >nul`r`nif not errorlevel 1 goto config`r`nexit /b 2`r`n:common`r`necho $l2dCommonG`r`nexit /b 0`r`n:worktree`r`necho worktree $l2dMain`r`necho HEAD $l2dHeadH`r`necho branch refs/heads/master`r`necho.`r`nexit /b 0`r`n:config`r`n> `"%~dp0config-invoked.txt`" echo config`r`n${l2dCmdConfigH}exit /b 0`r`n"
          Set-Content (Join-Path $l2dShim 'git.cmd') $l2dCmdH -Encoding ascii
          $l2dSh = "#!/bin/sh`necho invoked > `"`$(dirname `"`$0`")/invoked.txt`"`ncase `"`$*`" in *`"--git-common-dir`"*) printf '%s\n' '$l2dCommonG'; exit 0;; *`"worktree list --porcelain`"*) printf '%s\n' 'worktree $l2dMain' 'HEAD $l2dHeadH' 'branch refs/heads/master' ''; exit 0;; *`"config --local --get-all core.worktree`"*) echo config > `"`$(dirname `"`$0`")/config-invoked.txt`"; ${l2dShConfigH}exit 0;; *) exit 2;; esac`n"
          [System.IO.File]::WriteAllText((Join-Path $l2dShim 'git'), $l2dSh, (New-Object System.Text.UTF8Encoding($false)))
          if (-not $IsWindows) { & chmod +x (Join-Path $l2dShim 'git') 2>&1 | Out-Null }
          Remove-Item -Force $l2dMark, $l2dConfigMarkH -ErrorAction SilentlyContinue
          $l2dMainHashPreH = (Get-FileHash $l2dMainLedger -Algorithm SHA256).Hash
          $l2dPathOld = $env:PATH
          try {
            $env:PATH = "$l2dShim$([System.IO.Path]::PathSeparator)$l2dPathOld"
            $l2dOutH = (& pwsh -NoProfile -File (Join-Path $l2dMain 'scripts/lessons.ps1') bump L1 2>&1 | Out-String)
            $l2dExitH = $LASTEXITCODE
          }
          finally { $env:PATH = $l2dPathOld }
          $l2dMainHashPostH = (Get-FileHash $l2dMainLedger -Algorithm SHA256).Hash
          $l2dTailH = ($l2dOutH -replace '\s+', ' ').Trim()
          if (-not (Test-Path $l2dMark) -or -not (Test-Path $l2dConfigMarkH) -or $l2dExitH -eq 0 -or
              $l2dTailH -notmatch [regex]::Escape('[LSN-PLANE-UNRESOLVED]') -or $l2dMainHashPostH -ne $l2dMainHashPreH) {
            Fail "[LSN-PLANE-SUBMODULE] 闸2d(h/$($l2dCaseH.Name)) fail-closed/zero-write exit=$l2dExitH"
          }
        }

        # (e) 继承的 GIT_COMMON_DIR 不得劫持写入平面（R3 预审 #1）：git 执行 hook 时本就会设 GIT_DIR，
        #   这类变量会盖过 -C，未清理时解析会落到**另一个仓库**、把计数静默加到别人的账本上。
        #   夹具造第二个仓（自带同路径账本，故「误写」确实能成功），设 GIT_COMMON_DIR 指向它再跑 bump：
        #   断言本仓账本 6→7 且**另一个仓的账本逐字节不变**。未修版本会去加另一个仓的那份。
        $l2dOther = Join-Path $l2dRoot 'other'
        $l2dOtherLedger = Join-Path $l2dOther 'docs/lessons/LEDGER.md'
        New-Item -ItemType Directory -Force (Split-Path $l2dOtherLedger) | Out-Null
        Set-Content $l2dOtherLedger $l2dEntry -Encoding utf8
        & git -C $l2dOther init -q 2>&1 | Out-Null
        $l2dOtherPre = (Get-FileHash $l2dOtherLedger -Algorithm SHA256).Hash
        $l2dGcdOld = [Environment]::GetEnvironmentVariable('GIT_COMMON_DIR')
        try {
          $env:GIT_COMMON_DIR = (Join-Path $l2dOther '.git')
          $l2dOutE = (& pwsh -NoProfile -File (Join-Path $l2dMain 'scripts/lessons.ps1') bump L1 2>&1 | Out-String)
          $l2dExitE = $LASTEXITCODE
        }
        finally {
          if ($null -eq $l2dGcdOld) { Remove-Item Env:GIT_COMMON_DIR -ErrorAction SilentlyContinue }
          else { $env:GIT_COMMON_DIR = $l2dGcdOld }
        }
        $l2dOtherPost = (Get-FileHash $l2dOtherLedger -Algorithm SHA256).Hash
        $l2dMainE = Get-Content $l2dMainLedger -Raw
        $l2dTailE = ($l2dOutE -replace '\s+', ' ').Trim()
        if ($l2dOtherPost -ne $l2dOtherPre) {
          Fail "闸2d(e)：继承的 GIT_COMMON_DIR 劫持了写入平面——bump 把计数加到了**另一个仓库**的账本上（SHA256 $l2dOtherPre -> $l2dOtherPost）。解析前须清 GIT_DIR/GIT_COMMON_DIR/GIT_WORK_TREE。输出=$l2dTailE"
        }
        elseif ($l2dExitE -ne 0 -or $l2dMainE -notmatch '(?m)^- date:.*?recurrence:\s*7\b') {
          Fail "闸2d(e)：设了 GIT_COMMON_DIR 后 bump 未能正常写本仓账本（exit=$l2dExitE，期望 recurrence 7）——清理环境变量不应把正常路径一并弄坏。输出=$l2dTailE"
        }

        # (c) 主检出账本缺失 —— 必须 fail-closed，绝不回落到 worktree 那份（回落＝本闸要修的 bug 原样复活）。
        Remove-Item -Force $l2dMainLedger
        $l2dWtHashPreC = (Get-FileHash $l2dWtLedger -Algorithm SHA256).Hash
        $l2dOutC = (& pwsh -NoProfile -File $l2dWtLessons bump L1 2>&1 | Out-String)
        $l2dExitC = $LASTEXITCODE
        $l2dTailC = ($l2dOutC -replace '\s+', ' ').Trim()
        $l2dWtHashPostC = (Get-FileHash $l2dWtLedger -Algorithm SHA256).Hash
        if ($l2dWtHashPostC -ne $l2dWtHashPreC) {
          Fail "闸2d(c)：主检出账本缺失时 bump 仍写了 **worktree** 那份账本（SHA256 $l2dWtHashPreC -> $l2dWtHashPostC）——先写回落账本再抛 [LSN-PLANE-UNRESOLVED] 同样违约：禁止的是那次写入，不只是那个退出码（R3 预审 #3）。"
        }
        elseif ($l2dExitC -eq 0) { Fail "闸2d(c)：主检出账本缺失时 bump 仍退出 0——静默回落到当前检出的账本，正是本闸要根治的形态。输出=$l2dTailC" }
        elseif ($l2dTailC -notmatch [regex]::Escape('[LSN-PLANE-UNRESOLVED]')) {
          Fail "闸2d(c)：主检出账本缺失时 bump 虽非零退出，但未打印 ASCII 失败码 [LSN-PLANE-UNRESOLVED]（机检认哨兵、不认本地化文案，L165）。输出=$l2dTailC"
        }
        else { Write-Host '  2d lessons bump plane/fail-closed checks OK' -ForegroundColor Green }
        }
      }
    }
  }
}
finally {
  & git -C $l2dMain worktree remove --force $l2dWt 2>&1 | Out-Null
  Remove-Item -Recurse -Force $l2dRoot -ErrorAction SilentlyContinue
}

# 当前 2ds：真实 submodule 覆盖 common-dir 首条 + local core.worktree + 反向同仓验证及全平面零写入。
Step '2ds/17 lessons.ps1 submodule 主检出写入平面（TD145）'
$l2dSubRoot = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold lessons2d-submodule-$PID"
$l2dSubSeed = Join-Path $l2dSubRoot 'seed'
$l2dSubSuper = Join-Path $l2dSubRoot 'super project'
$l2dSubCheckout = Join-Path $l2dSubSuper 'nested module'
$l2dSubLinked = Join-Path $l2dSubRoot 'submodule linked checkout'
try {
  if (Test-Path $l2dSubRoot) { Remove-Item -Recurse -Force -LiteralPath $l2dSubRoot }
  New-Item -ItemType Directory -Force (Join-Path $l2dSubSeed 'docs/lessons'), (Join-Path $l2dSubSeed 'specs/archive'),
    (Join-Path $l2dSubSuper 'docs/lessons') | Out-Null
  Copy-Item (Join-Path $RepoRoot 'scripts') $l2dSubSeed -Recurse -Force
  $l2dSubEntry = @(
    '# submodule ledger ([LSN-PLANE-SUBMODULE] fixture)', '',
    '## L1',
    '- date: 2026-01-01 ｜ tags: seed ｜ tier: ledger ｜ kind: pitfall ｜ severity: minor ｜ recurrence: 3',
    '- symptom: seed', '- root_cause: seed', '- rule: seed rule', '- enforced_by: none（seed）', '- refs:'
  ) -join "`n"
  $l2dSubSeedLedger = Join-Path $l2dSubSeed 'docs/lessons/LEDGER.md'
  Set-Content -LiteralPath $l2dSubSeedLedger -Value $l2dSubEntry -Encoding utf8
  Set-Content -LiteralPath (Join-Path $l2dSubSeed 'specs/archive/lessons-archive.md') -Value '# archive' -Encoding utf8
  $l2dSubGit = @('-c', 'user.name=selftest', '-c', 'user.email=selftest@example.invalid', '-c', 'commit.gpgsign=false')
  & git -C $l2dSubSeed init -q 2>&1 | Out-Null
  & git -C $l2dSubSeed @l2dSubGit add -A 2>&1 | Out-Null
  & git -C $l2dSubSeed @l2dSubGit commit -qm 'submodule seed' 2>&1 | Out-Null
  $l2dSubSeedOk = ($LASTEXITCODE -eq 0)

  $l2dSuperLedger = Join-Path $l2dSubSuper 'docs/lessons/LEDGER.md'
  Set-Content -LiteralPath $l2dSuperLedger -Value '# superproject ledger must stay byte-identical' -Encoding utf8
  & git -C $l2dSubSuper init -q 2>&1 | Out-Null
  & git -C $l2dSubSuper @l2dSubGit add -A 2>&1 | Out-Null
  & git -C $l2dSubSuper @l2dSubGit commit -qm 'superproject seed' 2>&1 | Out-Null
  $l2dSubAddOut = (& git -C $l2dSubSuper -c protocol.file.allow=always submodule add -q $l2dSubSeed 'nested module' 2>&1 | Out-String)
  $l2dSubAddOk = ($LASTEXITCODE -eq 0)
  $l2dSubCommitOk = $false
  if ($l2dSubAddOk) {
    & git -C $l2dSubSuper @l2dSubGit add -A 2>&1 | Out-Null
    & git -C $l2dSubSuper @l2dSubGit commit -qm 'add nested module' 2>&1 | Out-Null
    $l2dSubCommitOk = ($LASTEXITCODE -eq 0)
  }
  $l2dSubWtOut = ''
  $l2dSubWtOk = $false
  if ($l2dSubCommitOk) {
    $l2dSubWtOut = (& git -C $l2dSubCheckout worktree add -q --detach $l2dSubLinked 2>&1 | Out-String)
    $l2dSubWtOk = ($LASTEXITCODE -eq 0)
  }
  $l2dSubSetupOk = $l2dSubSeedOk -and $l2dSubAddOk -and $l2dSubCommitOk -and $l2dSubWtOk
  $l2dSubLedger = Join-Path $l2dSubCheckout 'docs/lessons/LEDGER.md'
  $l2dSubLessons = Join-Path $l2dSubCheckout 'scripts/lessons.ps1'
  $l2dSubLinkedLedger = Join-Path $l2dSubLinked 'docs/lessons/LEDGER.md'
  $l2dSubLinkedLessons = Join-Path $l2dSubLinked 'scripts/lessons.ps1'
  if (-not $l2dSubSetupOk -or -not (Test-Path $l2dSubLedger) -or -not (Test-Path $l2dSubLessons) -or
      -not (Test-Path $l2dSubLinkedLedger) -or -not (Test-Path $l2dSubLinkedLessons)) {
    Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/setup)'
  }
  else {
    $l2dSubBefore = Get-Content -LiteralPath $l2dSubLedger -Raw
    $l2dSubExpected = [regex]::Replace($l2dSubBefore, '(?m)(^-[ \t]+date:.*?recurrence[ \t]*:[ \t]*)3\b', '${1}4', 1)
    $l2dSubSuperHash = (Get-FileHash -LiteralPath $l2dSuperLedger -Algorithm SHA256).Hash
    $l2dSubSeedHash = (Get-FileHash -LiteralPath $l2dSubSeedLedger -Algorithm SHA256).Hash
    $l2dSubLinkedHashBeforePrimary = (Get-FileHash -LiteralPath $l2dSubLinkedLedger -Algorithm SHA256).Hash
    $l2dSubSuperTreeBaseline = Get-Td145OutsideFileHashMap -Root $l2dSubSuper -ExcludedRoots @($l2dSubCheckout)
    if (-not $l2dSubSuperTreeBaseline.ContainsKey('.gitmodules')) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/super-tree-fixture)'
    }
    $l2dSubCommon = "$(& git -C $l2dSubCheckout rev-parse --git-common-dir 2>$null)".Trim()
    $l2dSubInternalLedger = Join-Path $l2dSubCommon 'docs/lessons/LEDGER.md'
    if (-not [System.IO.Path]::IsPathFullyQualified($l2dSubCommon) -or (Test-Path -LiteralPath $l2dSubInternalLedger)) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/common-fixture)'
    }
    $null = (& pwsh -NoProfile -File $l2dSubLessons bump L1 2>&1 | Out-String)
    $l2dSubExit = $LASTEXITCODE
    $l2dSubAfter = Get-Content -LiteralPath $l2dSubLedger -Raw
    if ($l2dSubExit -ne 0 -or $l2dSubAfter -cne $l2dSubExpected) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/target)'
    }
    if ((Get-FileHash -LiteralPath $l2dSubLinkedLedger -Algorithm SHA256).Hash -ne $l2dSubLinkedHashBeforePrimary) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/primary-linked-zero-write)'
    }
    if ((Get-FileHash -LiteralPath $l2dSuperLedger -Algorithm SHA256).Hash -ne $l2dSubSuperHash) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/primary-super-zero-write)'
    }
    if ((Get-FileHash -LiteralPath $l2dSubSeedLedger -Algorithm SHA256).Hash -ne $l2dSubSeedHash) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/primary-source-zero-write)'
    }
    $l2dSubSuperTreeAfterPrimary = Get-Td145OutsideFileHashMap -Root $l2dSubSuper -ExcludedRoots @($l2dSubCheckout)
    if (-not (Test-Td145FileHashMapEqual -Expected $l2dSubSuperTreeBaseline -Actual $l2dSubSuperTreeAfterPrimary)) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/primary-super-tree-zero-write)'
    }
    if (Test-Path -LiteralPath $l2dSubInternalLedger) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/primary-internal-zero-write)'
    }

    $l2dSubLinkedHashBeforeLinked = (Get-FileHash -LiteralPath $l2dSubLinkedLedger -Algorithm SHA256).Hash
    $l2dSubExpectedLinked = [regex]::Replace($l2dSubAfter, '(?m)(^-[ \t]+date:.*?recurrence[ \t]*:[ \t]*)4\b', '${1}5', 1)
    $l2dSubHijackSaved = @{}
    foreach ($l2dSubEnv in @('GIT_DIR', 'GIT_COMMON_DIR', 'GIT_WORK_TREE', 'GIT_CONFIG_COUNT', 'GIT_CONFIG_KEY_0', 'GIT_CONFIG_VALUE_0', 'GIT_CONFIG_PARAMETERS')) {
      $l2dSubHijackSaved[$l2dSubEnv] = [Environment]::GetEnvironmentVariable($l2dSubEnv)
    }
    $l2dSubConfigParametersEffective = $false
    try {
      $env:GIT_CONFIG_PARAMETERS = 'TD145_INVALID_CONFIG_PARAMETERS'
      & git -C $l2dSubLinked rev-parse --git-common-dir 2>$null | Out-Null
      $l2dSubConfigParametersEffective = ($LASTEXITCODE -ne 0)
      $env:GIT_DIR = Join-Path $l2dSubSuper '.git'
      $env:GIT_COMMON_DIR = Join-Path $l2dSubSuper '.git'
      $env:GIT_WORK_TREE = $l2dSubSuper
      $env:GIT_CONFIG_COUNT = '1'
      $env:GIT_CONFIG_KEY_0 = 'core.worktree'
      $env:GIT_CONFIG_VALUE_0 = $l2dSubSeed
      $null = (& pwsh -NoProfile -File $l2dSubLinkedLessons bump L1 2>&1 | Out-String)
      $l2dSubLinkedExit = $LASTEXITCODE
    }
    finally {
      foreach ($l2dSubEnv in $l2dSubHijackSaved.Keys) {
        if ($null -eq $l2dSubHijackSaved[$l2dSubEnv]) { Remove-Item "Env:$l2dSubEnv" -ErrorAction SilentlyContinue }
        else { Set-Item "Env:$l2dSubEnv" $l2dSubHijackSaved[$l2dSubEnv] }
      }
    }
    $l2dSubAfterLinked = Get-Content -LiteralPath $l2dSubLedger -Raw
    if (-not $l2dSubConfigParametersEffective -or $l2dSubLinkedExit -ne 0 -or $l2dSubAfterLinked -cne $l2dSubExpectedLinked) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/linked-target)'
    }
    if ((Get-FileHash -LiteralPath $l2dSubLinkedLedger -Algorithm SHA256).Hash -ne $l2dSubLinkedHashBeforeLinked) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/linked-zero-write)'
    }
    if ((Get-FileHash -LiteralPath $l2dSuperLedger -Algorithm SHA256).Hash -ne $l2dSubSuperHash) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/linked-super-zero-write)'
    }
    if ((Get-FileHash -LiteralPath $l2dSubSeedLedger -Algorithm SHA256).Hash -ne $l2dSubSeedHash) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/linked-source-zero-write)'
    }
    $l2dSubSuperTreeAfterLinked = Get-Td145OutsideFileHashMap -Root $l2dSubSuper -ExcludedRoots @($l2dSubCheckout)
    if (-not (Test-Td145FileHashMapEqual -Expected $l2dSubSuperTreeBaseline -Actual $l2dSubSuperTreeAfterLinked)) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/linked-super-tree-zero-write)'
    }
    if (Test-Path -LiteralPath $l2dSubInternalLedger) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/linked-internal-zero-write)'
    }

    $l2dSubCoreOriginalLines = @(& git --git-dir $l2dSubCommon config --get-all core.worktree 2>$null)
    $l2dSubCoreOriginalOk = ($LASTEXITCODE -eq 0 -and $l2dSubCoreOriginalLines.Count -eq 1 -and "$($l2dSubCoreOriginalLines[0])")
    $l2dSubCoreOriginal = if ($l2dSubCoreOriginalOk) { "$($l2dSubCoreOriginalLines[0])" } else { '' }
    $l2dSubOther = Join-Path $l2dSubRoot 'other repository'
    $l2dSubOtherLedger = Join-Path $l2dSubOther 'docs/lessons/LEDGER.md'
    New-Item -ItemType Directory -Force (Split-Path $l2dSubOtherLedger) | Out-Null
    Set-Content -LiteralPath $l2dSubOtherLedger -Value ($l2dSubEntry -replace 'recurrence: 3', 'recurrence: 9') -Encoding utf8
    & git -C $l2dSubOther init -q 2>&1 | Out-Null
    $l2dSubOtherSetupOk = ($LASTEXITCODE -eq 0)
    & git -C $l2dSubOther @l2dSubGit add -A 2>&1 | Out-Null
    $l2dSubOtherSetupOk = $l2dSubOtherSetupOk -and ($LASTEXITCODE -eq 0)
    & git -C $l2dSubOther @l2dSubGit commit -qm 'other repository' 2>&1 | Out-Null
    $l2dSubOtherSetupOk = $l2dSubOtherSetupOk -and ($LASTEXITCODE -eq 0)
    $l2dSubOtherHead = "$(& git -C $l2dSubOther rev-parse --verify HEAD 2>$null)".Trim()
    $l2dSubOtherSetupOk = $l2dSubOtherSetupOk -and ($LASTEXITCODE -eq 0) -and $l2dSubOtherHead -and (Test-Path -LiteralPath $l2dSubOtherLedger)
    $l2dSubPrimaryHashPreCross = (Get-FileHash -LiteralPath $l2dSubLedger -Algorithm SHA256).Hash
    $l2dSubLinkedHashPreCross = (Get-FileHash -LiteralPath $l2dSubLinkedLedger -Algorithm SHA256).Hash
    $l2dSubOtherHashPreCross = (Get-FileHash -LiteralPath $l2dSubOtherLedger -Algorithm SHA256).Hash
    $l2dSubRestoreRc = 1
    $l2dSubCoreRewriteRc = 1
    $l2dSubCrossExit = 0
    $l2dSubCrossOut = ''
    try {
      & git --git-dir $l2dSubCommon config core.worktree $l2dSubOther 2>&1 | Out-Null
      $l2dSubCoreRewriteRc = $LASTEXITCODE
      $l2dSubCoreReadback = "$(& git --git-dir $l2dSubCommon config --get core.worktree 2>$null)".Trim()
      $l2dSubCoreRewriteOk = ($l2dSubCoreRewriteRc -eq 0 -and $LASTEXITCODE -eq 0 -and $l2dSubCoreReadback -ceq $l2dSubOther)
      if ($l2dSubCoreOriginalOk -and $l2dSubOtherSetupOk -and $l2dSubCoreRewriteOk) {
        $l2dSubCrossOut = (& pwsh -NoProfile -File $l2dSubLinkedLessons bump L1 2>&1 | Out-String)
        $l2dSubCrossExit = $LASTEXITCODE
      }
    }
    finally {
      & git --git-dir $l2dSubCommon config core.worktree $l2dSubCoreOriginal 2>&1 | Out-Null
      $l2dSubRestoreRc = $LASTEXITCODE
      $l2dSubRestoredValue = "$(& git --git-dir $l2dSubCommon config --get core.worktree 2>$null)".Trim()
      $l2dSubRestoreOk = ($l2dSubRestoreRc -eq 0 -and $LASTEXITCODE -eq 0 -and $l2dSubRestoredValue -ceq $l2dSubCoreOriginal)
    }
    $l2dSubCrossTail = ($l2dSubCrossOut -replace '\s+', ' ').Trim()
    if (-not $l2dSubCoreOriginalOk -or -not $l2dSubOtherSetupOk -or -not $l2dSubCoreRewriteOk -or -not $l2dSubRestoreOk -or
        $l2dSubCrossExit -eq 0 -or $l2dSubCrossTail -notmatch [regex]::Escape('[LSN-PLANE-UNRESOLVED]') -or
        (Get-FileHash -LiteralPath $l2dSubLedger -Algorithm SHA256).Hash -ne $l2dSubPrimaryHashPreCross -or
        (Get-FileHash -LiteralPath $l2dSubLinkedLedger -Algorithm SHA256).Hash -ne $l2dSubLinkedHashPreCross -or
        (Get-FileHash -LiteralPath $l2dSubOtherLedger -Algorithm SHA256).Hash -ne $l2dSubOtherHashPreCross) {
      Fail "[LSN-PLANE-SUBMODULE] 闸2d(s/cross-repo) exit=$l2dSubCrossExit"
    }
    if (Test-Path -LiteralPath $l2dSubInternalLedger) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/internal-zero-write)'
    }
    if ((Get-FileHash -LiteralPath $l2dSuperLedger -Algorithm SHA256).Hash -ne $l2dSubSuperHash) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/super-zero-write)'
    }
    if ((Get-FileHash -LiteralPath $l2dSubSeedLedger -Algorithm SHA256).Hash -ne $l2dSubSeedHash) {
      Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/source-zero-write)'
    }

    $l2dSubWriteAnchor = 'Set-Content -Path $BumpLedger -Value $raw -Encoding utf8 -NoNewline'
    $l2dSubOwnershipMarker = ('TD145-BEHAVIOR/' + 'linked-zero-write')
    $l2dSubSuperMarker = ('TD145-BEHAVIOR/' + 'super-tree-zero-write')
    $l2dSubPrimaryAnchor = ('$mainCheckout = [System.IO.Path]::GetFullPath((Join-Path $commonDir ' + '$coreWorktree))')
    $l2dSubConfigProbe = '$coreWorktreeLines = @(& git -C $Root config --local --get-all core.worktree 2>$null)'
    $l2dSubTopProbe = '$topLines = @(& git -C $mainCheckout rev-parse --show-toplevel 2>$null)'
    $l2dSubCommonProbe = '$candidateCommonLines = @(& git -C $mainCheckout rev-parse --git-common-dir 2>$null)'
    $l2dSubRedCase = { param($id,$anchor,$replacement) [PSCustomObject]@{ Id=$id; Expect='red'; Marker='TD145-BEHAVIOR/target'; Edits=@([PSCustomObject]@{ Target='lessons.ps1'; Mode='replace'; Anchor=$anchor; Replacement=$replacement }) } }
    $l2dSubOwnershipFault = $l2dSubWriteAnchor + "`n    Set-Content -Path `$Ledger -Value `$raw -Encoding utf8 -NoNewline"
    $l2dSubSuperFault = $l2dSubWriteAnchor + "`n    Set-Content -Path (Join-Path (Split-Path -Parent `$BumpRoot) 'docs/lessons/LEDGER.md') -Value 'TD145 bad super write' -Encoding utf8"
    $l2dSubMutationCases = @(
      [PSCustomObject]@{ Id='baseline'; Expect='green'; Marker=''; Edits=@() },
      [PSCustomObject]@{ Id='primary-resolution-delete'; Expect='red'; Marker='TD145-BEHAVIOR/target'; Edits=@(
        [PSCustomObject]@{ Target='lessons.ps1'; Mode='delete-line'; Anchor=$l2dSubPrimaryAnchor; Replacement='' }
      ) },
      (& $l2dSubRedCase 'config-fail' $l2dSubConfigProbe '$coreWorktreeLines = @(& git -C $Root config --local --get-all 2>$null)'),
      (& $l2dSubRedCase 'top-fail' $l2dSubTopProbe '$topLines = @(& git -C $mainCheckout rev-parse --verify refs/heads/TD145-MISSING 2>$null)'),
      (& $l2dSubRedCase 'top-ambiguous' $l2dSubTopProbe ($l2dSubTopProbe + '; $topLines = @($mainCheckout, $mainCheckout)')),
      (& $l2dSubRedCase 'common-fail' $l2dSubCommonProbe '$candidateCommonLines = @(& git -C $mainCheckout rev-parse --verify refs/heads/TD145-MISSING 2>$null)'),
      (& $l2dSubRedCase 'common-ambiguous' $l2dSubCommonProbe ($l2dSubCommonProbe + '; $candidateCommonLines = @($commonDir, $commonDir)')),
      (& $l2dSubRedCase 'common-internal' $l2dSubPrimaryAnchor ("`$coreWorktree = 'internal'`n        $l2dSubPrimaryAnchor")),
      [PSCustomObject]@{ Id='ownership-fault'; Expect='red'; Marker=$l2dSubOwnershipMarker; Edits=@(
        [PSCustomObject]@{ Target='lessons.ps1'; Mode='replace'; Anchor=$l2dSubWriteAnchor; Replacement=$l2dSubOwnershipFault }
      ) },
      [PSCustomObject]@{ Id='ownership-survivor'; Expect='green'; Marker=''; Edits=@(
        [PSCustomObject]@{ Target='lessons.ps1'; Mode='replace'; Anchor=$l2dSubWriteAnchor; Replacement=$l2dSubOwnershipFault },
        [PSCustomObject]@{ Target='selftest.ps1'; Mode='delete-line'; Anchor=$l2dSubOwnershipMarker; Replacement='' }
      ) },
      [PSCustomObject]@{ Id='super-zero-write-fault'; Expect='red'; Marker=$l2dSubSuperMarker; Edits=@(
        [PSCustomObject]@{ Target='lessons.ps1'; Mode='replace'; Anchor=$l2dSubWriteAnchor; Replacement=$l2dSubSuperFault }
      ) },
      [PSCustomObject]@{ Id='super-zero-write-survivor'; Expect='green'; Marker=''; Edits=@(
        [PSCustomObject]@{ Target='lessons.ps1'; Mode='replace'; Anchor=$l2dSubWriteAnchor; Replacement=$l2dSubSuperFault },
        [PSCustomObject]@{ Target='selftest.ps1'; Mode='delete-line'; Anchor=$l2dSubSuperMarker; Replacement='' }
      ) }
    )
    foreach ($l2dSubMutationCase in $l2dSubMutationCases) {
      $l2dSubMutationRoot = Join-Path ([System.IO.Path]::GetTempPath()) "td145-behavior-mutant-$($l2dSubMutationCase.Id)-$PID-$([guid]::NewGuid().ToString('N'))"
      $l2dSubMutationBytes = @{}
      $l2dSubMutationHashes = @{}
      $l2dSubMutationRestored = $true
      $l2dSubMutationExit = 0
      $l2dSubMutationOut = ''
      $l2dSubMutationError = ''
      try {
        New-Item -ItemType Directory -Force $l2dSubMutationRoot | Out-Null
        Copy-Item -LiteralPath (Join-Path $RepoRoot 'scripts') -Destination (Join-Path $l2dSubMutationRoot 'scripts') -Recurse -Force
        foreach ($l2dSubMutationEdit in $l2dSubMutationCase.Edits) {
          $l2dSubMutationTarget = Join-Path $l2dSubMutationRoot "scripts/$($l2dSubMutationEdit.Target)"
          if (-not $l2dSubMutationBytes.ContainsKey($l2dSubMutationTarget)) {
            $l2dSubMutationBytes[$l2dSubMutationTarget] = [System.IO.File]::ReadAllBytes($l2dSubMutationTarget)
            $l2dSubMutationHashes[$l2dSubMutationTarget] = (Get-FileHash -LiteralPath $l2dSubMutationTarget -Algorithm SHA256).Hash
          }
          $l2dSubMutationSource = [System.IO.File]::ReadAllText($l2dSubMutationTarget)
          if ($l2dSubMutationEdit.Mode -eq 'delete-line') {
            $l2dSubMutationPattern = '(?m)^[^\r\n]*' + [regex]::Escape($l2dSubMutationEdit.Anchor) + '[^\r\n]*(?:\r?\n|$)'
            $l2dSubMutationMatches = @([regex]::Matches($l2dSubMutationSource, $l2dSubMutationPattern))
            if ($l2dSubMutationMatches.Count -ne 1) { throw "delete anchor=$($l2dSubMutationCase.Id) count=$($l2dSubMutationMatches.Count)" }
            $l2dSubMutationSource = [regex]::new($l2dSubMutationPattern).Replace($l2dSubMutationSource, '', 1)
          }
          else {
            $l2dSubMutationMatches = @([regex]::Matches($l2dSubMutationSource, [regex]::Escape($l2dSubMutationEdit.Anchor)))
            if ($l2dSubMutationMatches.Count -ne 1) { throw "replace anchor=$($l2dSubMutationCase.Id) count=$($l2dSubMutationMatches.Count)" }
            $l2dSubMutationSource = $l2dSubMutationSource.Replace($l2dSubMutationEdit.Anchor, $l2dSubMutationEdit.Replacement)
          }
          [System.IO.File]::WriteAllText($l2dSubMutationTarget, $l2dSubMutationSource, [System.Text.UTF8Encoding]::new($false))
        }
        $l2dSubMutationOut = (& pwsh -NoProfile -File (Join-Path $l2dSubMutationRoot 'scripts/selftest.ps1') -Shard core -Fixture td145-behavior-fixture 2>&1 | Out-String)
        $l2dSubMutationExit = $LASTEXITCODE
      }
      catch { $l2dSubMutationError = $_.Exception.Message }
      finally {
        foreach ($l2dSubMutationTarget in $l2dSubMutationBytes.Keys) {
          [System.IO.File]::WriteAllBytes($l2dSubMutationTarget, $l2dSubMutationBytes[$l2dSubMutationTarget])
          if ((Get-FileHash -LiteralPath $l2dSubMutationTarget -Algorithm SHA256).Hash -cne $l2dSubMutationHashes[$l2dSubMutationTarget]) {
            $l2dSubMutationRestored = $false
          }
        }
        Remove-Item -LiteralPath $l2dSubMutationRoot -Recurse -Force -ErrorAction SilentlyContinue
      }
      $l2dSubBehaviorFailures = @($l2dSubMutationOut -split '\r?\n' | ForEach-Object {
        $l2dSubBehaviorMatch = [regex]::Match($_, '^\[LSN-PLANE-SUBMODULE\][ \t]+(?<id>TD145-BEHAVIOR/[^ \t\r\n]+)')
        if ($l2dSubBehaviorMatch.Success) { $l2dSubBehaviorMatch.Groups['id'].Value }
      })
      $l2dSubExactRed = ($l2dSubBehaviorFailures.Count -eq 1 -and $l2dSubBehaviorFailures[0] -ceq $l2dSubMutationCase.Marker)
      if ($l2dSubMutationCase.Id -eq 'primary-resolution-delete') { $l2dSubExactRed = ($l2dSubBehaviorFailures -join ',') -ceq 'TD145-BEHAVIOR/target,TD145-BEHAVIOR/target-class' }
      $l2dSubMutationRedOk = ($l2dSubMutationCase.Expect -eq 'red' -and $l2dSubMutationExit -ne 0 -and $l2dSubExactRed -and
        $l2dSubMutationOut -match '(?m)^\[SELFTEST-FAILED-GATES\] shard=core gates=2ds\r?$')
      $l2dSubMutationGreenOk = ($l2dSubMutationCase.Expect -eq 'green' -and $l2dSubMutationExit -eq 0 -and
        $l2dSubBehaviorFailures.Count -eq 0 -and $l2dSubMutationOut -match '(?m)^\[TD145-BEHAVIOR\] PASS\r?$' -and
        $l2dSubMutationOut -notmatch '(?m)^\[SELFTEST-FAILED-GATES\]')
      if ($l2dSubMutationError) {
        Fail "[LSN-PLANE-SUBMODULE] 闸2d(s/mutation-$($l2dSubMutationCase.Id)) error=$l2dSubMutationError"
      }
      elseif (-not $l2dSubMutationRestored) {
        Fail "[LSN-PLANE-SUBMODULE] 闸2d(s/mutation-$($l2dSubMutationCase.Id)-restore)"
      }
      elseif (-not $l2dSubMutationRedOk -and -not $l2dSubMutationGreenOk) {
        Fail "[LSN-PLANE-SUBMODULE] 闸2d(s/mutation-$($l2dSubMutationCase.Id)) expect=$($l2dSubMutationCase.Expect) exit=$l2dSubMutationExit"
      }
      else { Write-Host "  [LSN-PLANE-SUBMODULE] TD145 mutation $($l2dSubMutationCase.Id) $($l2dSubMutationCase.Expect.ToUpperInvariant())" -ForegroundColor Green }
    }
  }
}
finally {
  if ((Test-Path -LiteralPath $l2dSubCheckout) -and (Test-Path -LiteralPath $l2dSubLinked)) {
    & git -C $l2dSubCheckout worktree remove --force $l2dSubLinked 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/cleanup-worktree)：linked submodule worktree 无法显式移除。' }
  }
  Remove-Item -Recurse -Force -LiteralPath $l2dSubRoot -ErrorAction SilentlyContinue
  if (Test-Path -LiteralPath $l2dSubRoot) { Fail '[LSN-PLANE-SUBMODULE] 闸2d(s/cleanup-root)：临时 submodule 根目录清理失败。' }
}
if (-not $failedSelftestGateIds.Contains('2ds')) {
  Write-Host '  [LSN-PLANE-SUBMODULE] 2ds PASS' -ForegroundColor Green
}

# --- 3 + 4. 模板哨兵 / 占位符完好 ---
Step '3/17 模板哨兵（CLAUDE.template.md）'
if ($isPostInit) { Skip-SelftestCheck -GateId '3' -Reason 'POST-INIT-NOT-APPLICABLE' -Message '  已初始化（无 CLAUDE.template.md），跳过——本闸只测元仓自身的模板形态。' }
else {
  $tpl = Join-Path $RepoRoot 'CLAUDE.template.md'
  $t = Get-Content $tpl -Raw
  if ($t -notmatch 'TEMPLATE-NOTE:START' -or $t -notmatch 'TEMPLATE-NOTE:END') { Fail 'CLAUDE.template.md 缺 TEMPLATE-NOTE 哨兵（init 删头注会失效）。' }
  if ($t -notmatch '\{\{PROJECT_NAME\}\}') { Fail 'CLAUDE.template.md 缺 {{PROJECT_NAME}} 占位符（模板被就地初始化？）。' }
  else { Write-Host '  哨兵 + 占位符完好' }
}

Step '4/17 模板产物占位符完好'
if ($isPostInit) { Skip-SelftestCheck -GateId '4' -Reason 'POST-INIT-NOT-APPLICABLE' -Message '  已初始化，跳过——init 已合法替换掉这些占位符，其消失是预期结果而非缺陷。' }
else {
  foreach ($rel in @('pyproject.toml.example')) {
    $p = Join-Path $RepoRoot $rel
    if ((Test-Path $p) -and ((Get-Content $p -Raw) -notmatch '\{\{[A-Z_]+\}\}')) { Fail "$rel 缺 {{TOKEN}}（模板被就地初始化？）。" }
  }
  if (-not $fail) { Write-Host '  OK' }
}

# --- 5. token 覆盖：所有含 {{TOKEN}} 的文件，扩展名须在 init 的处理清单内 ---
Step '5/17 token 覆盖（init 替换扩展名清单）'
if ($isPostInit) { Skip-SelftestCheck -GateId '5' -Reason 'POST-INIT-NOT-APPLICABLE' -Message '  已初始化，跳过——init 已替换掉全仓 {{TOKEN}}，本闸测的是元仓自身「扩展名清单是否漏项」。' }
else {
  # 与 init-scaffold.ps1 的 $exts 对齐；运行时脚本(.ps1)用定向 .Replace 且常在帮助文本里引用 token 字面量，故整体豁免。
  $initExts = @('.md', '.json', '.yml', '.yaml', '.toml', '.example')
  # 排除 gitignored 的 scratch/runtime 目录（与闸 ⑧ 的 $RootIgnore 同理）：这些不随 init 下发，
  # 故不受「扩展名须可被 init 处理」约束（如 .secrets/ 的 commit-message 暂存常含 {{TOKEN}} 字面量作文档）。
  # -Force：Linux 把 .github/.claude 等点目录标记 Hidden，不加会静默漏扫——TD40 同一盲点。
  $tokenFiles = Get-ChildItem -Path $RepoRoot -Recurse -File -Force |
    Where-Object { $_.FullName -notmatch '[\\/](\.git|node_modules|\.venv|_local|\.secrets|\.review|runtime)[\\/]' } |
    Where-Object { $_.Extension -ne '.ps1' } |
    Where-Object {
      try { (Get-Content $_.FullName -Raw -ErrorAction Stop) -match '\{\{[A-Z_]+\}\}' } catch { $false }
    }
  foreach ($f in $tokenFiles) {
    if ($f.Extension -notin $initExts) {
      $relPath = $f.FullName.Substring($RepoRoot.Length + 1)
      Fail "$relPath 含占位符但扩展名 $($f.Extension) 不在 init 处理清单 -> init 会漏替换。把该扩展名加进 init-scaffold.ps1 的 exts 清单，或改用别的载体。"
    }
  }
  if (-not $fail) { Write-Host "  含 token 的 $($tokenFiles.Count) 个非脚本文件扩展名均被 init 覆盖" }
}

# --- 6. 裁决 schema 漂移：review.ps1 产出结构须与 verdict.schema.json 一致 ---
# CLAUDE.md 把「改 review.ps1 输出结构须与 specs/verdict.schema.json 一致」列为人工不变量；此处机检之。
Step '6/17 裁决 schema 漂移（review.ps1 ↔ verdict.schema.json）'
$schemaPath = Join-Path $RepoRoot 'specs/verdict.schema.json'
$reviewPath = Join-Path $RepoRoot 'scripts/review.ps1'
if (-not (Test-Path $schemaPath)) { Fail 'specs\verdict.schema.json 不存在。' }
elseif (-not (Test-Path $reviewPath)) { Fail 'scripts\review.ps1 不存在。' }
else {
  $schema = $null
  try { $schema = Get-Content $schemaPath -Raw | ConvertFrom-Json } catch { Fail "verdict.schema.json 非法 JSON：$($_.Exception.Message)" }
  if ($schema) {
    $hasProp = { param($o, $n) $o.PSObject.Properties.Name -contains $n }
    $props = @($schema.properties.PSObject.Properties.Name)
    $required = @($schema.required)
    $rv = Get-Content $reviewPath -Raw
    # 抠出 review.ps1 里规范化写入 $verdictPath 的哈希表（含 verdict= 的那个 @{...}）
    $hm = [regex]::Match($rv, '@\{[^}]*verdict\s*=[^}]*\}')
    if (-not $hm.Success) { Fail 'review.ps1 未找到 verdict 哈希表（@{ verdict = ... }）——结构可能已改，无法核验漂移。' }
    else {
      $emitted = @([regex]::Matches($hm.Value, '(?m)(\w+)\s*=') | ForEach-Object { $_.Groups[1].Value })
      # 6a. additionalProperties:false 是「emitted ⊆ props」的前提
      if (-not (& $hasProp $schema 'additionalProperties') -or $schema.additionalProperties -ne $false) {
        Write-Warning '  schema 未设 additionalProperties:false —— 漂移守卫弱化（无法保证未声明字段被拒）。'
      }
      # 6b. review.ps1 产出的每个键必须在 schema.properties（否则 additionalProperties:false 会拒其输出）
      foreach ($k in $emitted) { if ($k -notin $props) { Fail "review.ps1 产出字段 '$k' 不在 verdict.schema.json properties（schema 漂移：补 schema 或改 review.ps1）。" } }
      # 6c. schema.required 的每个键必须被 review.ps1 实际产出
      foreach ($r in $required) { if ($r -notin $emitted) { Fail "schema.required 字段 '$r' 未被 review.ps1 产出（漂移：review.ps1 漏写必需字段）。" } }
      # 6d. verdict 枚举值须在 review.ps1 出现为字面量（task.ps1 据 'pass' 放行）
      $enum = @()
      if ((& $hasProp $schema 'properties') -and (& $hasProp $schema.properties 'verdict') -and (& $hasProp $schema.properties.verdict 'enum')) {
        $enum = @($schema.properties.verdict.enum)
      }
      foreach ($e in $enum) { if ($rv -notmatch "'$([regex]::Escape($e))'") { Fail "verdict 枚举值 '$e' 未在 review.ps1 出现为字面量（裁决取值与 schema 漂移）。" } }
      if (-not $fail) { Write-Host "  review.ps1 产出 {$($emitted -join ', ')} 与 schema 一致（required=$($required -join ','); enum=$($enum -join '/')）" }
    }
  }
}

# --- 7. PSScriptAnalyzer 静态检查（语法之外的 lint；缺模块则跳过，保持离线）---
Step '7/17 PSScriptAnalyzer lint（缺模块即跳过）'
$pssa = Get-Module -ListAvailable PSScriptAnalyzer | Select-Object -First 1
if (-not $pssa) {
  # TD56/TD-119：CI 是唯一能 provision PSSA 的环境；此处若静默 skip-as-pass，合并后 canary 会把 Error 级 lint 回归误报为绿
  #   （闸⑦ 计入 PASS）。scaffold-selftest.yml 已在 selftest 前 Install-Module PSScriptAnalyzer；
  #   $env:CI 下模块仍缺即 fail-loud（本地/离线仍优雅跳过）。
  if ($env:CI) { Fail 'PSScriptAnalyzer 未安装但处于 CI（$env:CI 已置）——lint 闸⑦ 不得 skip-as-pass；CI 应在 selftest 前 Install-Module PSScriptAnalyzer（TD56/TD-119）。' }
  else { Skip-SelftestCheck -GateId '7' -Reason 'TOOL-PSSA-MISSING' -Message '  PSScriptAnalyzer 未安装，跳过（离线环境正常）。装：Install-Module PSScriptAnalyzer -Scope CurrentUser' }
} else {
  Import-Module PSScriptAnalyzer -ErrorAction Stop
  # 本仓有意为之的风格，豁免：彩色 CLI 输出(Write-Host)、集合访问器复数名(Get-Lessons)、内部助手谓词(Next-Id)；
  # 空 catch 是钩子/reporter/可选探针的**有意 fail-safe**（钩子绝不能抛、心跳恒 0、可选探针缺失即跳过）——
  # 这类「失败即静默降级」是脚手架的刻意设计，非疏漏，故豁免 PSAvoidUsingEmptyCatchBlock（与上面同属「有意风格」）。
  # TD77：PSUseShouldProcessForStateChangingFunctions 命中的均是本文件内部测试夹具 helper（如
  #   New-Seed10fCard/New-HookTestRepo/New-HandoffProbe/Set-ZConfig）——从不对外暴露、从不被 -WhatIf/-Confirm
  #   调用，永远在同一作用域内直接求值调用；给它们接上真实 ShouldProcess/WhatIf 语义是纯仪式（违反 YAGNI），
  #   故同豁免（与上面同属「有意风格」，非疏漏）。
  $excludeRules = @('PSAvoidUsingWriteHost', 'PSUseSingularNouns', 'PSUseApprovedVerbs', 'PSAvoidUsingEmptyCatchBlock', 'PSUseShouldProcessForStateChangingFunctions')
  $diags = @()
  foreach ($f in $ps1) {
    $diags += @(Invoke-ScriptAnalyzer -Path $f.FullName -Severity Error, Warning -ExcludeRule $excludeRules)
  }
  $errs = @($diags | Where-Object { $_.Severity -eq 'Error' })
  $warns = @($diags | Where-Object { $_.Severity -eq 'Warning' })
  foreach ($d in $diags) {
    $color = if ($d.Severity -eq 'Error') { 'Red' } else { 'Yellow' }
    Write-Host ("  [{0}] {1}:{2} {3} — {4}" -f $d.Severity, (Split-Path $d.ScriptName -Leaf), $d.Line, $d.RuleName, $d.Message) -ForegroundColor $color
  }
  if ($errs.Count) { Fail "PSScriptAnalyzer 报 $($errs.Count) 个 Error。" }
  elseif ($warns.Count -and $StrictLint) { Fail "PSScriptAnalyzer 报 $($warns.Count) 个 Warning（-StrictLint 下视为失败）。" }
  elseif ($warns.Count) { Write-Host "  $($warns.Count) 个 Warning（建议性；-StrictLint 可升级为失败）。" -ForegroundColor DarkYellow }
  else { Write-Host '  无 Error/Warning（已豁免本仓有意风格）。' -ForegroundColor Green }
}

# TD77-STRICTLINT-DEFAULT 回归（R3 dimension #6 catch：DoD 原只搜标记文本，清零告警后无法证明三条分支
#   各自仍对——纯函数三态直接断言，不派子进程模拟三种运行环境）：
#   case1 元仓自身、未传参 -> 自动收紧；case2 已初始化下游、未传参 -> 仍宽松；
#   case3 元仓自身、显式 -StrictLint:$false -> 覆盖生效、不被自动收紧盖过。
$slCase1 = Resolve-StrictLintDefault -IsPostInit $false -ParamBound $false -Requested $false
$slCase2 = Resolve-StrictLintDefault -IsPostInit $true  -ParamBound $false -Requested $false
$slCase3 = Resolve-StrictLintDefault -IsPostInit $false -ParamBound $true  -Requested $false
if ($slCase1 -ne $true -or $slCase2 -ne $false -or $slCase3 -ne $false) {
  Fail "TD77-STRICTLINT-DEFAULT 回归失败：Resolve-StrictLintDefault(元仓/未传参)=$slCase1（期望 True）、(下游/未传参)=$slCase2（期望 False）、(元仓/显式 false)=$slCase3（期望 False）。"
} else {
  Write-Host "  TD77-STRICTLINT-DEFAULT 三态回归 OK（元仓自动收紧 / 已初始化下游仍宽松 / 显式 -StrictLint:`$false 覆盖生效）" -ForegroundColor DarkGray
}

# --- 8. init-scaffold 干跑冒烟：拷到临时目录跑 init，核验产出，绝不动元仓 ---
# 自动化 CLAUDE.md 原本要求人工做的「拷到 scratch 跑 init 确认无残留 {{TOKEN}}」。
Step '8/17 init-scaffold 干跑冒烟（临时目录，绝不动元仓）'
$versionConfigRaw = Get-Content (Join-Path $RepoRoot 'scripts/_config.ps1') -Raw
$svMeta = ([regex]::Match($versionConfigRaw, "(?m)^\s*ScaffoldVersion\s*=\s*'([^']*)'")).Groups[1].Value
$svOriginMeta = ([regex]::Match($versionConfigRaw, "(?m)^\s*ScaffoldOriginVersion\s*=\s*'([^']*)'")).Groups[1].Value
if (-not $svMeta) { Fail '_config.ps1 缺 ScaffoldVersion current 字段。' }
elseif ($svMeta -notmatch '^\d+\.\d+\.\d+$') { Fail "ScaffoldVersion='$svMeta' 非 semver（应 x.y.z）。" }
if (-not $svOriginMeta) { Fail '_config.ps1 缺 ScaffoldOriginVersion provenance 字段。' }
elseif ($svOriginMeta -notmatch '^\d+\.\d+\.\d+$') { Fail "ScaffoldOriginVersion='$svOriginMeta' 非 semver（应 x.y.z）。" }
elseif ($svMeta -match '^\d+\.\d+\.\d+$' -and [version]$svOriginMeta -gt [version]$svMeta) { Fail "ScaffoldOriginVersion '$svOriginMeta' 不得高于 current '$svMeta'。" }

$versionInitRoot = Join-Path ([System.IO.Path]::GetTempPath()) "scaffold-version-init-$PID-$([guid]::NewGuid().ToString('N'))"
try {
  New-Item -ItemType Directory -Force (Join-Path $versionInitRoot 'scripts') | Out-Null
  Copy-Item -LiteralPath (Join-Path $RepoRoot 'init-scaffold.ps1') -Destination (Join-Path $versionInitRoot 'init-scaffold.ps1')
  Copy-Item -LiteralPath (Join-Path $RepoRoot 'scripts/_config.ps1') -Destination (Join-Path $versionInitRoot 'scripts/_config.ps1')
  Set-Content -LiteralPath (Join-Path $versionInitRoot 'CLAUDE.template.md') -Value 'generated by scaffold v{{SCAFFOLD_VERSION}}' -Encoding utf8
  & pwsh -NoProfile -File (Join-Path $versionInitRoot 'init-scaffold.ps1') -ProjectName 'Version Child' -ProjectSlug 'version-child' -GhAccount 'smoke' -Force *> $null
  $versionInitExit = $LASTEXITCODE
  $versionChildConfig = Get-Content -LiteralPath (Join-Path $versionInitRoot 'scripts/_config.ps1') -Raw
  $versionChildOrigin = ([regex]::Match($versionChildConfig, "(?m)^\s*ScaffoldOriginVersion\s*=\s*'([^']*)'")).Groups[1].Value
  $versionChildCurrent = ([regex]::Match($versionChildConfig, "(?m)^\s*ScaffoldVersion\s*=\s*'([^']*)'")).Groups[1].Value
  if ($versionInitExit -ne 0 -or -not $svMeta -or $versionChildOrigin -cne $svMeta -or $versionChildCurrent -cne $svMeta) {
    Fail "8.0b child 版本错：want=$svMeta origin=$versionChildOrigin current=$versionChildCurrent exit=$versionInitExit"
  } else { Write-Host "  8.0b init child origin=current=$svMeta OK" -ForegroundColor Green }
} finally {
  Remove-Item -LiteralPath $versionInitRoot -Recurse -Force -ErrorAction SilentlyContinue
}

# 8.0c CHANGELOG ↔ ScaffoldVersion 一致（TD12/C04「CHANGELOG.md 按 ScaffoldVersion」机械化）：
#   CHANGELOG.md 顶层版本条目（## [x.y.z]）须 == _config 的 ScaffoldVersion——否则 bump 了版本却漏更 CHANGELOG，
#   fleet 回填的「按版本对照」就失真。把这条 release-ritual 契约从「人记得」升级为机检（治本 TD12）。
#   仅元仓适用：CHANGELOG.md 是元仓专属物，init -Cleanup 会删它（下游另起自己产品的），下游没有它属预期、非缺陷。
if ($isPostInit) { Skip-SelftestCheck -GateId '8.0c' -Reason 'POST-INIT-NOT-APPLICABLE' -Message '  8.0c 跳过（已初始化，CHANGELOG.md 属元仓专属物、下游预期不存在）。' }
else {
  $clPath = Join-Path $RepoRoot 'CHANGELOG.md'
  if (-not (Test-Path $clPath)) { Fail 'CHANGELOG.md 不存在（TD12：脚手架发布须有版本化变更日志，供下游 fleet 回填对照）。' }
  elseif ($svMeta) {
    $clTop = ([regex]::Match((Get-Content $clPath -Raw), '(?m)^##\s*\[(\d+\.\d+\.\d+)\]')).Groups[1].Value
    if (-not $clTop) { Fail 'CHANGELOG.md 未找到顶层版本条目（## [x.y.z]）——格式漂移或漏发布条目。' }
    elseif ($clTop -ne $svMeta) { Fail "CHANGELOG.md 顶条目版本 '$clTop' ≠ _config ScaffoldVersion '$svMeta'（发布漂移：bump 版本须同步在 CHANGELOG 加顶层条目）。" }
    else { Write-Host "  8.0c CHANGELOG 顶条目 v$clTop == ScaffoldVersion OK" -ForegroundColor Green }
  }
}

# 8.0b WorktreeRoot 可移植性（C02）：Windows 默认分支不得硬编码具体盘符（如 'D:\）——单盘机器首次 task start 会
#   抛 DriveNotFoundException。静态断言 Get-ScaffoldWorktreeRoot 用 $env:SystemDrive（或 $HOME），不写死非系统盘。
$cfgRawC02 = Get-Content (Join-Path $RepoRoot 'scripts/_config.ps1') -Raw
$wtFn = [regex]::Match($cfgRawC02, '(?s)function Get-ScaffoldWorktreeRoot\s*\{(.*?)\n\}')
if (-not $wtFn.Success) { Fail 'C02 守卫：未找到 Get-ScaffoldWorktreeRoot（结构变了？无法回归 worktree 根可移植性）。' }
else {
  $wtBody = $wtFn.Groups[1].Value
  if ($wtBody -match "'[A-Za-z]:\\") { Fail "C02 守卫：Get-ScaffoldWorktreeRoot 硬编码了盘符路径（如 'D:\\）——单盘机器首次 task start 崩；改用 `$env:SystemDrive。" }
  elseif ($wtBody -notmatch '\$env:SystemDrive' -and $wtBody -notmatch '\$HOME') { Fail 'C02 守卫：Get-ScaffoldWorktreeRoot 默认未用 $env:SystemDrive/$HOME（worktree 根可移植性回归）。' }
  else { Write-Host '  8.0b WorktreeRoot 默认可移植（$env:SystemDrive/$HOME，无硬编码盘符）OK' -ForegroundColor Green }
}

# 8.1 根目录洁净（机检 CLAUDE.md「不在仓库根新建文件，根仅允许既有顶层文件」）。
#   动机：模型系统提示/输出转储（如各模型的 CLAUDE-<x>.md）以往散落在仓库根，既被 init 扫描下发，
#   又得在下面冒烟里逐名 skip 才不污染——治本是把「允许的顶层条目」白名单化，新增即须显式登记。
#   规范：此类本地模型产物一律放 _local/models/（gitignored），绝不落根。新增正当顶层文件 => 加进 $RootAllow。
$RootAllow  = @(
  '.claude', '.github', 'docs', 'scripts', 'specs', '_local',        # 工作流交付目录 + 本地工作区
  'backend', 'frontend', 'prompts', 'context', 'data',              # 标准软件 + AI 应用骨架（下游填充内容）
  'android',                                                        # 本项目：Android Gradle 工程（ADR-0001）
  'configs', 'tests',
  '.env.example', '.gitattributes', '.gitignore', 'LICENSE', '.mcp.json',
  'AGENTS.md', 'CLAUDE.md', 'CLAUDE.template.md', 'TEMPLATE-README.md', 'CHANGELOG.md',
  'init-scaffold.ps1', 'pyproject.toml.example',
  'pyproject.toml', 'uv.lock',   # TD79：init -WithPython 改名 / uv sync 落的下游产物，非模板占位符本身
  'README.md',                  # C09：-Cleanup 从 TEMPLATE-README.md 提炼 English on-ramp 生成的存活文件
  'CLAUDE.scaffold-merge.md',   # C30：-Retrofit 遇既有 CLAUDE.md 时生成的合并辅助文件（合并完成后用户手动删）
  'task_plan.md', 'findings.md', 'progress.md'  # planning-with-files 三件套：工作流自身指定的根部会话工件（本仓 gitignored；下游同约定）。8.1 靠 check-ignore 豁免，但 8d2 冒烟树无 .git 豁免失效，故须白名单（TD79 同理）
)
$stray = Get-ChildItem $RepoRoot -Force | Where-Object { $_.Name -notin $RootAllow -and $_.Name -notin $RootIgnore }
# gitignore 豁免：被 .gitignore 命中的顶层条目（模型转储 CLAUDE-*.md、NOTES.md、*.local.md 等本地工作产物）
#   既不入库、也不被 init 扫描下发（见 .gitignore「本地工作文档」节），故不算「污染根」。
#   不豁免会让一个注定不下发的 gitignored 本地文件误杀唯一验收。git 不可用/非 git 仓时回退为原严格行为。
if ($stray) {
  $inGit = (& git -C $RepoRoot rev-parse --is-inside-work-tree 2>$null) -eq 'true'
  if ($inGit) {
    $names = @($stray | ForEach-Object { $_.Name })
    $ignored = @(& git -C $RepoRoot check-ignore -- @names 2>$null)
    $stray = @($stray | Where-Object { $_.Name -notin $ignored })
  }
}
if ($stray) {
  Fail "意外的顶层条目：$(($stray | ForEach-Object { $_.Name }) -join ', ')。模型系统提示/输出转储请放 _local/models/；正当新增顶层文件须登记进 selftest 的 `$RootAllow 白名单。"
}

# 8.2 CI 供应链 / 闸完整性（TD56/TD-119）：两份工作流是下发给每个下游的模板，爆炸半径被放大。全静态文本断言、
#   hermetic、无网络；两份 yml 随下游保留（TD15），故**无条件**运行、不受 $isPostInit 门控（下游同样适用）。
# 8.2a 三方 Action 必须钉 40-hex commit SHA：可变 major tag（@v6/@v7）被上游劫持即在每个下游 CI 跑任意代码。
$wfFiles = @('.github/workflows/ci.yml', '.github/workflows/scaffold-selftest.yml')
$usesTotal = 0
foreach ($wf in $wfFiles) {
  $wfPath = Join-Path $RepoRoot $wf
  if (-not (Test-Path $wfPath)) { Fail "8.2a TD56/TD-119：工作流文件缺失 $wf。"; continue }
  foreach ($um in (Select-String -Path $wfPath -Pattern '^\s*(?:-\s*)?uses:\s*(\S+)')) {
    $usesTotal++
    $ref = $um.Matches[0].Groups[1].Value
    if ($ref -notmatch '@[0-9a-f]{40}$') {
      Fail "8.2a TD56/TD-119：$wf 的 Action 未钉 40-hex commit SHA：'$ref'（可变 tag→供应链暴露；改 uses: owner/repo@<sha> # vN）。"
    }
  }
}
if ($usesTotal -lt 4) { Fail "8.2a TD56/TD-119：两份工作流合计仅扫到 $usesTotal 个 uses: 行（预期 ≥4）——扫描疑似 vacuous，uses: 形态或路径已漂移。" }
elseif (-not $fail) { Write-Host "  8.2a 工作流 Action 均钉 40-hex commit SHA（$usesTotal 个 uses:）OK" -ForegroundColor Green }

# 8.2b ci.yml 安全关键闸（check-secrets/check-licenses）脚本缺失须 fail-closed exit 1，而非 skip-as-pass——
#   否则「删掉脚本」的 PR 恰好让 required `verify` 闸无条件绿（正是它该拦的）。verify.ps1（占位符）与
#   check-cards（非安全关键）保留优雅跳过：前者刻意 ships-as-placeholder，见卡片 out-of-scope。
$ciText82 = Get-Content (Join-Path $RepoRoot '.github/workflows/ci.yml') -Raw
foreach ($g in @('check-secrets', 'check-licenses')) {
  if ($ciText82 -match "$g\.ps1 absent; skipping") {
    Fail "8.2b TD56/TD-119：ci.yml 对 $g.ps1 缺失仍走 skip-as-pass（删脚本即让 required verify 闸无条件绿）——应 else { Write-Error '... missing ...'; exit 1 }。"
  }
  elseif ($ciText82 -notmatch "$g\.ps1 missing \(gate removed\?\)") {
    Fail "8.2b TD56/TD-119：ci.yml 未对缺失的 $g.ps1 fail-closed（未见 '$g.ps1 missing (gate removed?)' 哨兵）。"
  }
}
$exitOnes82 = ([regex]::Matches($ciText82, 'exit 1\b')).Count
if ($exitOnes82 -lt 2) { Fail "8.2b TD56/TD-119：ci.yml 中 'exit 1' 出现 $exitOnes82 次（预期 ≥2：check-secrets/check-licenses 各一）——fail-closed 分支可能只 Write-Error 未真正非零退出。" }
elseif (-not $fail) { Write-Host '  8.2b ci.yml 安全关键闸缺脚本 fail-closed（exit 1）OK' -ForegroundColor Green }

# 8.2b2（TD2）：许可扫描本身必须离线，fresh runner 先完成 JDK/Android/Gradle setup、Gradle online build
# 与 pinned PyPI/npm scanner provisioning。License gate 规范块用 UTF-8/LF 哈希钉住，再造“移回 warm-up 前”
# 的单一位置变异，证明顺序断言真会红。
function Test-LicenseGateAfterGradleWarmup([string]$WorkflowText) {
  $license = [regex]::Match($WorkflowText, '(?ms)^      - name: License gate\r?\n.*?(?=^      - name: |\z)')
  $warmup = [regex]::Match($WorkflowText, '(?m)^      - name: Gradle online build \(warms cache for verify\.ps1''s --offline gate\)\s*$')
  $provision = [regex]::Match($WorkflowText, '(?m)^      - name: Provision license scanners \(online cache warm-up\)\s*$')
  $e2e = [regex]::Match($WorkflowText, '(?m)^      - name: E2E verify gate\s*$')
  if (-not $license.Success -or -not $warmup.Success -or -not $provision.Success -or -not $e2e.Success) { return $false }
  foreach ($setupName in @('Setup Java (Temurin 17)', 'Setup Android SDK', 'Setup Gradle (dependency cache across CI runs)')) {
    $setup = [regex]::Match($WorkflowText, "(?m)^      - name: $([regex]::Escape($setupName))\s*`$")
    if (-not $setup.Success -or $setup.Index -ge $warmup.Index) { return $false }
  }
  $canonicalBlock = (($license.Value -replace "`r`n", "`n") -replace "`r", "`n").TrimEnd("`n") + "`n"
  $actualHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($canonicalBlock)))
  return ($actualHash -ceq 'B813DA389397711A8E8E234AF8FB222FFD4A9D11DD7FC687366A52F6FBDD3B04' -and
          $provision.Index -gt $warmup.Index -and $license.Index -gt $provision.Index -and $license.Index -lt $e2e.Index)
}
$licenseGateMatch82 = [regex]::Match($ciText82, '(?ms)^      - name: License gate\r?\n.*?(?=^      - name: |\z)')
if (-not (Test-LicenseGateAfterGradleWarmup $ciText82)) {
  Fail '8.2b2 TD2：License gate 未保持规范字节或未严格位于 JDK/Android/Gradle setup + Gradle/pinned scanner online warm-up 之后、E2E verify 之前。'
} else {
  $withoutLicense82 = $ciText82.Remove($licenseGateMatch82.Index, $licenseGateMatch82.Length)
  $warmupAfterRemoval82 = [regex]::Match($withoutLicense82, '(?m)^      - name: Gradle online build \(warms cache for verify\.ps1''s --offline gate\)\s*$')
  $wrongOrder82 = $withoutLicense82.Insert($warmupAfterRemoval82.Index, $licenseGateMatch82.Value)
  if (Test-LicenseGateAfterGradleWarmup $wrongOrder82) {
    Fail '8.2b2 TD2：把未改的 License gate 单独移回 Gradle online warm-up 之前后断言仍通过——排序检查是 vacuous。'
  } else {
    Write-Host '  8.2b2 TD2 License gate 保持规范块 SHA-256，位于 JDK/Android/Gradle setup + Gradle/pinned scanner online warm-up 后、E2E 前；逆向移动变异被检出 OK' -ForegroundColor Green
  }
}

# 8.2c scaffold-selftest.yml 须在合并后/manual canary provision PSScriptAnalyzer，使 lint 闸⑦ 在唯一能装它的环境里真跑
#   （配合闸⑦ 的 $env:CI 缺模块即 Fail 守卫，见上）。断言 provisioning 步骤在位（非本文件、无自引用）。
$stText82 = Get-Content (Join-Path $RepoRoot '.github/workflows/scaffold-selftest.yml') -Raw
if ($stText82 -notmatch 'Install-Module\s+PSScriptAnalyzer') {
  Fail '8.2c TD56/TD-119：scaffold-selftest.yml 未 provision PSScriptAnalyzer（Install-Module PSScriptAnalyzer）——合并后/manual canary 的 lint 闸⑦ 会 fail-loud。'
}
elseif (-not $fail) { Write-Host '  8.2c scaffold-selftest.yml provision PSScriptAnalyzer OK' -ForegroundColor Green }

# 8.2d 产品 CI 的 PR 事件是合并闸，默认分支 push 是事后检测；完整 scaffold selftest 是合并后/手动 canary。
#   任务卡 DoD 与 R3 负责合并前的本卡验证，避免无关历史 harness 闸反复阻塞产品推进。
$trigMissing82 = $false
$ciTriggerText82 = Get-Content (Join-Path $RepoRoot '.github/workflows/ci.yml') -Raw
foreach ($trig in @('push', 'pull_request')) {
  if (-not (Test-MainMasterWorkflowTrigger $ciTriggerText82 $trig)) {
    $trigMissing82 = $true
    Fail "8.2d：ci.yml 缺 '${trig}:' 触发（或其 branches 非 [main, master]）。"
  }
}
$ciOutsideOnMutation82 = [regex]::Replace($ciTriggerText82, '(?m)^  pull_request:\s*\r?\n    branches:\s*\[\s*main\s*,\s*master\s*\]\s*\r?\n', '', 1) + "`n# 仅为文档示例，不是 on 事件：`n  pull_request:`n    branches: [main, master]"
if (Test-MainMasterWorkflowTrigger $ciOutsideOnMutation82 'pull_request') {
  $trigMissing82 = $true
