                elseif ($head3 -ne $head1) { Fail "T37-REMOTEMX/1：三跑恢复改动了 HEAD（$head1→$head3）——应幂等。" }
                elseif (-not (Test-Path (Join-Path $fx1.Root 'merge-reached'))) { Fail 'T37-REMOTEMX/1-reuse：复用腿未走到 mock 合并。' }
                elseif (-not (Test-Path $tok1)) { Fail 'T37-REMOTEMX/1-reuse：mock 合并成功但未铸 T24 合并凭据。' }
                else { Write-Host '  T37-REMOTEMX/1 pushed-no-PR(S2) 经收据 resume：run1 铸收据+push成(origin==HEAD)/PR腿失败→run2 收据放行+幂等push+PR新建腿→run3 复用腿+mock合并铸凭据；HEAD 三跑不变 OK' -ForegroundColor Green }
              }
            }
          }
        }
        finally { Remove-Item -Recurse -Force $fx1.Root -ErrorAction SilentlyContinue }
      }

      # 场景 2：push 被拒（非 FF）drive-through——裸 origin 预置分叉 → 首跑 ship 在 push 腿失败（TD44/:593）→
      # 教义 worktree 内 fetch + git merge origin/分叉（merge 从不 rebase，禁历史改写）→ 重跑同一 ship 幂等 push 变 FF、全绿至 mock 合并。
      if (Test-SelftestPrerequisite -GateIds @('T37-REMOTEMX/2', 'T37-REMOTEMX/2-rerun')) {
        $fx2 = & $rmMake 'nonff'
        try {
          if (-not $fx2.Ok) { Fail 'T37-REMOTEMX/2 setup：非 FF 夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx2.Root
            $env:GH_MOCK_WT = $fx2.Wt
            # 真 RED（非 -SkipRed，与场景 1 一致）：worktree README 无 GREENMX → -Phase red 落证据。
            & pwsh -NoProfile -File (Join-Path $fx2.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            # 裸 origin 预置分叉：先建 origin/T0-REMOTEMX(=base)，再经 clone 在其上加一提交（改 extra.txt——与本地 README 改动不同文件，
            # 令教义 merge 无内容冲突且两文件皆在 allow_paths 内）。
            & git -C $fx2.Repo push -q origin master:refs/heads/T0-REMOTEMX *> $null
            $div = Join-Path $fx2.Root 'diverge'
            & git clone -q $fx2.Origin $div *> $null
            & git -C $div config user.email selftest@local *> $null
            & git -C $div config user.name selftest *> $null
            & git -C $div checkout -q T0-REMOTEMX *> $null
            Set-Content (Join-Path $div 'extra.txt') 'origin diverged' -Encoding utf8
            & git -C $div add -A *> $null; & git -C $div commit -q -m 'origin diverge (extra.txt)' *> $null
            & git -C $div push -q origin T0-REMOTEMX *> $null
            # 本地 worktree 令 DoD 绿（GREENMX），交给 ship 的 commit 腿提交并铸收据；push 时 origin 已有 extra 提交 → 非 FF 被拒。
            Set-Content (Join-Path $fx2.Wt 'README.md') 'GREENMX local non-ff work' -Encoding utf8
            $s2a = (& pwsh -NoProfile -File (Join-Path $fx2.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $s2aExit = $LASTEXITCODE
            if ($s2aExit -eq 0) { Fail 'T37-REMOTEMX/2：origin/T0-REMOTEMX 分叉时首跑 push 仍成功退出 0（TD44 非 FF 护栏失效）。' }
            elseif ($s2a -notmatch 'push 失败' -and $s2a -notmatch 'fast-forward') { $s2d = if ($s2a.Length -gt 900) { $s2a.Substring($s2a.Length - 900) } else { $s2a }; Fail "T37-REMOTEMX/2：push 被拒但未点名非 FF/push 失败。尾段=$s2d" }
            elseif (Test-Path (Join-Path $fx2.Root 'merge-reached')) { Fail 'T37-REMOTEMX/2：push 失败却仍走到 gh pr merge（负哨兵 merge-reached 应缺）。' }
            elseif (Test-Path (Join-Path $fx2.Root 'merge-attempted')) { Fail 'T37-REMOTEMX/2：push 失败却触达 merge 腿（负哨兵 merge-attempted 应缺）。' }
            elseif (Test-Path (Join-Path $fx2.Root 'pr-created')) { Fail 'T37-REMOTEMX/2：push 失败前不应开 PR（负哨兵 pr-created 应缺）。' }
            else {
              # 教义恢复：worktree 内 fetch + git merge origin/分叉（禁 rebase），再重跑同一 ship（非 -SkipRed，经收据 resume 放行 RED）。
              & git -C $fx2.Wt fetch -q origin *> $null
              & git -C $fx2.Wt merge -q origin/T0-REMOTEMX -m 'merge origin diverge (doctrine)' *> $null
              $s2mergeExit = $LASTEXITCODE
              if ($s2mergeExit -ne 0) { Fail "T37-REMOTEMX/2：教义 git merge origin 分叉未干净合并（exit $s2mergeExit）——夹具分叉不应造成内容冲突（应为不同文件）。" }
              else {
                $s2b = (& pwsh -NoProfile -File (Join-Path $fx2.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
                $s2bExit = $LASTEXITCODE
                $head2b = "$(& git -C $fx2.Wt rev-parse HEAD 2>$null)".Trim()
                $originRef2b = & $rmOriginRef $fx2.Origin
                if ($s2bExit -ne 0) { $s2d = if ($s2b.Length -gt 900) { $s2b.Substring($s2b.Length - 900) } else { $s2b }; Fail "T37-REMOTEMX/2-rerun：merge 分叉后重跑 ship 未全绿（$s2bExit）——幂等 push 未变 FF 或后续腿失败。尾段=$s2d" }
                elseif ($s2b -notmatch 'T35-RECEIPT resume 放行') { Fail 'T37-REMOTEMX/2-rerun：merge 后重跑未经水位线收据 resume 放行 RED 闸（未打印 resume 放行行）。' }
                elseif (-not (Test-Path (Join-Path $fx2.Root 'merge-reached'))) { Fail 'T37-REMOTEMX/2-rerun：重跑 ship 未走到 mock 合并腿。' }
                elseif ($originRef2b -ne $head2b) { Fail "T37-REMOTEMX/2-rerun：FF push 后 origin ref($originRef2b) != worktree HEAD($head2b)——远端投影未更新（Codex R3 r3 #2）。" }
                else { Write-Host '  T37-REMOTEMX/2 push 非 FF drive-through（首跑 push 拒→教义 merge→重跑收据 resume+幂等 push 变 FF 全绿，origin ref==HEAD）OK' -ForegroundColor Green }
              }
            }
          }
        }
        finally { Remove-Item -Recurse -Force $fx2.Root -ErrorAction SilentlyContinue }
      }

      # 场景 3：远端合并失败态（TD89 点名零覆盖缺口）——注入 gh pr merge 非零 → ship fail-closed：非零退出、点名合并失败、绝不铸 T24 凭据。
      if (Test-SelftestPrerequisite -GateIds @('T37-REMOTEMX/3')) {
        $fx3 = & $rmMake 'mergefail'
        try {
          if (-not $fx3.Ok) { Fail 'T37-REMOTEMX/3 setup：合并失败夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx3.Root
            $tok3 = Join-Path $fx3.Repo '.git/scaffold-merged/T0-REMOTEMX'
            $env:GH_MOCK_WT = $fx3.Wt; $env:GH_MOCK_MERGE_FAIL = '1'
            # 真 RED（非 -SkipRed，与场景 1/2 一致）：worktree README 无 GREENMX → -Phase red 落证据；再写 GREENMX 令 DoD 绿。
            & pwsh -NoProfile -File (Join-Path $fx3.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fx3.Wt 'README.md') 'GREENMX merge-fail work' -Encoding utf8
            $env:GH_MOCK_CI_MODE = 'basic-red'
            $s3Red = (& pwsh -NoProfile -File (Join-Path $fx3.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String)
            $s3Rx = $LASTEXITCODE
            $s3Rt = @((Get-Content (Join-Path $fx3.Root 'ci-event-trace') -ErrorAction SilentlyContinue) | Where-Object { $_ }) -join '>'
            if ($s3Rx -eq 0 -or $s3Red -notmatch '\[CI-GATE-RED\]' -or $s3Red -match '\[CI-GATE-PASS\]' -or -not (Test-Path (Join-Path $fx3.Root 'ci-checked')) -or
                $s3Rt -ne 'r3>ci' -or (Test-Path (Join-Path $fx3.Root 'ci-workflow-checked')) -or (Test-Path (Join-Path $fx3.Root 'ci-jobs-consumed')) -or (Test-Path (Join-Path $fx3.Root 'merge-attempted'))) {
              Fail 'T37-REMOTEMX/3：候选 check run 红灯未在真实 CI gate fail-closed，或更早/更晚的腿错误满足断言。'
            }
            $c3 = Join-Path $fx3.Wt '.github/workflows/ci.yml'
            $c3t = Get-Content $c3 -Raw
            if ([regex]::Matches($c3t, '(?m)^  verify:').Count -ne 1) { Fail 'T37-REMOTEMX/3：verify job 非唯一。' }
            $c3t -replace '(?m)^  verify:', "  verify-basic:`n    name: Verify display" | Set-Content $c3 -NoNewline -Encoding utf8
            @('review-invoked', 'ci-event-trace', 'ci-checked', 'ci-workflow-checked', 'ci-jobs-consumed', 'ci-jobs-run-id', 'ci-gh-cwds', 'merge-attempted') |
              ForEach-Object { Remove-Item (Join-Path $fx3.Root $_) -ErrorAction SilentlyContinue }
            $wantPr3 = "$(Get-Content (Join-Path $fx3.Root 'fixture-pr-number') -Raw)".Trim()
            $wantRun3 = "$(Get-Content (Join-Path $fx3.Root 'fixture-run-id') -Raw)".Trim() + '/' + "$(Get-Content (Join-Path $fx3.Root 'fixture-run-attempt') -Raw)".Trim()
            $env:GH_MOCK_CI_MODE = 'basic-candidate'
            $outside3 = Join-Path $fx3.Root 'unrelated-cwd'; New-Item -ItemType Directory -Force $outside3 | Out-Null
            Push-Location $outside3
            try { $s3 = (& pwsh -NoProfile -File (Join-Path $fx3.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship 2>&1 | Out-String) }
            finally { Pop-Location }
            $s3Exit = $LASTEXITCODE
            $s3GreenTrace = @((Get-Content (Join-Path $fx3.Root 'ci-event-trace') -ErrorAction SilentlyContinue) | Where-Object { $_ }) -join '>'
            $s3Cwds = @((Get-Content (Join-Path $fx3.Root 'ci-gh-cwds') -ErrorAction SilentlyContinue) | Where-Object { $_ })
            # ci-gh-cwds 每行为 `<调用名>|<cwd>|<请求 URL>`（第三段由 T0-CI-PAGED-CONTRACT 加入，供分页闸核实
            # 「真的请求到了那个 endpoint / 那一页」）。故此处必须按 3 段切——按 2 段切会把 URL 并进 cwd 段。
            $s3BadCwds = @($s3Cwds | Where-Object { ($_ -split '\|', 3)[1] -ine $fx3.Wt })
            $s3CwdCalls = @($s3Cwds | ForEach-Object { ($_ -split '\|', 3)[0] }) -join '>'
            if ($s3Exit -eq 0) { Fail 'T37-REMOTEMX/3：merge 失败却 exit 0。' }
            elseif (-not (Test-Path (Join-Path $fx3.Root 'merge-attempted'))) { Fail 'T37-REMOTEMX/3：未触达 merge。' }
            elseif ($s3CwdCalls -cne 'head>checks>workflow>jobs>checks>workflow>jobs>final-pr' -or $s3BadCwds.Count -gt 0) { Fail "T37-REMOTEMX/3：wrapped gh 未统一绑定 worktree CWD（calls=$s3CwdCalls, bad=$($s3BadCwds -join ',')）。" }
            elseif (-not (Test-Path (Join-Path $fx3.Root 'review-invoked')) -or $s3GreenTrace -notmatch '^r3>ci(?:>ci)*$') { Fail "T37-REMOTEMX/3：R3/CI 序列=$s3GreenTrace" }
            elseif (-not (Test-Path (Join-Path $fx3.Root 'ci-workflow-checked')) -or -not (Test-Path (Join-Path $fx3.Root 'ci-jobs-consumed')) -or
                "$(Get-Content (Join-Path $fx3.Root 'ci-jobs-run-id') -Raw)".Trim() -ne $wantRun3) { Fail "T37-REMOTEMX/3：jobs run≠$wantRun3。" }
            elseif ("$(Get-Content (Join-Path $fx3.Root 'merge-pr-arg') -Raw)".Trim() -ne $wantPr3) { Fail "T37-REMOTEMX/3：merge PR≠$wantPr3。" }
            elseif ("$(Get-Content (Join-Path $fx3.Root 'merge-head-arg') -Raw)".Trim() -ne "$(git -C $fx3.Wt rev-parse HEAD)".Trim()) { Fail 'T37-REMOTEMX/3：merge head 未绑定。' }
            elseif (Test-Path (Join-Path $fx3.Root 'merge-reached')) { Fail 'T37-REMOTEMX/3：失败却有 merge-reached。' }
            elseif ($s3 -notmatch '合并失败') { Fail 'T37-REMOTEMX/3：缺合并失败诊断。' }
            elseif (Test-Path $tok3) { Fail 'T37-REMOTEMX/3：失败却铸 T24 凭据。' }
            else { Write-Host '  T37-REMOTEMX/3 远端合并失败态 fail-closed（非零退出 + merge-reached 缺 + 不铸 T24 凭据 + 点名合并失败）OK' -ForegroundColor Green }
          }
        }
        finally { Remove-Item -Recurse -Force $fx3.Root -ErrorAction SilentlyContinue }
      }

      # --- T37-CIGATE/API-CONTRACT（T0-CI-PAGED-CONTRACT）：候选 CI 分页读取的形态 / 总数 / 稳定身份 / 跨页重放契约 ---
      # check-runs / workflow-runs / jobs 三个分页 endpoint 共用生产侧同一个 Get-GhPagedCollectionBeforeDeadline。
      # 负例矩阵分两层（分层理由见下方 $ciSharedCases 处的注释）：三者各跑形态/严格 total/跨页重放三条，
      # 完整畸形矩阵只在 check-runs 上跑一遍。三个 endpoint 另各配一条「有效分页」正例。
      # 每条负例的判据都不满足于「非零退出」——那条 ship 管线里能让退出码非零的原因有几十种。要求四件事同时成立：
      #   (a) 该 endpoint 的真实 URL 真被请求过（Urls 里找得到），且被请求的**页数**恰好是夹具铺的那么多；
      #   (b) 链**停在**这一腿：它之后的 endpoint 读计数为 0，且最后一次 gh 调用就是它；
      #   (c) 打印的是该场景**专属**的闸门哨兵（区分 API 形态错 / 红灯 / workflow 不唯一）；
      #   (d) merge-attempted 与 merge-reached 双双缺席——「拦住了」的定义是没走到合并，不是退出码不为 0。
      if (Test-SelftestPrerequisite -GateIds @('T37-CIGATE/API-CONTRACT')) {
        $ciProblem = $null
        # 负例判据（返回空串=通过，否则返回可诊断的失败描述）。$Leg 既是 ci-gh-cwds 里的调用名，也是「应停在这一腿」。
        $ciExpectBlock = {
          param($r, [string]$Sentinel, [string]$Leg, [int]$Pages)
          $target = switch ($Leg) { 'checks' { '/check-runs' } 'workflow' { "head_sha=$($r.H)" } 'jobs' { '/jobs' } }
          $reads = switch ($Leg) { 'checks' { $r.CR } 'workflow' { $r.WR } 'jobs' { $r.JR } }
          $later = switch ($Leg) { 'checks' { $r.WR + $r.JR } 'workflow' { $r.JR } 'jobs' { 0 } }
          $hitTarget = @($r.Urls | Where-Object { $_ -like "*$target*" }).Count
          $hitPage2 = @($r.Urls | Where-Object { $_ -cmatch '[?&]page=2(?:&|$)' }).Count
          if ($r.X -eq 0) { return 'exit 0（未 fail-closed）' }
          if ($r.O -cnotmatch $Sentinel) { return "缺哨兵 $Sentinel" }
          if ($reads -ne $Pages) { return "$Leg 读计数=$reads，期望 $Pages（夹具铺了几页就该读几页）" }
          if ($later -ne 0) { return "$Leg 之后的腿仍被消费（later=$later）——未停在该腿" }
          if ($r.Calls.Count -eq 0 -or $r.Calls[-1] -cne $Leg) { return "最后一次 gh 调用=$($r.Calls -join '>')，期望止于 $Leg" }
          if ($hitTarget -lt 1) { return "未请求到真实 endpoint（找不到含 '$target' 的 URL）" }
          if ($Pages -ge 2 -and $hitPage2 -lt 1) { return '未请求 page=2——跨页路径根本没走到' }
          if ($r.MA -or $r.M) { return "触达合并腿（merge-attempted=$($r.MA) merge-reached=$($r.M)）" }
          if ($r.BadCwd.Count -gt 0) { return "gh 调用未绑定 worktree CWD：$($r.BadCwd -join ',')" }
          return ''
        }
        # 阻断类场景共用一棵夹具：每次 ship 都被 CI 闸拦下、不合并，故仓/worktree 状态不前进；
        # $rmReset 逐次清空全部哨兵与读计数（PR 号取自夹具固定文件、每轮复用，只是 pr-created 被清掉故每轮重走一次
        # PR 新建腿）⇒ 每个 mode 拿到的都是干净计数，跨例残留会被「读计数恰好等于铺的页数」当场揭穿。
        $ciNeg = & $rmMake 'cigate'
        try {
          if (-not $ciNeg.Ok) { $ciProblem = 'setup：阻断类夹具 start 未产出 worktree' }
          else {
            $env:GH_MOCK_WT = $ciNeg.Wt
            & pwsh -NoProfile -File (Join-Path $ciNeg.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $ciNeg.Wt 'README.md') 'GREENMX ci api contract' -Encoding utf8
          }
          # 矩阵分两层，理由是「一个函数、三处调用」这件事本身：
          #   ① 每个 endpoint 都跑的三条 —— 数组形态(object)、严格 total(fraction-total)、有效跨页读取后
          #      仍按身份拒绝(page-replay)。它们同时钉住 A1 要求的「三处共用同一读取函数」：三处的
          #      拒绝理由、页数与停腿位置完全同构，且各自命中的是自己那条真实 endpoint URL。
          #   ② 只在 check-runs 上跑一遍的完整畸形矩阵 —— 生产侧只有**一个** Get-GhPagedCollectionBeforeDeadline，
          #      同一分支在三处不会有不同行为；page-replay 已在三处各证一次该分支确实被执行。把这 14 条
          #      也 ×3 只是把同一分支重跑两遍，代价是 seeded-remote 分片多跑约 6 分钟（实测），买不到新覆盖。
          # 每条负例的 P = 夹具铺了几页 ⇒ 断言该 endpoint 恰好被读了几次（多读少读都算失败）。
          $ciSharedCases = @(@{ C = 'object'; P = 1 }, @{ C = 'fraction-total'; P = 1 }, @{ C = 'page-replay'; P = 2 })
          $ciCheckOnlyCases = @(
            @{ C = 'missing-total'; P = 1 }, @{ C = 'null-total'; P = 1 }, @{ C = 'string-total'; P = 1 }
            @{ C = 'negative-total'; P = 1 }, @{ C = 'total-drift'; P = 2 }, @{ C = 'item-not-object'; P = 1 }
            @{ C = 'id-missing'; P = 1 }, @{ C = 'id-null'; P = 1 }, @{ C = 'id-string'; P = 1 }
            @{ C = 'id-fraction'; P = 1 }, @{ C = 'id-zero'; P = 1 }, @{ C = 'id-negative'; P = 1 }
            @{ C = 'id-over-int64'; P = 1 }, @{ C = 'dup-in-page'; P = 1 }
          )
          $ciLegOf = @{ check = 'checks'; workflow = 'workflow'; jobs = 'jobs' }
          $ciMatrix = @()
          foreach ($ep in @('check', 'workflow', 'jobs')) {
            foreach ($case in $ciSharedCases) { $ciMatrix += @{ EP = $ep; C = $case.C; P = $case.P } }
          }
          foreach ($case in $ciCheckOnlyCases) { $ciMatrix += @{ EP = 'check'; C = $case.C; P = $case.P } }
          foreach ($case in $ciMatrix) {
            if ($ciProblem) { break }
            $r = & $ciShip $ciNeg "$($case.EP)-$($case.C)"
            $why = & $ciExpectBlock $r '\[CI-GATE-API\]' $ciLegOf[$case.EP] $case.P
            if ($why) { $ciProblem = "$($case.EP)-$($case.C)：$why"; continue }
            # A3 的要害不是「拦下了」而是「命中的是哪个出口」：重放/同页重复必须停在 **id 去重出口**，
            # 不是更早的 total 漂移、count>total 或通用 API 错误。三个出口的 Reason 各自可辨，故直接核文本。
            # 同时这也是「重复条目没进 items 累积」的证据——真进了累积，count 就会等于 total 而判为读完、走绿。
            if ($case.C -cin @('page-replay', 'dup-in-page') -and $r.O -cnotmatch 'id-duplicate:') {
              $ciProblem = "$($case.EP)-$($case.C)：拦下了但命中的不是 id 去重出口（诊断里无 id-duplicate:）"
            }
            elseif ($case.C -ceq 'total-drift' -and $r.O -cnotmatch 'total 2->3') {
              $ciProblem = "$($case.EP)-total-drift：拦下了但命中的不是 total 漂移出口"
            }
            elseif ($case.C -clike 'id-*' -and $r.O -cnotmatch 'id-not-positive-integer') {
              $ciProblem = "$($case.EP)-$($case.C)：拦下了但命中的不是 id 形态出口"
            }
          }
          # A1 正例之一（workflow-runs）：该 endpoint 的「有效分页」只能以下游拿到 2 条显形——生产侧要求
          # 该 head 恰有 1 个 run，故 runs=2 正是「两页都被累积进来了」的证据（读丢第二页就是 runs=1、直接走绿）。
          if (-not $ciProblem) {
            $r = & $ciShip $ciNeg 'workflow-paged'
            $why = & $ciExpectBlock $r '\[CI-GATE-WORKFLOW-AMBIGUOUS\]' 'workflow' 2
            if ($why) { $ciProblem = "workflow-paged：$why" }
            elseif ($r.O -cnotmatch 'runs=2') { $ciProblem = 'workflow-paged：未报 runs=2——跨页累积没发生' }
          }
          # 消费证明（本卡威胁模型的正身）：第二页是一条**红** check。它必须真的进了判定，
          # 否则「读到的条目喂给了决策」只是文案。诊断须点名第二页那条 audit=completed/failure。
          if (-not $ciProblem) {
            $r = & $ciShip $ciNeg 'check-paged-red'
            $why = & $ciExpectBlock $r '\[CI-GATE-RED\]' 'checks' 2
            if ($why) { $ciProblem = "check-paged-red：$why" }
            elseif ($r.O -cnotmatch 'audit=completed/failure') { $ciProblem = 'check-paged-red：诊断未点名第二页的红 check——第二页未进入判定' }
          }
        }
        finally {
          if ($ciNeg -and $ciNeg.Root) { Remove-Item -Recurse -Force $ciNeg.Root -ErrorAction SilentlyContinue }
        }
        # 会走到 merge 的两条正例各自开一棵新夹具（合并会铸凭据、推进仓状态，不能与阻断类共用）。
        foreach ($pos in @('check-paged', 'jobs-paged')) {
          if ($ciProblem) { break }
          $fxp = & $rmMake ($pos -replace '-', '')
          try {
            if (-not $fxp.Ok) { $ciProblem = "$pos setup：夹具 start 未产出 worktree"; break }
            $env:GH_MOCK_WT = $fxp.Wt
            & pwsh -NoProfile -File (Join-Path $fxp.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxp.Wt 'README.md') "GREENMX $pos" -Encoding utf8
            if ($pos -ceq 'jobs-paged') {
              # 候选 ci.yml 再声明一个 audit job，而夹具把 audit **只**放在 jobs 的第二页：
              # 读丢第二页 ⇒ 生产侧认定 audit 缺席、等到超时；能走到 merge 本身就是跨页累积的证据。
              Add-Content (Join-Path $fxp.Wt '.github/workflows/ci.yml') "`n  audit:`n    runs-on: windows-latest`n    steps: []" -Encoding utf8
            }
            $r = & $ciShip $fxp $pos
            $reads = if ($pos -ceq 'check-paged') { $r.CR } else { $r.JR }
            $page2 = @($r.Urls | Where-Object { $_ -cmatch '[?&]page=2(?:&|$)' }).Count
            if ($r.X -ne 0) { $ciProblem = "$pos：有效分页却未走通（exit $($r.X)）" }
            elseif (-not $r.M) { $ciProblem = "$pos：未走到 mock 合并（merge-reached 缺）" }
            elseif ($page2 -lt 1) { $ciProblem = "$pos：从未请求 page=2——分页路径没走" }
            elseif ($reads -ne 4) { $ciProblem = "$pos：目标 endpoint 读计数=$reads，期望 4（2 页 × 稳定态/终局快照各一轮）" }
            elseif ($r.MH -cne $r.H) { $ciProblem = "$pos：合并未绑 PR head（--match-head-commit=$($r.MH) != $($r.H)）" }
            elseif ($r.BadCwd.Count -gt 0) { $ciProblem = "$pos：gh 调用未绑定 worktree CWD" }
          }
          finally { if ($fxp -and $fxp.Root) { Remove-Item -Recurse -Force $fxp.Root -ErrorAction SilentlyContinue } }
        }
        if ($ciProblem) { Fail "T37-CIGATE/API-CONTRACT: $ciProblem" }
        else { Write-Host '  T37-CIGATE/API-CONTRACT OK' -ForegroundColor Green }
      }

      # --- T37-CIGATE/WORKFLOW-BINDING（T0-CI-IDENTITY-DEADLINE）：逐层身份绑定 · 单一 deadline · 终局快照 ---
      # 绑定链（A1）：已过 R3 的本地 HEAD → PR headRefOid → 候选 run 的 head_sha/event/path/pull_requests →
      # run id + attempt（jobs 只按这一对取）→ 终局 base/head 快照 → `gh pr merge --match-head-commit`。
      # 每条负例只切断链上**一环**，判据四件同时成立：非零退出 · 该环专属哨兵 · 三个 endpoint 的读计数恰好
      # 等于「链应停在此处」时的计数（证明停在哪一环，而不是别处出错）· merge-attempted 与 merge-reached 双双缺席。
      # 三条 `-case` 负例（event / path / pull_requests 的属性名）是本卡硬约束的正身：**值本身全对、只有大小写不同**，
      # PowerShell 的 -eq/-in/-contains 与属性访问默认大小写不敏感，会照单全收；它们与本闸的绿路正例
      # （nomerge-green，同一份载荷、属性名小写）逐字之差就在大小写，故绿→红这一对本身即单点变异证明。
      # R4 单点变异收据（每枚只改生产侧**一处**、其余不动；判据 = 本闸变红且 [SELFTEST-FAILED-GATES] 点名本闸）：
      #   M1 `-ccontains 'number'` → `-contains`   ⇒ wfid-pr-key-case：exit 0（未 fail-closed）——只带 `Number` 的
      #      关联条目重新过闸，一路走到合并。这正是原卡实测踩到的那个洞。
      #   M2 `"$($run.event)" -cne` → `-ne`        ⇒ wfid-event-case：读计数 2/2/1（期望 1/1/0）。
      #   M3 `$path -cnotmatch` → `-notmatch`      ⇒ wfid-path-case：读计数 2/2/1（期望 1/1/0）。
      #   M5 `$proc.Kill($true)` → `$proc.Kill()`  ⇒ gh-hang：孙进程留下了完成哨兵（只杀了直接子进程）。
      # M2/M3 的**死法本身**是一条证据：单点变异只放松了稳定态那一处，终局快照那一处仍在，于是负例「停在哪一环」
      # 变了而不是干脆过闸——只看退出码的判据会把这种半失守读成「还是拦住了」，读计数断言才抓得到。
      if (Test-SelftestPrerequisite -GateIds @('T37-CIGATE/WORKFLOW-BINDING')) {
        $wbProblem = $null
        # 读计数判据：C/W/R = 该负例被拦下时 check-runs / workflow-runs / jobs 三个 endpoint 的期望读取次数。
        # 稳定态一轮各读 1 次，终局快照再各读 1 次 ⇒ 停在稳定态身份判定=1/1/0、停在终局快照=2/2/2。
        $wbExpect = {
          param($r, [string]$Sentinel, [int]$C, [int]$W, [int]$J, [string]$LedgerPattern)
          $why = & $ciExpectIdBlock $r $Sentinel
          if ($why) { return $why }
          if (($r.CR -ne $C) -or ($r.WR -ne $W) -or ($r.JR -ne $J)) {
            return "读计数 checks/workflow/jobs=$($r.CR)/$($r.WR)/$($r.JR)，期望 $C/$W/$J——链没有停在该环"
          }
          if ($LedgerPattern -and ($r.Led -cnotmatch $LedgerPattern)) {
            return "效果账本未点名被造坏的那一处（期望匹配 '$LedgerPattern'，实际：$($r.Led)）"
          }
          return ''
        }
        $wbNeg = & $rmMake 'wfbind'
        try {
          if (-not $wbNeg.Ok) { $wbProblem = 'setup：身份负例夹具 start 未产出 worktree' }
          else {
            $env:GH_MOCK_WT = $wbNeg.Wt
            & pwsh -NoProfile -File (Join-Path $wbNeg.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $wbNeg.Wt 'README.md') 'GREENMX workflow binding' -Encoding utf8
          }
          # 账本 pattern 逐条只匹配「被造坏的那一处 + 其余各处仍然合法」的完整形状：例如 pr-key-case 要求
          # event/path 都还是合法值、只有 prs=0，从而排除「其实是被更早的通用错误拦下」。
          $wbCases = @(
            @{ M = 'pr-head-mismatch'; S = '\[CI-GATE-HEAD-MISMATCH\]'; C = 0; W = 0; J = 0; L = 'c{40}' }
            @{ M = 'wfid-head'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/a{40}/pull_request/\.github/workflows/ci\.yml/prs=1' }
            @{ M = 'wfid-event-case'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/Pull_Request/\.github/workflows/ci\.yml/prs=1' }
            @{ M = 'wfid-path-case'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/pull_request/\.github/workflows/CI\.yml/prs=1' }
            @{ M = 'wfid-pr-key-case'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/pull_request/\.github/workflows/ci\.yml/prs=0' }
            @{ M = 'wfid-pr-other'; S = '\[CI-GATE-WORKFLOW-IDENTITY\]'; C = 1; W = 1; J = 0; L = '/pull_request/\.github/workflows/ci\.yml/prs=0' }
            @{ M = 'snap-retarget'; S = '\[CI-GATE-BASE-MISMATCH\]'; C = 2; W = 2; J = 2; L = 'master!=release' }
            @{ M = 'snap-head-moved'; S = '\[CI-GATE-HEAD-MOVED\]'; C = 2; W = 2; J = 2; L = '->b{40}' }
          )
          foreach ($c in $wbCases) {
            if ($wbProblem) { break }
            $r = & $ciShip $wbNeg $c.M
            $why = & $wbExpect $r $c.S $c.C $c.W $c.J $c.L
            if ($why) { $wbProblem = "$($c.M)：$why" }
          }
          # 决策前身份漂移：稳定态那一读身份完全正确、**终局快照**那一读才变。两条各打终局的一处判据——
          # 没有它们，终局那几行删掉也全绿（首读就非法的负例根本走不到终局，R3 r1 #6）。
          # run id 那条另核诊断点名夹具自己的 run id（期望值取自随机身份文件 ⇒ 断言里不可能是硬编码常数）。
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-final-drift'
            $why = & $wbExpect $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 2 2 1 ''
            if ($why) { $wbProblem = "wfid-final-drift：$why" }
            elseif ($r.O -cnotmatch "expected=$($r.RunId)\b") { $wbProblem = "wfid-final-drift：诊断未点名本夹具的 run id（expected=$($r.RunId)）" }
          }
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-final-pr-key-case'
            $why = & $wbExpect $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 2 2 1 ''
            if ($why) { $wbProblem = "wfid-final-pr-key-case：$why（终局那次 PR 关联判定若不是大小写敏感的，本例会一路走到合并）" }
          }
          # A3 单一 wall-clock deadline：stub 在 workflow 腿挂起 300s，并派一个**孙进程**在 40s 后写自己的完成哨兵。
          # 40s > 20s 上限是刻意的：孙进程若在 deadline 之前就写完，那枚哨兵的缺席只说明「它还没跑到」，
          # 证不了进程树被清理（本闸第一版实测踩到——12s 的孙进程在 20s 的 deadline 前自己完成了）。
          # 三件事同时成立才算数：① API 真被启动过（hang-started 在位，排除「根本没调用所以很快」的假绿）；
          # ② 整条 ship 的墙钟 < 配置上限 + 明确清理余量（余量 = 本 ship 在 CI 闸之前那段确定性管线的耗时上限）；
          # ③ 等过孙进程本该写哨兵的时刻之后，**两枚**完成哨兵都不在位 ⇒ 被杀的是进程树，不只是直接子进程。
          if (-not $wbProblem) {
            $wbCap = 20; $wbMargin = 85; $wbChildSleep = 40
            $r = & $ciShip $wbNeg 'gh-hang' @() "$wbCap"
            $why = & $ciExpectIdBlock $r '\[CI-GATE-TIMEOUT\]'
            $wbStartedAt = Join-Path $wbNeg.Root 'hang-started'
            if ($why) { $wbProblem = "gh-hang：$why" }
            elseif (-not (Test-Path $wbStartedAt)) { $wbProblem = 'gh-hang：hang-started 缺——挂起的那次 API 根本没被启动，超时不能算证据' }
            elseif ($r.Sec -ge ($wbCap + $wbMargin)) { $wbProblem = "gh-hang：墙钟 $([int]$r.Sec)s ≥ 上限 ${wbCap}s + 清理余量 ${wbMargin}s——deadline 未按剩余预算收口" }
            else {
              # 等到「孙进程起跑 + 睡眠 + 6s 落盘余量」那一刻再判，让「没被杀掉」这一可能性有充分机会显形。
              $wbSpawnedAt = [DateTimeOffset]::Parse("$(Get-Content $wbStartedAt -Raw)".Trim())
              $wbRemain = ($wbSpawnedAt.AddSeconds($wbChildSleep + 6) - [DateTimeOffset]::UtcNow).TotalSeconds
              if ($wbRemain -gt 0) { Start-Sleep -Milliseconds ([int]($wbRemain * 1000)) }
              if (Test-Path (Join-Path $wbNeg.Root 'hang-child-completed')) { $wbProblem = 'gh-hang：孙进程留下了完成哨兵——只杀了直接子进程，进程树未被清理' }
              elseif (Test-Path (Join-Path $wbNeg.Root 'hang-completed')) { $wbProblem = 'gh-hang：挂起的子进程自己跑完了——deadline 未真正杀进程' }
            }
          }
          # A3 之二：**一个共享预算**，不是「每次调用各起一个新超时」。gh-hang 只挂一条腿，两种实现的观测
          # 结果一样，故区分不开（R3 r1 #6）。本例让**每条** API 腿都睡 cap 的一大半：
          #   · 共享 deadline ⇒ 第一条腿花掉大半预算、第二条腿在剩余预算内超时 ⇒ [CI-GATE-TIMEOUT]、不合并；
          #   · 每次调用各自计时 ⇒ 每条腿都在自己的上限内从容返回 ⇒ 一路走到合并。
          # 判据同时钉住「预算真的跨腿累计」：slow-legs 记账 ≥2 条，且 checks/workflow 两条都被进入过。
          if (-not $wbProblem) {
            # 11 > cap/2 ⇒ 两条腿必然吃穿共享预算，单腿又吃不穿（故「一条腿超时」证不了共享，两条才行）。
            $wbCap = 20; $wbMargin = 85
            $r = & $ciShip $wbNeg 'gh-slow' @() "$wbCap" '11'
            $slowLegs = @((Get-Content (Join-Path $wbNeg.Root 'slow-legs') -ErrorAction SilentlyContinue) | Where-Object { $_ }).Count
            $why = & $ciExpectIdBlock $r '\[CI-GATE-TIMEOUT\]'
            if ($why) { $wbProblem = "gh-slow：$why（若走到了合并，说明每次调用各起了一个新超时、不是单一预算）" }
            elseif ($slowLegs -lt 2) { $wbProblem = "gh-slow：只有 $slowLegs 条腿被计时——预算没有跨腿累计，本例证不了「共享」" }
            elseif (($r.CR -lt 1) -or ($r.WR -lt 1)) { $wbProblem = "gh-slow：读计数 $($r.CR)/$($r.WR)/$($r.JR)——预算未跨越两个不同 endpoint" }
            elseif ($r.Sec -ge ($wbCap + $wbMargin)) { $wbProblem = "gh-slow：墙钟 $([int]$r.Sec)s ≥ ${wbCap}+${wbMargin}s——总预算未收口" }
          }
          # A5：-NoAutoMerge 只跳过合并腿，不放松任何一层——同一条身份负例带上它仍须被同一个哨兵拦下。
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg 'wfid-path-case' @('-NoAutoMerge')
            $why = & $wbExpect $r '\[CI-GATE-WORKFLOW-IDENTITY\]' 1 1 0 '/pull_request/\.github/workflows/CI\.yml/prs=1'
            if ($why) { $wbProblem = "nomerge-blocked：$why" }
          }
          # A5 绿路 + 三条 `-case` 负例的对照组：同一份载荷、属性名/取值全部小写合法 ⇒ 逐层绑定全过、
          # 打印 [CI-GATE-PASS]，但因 -NoAutoMerge 不触达合并腿。jobs 必须是按**本夹具自己的** run id/attempt 取的。
          if (-not $wbProblem) {
            $r = & $ciShip $wbNeg '' @('-NoAutoMerge')
            if ($r.X -ne 0) { $wbProblem = "nomerge-green：绿路却未走通（exit $($r.X)）；尾段=$($r.O.Substring([Math]::Max(0, $r.O.Length - 500)))" }
            elseif ($r.O -cnotmatch '\[CI-GATE-PASS\]') { $wbProblem = 'nomerge-green：缺 [CI-GATE-PASS]——候选 CI 闸未判绿' }
            elseif (($r.CR -ne 2) -or ($r.WR -ne 2) -or ($r.JR -ne 2)) { $wbProblem = "nomerge-green：读计数 $($r.CR)/$($r.WR)/$($r.JR) != 2/2/2——-NoAutoMerge 放松了某一层" }
            elseif ($r.MA -or $r.M) { $wbProblem = '-NoAutoMerge 却触达了合并腿' }
            elseif ($r.JobsRunId -cne "$($r.RunId)/$($r.Try)") { $wbProblem = "nomerge-green：jobs 未按本夹具 run 身份取（$($r.JobsRunId) != $($r.RunId)/$($r.Try)）" }
          }
        }
        finally { if ($wbNeg -and $wbNeg.Root) { Remove-Item -Recurse -Force $wbNeg.Root -ErrorAction SilentlyContinue } }
        # A4 的两条负例各改仓状态（一条在 R3 窗口里前移本地 HEAD，一条让裸 origin 的 master 长出新提交），
        # 故各用一棵全新夹具——与阻断类共用会把「下一条负例的基线」也一并改掉。
        foreach ($mv in @(
            @{ M = 'r3-head-move'; S = '\[CI-GATE-LOCAL-HEAD-MOVED\]'; C = 0; W = 0; J = 0 }
            @{ M = 'base-moved'; S = '\[CI-GATE-BASE-MOVED\]'; C = 1; W = 1; J = 1 })) {
          if ($wbProblem) { break }
          $fxm = & $rmMake ($mv.M -replace '-', '')
          try {
            if (-not $fxm.Ok) { $wbProblem = "$($mv.M) setup：夹具 start 未产出 worktree"; break }
            $env:GH_MOCK_WT = $fxm.Wt
            & pwsh -NoProfile -File (Join-Path $fxm.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxm.Wt 'README.md') "GREENMX $($mv.M)" -Encoding utf8
            $r = & $ciShip $fxm $mv.M
            $why = & $wbExpect $r $mv.S $mv.C $mv.W $mv.J ''
            if ($why) { $wbProblem = "$($mv.M)：$why" }
            elseif (($mv.M -ceq 'r3-head-move') -and (-not (Test-Path (Join-Path $fxm.Root 'r3-head-moved')))) {
              $wbProblem = 'r3-head-move：评审后端没有真的移动本地 HEAD，负例未构造出来'
            }
          }
          finally { if ($fxm -and $fxm.Root) { Remove-Item -Recurse -Force $fxm.Root -ErrorAction SilentlyContinue } }
        }
        # A3 之三：被 deadline 罩住的不只有 gh——CI 闸内的 `git fetch` 与 `git rev-parse` 也在里面。
        # 这两条腿此前零覆盖：把它们改回不受预算约束的直调 `& git`，上面每一条用例照样全绿（R3 r1 #6）。
        # 夹具装一枚**条件式 git PATH-stub**（默认逐字透传真 git），由 gh stub 的 jobs 腿上膛后挂起 300s：
        #   · 有 deadline ⇒ ship 在 cap + 清理余量内返回 [CI-GATE-TIMEOUT]；
        #   · 无 deadline（直调）⇒ ship 会一直卡在那条 git 上，本例根本不会返回。
        # 故「按时返回 + git-hang-started 在位」这一对，就是「该 git 腿确实在预算之内」的证据。
        # 单独一棵夹具：只有它需要那枚 git stub（装给全体等于让每次 git 都多经一层 pwsh，既慢又扩大失真面）。
        if (-not $wbProblem) {
          $fxg = & $rmMake 'gitleg'
          try {
            if (-not $fxg.Ok) { $wbProblem = 'git-leg setup：夹具 start 未产出 worktree' }
            else {
              $env:GH_MOCK_WT = $fxg.Wt
              & pwsh -NoProfile -File (Join-Path $fxg.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
              Set-Content (Join-Path $fxg.Wt 'README.md') 'GREENMX git leg deadline' -Encoding utf8
              # 真 git 的绝对路径必须在装 stub **之前**解析——装完之后 `git` 解析到的就是 stub 自己（自指死循环）。
              $env:GH_MOCK_REAL_GIT = (Get-Command git -CommandType Application | Select-Object -First 1).Source
              Set-Content (Join-Path $fxg.Shim 'git.ps1') $rmGitShim -Encoding utf8
              # 余量比别处宽：本夹具每一次 git 都多经一层 pwsh 透传（实测整条 ship 因此多花十几秒），
              # 而这两条用例要判的是「该 git 腿有没有被预算罩住」，不是 ship 前段有多快。
              $wbCap = 20; $wbMargin = 140
              foreach ($leg in @('git-fetch-hang', 'git-revparse-hang')) {
                if ($wbProblem) { break }
                $r = & $ciShip $fxg $leg @() "$wbCap"
                $why = & $ciExpectIdBlock $r '\[CI-GATE-TIMEOUT\]'
                if ($why) { $wbProblem = "$leg：$why（该 git 腿若是不受预算约束的直调，ship 会卡死而不是超时返回）" }
                elseif (-not (Test-Path (Join-Path $fxg.Root 'git-hang-started'))) { $wbProblem = "$leg：git-hang-started 缺——那条 git 根本没被挂起，超时不能算证据" }
                elseif ((Get-Content (Join-Path $fxg.Root 'git-hang-started') -Raw) -cnotmatch [regex]::Escape($leg)) { $wbProblem = "$leg：挂起的不是本例点名的那条 git 腿" }
                elseif ($r.Sec -ge ($wbCap + $wbMargin)) { $wbProblem = "$leg：墙钟 $([int]$r.Sec)s ≥ ${wbCap}+${wbMargin}s——该 git 腿不在共享预算内" }
              }
            }
          }
          finally {
            $env:GH_MOCK_REAL_GIT = $null
            if ($fxg -and $fxg.Root) { Remove-Item -Recurse -Force $fxg.Root -ErrorAction SilentlyContinue }
          }
        }
        if ($wbProblem) { Fail "T37-CIGATE/WORKFLOW-BINDING: $wbProblem" }
        else { Write-Host '  T37-CIGATE/WORKFLOW-BINDING OK' -ForegroundColor Green }
      }

      # --- T37-CIGATE/JOBS-DRIFT（T0-CI-IDENTITY-DEADLINE）：候选 ci.yml 声明的 job 集 ↔ run 实际返回的 job 集 ---
      # 两个平面共用一枚哨兵：① 候选树 ci.yml 的 jobs 块本身不可判（矩阵/重名/形态外）；② 已判绿的 run 返回的
      # job 名集合与声明集合不**逐名大小写敏感地相等**。jobs 腿只在 workflow run 已 completed+success 之后才读，
      # 那时 job 集已终局——故「集合不等」是漂移、不是「还没跑出来」，必须当场 fail-closed 而不是等到超时。
      # R4 单点变异收据：去掉 `Compare-Object … -CaseSensitive` ⇒ jobs-name-case：exit 0（未 fail-closed）——
      # 候选 ci.yml 声明 `verify`、run 返回 `Verify`，集合被判为相等并一路合并（[SELFTEST-FAILED-GATES] 点名本闸）。
      if (Test-SelftestPrerequisite -GateIds @('T37-CIGATE/JOBS-DRIFT')) {
        $jdProblem = $null
        $jdNeg = & $rmMake 'jobsdrift'
        try {
          if (-not $jdNeg.Ok) { $jdProblem = 'setup：job 漂移夹具 start 未产出 worktree' }
          else {
            $env:GH_MOCK_WT = $jdNeg.Wt
            & pwsh -NoProfile -File (Join-Path $jdNeg.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $jdNeg.Wt 'README.md') 'GREENMX jobs drift' -Encoding utf8
          }
          # 四条 API 侧负例各动一处：改名（声明的那个缺席）/ 只改大小写 / 多一个未声明的 / 同名重复占位。
          # 读计数恒为 1/1/1：它们都停在稳定态那一次 jobs 判定上，终局快照一次都不该跑到。
          foreach ($m in @('jobs-missing', 'jobs-name-case', 'jobs-extra', 'jobs-dup')) {
            if ($jdProblem) { break }
            $r = & $ciShip $jdNeg $m
            $why = & $ciExpectIdBlock $r '\[CI-GATE-JOBS-DRIFT\]'
            if ($why) { $jdProblem = "$m：$why" }
            elseif (($r.CR -ne 1) -or ($r.WR -ne 1) -or ($r.JR -ne 1)) { $jdProblem = "$m：读计数 $($r.CR)/$($r.WR)/$($r.JR) != 1/1/1——没停在稳定态 jobs 判定" }
            elseif ($r.O -cnotmatch 'expected=verify') { $jdProblem = "$m：诊断未点名候选 ci.yml 声明的期望集" }
          }
          # 首读合法、**终局那读**才漂：上面四条都停在第一次 jobs 判定，于是终局那次 Get-ExactCandidateJobState
          # 删掉也照样全绿。本条专打它——读计数 2/2/2 即「走到了终局才被拦」的证据（R3 r1 #6）。
          if (-not $jdProblem) {
            $r = & $ciShip $jdNeg 'jobs-final-drift'
            $why = & $ciExpectIdBlock $r '\[CI-GATE-JOBS-DRIFT\]'
            if ($why) { $jdProblem = "jobs-final-drift：$why" }
            elseif (($r.CR -ne 2) -or ($r.WR -ne 2) -or ($r.JR -ne 2)) { $jdProblem = "jobs-final-drift：读计数 $($r.CR)/$($r.WR)/$($r.JR) != 2/2/2——没走到终局 jobs 判定就被别处拦下了" }
            elseif ($r.O -cnotmatch 'final expected=verify') { $jdProblem = 'jobs-final-drift：拦下了但不是终局那处判据（诊断缺 final 前缀）' }
          }
        }
        finally { if ($jdNeg -and $jdNeg.Root) { Remove-Item -Recurse -Force $jdNeg.Root -ErrorAction SilentlyContinue } }
        # 下面两条都要改候选树的 ci.yml（改动会被 ship 提交进分支、推进 HEAD 与水位线收据），故各用一棵全新夹具，
        # 不与上面共用——共用会让后一条的基线 = 前一条改完的 ci.yml，声明集不再是它自己声明的那一份。
        #   ciyml-matrix：候选 ci.yml 的 jobs 块自身不可判（矩阵 job 名在运行期展开，声明集无法确定）⇒ 同一枚
        #     哨兵，且必须在**任何** gh 读取之前拦下（读计数全 0）。
        #   jobs-set-green：多声明一个 audit，run 返回的两条恰好等于 {verify, audit} ⇒ 逐名相等即放行并合并；
        #     它证明「集合相等」不是靠恒假谓词换来的（否则这条绿路也会被拦）。
        foreach ($jc in @(
            @{ M = ''; Tag = 'ciymlmatrix'; Yaml = "`n  fan:`n    strategy:`n      matrix:`n        os: [a, b]`n    runs-on: windows-latest`n    steps: []" }
            @{ M = 'jobs-set-green'; Tag = 'jobsgreen'; Yaml = "`n  audit:`n    runs-on: windows-latest`n    steps: []" })) {
          if ($jdProblem) { break }
          $fxj = & $rmMake $jc.Tag
          try {
            if (-not $fxj.Ok) { $jdProblem = "$($jc.Tag) setup：夹具 start 未产出 worktree"; break }
            $env:GH_MOCK_WT = $fxj.Wt
            & pwsh -NoProfile -File (Join-Path $fxj.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fxj.Wt 'README.md') "GREENMX $($jc.Tag)" -Encoding utf8
            Add-Content (Join-Path $fxj.Wt '.github/workflows/ci.yml') $jc.Yaml -Encoding utf8
            $r = & $ciShip $fxj $jc.M
            if ($jc.Tag -ceq 'ciymlmatrix') {
              $why = & $ciExpectIdBlock $r '\[CI-GATE-JOBS-DRIFT\]'
              if ($why) { $jdProblem = "ciyml-matrix：$why" }
              elseif (($r.CR -ne 0) -or ($r.WR -ne 0) -or ($r.JR -ne 0)) { $jdProblem = "ciyml-matrix：读计数 $($r.CR)/$($r.WR)/$($r.JR) != 0/0/0——声明集不可判时不得再去读任何 API" }
            }
            elseif ($r.X -ne 0) { $jdProblem = "jobs-set-green：声明集与返回集相等却未走通（exit $($r.X)）；尾段=$($r.O.Substring([Math]::Max(0, $r.O.Length - 500)))" }
            elseif (-not $r.M) { $jdProblem = 'jobs-set-green：未走到 mock 合并（merge-reached 缺）' }
            elseif ($r.MH -cne $r.H) { $jdProblem = "jobs-set-green：合并未绑 PR head（--match-head-commit=$($r.MH) != $($r.H)）" }
            # A5「两条绿路使用不同 PR/run id，stub 拒绝硬编码」：本夹具与 WORKFLOW-BINDING 绿路各自随机身份；
            # 这里核 jobs 腿确实按**本夹具自己的** run id/attempt 取，且判绿行点名的是本夹具的 PR 号。
            elseif ($r.JobsRunId -cne "$($r.RunId)/$($r.Try)") { $jdProblem = "jobs-set-green：jobs 未按本夹具 run 身份取（$($r.JobsRunId) != $($r.RunId)/$($r.Try)）" }
            elseif ($r.O -cnotmatch "#$($r.PrN)/") { $jdProblem = "jobs-set-green：[CI-GATE-PASS] 未点名本夹具的 PR 号 $($r.PrN)" }
          }
          finally { if ($fxj -and $fxj.Root) { Remove-Item -Recurse -Force $fxj.Root -ErrorAction SilentlyContinue } }
        }
        if ($jdProblem) { Fail "T37-CIGATE/JOBS-DRIFT: $jdProblem" }
        else { Write-Host '  T37-CIGATE/JOBS-DRIFT OK' -ForegroundColor Green }
      }

      # 场景 4 = 闸15t（TD94）：**收据缺失 + 已 push** 这条「最后手段」恢复平面的端到端夹具。
      # 为什么单列：T37 场景 1 覆盖的是**收据在位**经 resume 的主干；收据缺失走的是完全不同的人工路径——
      # 不能 resume，只能手工补跑全部确定性闸后用 `review.ps1 -PostStatus` 直连合并。那条路径**权限最大**
      # （可直接合并）**护栏最少**（不经 ship 管线），而 CI 又没有范围闸（TD89 根因）⇒ 序列里的范围步是该
      # 平面上范围闸的唯一承载。15q/15r 只锁了它的**文案**，本闸锁它的**行为**。
      # 判据（照 docs/DEVOPS-WORKFLOW.md 的恢复配方逐条建模，含 T53 落的 fail-closed 绑定）：
      #   负例：卡外改动 ⇒ 范围步 [SCOPE-BLOCK] 非零 ⇒ 链在此中止 ⇒ **review/merge 哨兵一个都不许出现**
      #         （证「不过范围闸就到不了合并」，而非只证「范围闸自己会红」——后者 15d/15d2 早已覆盖）。
      #   正例：全在界 ⇒ 范围步 [SCOPE-PASS] ⇒ 链续跑 -PostStatus ⇒ mock 合并被消费（merge-reached 在场）。
      #         正例给负例的红提供**鉴别力**：否则负例可能只是因为序列本身走不通而红（vacuous）。
      #   前置：收据须**真的被构造成缺失**（先断言它在、删掉、再断言它不在）——否则「收据缺失」是碰巧成立。
      if (Test-SelftestPrerequisite -GateIds @('T37-REMOTEMX/4')) {
        $fx4 = & $rmMake 'recovery'
        try {
          if (-not $fx4.Ok) { Fail '闸15t / T37-REMOTEMX/4 setup：恢复夹具 start 未产出 worktree。' }
          else {
            & $rmReset $fx4.Root
            $env:GH_MOCK_WT = $fx4.Wt
            # 让**本地 master 落后于 origin/master 一个提交**（先推、再 reset 回退本地）。
            # 为什么必须是「落后」而不是「领先」（codex R3 r3 #1）：三点 diff 由 merge-base 决定，本地领先时
            # `master...branch` 与 `origin/master...branch` 得到**同一份** feature 侧 diff ⇒ 加不加 -LocalBase 都一样、
            # 「远端基线」这条语义无从区分（原写法即如此，是 vacuous）。落后时 review.ps1 会打印
            # 「本地 'master' 落后 refs/remotes/origin/master N 个提交」——该提示**仅在 behindN>0 时**出现，
            # 故可作为「确实选了远端基线」的判据；一旦加 -LocalBase，baseRef 变成 refs/heads/master、behindN=0、提示消失。
            & git -C $fx4.Repo checkout -q master *> $null
            Set-Content (Join-Path $fx4.Repo 'origin-ahead.txt') 'T54：推到 origin/master 后本地回退，令本地 master 落后一个提交' -Encoding utf8
            & git -C $fx4.Repo add -A *> $null
            & git -C $fx4.Repo commit -q -m 'origin-ahead master commit' *> $null
            & git -C $fx4.Repo push -q origin master *> $null
            & git -C $fx4.Repo reset --hard HEAD~1 *> $null
            # 走到「已 push + PR 已开 + 收据已铸」：真 RED → 绿 → ship -NoAutoMerge（停在 PR-open，不合并）。
            & pwsh -NoProfile -File (Join-Path $fx4.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase red *> $null
            Set-Content (Join-Path $fx4.Wt 'README.md') 'GREENMX recovery work' -Encoding utf8
            & pwsh -NoProfile -File (Join-Path $fx4.Repo 'scripts/task.ps1') -TaskId T0-REMOTEMX -Phase ship -NoAutoMerge *> $null
            # 收据路径按 task.ps1 同款解析（git-common-dir；linked worktree 下禁用 $RepoRoot 形态拼）。
            $gcd4 = "$(& git -C $fx4.Wt rev-parse --git-common-dir 2>$null)".Trim()
            if ($gcd4 -and -not [System.IO.Path]::IsPathRooted($gcd4)) { $gcd4 = Join-Path $fx4.Wt $gcd4 }
            $rcpt4 = Join-Path (Join-Path $gcd4 'scaffold-shipped') 'T0-REMOTEMX'
            $prCreated4 = Test-Path (Join-Path $fx4.Root 'pr-created')
            if (-not $prCreated4) { Fail '闸15t setup：ship -NoAutoMerge 未开出 PR（pr-created 哨兵缺）——恢复场景的前提（已 push + PR 已开）没构造出来，后续断言失真。' }
            elseif (-not (Test-Path $rcpt4)) { Fail '闸15t 前置：ship 后收据本应在场却缺失——「删收据造 receipt-missing」这一步遂无意义（前提碰巧成立即 vacuous）。' }
            else {
              Remove-Item $rcpt4 -Force                                  # ← 造出 receipt-missing 态
              if (Test-Path $rcpt4) { Fail '闸15t 前置：收据删除失败，receipt-missing 态未构造出来。' }
              else {
                # 恢复配方的**可执行建模**：范围步非零即中止，绿才续跑 -PostStatus → 合并。
                # 与 DEVOPS-WORKFLOW 那段一一对应；本闸测的正是这条控制流，不是各闸自身（各闸另有夹具）。
                # 恢复配方的**完整**可执行建模——逐条对应 docs/DEVOPS-WORKFLOW.md「任何已 push 状态的手工恢复」：
                # fetch(查码) → PR baseRefName 核 → 取 head/base OID → DoD → verify → **范围闸**（主检出那份 +
                # -Path 指被审树 + -ExpectTip/-ExpectBase，远端模式）→ 许可 → 防泄露 → review -PostStatus -PrNumber
                # → 合并前复核 baseRefName + 基线 OID 未前移 → gh pr merge --match-head-commit。
                # **任一步非零即中止**（PowerShell 原生命令非零不自动中断，故每步都显式查）——这正是本闸要证的控制流。
                $recover4 = {
                  param($fx)
                  # **有序腿轨迹**：每步跑之前把腿名追加进 $script:r4Trace。断言比对的是整条轨迹，
                  # 故删掉/跳过任何一条腿都会让轨迹不等而变红——只断言最终结局的话，中间腿全无覆盖（codex R3 r2 #1）。
                  # **逐腿分别留存输出**：只攒一份聚合输出的话，「范围步是否印了 [SCOPE-BLOCK]」这种断言会被
                  # **别的腿**的输出满足（codex R3 r5：聚合搜索 ⇒ 断言面宽于契约，同 L165 那一族）。
                  $step = { param($name, $sb) if ($script:r4Stop) { return }; $script:r4Trace += $name; $o = (& $sb 2>&1 | Out-String); $script:r4Out += $o; $script:r4LegOut[$name] = $o; if ($LASTEXITCODE -ne 0) { $script:r4Stop = $name } }
                  # 这两个由腿内赋值、腿外读取：**必须预初始化**。否则某条腿被删/跳过时，外面那句读取会因
                  # StrictMode「变量未定义」直接抛异常、整段中止——红是红了，却红在异常而非有序轨迹断言上
                  # （变异实测：删 pr-base / pr-head 两腿即如此，判据分类器把它们标为「存疑」而非 OK）。
                  $script:r4PrBase = ''; $script:r4Head = ''
                  $script:r4Stop = $null; $script:r4Out = ''; $script:r4Trace = @(); $script:r4LegOut = @{}
                  # ① fetch 两侧（退出码必查：失败即拿陈旧 origin/* 判，连 allow_paths 都取自旧卡）
                  & $step 'fetch' { & git -C $fx.Wt fetch origin master T0-REMOTEMX }
                  # ② PR 的 baseRefName 须 == 本次判定的 base（retarget 会「按 A 判往 B 合」）
                  $prBase = ''
                  & $step 'pr-base' { $s = (& gh pr view 777 --json baseRefName --jq .baseRefName); $script:r4PrBase = "$s".Trim(); if ($script:r4PrBase -ne 'master') { cmd /c exit 1 } }
                  $prBase = $script:r4PrBase
                  # ③ head **取自 PR 元数据**（不是 check-scope 会自己解析的那个 ref——同源自比即恒等式，r2 #1）；
                  #    base 取远端跟踪引用（= 将被合并进的那个提交）。
                  $headOid = ''
                  & $step 'pr-head' { $s = (& gh pr view 777 --json headRefOid --jq .headRefOid); $script:r4Head = "$s".Trim(); if ($script:r4Head -notmatch '^[0-9a-f]{40}$') { cmd /c exit 1 } }
                  $headOid = $script:r4Head
                  $baseOid = "$(& git -C $fx.Wt rev-parse refs/remotes/origin/master 2>$null)".Trim()
                  # ④ DoD（卡上原命令，在被审工作树里跑）
                  & $step 'dod' { Push-Location $fx.Wt; try { & pwsh -NoProfile -Command 'if (-not (Select-String -Path README.md -Pattern GREENMX -Quiet)) { exit 1 }' } finally { Pop-Location } }
                  # ⑤ verify 总闸
                  & $step 'verify' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/verify.ps1') }
                  # ⑥ **范围闸**——跑受信主检出那份、-Path 指被审树、两侧 OID 都钉进去（远端模式，不加 -Local）
                  & $step 'scope' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-scope.ps1') -TaskId T0-REMOTEMX -Base master -Path $fx.Wt -ExpectTip $headOid -ExpectBase $baseOid }
                  # ⑦ 许可闸 ⑧ 防泄露闸
                  & $step 'license' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-licenses.ps1') }
                  & $step 'secrets' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/check-secrets.ps1') }
                  # ⑨ 第二模型评审 + 回贴状态（最后手段路径的评审腿）
                  # 权威配方用的是**缺省远端基线**（不带 -LocalBase）——夹具跟着用，否则测的是另一套基线选择语义、
                  # 远端基线解析的回归会被藏住（codex R3 r2 #3）。夹具已让本地 master 与 origin/master **有意不同**。
                  & $step 'review' { & pwsh -NoProfile -File (Join-Path $fx.Repo 'scripts/review.ps1') -WorktreePath $fx.Wt -Base master -PostStatus -PrNumber 777 }
                  # ⑩ 合并前复核：baseRefName 未变 + 基线 OID 未前移
                  & $step 'pr-base-2' { $s = (& gh pr view 777 --json baseRefName --jq .baseRefName); if ("$s".Trim() -ne 'master') { cmd /c exit 1 } }
                  # fetch 与比对**拆成两步**：写在同一步里的话，后面那条成功的 rev-parse 会把 fetch 的 $LASTEXITCODE
                  # 冲掉，于是 fetch 失败也照样拿陈旧 ref 过等值检查（codex R3 r2 #2）。
                  & $step 'fetch-2' { & git -C $fx.Wt fetch origin master }
                  & $step 'base-oid-2' { $b2 = "$(& git -C $fx.Wt rev-parse refs/remotes/origin/master 2>$null)".Trim(); if ($b2 -ne $baseOid) { cmd /c exit 1 } }
                  # ⑪ 合并——绑 head，head 一变即拒
                  & $step 'merge' { & gh pr merge 777 --squash --match-head-commit $headOid }
                  return [pscustomobject]@{ Out = $script:r4Out; LegOut = $script:r4LegOut; StoppedAt = $script:r4Stop; Head = $headOid; Base = $baseOid; PrBase = $prBase; Trace = @($script:r4Trace) }
                }
                # 三枚「腿被消费」哨兵：评审 / 状态回贴 / 合并。负例须**三枚全缺**——只看 merge 不够，
                # 评审若已在被拦的路径上跑过，就说明控制流没有真的在范围步止住（codex R3 r1 #3）。
                # 配方的**完整有序腿清单**：负例须恰好走到 scope 为止，正例须一条不落地走完。
                $legsAll4 = @('fetch', 'pr-base', 'pr-head', 'dod', 'verify', 'scope', 'license', 'secrets', 'review', 'pr-base-2', 'fetch-2', 'base-oid-2', 'merge')
                $legsNeg4 = @('fetch', 'pr-base', 'pr-head', 'dod', 'verify', 'scope')
                # `merge-attempted` 必须在列：stub 一被调用就写它，而 `merge-reached` 要等参数校验通过且成功才写。
                # 负例说的是「合并腿**一次都没被调用**」，那就得断言 attempted 缺——只断言 reached 缺会放过
                # 「调用了但因参数不符而失败」的情形（codex R3 r3 #3）。
                $sent4 = @('review-invoked', 'status-posted', 'pr-commented', 'merge-attempted', 'merge-reached')
                $clearSent4 = { foreach ($s in $sent4) { Remove-Item (Join-Path $fx4.Root $s) -ErrorAction SilentlyContinue } }
                # 本场景自用的单次调用器（15s 的 $ssRun* 属另一闸的作用域，勿跨用）。
                $run4 = { param($Exe, $A) $o = (& pwsh -NoProfile -File $Exe @A 2>&1 | Out-String); return [pscustomobject]@{ Out = $o; Exit = $LASTEXITCODE } }
                $hitSent4 = { @($sent4 | Where-Object { Test-Path (Join-Path $fx4.Root $_) }) }
                # ── 负例：种卡外文件（allow_paths = README.md/extra.txt ⇒ oob.md 越界）、提交并**推到 origin**。
                #    必须真 push：本卡测的是「**已 push** 状态」的恢复平面，只在本地提交的话远端仍停在旧 sha，
                #    远端模式的检查器根本看不到这个越界改动（codex R3 r1 #1 实测）。
                Set-Content (Join-Path $fx4.Wt 'oob.md') 'T54 负例：卡外改动，恢复序列的范围步必须拦下' -Encoding utf8
                & git -C $fx4.Wt add -A *> $null
                & git -C $fx4.Wt commit -q -m 'oob change' *> $null
                & git -C $fx4.Wt push -q origin T0-REMOTEMX *> $null
                & $clearSent4
                $neg4 = & $recover4 $fx4
                # @() 包裹**调用点**：scriptblock 返回单元素时 `&` 会解包成标量，StrictMode 下取 .Count 即抛。
                $negHit4 = @(& $hitSent4)
                if (($neg4.Trace -join '>') -ne ($legsNeg4 -join '>')) { Fail "闸15t 负例：腿轨迹与配方不符——实际 [$($neg4.Trace -join '>')]，期望 [$($legsNeg4 -join '>')]。删掉/跳过任一前置腿（fetch/PR base/head/DoD/verify）都会命中这条：只断言最终结局的话那些腿零覆盖。" }
                elseif ($neg4.StoppedAt -ne 'scope') { Fail "闸15t 负例：恢复序列没有停在**范围步**（实际停在 '$($neg4.StoppedAt)'；`$null=一路走到底）——最后手段平面上越界可直达合并，或红在了别的面上（断言失真）。`n输出=$($neg4.Out)" }
                elseif ("$($neg4.LegOut['scope'])" -notmatch '\[SCOPE-BLOCK\]') { Fail "闸15t 负例：停在范围步但**范围步自己的输出**没印 [SCOPE-BLOCK] 哨兵——可能是不可判分支而非越界判定（只搜聚合输出会被别的腿满足，故此处只看该腿）。`n范围步输出=$($neg4.LegOut['scope'])" }
                elseif ($negHit4.Count -gt 0) { Fail "闸15t 负例：范围闸 BLOCK 了，但下游腿仍被消费（哨兵在场：$($negHit4 -join ', ')）——「不过范围闸就到不了评审/回贴/合并」不成立。" }
                else {
                  # ── 正例：反向提交撤出卡外文件（禁改写历史——T36-DOCTRINE）并推上去，同一序列须**全程走通** ──
                  Remove-Item (Join-Path $fx4.Wt 'oob.md') -Force
                  & git -C $fx4.Wt add -A *> $null
                  & git -C $fx4.Wt commit -q -m 'revert oob (反向提交撤出卡外改动)' *> $null
                  & git -C $fx4.Wt push -q origin T0-REMOTEMX *> $null
                  & $clearSent4
                  $pos4 = & $recover4 $fx4
                  $posMiss4 = @($sent4 | Where-Object { -not (Test-Path (Join-Path $fx4.Root $_)) })
                  if ($pos4.StoppedAt) { Fail "闸15t 正例：全部改动都在 allow_paths 内时恢复序列仍在 '$($pos4.StoppedAt)' 步中止——该序列走不通，负例的红遂失去鉴别力（可能只是序列本身坏了）。`n输出=$($pos4.Out)" }
                  elseif (($pos4.Trace -join '>') -ne ($legsAll4 -join '>')) { Fail "闸15t 正例：腿轨迹与配方不符——实际 [$($pos4.Trace -join '>')]，期望 [$($legsAll4 -join '>')]。删掉任一腿（fetch/PR base 两次/head/DoD/verify/范围/许可/密钥/评审/基线 OID 复核/合并）都会命中这条。" }
                  elseif ((Get-Content (Join-Path $fx4.Root 'merge-head-arg') -Raw -ErrorAction SilentlyContinue).Trim() -ne $pos4.Head) { Fail "闸15t 正例：`gh pr merge` 的 --match-head-commit 实参与 PR head 不符（实参=$((Get-Content (Join-Path $fx4.Root 'merge-head-arg') -Raw -ErrorAction SilentlyContinue))，head=$($pos4.Head)）——「合并绑 head」只是文案、没真绑。" }
                  # 评审腿确实走了**远端基线**：本地 master 已被造成落后 1 个提交，review.ps1 遂打印「落后 … refs/remotes/origin/master」
                  # 提示（仅 behindN>0 时出现）。加 -LocalBase 会让 baseRef 变本地、behindN=0、提示消失 ⇒ 本断言即红（codex R3 r3 #1）。
                  # 远端基线判据：只看**评审腿自己**的输出里有没有 `refs/remotes/origin/master` 这个**稳定 ASCII 串**。
                  # 两点都要紧：① 必须**按腿**看——范围步也印这个串（`基线 = …`），搜聚合输出会恒真（变异 D 首轮即因此存活）；
                  # ② 判据必须是 ASCII，不能拿中文提示当锚（本卡自己的纪律就是「机检认 ASCII、本地化文案只给人读」，
                  # 上一版拿「落后」做判据是自相矛盾，codex R3 r5 指出）。
                  # 加回 -LocalBase 时 baseRef 变 refs/heads/master、behindN=0、该提示不印 ⇒ 评审腿输出里就没有这个串。
                  elseif ("$($pos4.LegOut['review'])" -notmatch [regex]::Escape('refs/remotes/origin/master')) { Fail "闸15t 正例：**评审腿自己的输出**里没有 refs/remotes/origin/master——说明评审没走远端基线（加了 -LocalBase 即如此），测的是另一套基线选择语义。`n评审腿输出=$($pos4.LegOut['review'])" }
                  elseif ("$($pos4.LegOut['scope'])" -notmatch '\[SCOPE-PASS\]') { Fail "闸15t 正例：**范围步自己的输出**未印 [SCOPE-PASS]——判定结论未被打印（只看聚合输出会被别的腿满足）。`n范围步输出=$($pos4.LegOut['scope'])" }
                  elseif ($posMiss4.Count -gt 0) { Fail "闸15t 正例：序列走通却有腿没被消费（哨兵缺：$($posMiss4 -join ', ')）——正例没真正覆盖到「范围过 → 评审+回贴 → 合并」全段。`n输出=$($pos4.Out)" }
                  else {
                    # 两枚**绑定承重性**用例（不属恢复链，单独跑；codex R3 r3 #2）：只记录 'scope' 标签证明不了
                    # -ExpectTip/-ExpectBase 真在起作用——把它们摘掉或改走 -Local，正/负例照样得到 BLOCK/PASS。
                    # 故直接喂**不符的 OID**，要求以 [SCOPE-TIPMISMATCH] 失败：该哨兵只有绑定生效时才可能出现。
                    # 不符值必须是**本仓可解析、但不是目标**的真实 OID（tip 侧喂 base 的、base 侧喂 head 的），
                    # 另一侧保持正确。喂 `000…001` 那种解析不出的串只会停在「OID 解析失败」那一支，**根本走不到**
                    # `$full -ne $ActualSha` 身份比对——把身份比对整句删掉也照样绿（codex R3 r4；15s 的 n2/n8 早已按
                    # 此法写，本卡新加的 pin 用例却没沿用）。故另断言文案含 `judged=`，证明拦它的确是身份比对那一支。
                    $csExe4 = Join-Path $fx4.Repo 'scripts/check-scope.ps1'
                    $pinTip4 = & $run4 $csExe4 @('-TaskId', 'T0-REMOTEMX', '-Base', 'master', '-Path', $fx4.Wt, '-ExpectTip', $pos4.Base, '-ExpectBase', $pos4.Base)
                    $pinBase4 = & $run4 $csExe4 @('-TaskId', 'T0-REMOTEMX', '-Base', 'master', '-Path', $fx4.Wt, '-ExpectTip', $pos4.Head, '-ExpectBase', $pos4.Head)
                    if ($pinTip4.Exit -eq 0 -or $pinTip4.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15t(pin/tip)：喂入**可解析但不符**的 -ExpectTip（基线 OID）仍未以 [SCOPE-TIPMISMATCH] 失败（exit=$($pinTip4.Exit)）——该绑定参数不承重。`n输出=$($pinTip4.Out)" }
                    elseif ($pinTip4.Out -notmatch [regex]::Escape('judged=')) { Fail "闸15t(pin/tip)：失败文案里没有 judged=/expect= 两个 OID——说明拦它的是「OID 解析失败」那一支，而非**提交身份比对**；删掉身份比对整句本用例仍会绿（vacuous）。`n输出=$($pinTip4.Out)" }
                    elseif ($pinBase4.Exit -eq 0 -or $pinBase4.Out -notmatch [regex]::Escape('[SCOPE-TIPMISMATCH]')) { Fail "闸15t(pin/base)：喂入**可解析但不符**的 -ExpectBase（尖端 OID）仍未以 [SCOPE-TIPMISMATCH] 失败（exit=$($pinBase4.Exit)）——基线那一侧的绑定不承重。`n输出=$($pinBase4.Out)" }
                    elseif ($pinBase4.Out -notmatch [regex]::Escape('judged=')) { Fail "闸15t(pin/base)：失败文案里没有 judged=/expect= 两个 OID——拦它的是解析失败那一支而非身份比对（vacuous）。`n输出=$($pinBase4.Out)" }
                    else { Write-Host '  闸15t / T37-REMOTEMX/4 收据缺失+已 push 恢复平面 OK（完整配方逐步建模 + 有序腿轨迹比对；负例=已推的卡外改动令序列**停在范围步**且 review/status/pr-comment/merge-attempted/merge-reached 五枚哨兵全缺；正例=反向提交推上去后全程走通、五枚哨兵全在、--match-head-commit 实参 == PR head、评审腿走的是 refs/remotes/origin/master 远端基线；另两枚 pin 用例证 -ExpectTip/-ExpectBase 各自承重）' -ForegroundColor Green }
                  }
                }
              }
            }
          }
        }
        finally { Remove-Item -Recurse -Force $fx4.Root -ErrorAction SilentlyContinue }
      }
    }
    finally {
      $env:PATH = $rmSavedPath; $env:GH_MOCK_ROOT = $rmSavedRoot; $env:GH_MOCK_WT = $rmSavedWt; $env:GH_MOCK_MERGE_FAIL = $rmSavedMergeFail
      $env:GH_MOCK_BASE_MODE = $rmSavedBaseMode; $env:GH_MOCK_MERGE_STATE = $rmSavedMergeState
      $env:GH_MOCK_CI_MODE = $rmSavedCiMode; $env:SCAFFOLD_CI_TIMEOUT_SEC = $rmSavedCiTimeout
      $env:GH_MOCK_SLOW_SEC = $rmSavedSlowSec; $env:GH_MOCK_REAL_GIT = $rmSavedRealGit
      foreach ($rr in $script:rmRoots) { Remove-Item -Recurse -Force $rr -ErrorAction SilentlyContinue }
    }
  }
}
[void]$executedGateGroups.Add('seeded:17-remote')
}
}

if (Test-SeededShardRegionSelected -Region 'scanner') {
# ── 17cc/17dd（T0-GATE-HARDENING）+ 17cc(case)/17ee（T0-GATE-FIXFORWARD）：许可闸 Gradle 清单递归发现
#   （含 libs.versions.toml）+ verify.ps1 --no-daemon + 路径比较大小写语义跟随文件系统 + 发布清单 Gradle
#   阻断项单一解锁，各配单句删除变异。判据一律走独立子进程 + 专属断言 MARKER：子进程内部完成
#   「取内容 → 判定 → 打印 MARKER → 按结果退出 0/1」，外层只读子进程的退出码 + MARKER 文本——
#   卡片 dod_assert 字面要求「非零 且 命中指定断言文本」才算杀死变异，不是任意 nonzero、不是任意文本；
#   17cc(case)/17ee 的每枚变异进一步声明**它该红在哪一条子断言**上并锚定精确匹配失败码。
#   变异对象一律不是生产文件本体（临时同目录/暂存副本），结尾核**三份**生产文件 SHA256 全程未变（L196）：
#   scripts/check-licenses.ps1、scripts/verify.ps1、docs/RELEASE-CHECKLIST.md。
#   （命名 17cc/17dd/17ee 避开既有 17aa TD68 远端基线评审套件撞号。）
$realCLPath = Join-Path $RepoRoot 'scripts/check-licenses.ps1'
$realVfPath = Join-Path $RepoRoot 'scripts/verify.ps1'
$realCLHashBefore = (Get-FileHash -LiteralPath $realCLPath -Algorithm SHA256).Hash
$realVfHashBefore = (Get-FileHash -LiteralPath $realVfPath -Algorithm SHA256).Hash

# 独立子进程内部完成判断。脚本块固定，路径/needle/marker 全走 -Args 参数数组；含撇号或空格的合法路径不会进入
# PowerShell 源码文本，避免解析失败与命令注入。
function Invoke-MarkerAssertion(
  [ValidateSet('RunScript', 'ReadFile', 'GradleLibrary')][string]$Mode,
  [string]$SourcePath,
  [string]$Needle,
  [string]$MarkerId,
  [string]$ProbeRoot = ''
) {
  $child = {
    param([string]$ChildMode, [string]$ChildSourcePath, [string]$ChildNeedle, [string]$ChildMarkerId, [string]$ChildProbeRoot)
    $c = if ($ChildMode -eq 'RunScript') {
      & pwsh -NoProfile -File $ChildSourcePath 2>&1 | Out-String
    } elseif ($ChildMode -eq 'GradleLibrary') {
      . $ChildSourcePath -AsLibrary
      Get-GradleDiscoveryResults -Root $ChildProbeRoot | Out-String
    } else {
      Get-Content -LiteralPath $ChildSourcePath -Raw
    }
    if ($c.Contains($ChildNeedle)) { Write-Output "MARKER:${ChildMarkerId}:PRESENT"; exit 0 }
    Write-Output "MARKER:${ChildMarkerId}:ABSENT"; exit 1
  }
  $stdout = & pwsh -NoProfile -Command $child -Args @($Mode, $SourcePath, $Needle, $MarkerId, $ProbeRoot)
  return [PSCustomObject]@{ Exit = $LASTEXITCODE; StdOut = ($stdout -join "`n") }
}
# 核验判据结果是否吻合期望（exit 0 + PRESENT，或 exit 非零 + ABSENT）；不吻合即 Fail 并返回 $false。
function Test-MarkerResult($Result, [string]$MarkerId, [bool]$ExpectPresent, [string]$Context) {
  $word = if ($ExpectPresent) { 'PRESENT' } else { 'ABSENT' }
  $bad = if ($ExpectPresent) { $Result.Exit -ne 0 } else { $Result.Exit -eq 0 }
  if ($bad -or $Result.StdOut -notmatch "MARKER:${MarkerId}:$word") {
    Fail "$Context`: 判据子进程退出 $($Result.Exit)、stdout=$($Result.StdOut)（期望 exit $(if($ExpectPresent){'0'}else{'非零'}) + $word）。"
    return $false
  }
  return $true
}

# 判据失败码的**锚定**匹配（本轮 R3 发现）：`[regex]::Escape` 只转义元字符、**并不锚定**——裸子串匹配会让
# `ABSENT-CANON` 被 `ABSENT-CANONICAL` 这类后缀形态白拿分，等于"红在别的子断言上"仍被记为杀死。
# 锚到「行首 MARKER:<id>:<码> + 边界」，边界只允许行尾或 `(`（后者是刻意保留的诊断括号，如
# `ABSENT-HITSET(got=…)`）。凡按专属失败码分类的变异一律走本函数，不再各写一份裸匹配。
function Test-MarkerCode([string]$StdOut, [string]$MarkerId, [string]$Code) {
  $pattern = '(?m)^MARKER:' + [regex]::Escape($MarkerId) + ':' + [regex]::Escape($Code) + '(\(|\s*$)'
  return ($StdOut -match $pattern)
}

# 参数化子进程的路径安全回归：同一份含撇号路径分别走 RunScript / ReadFile，两路都必须命中。
$quotedProbeRoot = Join-Path ([System.IO.Path]::GetTempPath()) "st17cc-o'brien-$PID"
try {
  New-Item -ItemType Directory -Force $quotedProbeRoot | Out-Null
  $quotedProbeScript = Join-Path $quotedProbeRoot "probe script.ps1"
  Set-Content -LiteralPath $quotedProbeScript -Value "Write-Output 'QUOTED-PATH-OK'" -Encoding utf8
  $quotedRun = Invoke-MarkerAssertion -Mode RunScript -SourcePath $quotedProbeScript -Needle 'QUOTED-PATH-OK' -MarkerId 'QUOTED-RUN'
  $quotedRead = Invoke-MarkerAssertion -Mode ReadFile -SourcePath $quotedProbeScript -Needle 'QUOTED-PATH-OK' -MarkerId 'QUOTED-READ'
  if ((Test-MarkerResult $quotedRun 'QUOTED-RUN' $true '17cc quoted-path RunScript') -and
      (Test-MarkerResult $quotedRead 'QUOTED-READ' $true '17cc quoted-path ReadFile')) {
    Write-Host '  17cc 参数化子进程安全接收含撇号/空格路径 OK（RunScript + ReadFile）' -ForegroundColor Green
  }
} finally { Remove-Item -Recurse -Force $quotedProbeRoot -ErrorAction SilentlyContinue }

# 单句删除变异：定位唯一命中行、变异、跑 $Probe、还原、核 SHA256 未漂移（L196：同回合内完成）。
function Invoke-LineDeletionMutation([string]$Path, [string[]]$OrigLines, [string]$LineMarker, [scriptblock]$Probe) {
  $idx = @(0..($OrigLines.Count - 1) | Where-Object { $OrigLines[$_] -match [regex]::Escape($LineMarker) })
  if ($idx.Count -ne 1) { return [PSCustomObject]@{ Ok = $false; Reason = "源码里含「$LineMarker」的行数=$($idx.Count)（期望恰好 1）——变异定位不唯一，源码可能已漂移。" } }
  $origHash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash
  $mutLines = @(for ($i = 0; $i -lt $OrigLines.Count; $i++) { if ($i -ne $idx[0]) { $OrigLines[$i] } })
  Set-Content -LiteralPath $Path -Value $mutLines -Encoding utf8
  $probeResult = & $Probe
  Set-Content -LiteralPath $Path -Value $OrigLines -Encoding utf8
  $newHash = (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash
  if ($newHash -ne $origHash) { return [PSCustomObject]@{ Ok = $false; Reason = "变异还原后 SHA256 不符（原=$origHash，还原后=$newHash）——mutant 副本未干净还原。" } }
  return [PSCustomObject]@{ Ok = $true; Result = $probeResult }
}

# TD27: run the emitted non-Windows body through pwsh on every host. The target marker deliberately includes
# both forwarded arguments, while the semantic result turns a missing invocation into one exact failure code.
function Invoke-Td27PosixShimProbe([string]$HarnessPath, [string]$ExpectedReceipt, [string]$MarkerId) {
  $raw = (& pwsh -NoProfile -File $HarnessPath 'td27-sentinel-one' 'td27-sentinel-two' 2>&1 | Out-String)
  $rawExit = $LASTEXITCODE
  $present = $rawExit -eq 0 -and $raw.Contains($ExpectedReceipt)
  $code = if ($present) { 'PRESENT' } else { 'ABSENT-TD27-POSIX-INVOKE' }
  $semanticExit = if ($present) { 0 } else { 1 }
  return [PSCustomObject]@{ Exit = $semanticExit; StdOut = "MARKER:${MarkerId}:$code`nRAW_EXIT=$rawExit`n$raw"; RawExit = $rawExit; Raw = $raw }
}

if (Test-SeededShardRegionSelected -Region 'scanner') {
  # 17ac(TD27). Force the extensionless POSIX body through pwsh even on Windows. The shim target deliberately
  # lives in a different directory with whitespace and an apostrophe, so PSScriptRoot/current-directory fallback
  # cannot accidentally pass. The real Linux shebang+chmod path remains covered by 17ac(moving-ref) above.
  $td27ProbeRoot = Join-Path ([System.IO.Path]::GetTempPath()) "st17ac-td27-$PID"
  try {
    $td27WrapperRoot = Join-Path $td27ProbeRoot 'wrapper separate'
    $td27TargetRoot = Join-Path $td27ProbeRoot "target o'brien separate"
    $td27ControlHarness = Join-Path $td27WrapperRoot 'git-control.ps1'
    $td27MutantHarness = Join-Path $td27WrapperRoot 'git-mutant.ps1'
    $td27TargetShim = Join-Path $td27TargetRoot 'git-shim.ps1'
    $td27Receipt = 'TD27-POSIX-SHIM:td27-sentinel-one|td27-sentinel-two'
    New-Item -ItemType Directory -Force $td27WrapperRoot, $td27TargetRoot | Out-Null
    @'
$received = [string]::Join('|', [string[]]$args)
if ($received -ceq 'td27-sentinel-one|td27-sentinel-two') {
  Write-Output 'TD27-POSIX-SHIM:td27-sentinel-one|td27-sentinel-two'
  exit 0
}
Write-Error "unexpected TD27 arguments: $received"
exit 41
'@ | Set-Content -LiteralPath $td27TargetShim -Encoding utf8

    $td27SetupFailures = @()
    if (-not (Test-Path -LiteralPath $td27TargetShim)) { $td27SetupFailures += 'target git-shim.ps1 was not created' }
    if ((Split-Path -Parent $td27TargetShim) -ceq $td27WrapperRoot) { $td27SetupFailures += 'target and wrapper directories are not separate' }
    if (-not $td27TargetShim.Contains(' ') -or -not $td27TargetShim.Contains("'")) { $td27SetupFailures += 'target path lacks required whitespace/apostrophe coverage' }
    if (Test-Path -LiteralPath (Join-Path $td27WrapperRoot 'git-shim.ps1')) { $td27SetupFailures += 'wrapper directory unexpectedly contains a local git-shim.ps1' }
    if (-not (Get-Command Get-AcMoveGitWrapperBody -ErrorAction SilentlyContinue)) { $td27SetupFailures += '17ac wrapper emitter is unavailable in seeded scope' }
    if ($td27SetupFailures.Count) {
      Fail "闸17ac(td27-posix-shim)(setup)：$($td27SetupFailures -join '; ')——不能把缺目标/同目录/缺 emitter 误记为 TD27 语义 RED。"
    } else {
      $td27PosixBody = Get-AcMoveGitWrapperBody -ShimScript $td27TargetShim -UseWindows $false
      Set-Content -LiteralPath $td27ControlHarness -Value $td27PosixBody -Encoding utf8
      $td27ParseErrors = $null
      [void][System.Management.Automation.Language.Parser]::ParseFile($td27ControlHarness, [ref]$null, [ref]$td27ParseErrors)
      if ($td27ParseErrors.Count -ne 0) {
        Fail "闸17ac(td27-posix-shim)(setup)：emitted POSIX harness is not parseable ($($td27ParseErrors[0].Message))——parser failure is not TD27 behavior evidence。"
      } else {
        $td27Control = Invoke-Td27PosixShimProbe -HarnessPath $td27ControlHarness -ExpectedReceipt $td27Receipt -MarkerId 'TD27-POSIX-CONTROL'
        if (-not (Test-MarkerResult $td27Control 'TD27-POSIX-CONTROL' $true "种子缺陷 17ac(td27-posix-shim)：forced POSIX body must invoke absolute target=$td27TargetShim (wrapper=$td27WrapperRoot) and forward both sentinels")) {
          # This is the intended initial RED: the old PSScriptRoot body resolves only beside the harness, not at the target.
          if ($td27PosixBody.Contains('$PSScriptRoot/git-shim.ps1')) {
            Write-Warning "TD27-POSIX-SHIM RED confirmed: emitted body still uses PSScriptRoot while target is separate ($td27TargetShim)."
          }
        } else {
          Set-Content -LiteralPath $td27MutantHarness -Value $td27PosixBody -Encoding utf8
          $td27MutantLines = Get-Content -LiteralPath $td27MutantHarness
          # Invoke-LineDeletionMutation restores a line array; normalize the disposable fixture to that shape first.
          Set-Content -LiteralPath $td27MutantHarness -Value $td27MutantLines -Encoding utf8
          $td27MutantLines = Get-Content -LiteralPath $td27MutantHarness
          $td27InvocationLines = @($td27MutantLines | Where-Object { $_ -match '^&\s+.*@args\s*$' })
          if ($td27InvocationLines.Count -ne 1) {
            Fail "闸17ac(td27-posix-shim-mut)(setup)：emitted POSIX invocation line count=$($td27InvocationLines.Count) (expected 1)——不能把定位漂移记为 deletion mutation death。"
          } else {
            $td27PosixProbe = ${function:Invoke-Td27PosixShimProbe}
            $td27MutationProbe = {
              $mutantParseErrors = $null
              [void][System.Management.Automation.Language.Parser]::ParseFile($td27MutantHarness, [ref]$null, [ref]$mutantParseErrors)
              if ($mutantParseErrors.Count -ne 0) {
                return [PSCustomObject]@{ Exit = 1; StdOut = "MARKER:TD27-POSIX-MUT:SETUP-PARSE($($mutantParseErrors[0].Message))"; RawExit = -1 }
              }
              $result = & $td27PosixProbe -HarnessPath $td27MutantHarness -ExpectedReceipt $td27Receipt -MarkerId 'TD27-POSIX-MUT'
              if ($result.RawExit -ne 0) {
                return [PSCustomObject]@{ Exit = 1; StdOut = "MARKER:TD27-POSIX-MUT:SETUP-RUNTIME(raw-exit=$($result.RawExit))`n$($result.Raw)"; RawExit = $result.RawExit }
              }
              return $result
            }.GetNewClosure()
            $td27Mutation = Invoke-LineDeletionMutation -Path $td27MutantHarness -OrigLines $td27MutantLines -LineMarker $td27InvocationLines[0] -Probe $td27MutationProbe
            if (-not $td27Mutation.Ok) {
              Fail "闸17ac(td27-posix-shim-mut)(setup)：$($td27Mutation.Reason)"
            } elseif (-not (Test-MarkerResult $td27Mutation.Result 'TD27-POSIX-MUT' $false '种子缺陷 17ac(td27-posix-shim-mut)：deleting the one POSIX invocation must make the forced probe nonzero')) {
              # Test-MarkerResult already records the exact observed marker/exit.
            } elseif (-not (Test-MarkerCode $td27Mutation.Result.StdOut 'TD27-POSIX-MUT' 'ABSENT-TD27-POSIX-INVOKE')) {
              Fail "种子缺陷 17ac(td27-posix-shim-mut)：deletion became nonzero without exact ABSENT-TD27-POSIX-INVOKE classification (stdout=$($td27Mutation.Result.StdOut))——generic crash is not mutation death。"
            } else {
              Write-Host '  17ac(td27-posix-shim) forced POSIX absolute apostrophe/space target + exact forwarded sentinels OK; one-line deletion is nonzero ABSENT-TD27-POSIX-INVOKE and restores fixture SHA OK' -ForegroundColor Green
            }
          }
        }
      }
    }
  } finally {
    Remove-Item -LiteralPath $td27ProbeRoot -Recurse -Force -ErrorAction SilentlyContinue
    if (Test-Path -LiteralPath $td27ProbeRoot) { Fail "闸17ac(td27-posix-shim) 收尾：temporary fixture $td27ProbeRoot was not removed。" }
  }
}
# 建目录联接/符号链接，跨平台优先符号链接（Linux 免权限即可用；Windows 无 Dev Mode/管理员会失败）——
# 失败则退回目录联接（Windows 免管理员）。两者都建不出时返回 $false（调用方须优雅退化，R3 round-5 dimension
# #6：CI 的 ubuntu 支路建不出联接，若只退化成静态检查就验证不到真实穿越行为，须让符号链接撑起该支路）。
function New-ScaffoldReparseLink([string]$LinkPath, [string]$TargetPath) {
  try { New-Item -ItemType SymbolicLink -Path $LinkPath -Target $TargetPath -ErrorAction Stop | Out-Null }
  catch {
    try { New-Item -ItemType Junction -Path $LinkPath -Target $TargetPath -ErrorAction Stop | Out-Null }
    catch { return $false }
  }
  $item = Get-Item -LiteralPath $LinkPath -Force -ErrorAction SilentlyContinue
  return [bool]($item -and (($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0))
}

$needleA = 'android/gradle/libs.versions.toml'
$needleB = 'android/core/build.gradle.kts'

# 17cc. Gradle 清单递归发现（真实 android/ 树；两分支各自单句删除变异，数据驱动共用同一套判据/变异机制）
$mutantCL = Join-Path $RepoRoot "scripts/.st17cc-mutant-$PID.ps1"
try {
  Copy-Item -LiteralPath $realCLPath -Destination $mutantCL -Force
  $baseA = Invoke-MarkerAssertion -Mode GradleLibrary -SourcePath $mutantCL -Needle $needleA -MarkerId 'GRADLE-A-BASE' -ProbeRoot $RepoRoot
  $baseB = Invoke-MarkerAssertion -Mode GradleLibrary -SourcePath $mutantCL -Needle $needleB -MarkerId 'GRADLE-B-BASE' -ProbeRoot $RepoRoot
  $baseOk = (Test-MarkerResult $baseA 'GRADLE-A-BASE' $true "17cc 基线（$needleA，递归发现分支①未生效或该文件缺失）") -and
            (Test-MarkerResult $baseB 'GRADLE-B-BASE' $true "17cc 基线（$needleB，递归发现分支②未生效）")
  if ($baseOk) {
    Write-Host "  17cc 基线（GREEN）：$needleA / $needleB 两条判据子进程均 exit 0 + PRESENT OK" -ForegroundColor Green
    $origLines = Get-Content -LiteralPath $mutantCL
    Set-Content -LiteralPath $mutantCL -Value $origLines -Encoding utf8   # 规整化：Get-Content/Set-Content 往返非字节级恒等，先写一遍原始行数组令后续「变异→还原」哈希可比。
    $cases = @(
      @{ Id = 'A'; Label = 'libs.versions.toml 发现分支'; LineMarker = "-Names @('libs.versions.toml')"; Target = $needleA; Control = $needleB }
      @{ Id = 'B'; Label = 'build.gradle{,.kts} 发现分支'; LineMarker = "-Names @('build.gradle', 'build.gradle.kts')"; Target = $needleB; Control = $needleA }
    )
    $invokeMarkerAssertion = ${function:Invoke-MarkerAssertion}
    foreach ($case in $cases) {
      $selfMarker = "GRADLE-$($case.Id)-MUT"; $ctrlMarker = "GRADLE-$($case.Id)-MUT-CTRL"
      $probe = {
        [PSCustomObject]@{
          Self = & $invokeMarkerAssertion -Mode GradleLibrary -SourcePath $mutantCL -Needle $case.Target -MarkerId $selfMarker -ProbeRoot $RepoRoot
          Ctrl = & $invokeMarkerAssertion -Mode GradleLibrary -SourcePath $mutantCL -Needle $case.Control -MarkerId $ctrlMarker -ProbeRoot $RepoRoot
        }
      }.GetNewClosure()
      try {
        Remove-Item Function:Invoke-MarkerAssertion -ErrorAction Stop
        $m = Invoke-LineDeletionMutation -Path $mutantCL -OrigLines $origLines -LineMarker $case.LineMarker -Probe $probe
      } finally {
        Set-Item Function:Invoke-MarkerAssertion -Value $invokeMarkerAssertion -ErrorAction Stop
      }
      if (-not $m.Ok) { Fail "17cc($($case.Id))：$($m.Reason)"; continue }
      $selfOk = Test-MarkerResult $m.Result.Self $selfMarker $false "种子缺陷 17cc($($case.Id))：删掉$($case.Label)那一行后（vacuous mutation，卡片 dod_assert 字面要求：非零且命中指定断言文本）"
      if (-not $selfOk) { continue }
      $ctrlOk = Test-MarkerResult $m.Result.Ctrl $ctrlMarker $true "17cc($($case.Id)) 分类器：删掉$($case.Label)那一行后，控制组判据（两分支须真正独立，L165）"
      if (-not $ctrlOk) { continue }
      Write-Host "  17cc($($case.Id)) $($case.Label)：外层 Invoke-MarkerAssertion 解绑后，真实 A/B probe 仍给出目标 exit 非零 + ABSENT、控制组 exit 0 + PRESENT，副本已还原且 SHA256 一致 OK（TD23）" -ForegroundColor Green
    }
  }
} finally {
  Remove-Item -LiteralPath $mutantCL -Force -ErrorAction SilentlyContinue
  if (Test-Path $mutantCL) { Fail "17cc 收尾：临时同目录副本 $mutantCL 未能删除——请手动清理，避免 git status 出现 ?? 残留。" }
}

# 17cc(prune). 排除目录真正「下钻前剪枝」，非「枚举后过滤」：用会对被排除目录名抛错的桩 -Enumerator，
# 剪枝失效时桩抛出可辨认异常；剪枝生效时桩永不被这些目录调用。合成小夹具，不碰真实 android/ 树体积。
. $realCLPath -AsLibrary
$fxPrune = Join-Path ([System.IO.Path]::GetTempPath()) "st17cc-prune-$PID"
if (Test-Path $fxPrune) { Remove-Item -Recurse -Force $fxPrune }
try {
  New-Item -ItemType Directory -Force (Join-Path $fxPrune 'real') | Out-Null
  Set-Content (Join-Path $fxPrune 'real/build.gradle') 'real' -Encoding utf8
  # 夹具期望集必须独立于生产列表；否则删除生产项时，夹具与 oracle 会同步缩小并假绿。全局名称级缓存可在任意
  # 深度出现；路径级产物只排除仓根 data/ 与 frontend/dist/；android/.gitignore 的未锚定目录型规则
  # 则在 android/ 之下任意深度生效，但不得伤及其它树中同名的业务目录。
  $expectedSkipNames = @('.gradle', 'build', 'node_modules', '.git', '.venv', '__pycache__', '.pytest_cache', '.ruff_cache', '.mypy_cache', '.review', '_local', 'runtime', 'auth', '.secrets', '.idea', '.vscode')
  $expectedSkipPaths = @('data', 'frontend/dist')
  $expectedAndroidSkipNames = @('.kotlin', 'captures', '.cxx')
  $broadPathSkips = @((@($expectedSkipPaths | ForEach-Object { Split-Path -Leaf $_ }) + $expectedAndroidSkipNames) | Where-Object { $gradleSkipDirs -contains $_ })
  if ($broadPathSkips.Count -gt 0) { Fail "17cc(prune)：路径级 ignore 被错误扩大成全局名称排除：$($broadPathSkips -join ', ')。" }
  foreach ($skip in $expectedSkipNames) {
    New-Item -ItemType Directory -Force (Join-Path $fxPrune "$skip/decoy") | Out-Null
    Set-Content (Join-Path $fxPrune "$skip/decoy/build.gradle") 'decoy' -Encoding utf8
  }
  foreach ($skip in $expectedSkipPaths) {
    New-Item -ItemType Directory -Force (Join-Path $fxPrune "$skip/decoy") | Out-Null
    Set-Content (Join-Path $fxPrune "$skip/decoy/build.gradle") 'decoy' -Encoding utf8
  }
  foreach ($skip in $expectedAndroidSkipNames) {
    $nested = "android/feature/deep/$skip"
    New-Item -ItemType Directory -Force (Join-Path $fxPrune "$nested/decoy") | Out-Null
    Set-Content (Join-Path $fxPrune "$nested/decoy/build.gradle") 'decoy' -Encoding utf8
  }
  # 同名目录在规则作用域外必须被扫到：dist 只排 frontend/dist，captures 只排 android 子树。
  $allowedRelativeHits = @('real/build.gradle', 'android/dist/build.gradle', 'other/captures/build.gradle')
  foreach ($allowed in $allowedRelativeHits) {
    New-Item -ItemType Directory -Force (Split-Path -Parent (Join-Path $fxPrune $allowed)) | Out-Null
    Set-Content (Join-Path $fxPrune $allowed) 'allowed' -Encoding utf8
  }
  $throwIfExcluded = {
    param($d)
    $leaf = Split-Path -Leaf $d
    $relative = [System.IO.Path]::GetRelativePath($fxPrune, $d).Replace('\', '/')
    $isAndroidLocal = $relative.StartsWith('android/') -and ($expectedAndroidSkipNames -contains $leaf)
    if (($expectedSkipNames -contains $leaf) -or ($expectedSkipPaths -contains $relative) -or $isAndroidLocal) { throw "PRUNE-VIOLATION: enumerator invoked on excluded dir $d" }
    Get-ChildItem -LiteralPath $d -Force -ErrorAction Stop
  }.GetNewClosure()
  try {
    $pruneHits = @(Find-GradleManifests -Root $fxPrune -Names @('build.gradle') -Enumerator $throwIfExcluded)
    $actualRelativeHits = @($pruneHits | ForEach-Object { [System.IO.Path]::GetRelativePath($fxPrune, $_).Replace('\', '/') } | Sort-Object)
    $expectedRelativeHits = @($allowedRelativeHits | Sort-Object)
    if (($actualRelativeHits -join '|') -ne ($expectedRelativeHits -join '|')) {
      Fail "17cc(prune)：期望发现作用域外的 $($expectedRelativeHits -join ', ')，实得 $($actualRelativeHits -join ', ')。"
    } else {
      Write-Host "  17cc(prune) 独立 ignore 契约全部剪枝 OK（全局名称 $($expectedSkipNames.Count) 项 + 精确路径 $($expectedSkipPaths.Count) 项 + Android 子树名称 $($expectedAndroidSkipNames.Count) 项）" -ForegroundColor Green
    }
  } catch {
    Fail "种子缺陷 17cc(prune)：$($_.Exception.Message) —— Find-GradleManifests 真的下钻进了被排除目录（先枚举全树、再事后过滤的旧行为回归）。"
  }
} finally { Remove-Item -Recurse -Force $fxPrune -ErrorAction SilentlyContinue }

# 17cc(case). 路径比较的大小写语义必须跟随文件系统（T0-GATE-FIXFORWARD · T0-GATE-HARDENING 事后 R3 block ①）。
#   病因：`-contains`/`-notcontains` 恒**不敏感**，而同一行的 `StartsWith('android/')` 恒**敏感**——一行两套语义。
#   后果双向：Linux（敏感）上被追踪的 `Build/`、`Data/` 被当成 ignore 的 `build/`、`data` **静默剪掉**（漏扫，
#   而"没扫到"会被当成"没有清单"，正是本闸 fail-closed 要根除的形态）；Windows（不敏感）上 `Android/` 前缀
#   又匹配不上 `android/`，该剪的 `.kotlin` 反而没剪。
#   夹具每个轴造**一对**探针（错大小写 + 正确大小写），尽量放在**不同父目录**下——Windows 同一目录内
#   `build/` 与 `Build/` 无法并存（New-Item 只会返回既有那个），换父目录即可让两支在两个平台都存在。
#   **例外（刻意接受）**：`android/` 前缀那一轴的两支父目录名本身只差大小写（`Android/` vs `android/`），
#   在 Windows 上必然坍缩成同一个物理目录（先建的那个定名），故该轴的"两支并存"只在 Linux 成立。
#   这不影响判据正确性：Windows 上两支都该被剪、期望集里本来就都没有它们；Linux 上两支才分立并各自出现在
#   期望集里。因此 **Linux 那条分支在 Windows 上无法端到端复现**，只能靠 CI 的 ubuntu 腿真跑
#   （守卫④三条路径的判定已按 Ordinal 逐条核过：Android/... 前缀不匹配→发现、android/...→剪、
#   android/deep2/.KOTLIN 名不匹配→发现）。
#     · 错大小写那支：期望**随平台不同**（不敏感 → 被剪；敏感 → 被发现），钉住"语义跟随文件系统"。
#     · 正确大小写那支：两平台都该被剪，是**删除变异的靶**——删掉某道守卫它就冒出来，于是变异在两个平台
#       **都**能被杀死（只有错大小写探针时，删守卫在其中一个平台恰好不改变结果，变异会假幸存）。
#   期望集按 OS 分：**同一棵树在敏感/不敏感文件系统上本就该给出不同的正确答案**，这不是平台妥协。
#   判据**只有一份**，写在子进程脚本块 $caseProbe 里：三个比较器各自的两模式不变量、缺省跟随文件系统、
#   以及端到端命中集逐字比对**全在它里面**。基线跑一次未变异副本 = 本闸的真断言；每枚变异跑同一份判据 =
#   真在测那条断言。**绝不在父进程另写一份等价判据**——那样删掉真断言后变异照样绿（vacuous mutation）。
#   失败分五种 ABSENT 后缀（EQUALS-MODES / LIST-MODES / PREFIX-MODES / UNIT-DEFAULT / HITSET），
#   且**每枚变异声明它该红在哪一条**并做锚定精确匹配——否则一枚变异可能因别的子断言先失败而被误判为已杀死。
$fxCase = Join-Path ([System.IO.Path]::GetTempPath()) "st17cc-case-$PID"
$mutantCaseCL = Join-Path $RepoRoot "scripts/.st17cc-case-mutant-$PID.ps1"
if (Test-Path $fxCase) { Remove-Item -Recurse -Force $fxCase }
try {
  # 五个调用点各配探针。排除列表**显式传参**、且经 -Args 传进子进程（父子共用同一份字面量，不各写一份）：
  # 本闸测的是比较语义与守卫接线，真实 ignore 清单由 17cc(prune) 守。
  $caseSkipDirs = 'build'
  $caseSkipRelativePaths = 'wrong/data|right/data'
  $caseAndroidSkipDirs = '.kotlin'
  $caseNames = 'build.gradle'
  $caseProbes = @(
    @{ Rel = 'wrong/Build/x/build.gradle';               Kind = 'wrong'; Axis = '守卫② SkipDirs 名称级排除' }
    @{ Rel = 'right/build/x/build.gradle';               Kind = 'right'; Axis = '守卫② SkipDirs 名称级排除' }
    @{ Rel = 'wrong/Data/x/build.gradle';                Kind = 'wrong'; Axis = '守卫③ SkipRelativePaths 路径级排除' }
    @{ Rel = 'right/data/x/build.gradle';                Kind = 'right'; Axis = '守卫③ SkipRelativePaths 路径级排除' }
    @{ Rel = 'Android/deep/.kotlin/x/build.gradle';      Kind = 'wrong'; Axis = '守卫④ android/ 前缀（前缀错大小写）' }
    @{ Rel = 'android/deep2/.KOTLIN/x/build.gradle';     Kind = 'wrong'; Axis = '守卫④ AndroidSkipDirs（目录名错大小写，前缀正确）' }
    @{ Rel = 'android/deep/.kotlin/x/build.gradle';      Kind = 'right'; Axis = '守卫④ 全部正确大小写' }
    @{ Rel = 'names/BUILD.GRADLE';                       Kind = 'wrong'; Axis = 'Names 清单文件名' }
    @{ Rel = 'keep/build.gradle';                        Kind = 'ctrl';  Axis = '对照（正确大小写，两平台恒命中）' }
  )
  foreach ($p in $caseProbes) {
    New-Item -ItemType Directory -Force (Split-Path -Parent (Join-Path $fxCase $p.Rel)) | Out-Null
    Set-Content (Join-Path $fxCase $p.Rel) 'case-probe' -Encoding utf8
  }
  # 不敏感文件系统（Windows/macOS）：错大小写 == 正确大小写，故三道排除对两支都生效、BUILD.GRADLE 算清单。
  # 敏感文件系统（Linux/CI）：错大小写 ≠ 被 ignore 的那个，故排除只对正确大小写那支生效、BUILD.GRADLE 不算清单。
  #   注意 android/deep2/.KOTLIN 这一支：前缀正确、只有目录名错大小写——它是 **AndroidSkipDirs 比较器的
  #   casing 覆盖**（前缀那支变了大小写就走不到名称比较，测不到这一段）。
  $caseInsensitiveFs = ($IsWindows -or $IsMacOS)
  $expectedCaseHits = @(if ($caseInsensitiveFs) {
      'keep/build.gradle'; 'names/BUILD.GRADLE'
    } else {
      'Android/deep/.kotlin/x/build.gradle'; 'android/deep2/.KOTLIN/x/build.gradle'; 'keep/build.gradle'
      'wrong/Build/x/build.gradle'; 'wrong/Data/x/build.gradle'
    }) | Sort-Object
  $fsLabel = if ($caseInsensitiveFs) { '不敏感（Windows/macOS）' } else { '敏感（Linux）' }
  # 内联不经 GetNewClosure()：$LASTEXITCODE 需取子进程调用后的新鲜值（同 17cc(reparse-mut) 的注记）。
  $caseProbe = {
    param([string]$LibraryPath, [string]$ProbeRoot, [string]$Expected, [string]$MarkerId, [string]$InsensitiveFs,
          [string]$SkipDirs, [string]$SkipRelPaths, [string]$AndroidSkips, [string]$Names)
    Set-StrictMode -Version Latest
    $ErrorActionPreference = 'Stop'
    . $LibraryPath -AsLibrary
    # 三个比较器各自的两模式不变量：显式传 -Comparison 时答案必须相反（证语义真被参数化，而非写死一种）。
    $eqOrd = [bool](Test-GradleNameEquals -Left 'Build' -Right 'build' -Comparison ([System.StringComparison]::Ordinal))
    $eqIgn = [bool](Test-GradleNameEquals -Left 'Build' -Right 'build' -Comparison ([System.StringComparison]::OrdinalIgnoreCase))
    if ($eqOrd -or (-not $eqIgn)) { Write-Output "MARKER:${MarkerId}:ABSENT-EQUALS-MODES(ord=$eqOrd,ign=$eqIgn)"; exit 1 }
    $lsOrd = [bool](Test-GradleNameInList -List @('build') -Value 'Build' -Comparison ([System.StringComparison]::Ordinal))
    $lsIgn = [bool](Test-GradleNameInList -List @('build') -Value 'Build' -Comparison ([System.StringComparison]::OrdinalIgnoreCase))
    if ($lsOrd -or (-not $lsIgn)) { Write-Output "MARKER:${MarkerId}:ABSENT-LIST-MODES(ord=$lsOrd,ign=$lsIgn)"; exit 1 }
    $pfOrd = [bool](Test-GradlePathPrefix -Path 'Android/x' -Prefix 'android/' -Comparison ([System.StringComparison]::Ordinal))
    $pfIgn = [bool](Test-GradlePathPrefix -Path 'Android/x' -Prefix 'android/' -Comparison ([System.StringComparison]::OrdinalIgnoreCase))
    if ($pfOrd -or (-not $pfIgn)) { Write-Output "MARKER:${MarkerId}:ABSENT-PREFIX-MODES(ord=$pfOrd,ign=$pfIgn)"; exit 1 }
    # 缺省语义必须跟随本机文件系统（三个比较器共用同一个 $gradlePathComparison，测其一即测缺省源）。
    $def = [bool](Test-GradleNameEquals -Left 'Build' -Right 'build')
    if ($def -ne [bool]::Parse($InsensitiveFs)) { Write-Output "MARKER:${MarkerId}:ABSENT-UNIT-DEFAULT(def=$def)"; exit 1 }
    # 端到端：一棵树、五个调用点，命中集必须**逐字等于**本平台期望集（不是"包含/不包含"的宽断言，L165）。
    $h = @(Find-GradleManifests -Root $ProbeRoot -Names ($Names -split '\|') -SkipDirs ($SkipDirs -split '\|') -SkipRelativePaths ($SkipRelPaths -split '\|') -AndroidSkipDirs ($AndroidSkips -split '\|'))
    $rel = @($h | ForEach-Object { [System.IO.Path]::GetRelativePath($ProbeRoot, $_).Replace('\', '/') } | Sort-Object) -join '|'
    if ($rel -ne $Expected) { Write-Output "MARKER:${MarkerId}:ABSENT-HITSET(got=$rel)"; exit 1 }
    Write-Output "MARKER:${MarkerId}:PRESENT"; exit 0
  }
  # 判据调用的固定尾参（除 MarkerId 外全同），基线与每枚变异共用——参数一变两边同时变，不会漂移。
  $caseTail = @($caseInsensitiveFs.ToString(), $caseSkipDirs, $caseSkipRelativePaths, $caseAndroidSkipDirs, $caseNames)
  # **必须是函数、不能是 GetNewClosure() 的脚本块**：闭包会把 $LASTEXITCODE 这类自动变量在建闭包那一刻冻进
  # 私有作用域，闭包体内 & pwsh 更新的是外层动态作用域的值，闭包读到的还是冻结时的旧值（子进程明明 exit 1，
  # 父进程却读成 0，判据遂"退出 0 + ABSENT"自相矛盾）。函数体内读则取的是调用后的新鲜值——同
  # Invoke-MarkerAssertion 的写法，与 17cc(reparse-mut) 处那段注记同源。
  function Invoke-CaseProbe([scriptblock]$Body, [string[]]$ArgList) {
    $out = & pwsh -NoProfile -Command $Body -Args $ArgList
    return [PSCustomObject]@{ Exit = $LASTEXITCODE; StdOut = ($out -join "`n") }
  }
  $invokeCaseProbe = ${function:Invoke-CaseProbe}
  $caseProbeArgs = { param([string]$MarkerId) @($mutantCaseCL, $fxCase, ($expectedCaseHits -join '|'), $MarkerId) + $caseTail }.GetNewClosure()

  Copy-Item -LiteralPath $realCLPath -Destination $mutantCaseCL -Force
  $caseLines = Get-Content -LiteralPath $mutantCaseCL
  Set-Content -LiteralPath $mutantCaseCL -Value $caseLines -Encoding utf8   # 规整化（同 17cc 主体）：令后续「变异→还原」哈希可比。
  $caseBase = Invoke-CaseProbe -Body $caseProbe -ArgList (& $caseProbeArgs 'GRADLE-CASE-BASE')
  if (Test-MarkerResult $caseBase 'GRADLE-CASE-BASE' $true "种子缺陷 17cc(case)：本机文件系统大小写$fsLabel，三个比较器的两模式不变量、缺省语义或命中集（期望 [$($expectedCaseHits -join ', ')]）不符——五个调用点里至少一个仍在用恒不敏感的比较或恒敏感的前缀判断") {
    Write-Host "  17cc(case) 基线（GREEN）：Equals/InList/Prefix 三比较器两模式各自相反 + 缺省跟随文件系统（$fsLabel）+ 五个调用点命中集逐字等于期望集（$($expectedCaseHits.Count) 项）OK" -ForegroundColor Green

    # 变异组。删除变异一律复用既有 Invoke-LineDeletionMutation（定位唯一行 → 删 → 跑判据 → 还原 → 核 SHA256），
    # 不另起一套 copy/locate/mutate/restore 循环（卡片 non_goals：复用 17cc/17dd 的 harness）。
    # 唯一例外是比较器缺省那一枚：它**只能替换、不能删除**——删掉该行后 $gradlePathComparison 未定义，子进程会
    # 崩在 StrictMode 而非给出错误命中集，那是"崩溃杀"，证明不了语义。替换成**本平台的错误语义**才是行为杀
    # （不敏感机器换成恒敏感、敏感机器换成恒不敏感；用同一常量则会在其中一个平台假幸存）。
    $wrongComparison = if ($caseInsensitiveFs) { '[System.StringComparison]::Ordinal' } else { '[System.StringComparison]::OrdinalIgnoreCase' }
    $caseMutations = @(
      @{ Id = 'guard2'; Code = 'ABSENT-HITSET'; Label = '守卫② SkipDirs 名称级排除'
         Marker = '$skip = Test-GradleNameInList -List $SkipDirs -Value $e.Name' }
      @{ Id = 'guard3'; Code = 'ABSENT-HITSET'; Label = '守卫③ SkipRelativePaths 路径级排除'
         Marker = '$skip = Test-GradleNameInList -List $SkipRelativePaths -Value $relativePath' }
      @{ Id = 'guard4'; Code = 'ABSENT-HITSET'; Label = '守卫④ android/ 前缀 + AndroidSkipDirs'
         Marker = 'Test-GradlePathPrefix -Path $relativePath -Prefix ''android/''' }
      @{ Id = 'names'; Code = 'ABSENT-HITSET'; Label = 'Names 清单文件名收集行'
         Marker = 'if (Test-GradleNameInList -List $Names -Value $e.Name) { $found.Add($e.FullName) }' }
      @{ Id = 'equals'; Code = 'ABSENT-EQUALS-MODES'; Label = 'Test-GradleNameEquals 的比较本体'
         Marker = 'return [string]::Equals($Left, $Right, $Comparison)' }
      # LIST-MODES 必须有一枚**只打中它**的变异：删 Test-GradleNameEquals 的本体会让判据在更早的
      # EQUALS-MODES 就退出，LIST-MODES 那条断言永远走不到，等于没被证明在测（本轮 R3 的发现）。
      # 删这一行只让 InList 恒 $false、Equals 本体完好，故判据必然停在 LIST-MODES。
      @{ Id = 'list'; Code = 'ABSENT-LIST-MODES'; Label = 'Test-GradleNameInList 的遍历比较本体'
         Marker = 'foreach ($item in $List) { if (Test-GradleNameEquals -Left $item -Right $Value -Comparison $Comparison) { return $true } }' }
      @{ Id = 'prefix'; Code = 'ABSENT-PREFIX-MODES'; Label = 'Test-GradlePathPrefix 的比较本体'
         Marker = 'return $Path.StartsWith($Prefix, $Comparison)' }
    )
    foreach ($cm in $caseMutations) {
      $mMarkerId = "GRADLE-CASE-MUT-$($cm.Id.ToUpperInvariant())"
      $probe = {
        try {
          & $invokeCaseProbe -Body $caseProbe -ArgList (& $caseProbeArgs $mMarkerId)
        } catch {
          Fail "[TD25-CLOSURE-SCOPE] 17cc(case-mut/$($cm.Id))：移除 ambient Invoke-CaseProbe 后真实 probe 未保留其 marker/exit 判据。"
          [PSCustomObject]@{ Exit = 1; StdOut = "TD25-CLOSURE-SCOPE: $($_.Exception.Message)" }
        }
      }.GetNewClosure()
      try {
        if ($cm.Id -eq 'guard2') { Remove-Item Function:Invoke-CaseProbe -ErrorAction Stop }
        $m = Invoke-LineDeletionMutation -Path $mutantCaseCL -OrigLines $caseLines -LineMarker $cm.Marker -Probe $probe
      } finally {
        if ($cm.Id -eq 'guard2') { Set-Item Function:Invoke-CaseProbe -Value $invokeCaseProbe -ErrorAction Stop }
      }
      if (-not $m.Ok) { Fail "17cc(case-mut/$($cm.Id))：$($m.Reason)"; continue }
      if (-not (Test-MarkerResult $m.Result $mMarkerId $false "种子缺陷 17cc(case-mut/$($cm.Id))：删掉「$($cm.Label)」后（vacuous coverage：本闸测不出这道守卫/这条语义被摘掉的回归）")) { continue }
      # 分类器：不只要"非零 + ABSENT"，还要红在**它该红的那一条**上——否则一枚变异可能因别的子断言先失败而假杀。
      if (-not (Test-MarkerCode $m.Result.StdOut $mMarkerId $cm.Code)) {
        Fail "17cc(case-mut/$($cm.Id)) 分类器：变异确实变红，但失败码不是预期的 $($cm.Code)（实得 stdout=$($m.Result.StdOut)）——红在了别的子断言上，本枚变异并未证明它针对的那条断言在测。"
      } else {
        Write-Host "  17cc(case-mut/$($cm.Id)) $($cm.Label)：单句删除后判据子进程 exit 非零 + $($cm.Code)（RED，红在该红的那条上）、副本已还原且 SHA256 一致 OK" -ForegroundColor Green
      }
    }
    # 缺省语义替换变异（唯一非删除的一枚，理由见上）。
    $defMarker = '$gradlePathComparison = if ($IsWindows -or $IsMacOS)'
    $defIdx = @(0..($caseLines.Count - 1) | Where-Object { $caseLines[$_] -match [regex]::Escape($defMarker) })
    if ($defIdx.Count -ne 1) {
      Fail "17cc(case-mut/default) 前置：源码里含比较器缺省定义「$defMarker」的行数=$($defIdx.Count)（期望恰好 1）——变异定位不唯一，源码可能已漂移。"
    } else {
      $defBaselineHash = (Get-FileHash -LiteralPath $mutantCaseCL -Algorithm SHA256).Hash
      $defMut = $caseLines.Clone(); $defMut[$defIdx[0]] = "`$gradlePathComparison = $wrongComparison"
      Set-Content -LiteralPath $mutantCaseCL -Value $defMut -Encoding utf8
      $defRes = Invoke-CaseProbe -Body $caseProbe -ArgList (& $caseProbeArgs 'GRADLE-CASE-MUT-DEFAULT')
      Set-Content -LiteralPath $mutantCaseCL -Value $caseLines -Encoding utf8
      $defRestored = (Get-FileHash -LiteralPath $mutantCaseCL -Algorithm SHA256).Hash
      if ($defRestored -ne $defBaselineHash) {
        Fail "17cc(case-mut/default) 收尾：变异副本还原后 SHA256 与规整化基线不符（还原后=$defRestored，基线=$defBaselineHash）——mutant 未干净还原（L196）。"
      } elseif (Test-MarkerResult $defRes 'GRADLE-CASE-MUT-DEFAULT' $false "种子缺陷 17cc(case-mut/default)：把比较器缺省值替换成 $wrongComparison（本平台的错误语义）后（vacuous coverage：本闸测不出「缺省语义与文件系统不符」这类回归）") {
        if (-not (Test-MarkerCode $defRes.StdOut 'GRADLE-CASE-MUT-DEFAULT' 'ABSENT-UNIT-DEFAULT')) {
          Fail "17cc(case-mut/default) 分类器：变异确实变红，但失败码不是预期的 ABSENT-UNIT-DEFAULT（实得 stdout=$($defRes.StdOut)）——红在了别的子断言上。"
        } else {
          Write-Host "  17cc(case-mut/default) 比较器缺省语义 → $wrongComparison：替换后判据子进程 exit 非零 + ABSENT-UNIT-DEFAULT（RED，红在该红的那条上）、副本已还原 OK" -ForegroundColor Green
        }
      }
    }
  }
} finally {
  Remove-Item -Recurse -Force $fxCase -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath $mutantCaseCL -Force -ErrorAction SilentlyContinue
  if (Test-Path $mutantCaseCL) { Fail "17cc(case) 收尾：临时同目录副本 $mutantCaseCL 未能删除——请手动清理，避免 git status 出现 ?? 残留。" }
}

# 17cc(reparse). 目录联接/符号链接（ReparsePoint）绝不下钻——联接若指向仓外目录，扫描范围可能溢出仓外；
# 联接若自引用/循环，遍历不终止。夹具：$fxReparseRoot/inside/link-out 指向**仓外**独立临时目录 $fxOutside
# （放一个 decoy build.gradle）。New-ScaffoldReparseLink 跨平台建链（symlink 优先、Windows 退回 junction），
# 建不出时静态兜底——用 AST token 流剔除 Comment 类 token 后核 ReparsePoint 判据在**非注释代码**中，
# 注释单独出现不算数。命中集合须同时拒绝别名路径（$reparseLinkPath）与物理目标路径（$fxOutside）两个前缀
# ——联接若被追进去，Get-ChildItem 报告的是"枚举时给的目录路径"即别名路径，只查物理目标前缀会永远命中不了、
# 判据空转；并要求恰好 1 个命中（不止查"无泄漏+有内部命中"两个独立条件的并集）。另配守卫失效变异：
# 源码副本里把守卫①整条赋值**替换**成恒 `$false`（该守卫自 T0-GATE-FIXFORWARD 起是独占一行的赋值，
# 删掉它会让 $skip 未定义而崩在 StrictMode，那是崩溃杀、证明不了守卫语义，故此处用替换而非删除），
# 证明"如果有人真弱化了这段守卫"，本闸的行为断言确实会栽（不是"不管有没有守卫都恒 OK"的摆设）。
$fxReparseRoot = Join-Path ([System.IO.Path]::GetTempPath()) "st17cc-reparse-o'brien-$PID"
$fxOutside = Join-Path ([System.IO.Path]::GetTempPath()) "st17cc-reparse-outside-o'brien-$PID"
if (Test-Path $fxReparseRoot) { Remove-Item -Recurse -Force $fxReparseRoot }
if (Test-Path $fxOutside) { Remove-Item -Recurse -Force $fxOutside }
$reparseLinkPath = Join-Path $fxReparseRoot 'inside/link-out'
$mutantReparseCL = Join-Path $RepoRoot "scripts/.st17cc-reparse-mutant-$PID.ps1"
try {
  New-Item -ItemType Directory -Force (Join-Path $fxReparseRoot 'inside') | Out-Null
  Set-Content (Join-Path $fxReparseRoot 'inside/build.gradle') 'inside' -Encoding utf8
  New-Item -ItemType Directory -Force $fxOutside | Out-Null
  Set-Content (Join-Path $fxOutside 'build.gradle') 'outside-decoy' -Encoding utf8
  $canLink = New-ScaffoldReparseLink -LinkPath $reparseLinkPath -TargetPath $fxOutside
  if (-not $canLink) {
    $reparseTokens = $null
    [System.Management.Automation.Language.Parser]::ParseFile($realCLPath, [ref]$reparseTokens, [ref]$null) | Out-Null
    $nonCommentReparseHits = @($reparseTokens | Where-Object { $_.Kind -ne [System.Management.Automation.Language.TokenKind]::Comment -and $_.Text -match 'ReparsePoint' })
    if ($nonCommentReparseHits.Count -eq 0) { Fail '17cc(reparse) 静态兜底：check-licenses.ps1 的非注释 token 里未见 ReparsePoint 判据——剪枝逻辑可能未落地或已被删（本机/本用户无法建符号链接/目录联接，只能退化到源码静态核验；注释单独出现不算数）。' }
    else { Skip-SelftestCheck -GateId '17cc(reparse-functional)' -Reason 'REPARSE-CAPABILITY-MISSING' -Message '  17cc(reparse) 半覆盖：本机/本用户无法建符号链接/目录联接（非本卡缺陷），已退化为 token 级静态核验——ReparsePoint 判据在非注释代码中确认在场 OK' }
  } else {
    $reparseHits = @(Find-GradleManifests -Root $fxReparseRoot -Names @('build.gradle'))
    $leakedHits = @($reparseHits | Where-Object { $_.StartsWith($fxOutside) -or $_.StartsWith($reparseLinkPath) })
    $insideHit = Join-Path $fxReparseRoot 'inside/build.gradle'
    if ($leakedHits.Count -gt 0) {
      Fail "种子缺陷 17cc(reparse)：Find-GradleManifests 经链接追进了目标（命中 $($leakedHits -join ', ')，物理目标=$fxOutside / 别名路径=$reparseLinkPath 两者之一）——未跳过 ReparsePoint，可能扫出仓外或经自引用联接死循环。"
    } elseif ($reparseHits.Count -ne 1 -or $reparseHits[0] -ne $insideHit) {
      Fail "17cc(reparse)：期望恰好 1 个命中（$insideHit），实得 $($reparseHits.Count) 个（$($reparseHits -join ', ')）——精确命中数不符。"
    } else {
      Write-Host "  17cc(reparse) 联接（ReparsePoint）从未被追进 OK（恰好 1 个命中=$insideHit；链接别名路径与物理目标路径均未出现）" -ForegroundColor Green

      Copy-Item -LiteralPath $realCLPath -Destination $mutantReparseCL -Force
      $reparseLines = Get-Content -LiteralPath $mutantReparseCL
      Set-Content -LiteralPath $mutantReparseCL -Value $reparseLines -Encoding utf8   # 规整化（同上）。
      # 注意：本 marker 是生产那一行的**字面副本**，生产行改写时必须同步改这里（否则定位不唯一 → 本闸 fail-closed 报"源码已漂移"）。
      $guardMarker = '$skip = [bool]($e.Attributes -band [System.IO.FileAttributes]::ReparsePoint)'
      $guardWeakened = '$skip = $false'
      # 不用 GetNewClosure() 包这段：脚本块一旦 GetNewClosure()，$LASTEXITCODE 这类自动变量会在建闭包那一刻
      # 就被"冻结"进闭包私有作用域，闭包体内真正跑的 & pwsh 子进程更新的是外层动态作用域的 $LASTEXITCODE，
      # 闭包读到的却还是冻结时的旧值（曾在此踩过一次：leak 判据打印对了 ABSENT，退出码却读成陈旧的 0）。
      # 直接内联、不经闭包，$LASTEXITCODE 才是子进程调用后的新鲜值。
      $reparseGuardIdx = @(0..($reparseLines.Count - 1) | Where-Object { $reparseLines[$_] -match [regex]::Escape($guardMarker) })
      if ($reparseGuardIdx.Count -ne 1) {
        Fail "17cc(reparse-mut) 前置：源码里含守卫子句「$guardMarker」的行数=$($reparseGuardIdx.Count)（期望恰好 1）——变异定位不唯一，源码可能已漂移。"
      } else {
        $mutReparseLines = $reparseLines.Clone()
        $mutReparseLines[$reparseGuardIdx[0]] = $reparseLines[$reparseGuardIdx[0]].Replace($guardMarker, $guardWeakened)
        Set-Content -LiteralPath $mutantReparseCL -Value $mutReparseLines -Encoding utf8
        $reparseProbe = {
          param([string]$LibraryPath, [string]$ProbeRoot, [string]$OutsidePath, [string]$LinkPath)
          Set-StrictMode -Version Latest
          $ErrorActionPreference = 'Stop'
          . $LibraryPath -AsLibrary
          $h = @(Find-GradleManifests -Root $ProbeRoot -Names @('build.gradle'))
          $leaked = @($h | Where-Object { $_.StartsWith($OutsidePath) -or $_.StartsWith($LinkPath) })
          if ($leaked.Count -gt 0) { Write-Output 'MARKER:REPARSE-GUARD-MUT:ABSENT'; exit 1 }
          Write-Output 'MARKER:REPARSE-GUARD-MUT:PRESENT'; exit 0
        }
        $probeStdOut = & pwsh -NoProfile -Command $reparseProbe -Args @($mutantReparseCL, $fxReparseRoot, $fxOutside, $reparseLinkPath)
        $rp = [PSCustomObject]@{ Exit = $LASTEXITCODE; StdOut = ($probeStdOut -join "`n") }
        Set-Content -LiteralPath $mutantReparseCL -Value $reparseLines -Encoding utf8
        if (Test-MarkerResult $rp 'REPARSE-GUARD-MUT' $false '种子缺陷 17cc(reparse-mut)：弱化 ReparsePoint 守卫子句后（vacuous coverage：本闸测不出"忘了写/被删掉守卫"这类回归）') {
          Write-Host '  17cc(reparse-mut) 守卫失效变异 OK（弱化判据后探测子进程 exit 非零 + ABSENT，证本闸真能抓到"忘了挡 ReparsePoint"的回归）' -ForegroundColor Green
        }
      }
    }
  }
} finally {
  if (Test-Path $reparseLinkPath) { Remove-Item -LiteralPath $reparseLinkPath -Force -ErrorAction SilentlyContinue }
  Remove-Item -Recurse -Force $fxReparseRoot -ErrorAction SilentlyContinue
  Remove-Item -Recurse -Force $fxOutside -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath $mutantReparseCL -Force -ErrorAction SilentlyContinue
  if (Test-Path $mutantReparseCL) { Fail "17cc(reparse-mut) 收尾：临时同目录副本 $mutantReparseCL 未能删除——请手动清理，避免 git status 出现 ?? 残留。" }
}

# 17cc(enum-err). 枚举出错 → 两分支各自返回一条发现错误（主流程 fail-closed，不静默吞掉）。用恒抛错的桩
# -Enumerator（不必真造 Windows ACL 不可读目录），直测 Get-GradleDiscoveryResults：两分支各自 try/catch，
# 各自应贡献一条含分支专属前缀的错误文案。
$throwAlways = { param($d) throw "SIMULATED-ENUM-ERROR for $d" }
$enumErrResults = @(Get-GradleDiscoveryResults -Root (Join-Path ([System.IO.Path]::GetTempPath()) "st17cc-enumerr-$PID") -Enumerator $throwAlways)
if ($enumErrResults.Count -ne 2) {
  Fail "种子缺陷 17cc(enum-err)：枚举全程抛错时应各分支各记 1 条发现错误（共 2 条），实得 $($enumErrResults.Count) 条：$($enumErrResults -join ' | ')——枚举错误未被两个分支各自捕获记账（可能被静默吞掉）。"
} elseif (-not (@($enumErrResults) -match 'libs\.versions\.toml 递归枚举失败') -or -not (@($enumErrResults) -match 'build\.gradle\{,\.kts\} 递归枚举失败')) {
  Fail "种子缺陷 17cc(enum-err)：2 条错误里未见两个分支各自的失败前缀文案（实得：$($enumErrResults -join ' | ')）——不是两个分支各自 fail-closed 记账。"
} else {
  Write-Host '  17cc(enum-err) 枚举出错 → 两分支各自返回 1 条发现错误（主流程阻断，不静默吞掉）OK' -ForegroundColor Green
}

# 17cc(scanner-integration). Scanner 的细粒度行为与 mutation 只由专用套件维护；seeded 只聚合其 cache-independent
# 总验收，避免在通用 harness 复制上千行 fixture，也不要求合并后 canary 预热真实 Gradle cache。
# 注意本调用**不**传 -SkipMutations：本套件自己的 wiring 变异与四个子套件的 mutation 都会跑。要省那份
# 成本须显式传参——该开关现在两处都认（此前只是被接受、从不转发，于是「开关有效」与「开关被忽略」在输出上
# 无从分辨）。**可读证据**：本闸的 stdout 里会先出现 `license-scanner-check(integration wiring mutations):
# PASS (N)`，它只在**没有** -SkipMutations 时打印；四个子套件的 `…(<suite> mutations): PASS` 由本套件
# 逐个断言其在/不在，另有一次子进程 `-Suite integration -SkipMutations` 真跑，要求整份 stdout 里
# 一条 `mutations): PASS` 都没有。
#
# **原 17cc(scanner)/17cc(scanner-mut) 那 1434 行 fixture 逐类去向**（删除即失覆盖，故逐类点名它现在
# 由哪个套件、以哪个失败码守；这张表就是「删掉的东西没消失」的证据本身）。
# **一行都不许省**：漏掉的那一行读起来等同于「已覆盖」——2026-08-23 的独立复核逐条比对了删除块里的 59 个
# `Fail` 哨兵，缺的恰好是三个**真的没人守**的类（pom-mixed / pom-conflict / gradle-parse）。它们已在
# license-scanner-check.ps1 里补上真实用例与变异，并各占下表一行；此后新增/删除一类都须同步这张表。
#   wrapper-*（wrapper 选平台 / 发行树七个就绪合取：完成标记 · root 基数 · root 精确名 · launcher 基数 ·
#              launcher 精确名 · bin/gradle · bin/gradle.bat）
#                                   → graph 套件，`GRADLE-WRAPPER-OFFLINE` + 零 wrapper 调用；
#                                     每个合取一枚专属 `[GRAPH-WRAPPER-*]` 断言码与配套变异
#   cache-*（冷/陈旧 cache 零启动、metadata 格式版本、caller 与 ambient cache 不一致）
#                                   → graph 套件，`GRADLE-CACHE-OFFLINE` + 零 wrapper 调用
#   invocation-*（四张已解析 classpath、--offline/--no-daemon、POSIX 经 sh、GRADLE_USER_HOME 绑定、
#                 platform-wrapper 的 Windows/Unix 选择）
#                                   → graph 套件，`graph collector invoked N configurations` / `omitted --offline` 等
#   subprocess-*（非零子进程的退出码与目标 provenance；即旧 gradle-exit）
#                                   → graph 套件，`GRADLE-SUBPROCESS`
#   parser-*（constraint (c) 边 · 重定向 · project 边界 · 选中目标 · 未解析 FAILED/(n) ·
#             非具体版本（含 dot-segment / 动态 selector，即旧 gav-parse）· 空 requested selector ·
#             空重定向尾 · 畸形 project 目标）
#                                   → graph 套件 `$parserCases`，`GRADLE-PARSE` / `GRADLE-UNRESOLVED`
#   gradle-parse（Gradle 退出 0、却零个可解析 GAV **且**零个解析错误 ⇒ 许可闸绿着「什么都没扫到」）
#                                   → graph 套件 `[GRAPH-EMPTY-REPORT]`，四张图各一条 `GRADLE-PARSE`
#   pom-*（多许可 POM · DTD 与畸形 XML（即旧 pom-parse，与 DTD 同落 `GRADLE-POM` 汇）· 自述 GAV/version
#          不符（即旧 gav / gav-version）· 空 license/name · license 名逐字保留 · 单例元素重复 ·
#          畸形 parent GAV）
#                                   → policy 套件，`[POLICY-POM-DTD]` / `[POLICY-POM-GAV]` / `[POLICY-POM-LICENSE-NAME]` /
#                                     `[POLICY-POM-MULTI]` / `[POLICY-POM-SINGLETON-*]` / `[POLICY-POM-PARENT-*]`
#   pom-multicopy-*（同一 GAV 的**多份**缓存 POM 副本：缺失/已声明**混合**，以及副本间许可证**冲突**——
#                    两者都不可由豁免表覆盖，否则一份 licence-less 副本 + 一份声明了 copyleft 的副本会被
#                    人工回退洗白；见 docs/LICENSE-POLICY.md §3.2）
#                                   → policy 套件，`[POLICY-POM-MULTICOPY-MIXED]` / `[POLICY-POM-MULTICOPY-CONFLICT]`
#   license-classification（EPL 禁列 · 无 POM 的 unknown · 缓存 POM 的 unknown-license · 关键词子串伪装 ·
#                           LGPL 黄牌精确名 · 纯 GPL 分不分发；以及「CLI 必须非零并点名坐标与类别」那一层）
#                                   → policy 套件：`[POLICY-CLASSIFICATION]`（分类器本体）+
#                                     `[POLICY-MAIN-*]`（生产调用方的 bad/warn 桶）+
#                                     `[POLICY-PROCESS-*]`（子进程 CLI 的退出码与点名）
#   override-*（精确豁免回退 · 缺 license/name 回退 · 无回退即失败 · declared 映射（exact / canonical /
#               禁列优先 / risk 别名）· 畸形豁免表 fail-closed · GAV 序数比较）
#                                   → policy 套件，`[POLICY-OVERRIDE-*]` / `[POLICY-DECLARED-*]` / `[POLICY-METADATA-NO-FALLBACK]`
#   redaction（URI userinfo（含 wrapper distributionUrl 里的凭据，经 `[DIAG-ENTRY-WRAPPER-EXCEPTION]`
#              同一条生产入口）· Authorization · 密钥式键 · 用户目录 · 控制/格式字符 · ANSI · 换行注入 ·
#              行/字符上界；即旧 parse-redaction 与 pom-/override-/wrapper-url- 各 injection 族）
#                                   → diagnostics 套件，`[DIAG-*]`；「不得因此启动 wrapper」那一半在 graph 套件
#                                     的 `GRADLE-WRAPPER-OFFLINE` 零启动断言里
#   gav-bounds（255 字符段 · 256 拒收 · 审计信封）
#                                   → gav-bounds 套件，`[GAV-*]`
# 判据锚 ASCII 哨兵（L165）：`PASS` 后面的 `[real-scan=…]` 说明本次**真的**跑了哪一支。两种模式的中文
# 文案不同但前缀相同，只判前缀分辨不出——本闸以 -SkipRealScan 运行，就必须读到 `[real-scan=skipped]`。
$licenseIntegrationOutput = (& pwsh -NoProfile -File (Join-Path $RepoRoot 'scripts/license-scanner-check.ps1') -Suite integration -SkipRealScan 2>&1 | Out-String)
$licenseIntegrationExit = $LASTEXITCODE
if ($licenseIntegrationExit -ne 0 -or $licenseIntegrationOutput -notmatch 'license-scanner-check\(integration\): PASS \[real-scan=skipped\]') {
  $licenseIntegrationTail = if ($licenseIntegrationOutput.Length -gt 4000) { $licenseIntegrationOutput.Substring($licenseIntegrationOutput.Length - 4000) } else { $licenseIntegrationOutput }
  Fail "种子缺陷 17cc(scanner-integration)：专用 license scanner 总验收失败，或 PASS 行缺 ASCII 哨兵 [real-scan=skipped]（exit=$licenseIntegrationExit）：$licenseIntegrationTail"
} else {
  Write-Host '  17cc(scanner-integration) graph/policy/diagnostics/gav-bounds 子套件聚合 PASS OK（哨兵 [real-scan=skipped] 已确认本闸**未**执行真实仓 Strict 扫描——那条证据由卡片 DoD 的默认 integration 运行提供）' -ForegroundColor Green
}

# 17dd. verify.ps1 的 Android 闸调用含 --no-daemon（源码断言，纯文本、不执行整套 Gradle 构建——避免 R3
# 沙箱不保证可复跑的重型套件，L60/L62）。断言锚定到完整调用行（.\gradlew.bat + --offline + --no-daemon +
# :core:check 同一行），不是裸子串「--no-daemon」——裸子串会被同文件里提到该 flag 的注释满足，也保护不到
# 显式相对路径。变异写到临时暂存文件（不是真实 verify.ps1），真实 verify.ps1 全程只读、连一次写操作都没经历过。
$vfInvocationLiteral = '.\gradlew.bat --offline --no-daemon -q :core:check'
$vfOrigLines = Get-Content -LiteralPath $realVfPath
$vfIdx = @(0..($vfOrigLines.Count - 1) | Where-Object { $vfOrigLines[$_] -match [regex]::Escape($vfInvocationLiteral) })
if ($vfIdx.Count -ne 1) {
  Fail "17dd 前置：verify.ps1 里含完整调用行「$vfInvocationLiteral」的行数=$($vfIdx.Count)（期望恰好 1）——断言定位不唯一，或该调用形态尚未落地/已漂移。"
} else {
    $vfScratch = Join-Path ([System.IO.Path]::GetTempPath()) "st17dd-verify-o'brien-$PID.ps1"
  try {
    Set-Content -LiteralPath $vfScratch -Value $vfOrigLines -Encoding utf8
    $vfBase = Invoke-MarkerAssertion -Mode ReadFile -SourcePath $vfScratch -Needle $vfInvocationLiteral -MarkerId 'VERIFY-NODAEMON-BASE'
    if (Test-MarkerResult $vfBase 'VERIFY-NODAEMON-BASE' $true '17dd 基线（判据本身与文件内容不一致，需排查）') {
      $vfMut = @(for ($i = 0; $i -lt $vfOrigLines.Count; $i++) { if ($i -ne $vfIdx[0]) { $vfOrigLines[$i] } })
      if ($vfMut.Count -ne ($vfOrigLines.Count - 1)) {
        Fail "17dd 分类器：变异后行数=$($vfMut.Count)，期望恰好比原文件少 1 行（$($vfOrigLines.Count - 1)）——变异不是干净的单句删除。"
      } else {
        Set-Content -LiteralPath $vfScratch -Value $vfMut -Encoding utf8
        $vfMutResult = Invoke-MarkerAssertion -Mode ReadFile -SourcePath $vfScratch -Needle $vfInvocationLiteral -MarkerId 'VERIFY-NODAEMON-MUT'
        if (Test-MarkerResult $vfMutResult 'VERIFY-NODAEMON-MUT' $false '种子缺陷 17dd：删掉完整调用行后（vacuous mutation：断言未真正定位到该调用）') {
          Write-Host '  17dd verify.ps1 --no-daemon：锚定完整调用行，判据子进程基线 exit 0 + PRESENT（GREEN）、单句删除变异后 exit 非零 + ABSENT（RED），真实 verify.ps1 全程只读 OK' -ForegroundColor Green
        }
      }
    }
  } finally {
    Remove-Item -LiteralPath $vfScratch -Force -ErrorAction SilentlyContinue
    if (Test-Path $vfScratch) { Fail "17dd 收尾：临时暂存文件 $vfScratch 未能删除——请手动清理，避免残留。" }
  }
}
# DoD 判据镜像：与卡片 dod_command 的 Select-String 用同一形态直接核真实文件（只读），证两者判的是同一处命中。
if (-not (Select-String -Path $realVfPath -Pattern '--no-daemon' -SimpleMatch -Quiet)) {
  Fail "DoD 判据镜像：Select-String -Path verify.ps1 -Pattern '--no-daemon' -SimpleMatch 未命中——与 dod_command 的判据不一致。"
}

# 17ee（T0-GATE-FIXFORWARD · 事后 R3 block ②）：发布清单的 Gradle 阻断项只有**一条**解锁路径。
#   病因：第 27 项要求 `-Strict` 通过，紧邻的第 28 项却写「人工核验②走完 -Strict 依旧退出 1，是设计使然」——
#   两项相邻互斥，发布者要么在闸红着时勾选（正是 fail-closed 要根除的习惯），要么永远被挡。人裁：删掉②，
#   解锁点唯一 = 扫描器（T0-LICENSE-SCANNER）落地。**「无矛盾」的判据不是"两项都能勾"，而是"两项由同一个动作解锁"。**
#   判据锚 ASCII 哨兵（L165：本地化文案只给人读，编码链一变即假红/假绿）。
#   **判据只有一份**，写在子进程脚本块 $rcProbe 里：真实清单跑它 = 本闸的真断言；每枚变异把改过的内容写进
#   暂存副本、跑**同一个** $rcProbe = 真在测那条断言。绝不在父进程另写一份等价谓词——那样"变异"只证明副本
#   自洽，把真断言删掉照样绿（vacuous mutation）。
#   **为什么钉整行 SHA-256 而不是"不含②"**：`②` 只是当前那条替代路径**碰巧用的字形**；写成「或完成人工逐条
#   核验后即可勾选」照样是第二条解锁路径，却不含该字形——"不含某字形"这个断言**窄于契约**，测不出改写形态
#   （L165：断言面必须恰好等于被测契约）。任意散文替代无法用模式穷举，故改为**钉死这一项的规范文本**：
#   逐字节 SHA-256 匹配。代价是措辞一改就红——这正是意图：这一项是**人裁定下的契约**，改它必须是显式动作
#   （连同本闸的期望哈希一起改），而不是某次顺手润色悄悄带过去。
$realRcPath = Join-Path $RepoRoot 'docs/RELEASE-CHECKLIST.md'
$realRcHashBefore = (Get-FileHash -LiteralPath $realRcPath -Algorithm SHA256).Hash
$rcSentinel = '[GRADLE-LIC-SCANNER-ONLY]'
# 规范项文本的 SHA-256（UTF-8 字节，行尾已由 Get-Content 剥离）。改这一项的措辞 → 同步改这里，二者是一对。
$rcCanonHash = '90A40E0A3CEFC75ABDE5B836177E3FB410BFE28D8B79D515E996841EBC80695F'
$rcEditorWarning = '<!-- 编辑本项的任何字符都须同步更新 scripts/selftest.ps1 的 17ee $rcCanonHash，并重跑 pwsh -NoProfile -File scripts/selftest.ps1 -Shard seeded。 -->'
$rcOrigLines = Get-Content -LiteralPath $realRcPath
# 内联不经 GetNewClosure()：$LASTEXITCODE 需取子进程调用后的新鲜值（同 17cc(reparse-mut) 的注记）。
$rcProbe = {
  param([string]$ChecklistPath, [string]$Sentinel, [string]$CanonHash, [string]$EditorWarning, [string]$MarkerId)
  Set-StrictMode -Version Latest
  $ErrorActionPreference = 'Stop'
  $lines = @(Get-Content -LiteralPath $ChecklistPath)
  $idx = @(0..($lines.Count - 1) | Where-Object { $lines[$_].Contains($Sentinel) })
  if ($idx.Count -ne 1) { Write-Output "MARKER:${MarkerId}:ABSENT-SENTINEL(count=$($idx.Count))"; exit 1 }
  if ($idx[0] -eq 0 -or $lines[$idx[0] - 1] -cne $EditorWarning) { Write-Output "MARKER:${MarkerId}:ABSENT-EDITOR-WARNING"; exit 1 }
  $item = $lines[$idx[0]]
  if (-not $item.Contains('T0-LICENSE-SCANNER')) { Write-Output "MARKER:${MarkerId}:ABSENT-UNLOCK"; exit 1 }
  $actual = [System.BitConverter]::ToString([System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($item))).Replace('-', '')
  if ($actual -ne $CanonHash) { Write-Output "MARKER:${MarkerId}:ABSENT-CANON(actual=$actual)"; exit 1 }
  Write-Output "MARKER:${MarkerId}:PRESENT"; exit 0
}
$rcScratch = Join-Path ([System.IO.Path]::GetTempPath()) "st17ee-checklist-$PID.md"
try {
  # 基线：真实清单直接过判据（本闸的真断言就是这一次调用）。
  $rcBaseOut = & pwsh -NoProfile -Command $rcProbe -Args @($realRcPath, $rcSentinel, $rcCanonHash, $rcEditorWarning, 'RC-GATE-BASE')
  $rcBase = [PSCustomObject]@{ Exit = $LASTEXITCODE; StdOut = ($rcBaseOut -join "`n") }
  if (Test-MarkerResult $rcBase 'RC-GATE-BASE' $true "种子缺陷 17ee：发布清单的 Gradle 阻断项未满足单一解锁契约（哨兵「$rcSentinel」恰好 1 处 + 紧邻编辑警示 + 指名 T0-LICENSE-SCANNER + 规范文本 SHA-256 == $rcCanonHash；措辞被改过就要连同本闸的期望哈希一起显式更新）") {
    $rcIdx = @(0..($rcOrigLines.Count - 1) | Where-Object { $rcOrigLines[$_].Contains($rcSentinel) })
    # 三类变异：删整项 / 抹掉唯一解锁点 / **加一条第二解锁路径**。第三类刻意造两个形态——带序号字形「②」的，
    # 与**完全不带序号、纯散文**的——后者正是"不含②"式弱断言拦不住的那种改写，规范文本哈希能一并抓住。
    $rcAltNumbered = ' 两者选一即满足：' + [char]0x2461 + ' 人工逐条核验并登记进 docs/LICENSE-POLICY.md 第 3 节。'
    $rcAltProse = ' 或者，完成人工逐条核验并登记后亦可勾选本项。'
    $rcMutations = @(
      @{ Id = 'sentinel'; Code = 'ABSENT-SENTINEL'; Label = '删掉整条 Gradle 阻断项（单句删除）'
         Lines = @(for ($i = 0; $i -lt $rcOrigLines.Count; $i++) { if ($i -ne $rcIdx[0]) { $rcOrigLines[$i] } }) }
      @{ Id = 'unlock'; Code = 'ABSENT-UNLOCK'; Label = '抹掉唯一解锁点 T0-LICENSE-SCANNER 的指名'
         Lines = @($rcOrigLines | ForEach-Object { $_.Replace('T0-LICENSE-SCANNER', 'TBD') }) }
      @{ Id = 'altnumbered'; Code = 'ABSENT-CANON'; Label = '把带序号的人工替代写回该项（本次人裁的真实回归）'
         Lines = @(for ($i = 0; $i -lt $rcOrigLines.Count; $i++) { if ($i -eq $rcIdx[0]) { $rcOrigLines[$i] + $rcAltNumbered } else { $rcOrigLines[$i] } }) }
      @{ Id = 'altprose'; Code = 'ABSENT-CANON'; Label = '把**不带序号**的散文替代写进该项（"不含②"式弱断言拦不住的形态）'
         Lines = @(for ($i = 0; $i -lt $rcOrigLines.Count; $i++) { if ($i -eq $rcIdx[0]) { $rcOrigLines[$i] + $rcAltProse } else { $rcOrigLines[$i] } }) }
    )
    foreach ($rm in $rcMutations) {
      Set-Content -LiteralPath $rcScratch -Value $rm.Lines -Encoding utf8
      $rmMarkerId = "RC-GATE-MUT-$($rm.Id.ToUpperInvariant())"
      $rmOut = & pwsh -NoProfile -Command $rcProbe -Args @($rcScratch, $rcSentinel, $rcCanonHash, $rcEditorWarning, $rmMarkerId)
      $rmRes = [PSCustomObject]@{ Exit = $LASTEXITCODE; StdOut = ($rmOut -join "`n") }
      if (-not (Test-MarkerResult $rmRes $rmMarkerId $false "种子缺陷 17ee(mut/$($rm.Id))：$($rm.Label)后（vacuous coverage：本闸测不出这条回归）")) { continue }
      # 分类器：不只要"非零 + ABSENT"，还要红在**它该红的那一条**上——否则一枚变异可能因别的子断言先失败而假杀。
      if (-not (Test-MarkerCode $rmRes.StdOut $rmMarkerId $rm.Code)) {
        Fail "17ee(mut/$($rm.Id)) 分类器：变异确实变红，但失败码不是预期的 $($rm.Code)（实得 stdout=$($rmRes.StdOut)）——红在了别的子断言上，本枚变异并未证明它针对的那条断言在测。"
      } else {
        Write-Host "  17ee(mut/$($rm.Id)) $($rm.Label)：判据子进程 exit 非零 + $($rm.Code)（RED，红在该红的那条上）OK" -ForegroundColor Green
      }
    }
    $rcWarningDeletedLines = @(for ($i = 0; $i -lt $rcOrigLines.Count; $i++) { if ($i -ne ($rcIdx[0] - 1)) { $rcOrigLines[$i] } })
    Set-Content -LiteralPath $rcScratch -Value $rcWarningDeletedLines -Encoding utf8
    $rcWarningMutOut = & pwsh -NoProfile -Command $rcProbe -Args @($rcScratch, $rcSentinel, $rcCanonHash, $rcEditorWarning, 'RC-GATE-MUT-EDITOR-WARNING')
    $rcWarningMut = [PSCustomObject]@{ Exit = $LASTEXITCODE; StdOut = ($rcWarningMutOut -join "`n") }
    if (Test-MarkerResult $rcWarningMut 'RC-GATE-MUT-EDITOR-WARNING' $false '种子缺陷 17ee(mut/editor-warning)：只删紧邻编辑警示后（vacuous coverage：本闸测不出警示消失）') {
      if (-not (Test-MarkerCode $rcWarningMut.StdOut 'RC-GATE-MUT-EDITOR-WARNING' 'ABSENT-EDITOR-WARNING')) {
        Fail "17ee(mut/editor-warning) 分类器：变异确实变红，但失败码不是预期的 ABSENT-EDITOR-WARNING（实得 stdout=$($rcWarningMut.StdOut)）——红在了别的子断言上，本枚变异并未证明它针对的紧邻编辑警示在测。"
      } else {
        Write-Host '  17ee(mut/editor-warning) 只删紧邻编辑警示：判据子进程 exit 非零 + ABSENT-EDITOR-WARNING（RED，红在该红的那条上）OK' -ForegroundColor Green
      }
    }
    Write-Host "  17ee 发布清单 Gradle 阻断项单一解锁（哨兵 $rcSentinel + 紧邻编辑警示 + 指名 T0-LICENSE-SCANNER + 规范文本 SHA-256 钉死）OK；原有 4 枚变异（删项 / 抹解锁点 / 带序号替代 / 不带序号散文替代）与编辑警示删除变异各自按专属失败码分类被杀，真实清单全程只读" -ForegroundColor Green
  }
} finally {
  Remove-Item -LiteralPath $rcScratch -Force -ErrorAction SilentlyContinue
  if (Test-Path $rcScratch) { Fail "17ee 收尾：临时暂存文件 $rcScratch 未能删除——请手动清理，避免残留。" }
}

# 17ff（TD16）：下游项目的权威文档不得把上游脚手架 TD 编号误解析为本项目 tracker 的同号债项。
# 按「唯一 source anchor → 该处 reference → 可解析 target」验证九个实际引用，而不是只在整文件搜到任一正确字面量。
$authorityRefRules = @(
  @{ Id='security-org'; Path='docs/SECURITY.md'; Anchor='需要真门禁者应改用'; Before=0; After=0; Expected='治理边界以本节为准'; Mutant='见 `specs/tech-debt-tracker.md` TD14'; Forbidden=@('specs/tech-debt-tracker.md` TD14'); TargetPath='docs/SECURITY.md'; TargetAnchor='## 4. main 分支保护' }
  @{ Id='idea-org'; Path='docs/IDEA-TO-PLAN.md'; Anchor='T2 的「团队 / 合规」'; Before=0; After=0; Expected='见 `docs/SECURITY.md` §4'; Mutant='见 `docs/SECURITY.md` §4 与 `specs/tech-debt-tracker.md` TD14'; Forbidden=@('specs/tech-debt-tracker.md` TD14'); TargetPath='docs/SECURITY.md'; TargetAnchor='## 4. main 分支保护' }
  @{ Id='config-org'; Path='scripts/_config.ps1'; Anchor='git 层控制仍锁单个人账号'; Before=0; After=0; Expected='见 _guard.ps1 + docs/SECURITY.md §4'; Mutant='见 _guard.ps1 + docs/SECURITY.md §4 + tech-debt TD14'; Forbidden=@('tech-debt TD14'); TargetPath='docs/SECURITY.md'; TargetAnchor='## 4. main 分支保护' }
  @{ Id='loop-r3-primary'; Path='docs/LOOP-ENGINEERING.md'; Anchor='**唯一 carve-out 是 R3**'; Before=0; After=1; Expected='见 `docs/QUALITY-RUBRIC.md` §0）'; Mutant='见 `docs/QUALITY-RUBRIC.md` §0 与 `specs/tech-debt-tracker.md` TD1）'; Forbidden=@('specs/tech-debt-tracker.md` TD1'); TargetPath='docs/QUALITY-RUBRIC.md'; TargetAnchor='## 0. Reviewer stance' }
  @{ Id='loop-r3-recap'; Path='docs/LOOP-ENGINEERING.md'; Anchor='**修法 = 既有确定性闸**'; Before=0; After=0; Expected='carve-out 见本文件上文与 `docs/QUALITY-RUBRIC.md` §0'; Mutant='carve-out 见 `specs/tech-debt-tracker.md` TD1'; Forbidden=@('specs/tech-debt-tracker.md` TD1'); TargetPath='docs/QUALITY-RUBRIC.md'; TargetAnchor='## 0. Reviewer stance' }
