  $crlfChars = ((& git -C $chars60000Root -c core.quotepath=false diff 'master...HEAD' --unified=3 | Out-String) -replace "`r`n", "`n") -replace "`n", "`r`n"
  if ($IsWindows -and $crlfChars.Length -le $canonChars) { $sizeFailures += 'CRLF/LF control is inert: the two forms measure the same, so this assertion cannot detect platform drift' }
  if ($chars60001.Exit -eq 0 -or $chars60001.Text -notmatch '\[R3-DIFF-TOO-LARGE\]' -or $chars60001.Text -notmatch 'diffChars=60001') { $sizeFailures += "60001-char mutant was not blocked with exact metric (exit=$($chars60001.Exit))" }
  if ($binary.Exit -ne 0 -or $binary.Text -notmatch 'binaryFiles=1') { $sizeFailures += "binary numstat was misparsed or hidden (exit=$($binary.Exit))" }
  if ($diffFailure.Exit -eq 0 -or $diffFailure.Text -notmatch '\[R3-DIFF-COMMAND-FAILED\]') { $sizeFailures += "git diff command failure did not fail closed with its diagnostic (exit=$($diffFailure.Exit))" }
  if ($argConflict.Exit -eq 0 -or $argConflict.Text -notmatch '\[R3-DIFF-ARGS-INVALID\]') { $sizeFailures += 'SizeOnly + ResetRounds did not fail with R3-DIFF-ARGS-INVALID' }
  if ($skipConflict.Exit -eq 0 -or $skipConflict.Text -notmatch '\[R3-DIFF-ARGS-INVALID\]') { $sizeFailures += 'SizeOnly + SkipReview was accepted' }
  if ($tooHighLines.Exit -eq 0 -or $tooHighLines.Text -notmatch 'MaxChangedLines') { $sizeFailures += 'MaxChangedLines accepted a value above 1000' }
  if ($tooHighChars.Exit -eq 0 -or $tooHighChars.Text -notmatch 'MaxDiffChars') { $sizeFailures += 'MaxDiffChars accepted a value above 60000' }
  if ($malformedNumstat.Exit -eq 0 -or $malformedNumstat.Text -notmatch '\[R3-DIFF-NUMSTAT-INVALID\]') { $sizeFailures += "malformed numstat did not fail closed with its diagnostic (exit=$($malformedNumstat.Exit))" }
  if ($movedHead.Exit -ne 0 -or $movedHead.Text -notmatch 'changedLines=1' -or -not (Test-Path (Join-Path $moveHeadRoot 'head-moved.marker'))) { $sizeFailures += "moving HEAD changed the captured diff authority (exit=$($movedHead.Exit))" }
  if ($largeFullReview.Exit -eq 0 -or $largeFullReview.Text -notmatch '\[R3-DIFF-TOO-LARGE\]' -or $largeFullReview.Text -match 'Codex 评审|第二模型评审') { $sizeFailures += 'normal review did not stop at the size gate before reviewer invocation' }
  $sizeCases = @($small999, $boundary1000, $large1001, $chars60000, $chars60001, $binary, $diffFailure, $argConflict, $skipConflict, $tooHighLines, $tooHighChars, $malformedNumstat, $overflowNumstat, $prefixNumstat, $blankNumstat, $sumOverflowNumstat, $rowOverflowNumstat, $movedHead, $largeFullReview)
  if (@($sizeCases | Where-Object { $_.ReviewerInvoked }).Count -ne 0) { $sizeFailures += 'the reviewer was invoked on a size-gated run (spy marker present)' }
  if (-not $smallFullReview.ReviewerInvoked) { $sizeFailures += 'reviewer spy is inert: an in-budget full review left no marker, so "no marker" proves nothing' }
  if ($blockedFullReview.Rounds -lt 1) { $sizeFailures += 'rounds counter is inert: a reviewer-blocked run left no .rounds file, so "zero rounds" proves nothing' }
  if (@($sizeCases | Where-Object { $_.Rounds -ne 0 }).Count -ne 0) { $sizeFailures += 'size evaluation created/incremented an R3 round counter' }
  if ($reviewSizeText -notmatch '\[int\]\$MaxChangedLines\s*=\s*1000' -or $reviewSizeText -notmatch '\[int\]\$MaxDiffChars\s*=\s*60000') { $sizeFailures += 'production parameter defaults are not 1000 lines / 60000 chars' }
  function Test-SizeStepBeforePush([string]$Text) {
    $sizeStepPos = $Text.IndexOf("Step '真实 diff 预算闸", [System.StringComparison]::Ordinal)
    $pushStepPos = $Text.IndexOf("Step 'push + 开 PR", [System.StringComparison]::Ordinal)
    return $sizeStepPos -ge 0 -and $pushStepPos -ge 0 -and $sizeStepPos -lt $pushStepPos
  }
  if (-not (Test-SizeStepBeforePush $taskSizeText)) { $sizeFailures += 'task.ps1 does not run SizeOnly before push + PR' }
  if ($taskSizeText -notmatch "Add-CatchRecord 'review-size'") { $sizeFailures += 'task.ps1 does not record review-size gate blocks' }
  if ($taskSizeText -match '尚未 push、开 PR' -or $taskSizeText -notmatch '本次调用' -or $taskSizeText -notmatch '现有远端') { $sizeFailures += 'task.ps1 overclaims that no earlier push or PR can exist after a size block' }
  $a14Devops = Get-Content -LiteralPath (Join-Path $RepoRoot 'docs/DEVOPS-WORKFLOW.md') -Raw
  $a14Rubric = Get-Content -LiteralPath (Join-Path $RepoRoot 'docs/QUALITY-RUBRIC.md') -Raw

  # T0-R3-FLOW-ENUM-SYNC：所有“确定性闸/防泄露”发现命中先显式分类，再对每个枚举文本块做有序断言。
  # 新命中若没有登记会直接变红；登记为 enum 的命中必须绑定一个具名 site，不能靠全文中别处的词满足。
  function Get-EnumSyncSegment([string]$Text, [string]$StartAnchor, [string]$EndAnchor) {
    $lines = @(($Text -replace "`r`n", "`n") -split "`n")
    $starts = @(for ($i = 0; $i -lt $lines.Count; $i++) { if ($lines[$i].Contains($StartAnchor)) { $i } })
    if ($starts.Count -ne 1) { throw "start anchor '$StartAnchor' must occur once (found $($starts.Count))" }
    $start = [int]$starts[0]
    if ($EndAnchor -eq $StartAnchor) { $end = $start }
    else {
      $ends = @(for ($i = $start; $i -lt $lines.Count; $i++) { if ($lines[$i].Contains($EndAnchor)) { $i } })
      if ($ends.Count -ne 1) { throw "end anchor '$EndAnchor' after '$StartAnchor' must occur once (found $($ends.Count))" }
      $end = [int]$ends[0]
    }
    [pscustomobject]@{ Text = ($lines[$start..$end] -join "`n"); Lines = $lines; Start = $start; End = $end }
  }

  function Test-EnumSyncOrdered([string]$Text, [string[]]$Needles) {
    $cursor = 0
    foreach ($needle in $Needles) {
      $at = $Text.IndexOf($needle, $cursor, [System.StringComparison]::Ordinal)
      if ($at -lt 0) { return $false }
      $cursor = $at + $needle.Length
    }
    return $true
  }

  $enumSyncSites = @(
    @{ Id='task-help'; File='task'; Start='ship    : DoD(必绿)'; End='R3 与候选 CI 都作为 mandatory gate'; Needles=@('防泄露闸', '真实 diff 预算', 'push', '开 PR', 'Codex 评审') }
    @{ Id='task-saga-legs'; File='task'; Start='$sagaLegs = @('; End='$sagaLegs = @('; Needles=@('防泄露闸', '真实 diff 预算', 'push+PR', 'R3 评审') }
    @{ Id='task-resume-hint'; File='task'; Start='[TD85-RESUME] 水位线收据未能放行本次 resume（缺失/损坏/不自洽）'; End='[TD85-RESUME] 水位线收据未能放行本次 resume（缺失/损坏/不自洽）'; Needles=@('防泄露闸', '真实 diff 预算', 'review.ps1', 'gh pr merge') }
    @{ Id='task-phase-label'; File='task'; Start="Step '真实 diff 预算闸"; End="Step '真实 diff 预算闸"; Needles=@("Step '真实 diff 预算闸") }
    @{ Id='task-local-gates'; File='task'; Start='# 本地闸门（DoD + verify'; End='# 本地闸门（DoD + verify'; Needles=@('防泄露闸', '真实 diff 预算', 'Codex 评审') }
    @{ Id='task-saga-rule-comment'; File='task'; Start='# 必须先在 worktree **手动补跑全部确定性闸'; End='# 必须先在 worktree **手动补跑全部确定性闸'; Needles=@('防泄露闸', '真实 diff 预算') }
    @{ Id='task-saga-rule-output'; File='task'; Start='【闸门保真总则】已推送恢复合并前'; End='【闸门保真总则】已推送恢复合并前'; Needles=@('防泄露闸', '真实 diff 预算') }
    @{ Id='task-r3-pass'; File='task'; Start='R3 已 pass、合并腿未完成'; End='R3 已 pass、合并腿未完成'; Needles=@('防泄露闸', '真实 diff 预算', 'gh pr merge') }
    @{ Id='task-pr-open'; File='task'; Start='PR #$sagaPrNum 已开'; End='PR #$sagaPrNum 已开'; Needles=@('防泄露闸', '真实 diff 预算', 'review.ps1') }
    @{ Id='task-pr-unknown'; File='task'; Start='commit 已落、PR 状态未知'; End='commit 已落、PR 状态未知'; Needles=@('防泄露闸', '真实 diff 预算', 'review.ps1') }
    @{ Id='docs-english-overview'; File='docs'; Start='> EN: The authoritative operating manual'; End='> EN: The authoritative operating manual'; Budget='real-diff budget'; Needles=@('secret-leak', 'real-diff budget', 'push/PR-base validation', 'codex R3 review') }
    @{ Id='docs-ship'; File='docs'; Start='# 远端基线定向 fetch'; End='# 远端基线定向 fetch'; Needles=@('防泄露闸', '真实 diff 预算', 'push', 'PR', 'R3') }
    @{ Id='docs-resume'; File='docs'; Start='ship 非原子 → 重跑同一条'; End='ship 非原子 → 重跑同一条'; Needles=@('防泄露', '真实 diff 预算', 'push/PR', 'R3') }
    @{ Id='docs-s1'; File='docs'; Start='S1 committed-unpushed'; End='S1 committed-unpushed'; Needles=@('防泄露', '真实 diff 预算') }
    @{ Id='docs-gate-fidelity'; File='docs'; Start='任何已 push 状态的手工恢复都必须保持闸门保真'; End='任何已 push 状态的手工恢复都必须保持闸门保真'; Needles=@('防泄露', '真实 diff 预算') }
    @{ Id='docs-manual-commands'; File='docs'; Start='# 4. 商用许可闸'; End='-SizeOnly'; Needles=@('check-secrets.ps1', '真实 diff 预算', '-SizeOnly') }
    @{ Id='docs-last-resort'; File='docs'; Start='receipt 丢失且已 push 时的最后手段'; End='receipt 丢失且已 push 时的最后手段'; Needles=@('防泄露', '真实 diff 预算') }
  )

  function Get-EnumSyncFailures([string]$TaskText, [string]$DocsText) {
    $failures = @()
    foreach ($site in $enumSyncSites) {
      try {
        $source = if ($site.File -eq 'task') { $TaskText } else { $DocsText }
        $segment = Get-EnumSyncSegment $source $site.Start $site.End
        if (-not (Test-EnumSyncOrdered $segment.Text $site.Needles)) { $failures += $site.Id }
      } catch { $failures += $site.Id }
    }
    return @($failures)
  }

  function Remove-EnumSyncBudgetAtSite([string]$Text, [hashtable]$Site) {
    $segment = Get-EnumSyncSegment $Text $Site.Start $Site.End
    $budgetPhrase = if ($Site.ContainsKey('Budget')) { [string]$Site.Budget } else { '真实 diff 预算' }
    $budgetHits = 0
    for ($i = $segment.Start; $i -le $segment.End; $i++) {
      $budgetHits += ([regex]::Matches($segment.Lines[$i], [regex]::Escape($budgetPhrase))).Count
    }
    if ($budgetHits -ne 1) { throw "site '$($Site.Id)' must contain exactly one budget phrase to mutate (found $budgetHits)" }
    for ($i = $segment.Start; $i -le $segment.End; $i++) {
      if ($segment.Lines[$i].Contains($budgetPhrase)) {
        $segment.Lines[$i] = $segment.Lines[$i].Replace($budgetPhrase, '')
        break
      }
    }
    return ($segment.Lines -join "`n")
  }

  # A1 的 grep 权威面：每条当前命中均逐条登记；enum 绑定上面的 site，note 明确判为非枚举说明。
  $enumSyncDiscovery = @(
    @{ File='docs'; Anchor='> EN: The authoritative operating manual'; Class='enum'; Site='docs-english-overview' }
    @{ File='docs'; Anchor='# 远端基线定向 fetch'; Class='enum'; Site='docs-ship' }
    @{ File='docs'; Anchor='ship 非原子 → 重跑同一条'; Class='enum'; Site='docs-resume' }
    @{ File='docs'; Anchor='S1 committed-unpushed'; Class='enum'; Site='docs-s1' }
    @{ File='docs'; Anchor='S2 pushed-no-PR'; Class='note' }
    @{ File='docs'; Anchor='S9 evidence lost'; Class='note' }
    @{ File='docs'; Anchor='任何已 push 状态的手工恢复都必须保持闸门保真'; Class='enum'; Site='docs-gate-fidelity' }
    @{ File='docs'; Anchor='# 5. 防泄露闸'; Class='enum'; Site='docs-manual-commands' }
    @{ File='docs'; Anchor='receipt 丢失且已 push 时的最后手段'; Class='enum'; Site='docs-last-resort' }
    @{ File='docs'; Anchor='if ($baseOid2 -ne $baseOid)'; Class='note' }
    @{ File='docs'; Anchor='**不**做【R3 评审】subagent'; Class='note' }
    @{ File='docs'; Anchor='防泄露闸 `check-secrets.ps1` 已接入'; Class='note' }
    @{ File='docs'; Anchor='`/security-review-local` 是模型在环'; Class='note' }
    @{ File='task'; Anchor='ship    : DoD(必绿)'; Class='enum'; Site='task-help' }
    @{ File='task'; Anchor='R3 与候选 CI 都作为 mandatory gate'; Class='note' }
    @{ File='task'; Anchor='$sagaLegs = @('; Class='enum'; Site='task-saga-legs' }
    @{ File='task'; Anchor='# 收据在位 ='; Class='note' }
    @{ File='task'; Anchor='# PR head =='; Class='note' }
    @{ File='task'; Anchor='[TD85-RESUME] 水位线收据未能放行本次 resume（缺失/损坏/不自洽）'; Class='enum'; Site='task-resume-hint' }
    @{ File='task'; Anchor='T35-RECEIPT：已铸水位线收据'; Class='note' }
    @{ File='task'; Anchor="Step '防泄露闸"; Class='note' }
    @{ File='task'; Anchor='$sagaDone += ''防泄露闸'''; Class='note' }
    @{ File='task'; Anchor='# 本地闸门（DoD + verify'; Class='enum'; Site='task-local-gates' }
    @{ File='task'; Anchor='# 铸造/RED 闸的收据 resume'; Class='note' }
    @{ File='task'; Anchor='$sagaSafeWhy ='; Class='note' }
    @{ File='task'; Anchor='-Local（提交未推送）'; Class='note' }
    @{ File='task'; Anchor='[CI-GATE-BASE-MOVED]'; Class='note' }
    @{ File='task'; Anchor='# 必须先在 worktree **手动补跑全部确定性闸'; Class='enum'; Site='task-saga-rule-comment' }
    @{ File='task'; Anchor='【闸门保真总则】已推送恢复合并前'; Class='enum'; Site='task-saga-rule-output' }
    @{ File='task'; Anchor='R3 已 pass、合并腿未完成'; Class='enum'; Site='task-r3-pass' }
    @{ File='task'; Anchor='PR #$sagaPrNum 已开'; Class='enum'; Site='task-pr-open' }
    @{ File='task'; Anchor='commit 已落、PR 状态未知'; Class='enum'; Site='task-pr-unknown' }
  )

  foreach ($sourceSpec in @(@{ Id='task'; Text=$taskSizeText }, @{ Id='docs'; Text=$a14Devops })) {
    $sourceLines = @(($sourceSpec.Text -replace "`r`n", "`n") -split "`n")
    $hits = @(for ($i = 0; $i -lt $sourceLines.Count; $i++) {
      if ($sourceLines[$i].Contains('确定性闸') -or $sourceLines[$i].Contains('防泄露') -or $sourceLines[$i].Contains('secret-leak')) {
        [pscustomobject]@{ Line=$i + 1; Text=$sourceLines[$i] }
      }
    })
    foreach ($hit in $hits) {
      $matches = @($enumSyncDiscovery | Where-Object { $_.File -eq $sourceSpec.Id -and $hit.Text.Contains($_.Anchor) })
      if ($matches.Count -ne 1) { $sizeFailures += "enum discovery $($sourceSpec.Id):$($hit.Line) must have one classification (found $($matches.Count))" }
    }
    foreach ($entry in @($enumSyncDiscovery | Where-Object File -eq $sourceSpec.Id)) {
      $matchingHits = @($hits | Where-Object { $_.Text.Contains($entry.Anchor) })
      if ($matchingHits.Count -ne 1) { $sizeFailures += "enum discovery inventory '$($entry.Anchor)' must match one $($sourceSpec.Id) hit (found $($matchingHits.Count))" }
    }
  }
  $discoveredSites = @($enumSyncDiscovery | Where-Object Class -eq 'enum' | ForEach-Object Site | Sort-Object -Unique)
  $expectedDiscoveredSites = @($enumSyncSites | Where-Object Id -ne 'task-phase-label' | ForEach-Object Id | Sort-Object -Unique)
  if (($discoveredSites -join '|') -ne ($expectedDiscoveredSites -join '|')) { $sizeFailures += 'enum discovery registrations and anchored sites are not one-to-one' }

  $enumSyncFailures = @(Get-EnumSyncFailures $taskSizeText $a14Devops)
  foreach ($enumFailure in $enumSyncFailures) { $sizeFailures += "enum site '$enumFailure' is missing or out of order" }
  if ($enumSyncFailures.Count -eq 0) {
    foreach ($site in $enumSyncSites) {
      $mutTask = $taskSizeText; $mutDocs = $a14Devops
      if ($site.File -eq 'task') { $mutTask = Remove-EnumSyncBudgetAtSite $mutTask $site }
      else { $mutDocs = Remove-EnumSyncBudgetAtSite $mutDocs $site }
      $mutFailures = @(Get-EnumSyncFailures $mutTask $mutDocs)
      if (($mutFailures -join '|') -ne $site.Id) { $sizeFailures += "enum mutant '$($site.Id)' must kill only its own assertion (got: $($mutFailures -join ', '))" }
    }
  }

  # A4/A6：三行注释必须以段落而非锚点单行判定；预算挪到 push 后必须被有序子序列拒绝。
  $multiLineEnum = "ship : 防泄露闸 → 真实 diff 预算`n       → push → 开 PR`n       → Codex 评审"
  $multiLineNeedles = @('防泄露闸', '真实 diff 预算', 'push', '开 PR', 'Codex 评审')
  $multiLineBlock = Get-EnumSyncSegment $multiLineEnum 'ship :' 'Codex 评审'
  if ($multiLineBlock.Start -ne 0 -or $multiLineBlock.End -ne 2 -or -not (Test-EnumSyncOrdered $multiLineBlock.Text $multiLineNeedles)) { $sizeFailures += 'multiline enum block was not extracted and accepted as one segment' }
  if (Test-EnumSyncOrdered (($multiLineEnum -split "`n")[0]) $multiLineNeedles) { $sizeFailures += 'single-line extraction control is inert' }
  $misorderedEnum = "ship : 防泄露闸 → push → 真实 diff 预算 → 开 PR → Codex 评审"
  if (Test-EnumSyncOrdered $misorderedEnum $multiLineNeedles) { $sizeFailures += 'out-of-order budget-after-push fixture was accepted' }

  # A7：说明性 -SizeOnly decoy 位于真实调用点之前，顺序判定仍只锚 Step 标签。
  $decoyTaskText = $taskSizeText.Replace("Step '真实 diff 预算闸", "# explanatory -SizeOnly decoy`n      Step '真实 diff 预算闸")
  $decoyPos = $decoyTaskText.IndexOf('# explanatory -SizeOnly decoy', [System.StringComparison]::Ordinal)
  $decoyStepPos = $decoyTaskText.IndexOf("Step '真实 diff 预算闸", [System.StringComparison]::Ordinal)
  if ($decoyPos -lt 0 -or $decoyPos -ge $decoyStepPos) { $sizeFailures += 'SizeOnly decoy fixture is inert' }
  if (-not (Test-SizeStepBeforePush $decoyTaskText)) { $sizeFailures += 'Step-anchored size-before-push predicate failed under a SizeOnly decoy' }
  $missingStepWithDecoy = $taskSizeText.Replace("Step '真实 diff 预算闸", '# explanatory -SizeOnly decoy')
  $naiveSizePos = $missingStepWithDecoy.IndexOf('-SizeOnly', [System.StringComparison]::Ordinal)
  $naivePushPos = $missingStepWithDecoy.IndexOf("Step 'push + 开 PR", [System.StringComparison]::Ordinal)
  if ($naiveSizePos -lt 0 -or $naivePushPos -lt 0 -or $naiveSizePos -ge $naivePushPos) { $sizeFailures += 'first-SizeOnly decoy control did not falsely pass' }
  if (Test-SizeStepBeforePush $missingStepWithDecoy) { $sizeFailures += 'Step-anchored predicate accepted a decoy after the real size phase label was removed' }

  # A8：last-resort 命令须保留逐字反斜杠路径；文件和显式 lone-CR mutation 都由 byte oracle 判。
  try {
    $lastResortBlock = Get-EnumSyncSegment $a14Devops 'receipt 丢失且已 push 时的最后手段' 'gh pr merge <PR号> --squash --match-head-commit $head'
    $expectedReviewCommand = '> pwsh -NoProfile -File scripts\review.ps1 -WorktreePath <worktree> -Base <base> -PostStatus -PrNumber <PR号>'
    $reviewCommandLines = @($lastResortBlock.Text -split "`n" | Where-Object { $_.Contains('pwsh -NoProfile -File') -and $_.Contains('-PostStatus') })
    if ($reviewCommandLines.Count -ne 1 -or $reviewCommandLines[0].Trim() -cne $expectedReviewCommand) { $sizeFailures += 'last-resort review command line no longer exactly preserves literal scripts\review.ps1' }
  } catch { $sizeFailures += "last-resort review command block is not extractable: $($_.Exception.Message)" }
  function Get-LoneCrCount([byte[]]$Bytes) {
    $count = 0
    for ($i = 0; $i -lt $Bytes.Length; $i++) {
      if ($Bytes[$i] -eq 13 -and ($i + 1 -ge $Bytes.Length -or $Bytes[$i + 1] -ne 10)) { $count++ }
    }
    return $count
  }
  function Test-NoLoneCr([byte[]]$Bytes) { return (Get-LoneCrCount $Bytes) -eq 0 }
  $devopsBytes = [System.IO.File]::ReadAllBytes((Join-Path $RepoRoot 'docs/DEVOPS-WORKFLOW.md'))
  if (-not (Test-NoLoneCr $devopsBytes)) { $sizeFailures += 'DEVOPS-WORKFLOW contains a lone CR byte' }
  $crInsertAt = [Math]::Min(32, $devopsBytes.Length)
  $loneCrMutant = New-Object byte[] ($devopsBytes.Length + 1)
  [Array]::Copy($devopsBytes, 0, $loneCrMutant, 0, $crInsertAt)
  $loneCrMutant[$crInsertAt] = 13
  [Array]::Copy($devopsBytes, $crInsertAt, $loneCrMutant, $crInsertAt + 1, $devopsBytes.Length - $crInsertAt)
  if ((Get-LoneCrCount $loneCrMutant) -ne 1 -or (Test-NoLoneCr $loneCrMutant)) { $sizeFailures += 'lone-CR mutation was not rejected by the production-file predicate' }

  $a14DevopsPara = @($a14Devops -split "`r?`n" | Where-Object { $_.Contains('allow_paths` 的条目数只在建卡期') })
  if ($a14DevopsPara.Count -ne 1) { $sizeFailures += "A14: DEVOPS-WORKFLOW's 'allow_paths is not a size proof' paragraph is missing or duplicated (found $($a14DevopsPara.Count))" }
  else {
    foreach ($a14Needle in @('**不是**规模证明', '真实 diff 预算', '只允许收紧')) {
      if (-not $a14DevopsPara[0].Contains($a14Needle)) { $sizeFailures += "A14: DEVOPS-WORKFLOW paragraph no longer states '$a14Needle'" }
    }
  }
  $a14RubricLines = @($a14Rubric -split "`r?`n" | Where-Object { $_.Contains('additions + deletions <= 1000') })
  if ($a14RubricLines.Count -lt 2) { $sizeFailures += "A14: QUALITY-RUBRIC 4.1 must state the 1000/60000 pair in both languages (found $($a14RubricLines.Count))" }
  if (-not ($a14Rubric.Contains('may only be tightened, never raised') -or $a14Rubric.Contains('只能收紧上限'))) { $sizeFailures += 'A14: QUALITY-RUBRIC 4.1 no longer states that the limits may only be tightened' }
  if ($sizeFailures.Count) { Fail "种子缺陷 17ai：真实 diff 预算闸未闭合：$($sizeFailures -join '；')" }
  else { Write-Host '  17ai diff 预算 OK（999/1000 行过；1001 拦；60000 过、60001 拦；两组参数冲突已拒）' -ForegroundColor Green }
} finally {
  Remove-Item -LiteralPath $sizeRoot -Recurse -Force -ErrorAction SilentlyContinue
}

# 17hh（TD22）：归档 merged 卡后，三个具名非归档来源必须改指向 archive 路径；不把此债扩成全仓历史链接扫描。
$archivedCardRefRules = @(
  @{ Id='claude-toolchain'; Path='CLAUDE.md'; Anchor='Android 工程（T0-TOOLCHAIN 落地后）'; Before=0; After=0; LiveRef='specs/tasks/T0-TOOLCHAIN.md'; ArchiveRef='specs/archive/tasks/T0-TOOLCHAIN.md' }
  @{ Id='adr-backup-format'; Path='docs/adr/0002-local-data-saf-encrypted-backup.md'; Anchor='分块 AES-256-GCM（STREAM 构造）'; Before=0; After=0; LiveRef='specs/tasks/T5-BACKUP-FORMAT.md'; ArchiveRef='specs/archive/tasks/T5-BACKUP-FORMAT.md' }
  @{ Id='capture-baseline'; Path='android/core/src/test/kotlin/nz/myinspection/core/capture/InspectionRepositoryTest.kt'; Anchor='澄清后的契约'; Before=0; After=0; LiveRef='specs/tasks/T2-CAPTURE-CORE.md'; ArchiveRef='specs/archive/tasks/T2-CAPTURE-CORE.md' }
)
function Get-ArchivedCardSourceSegment([string]$Root, [object]$Rule) {
  $path = Join-Path $Root $Rule.Path
  if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
    return [pscustomobject]@{ Ok=$false; Code="MISSING-SOURCE:$($Rule.Id)"; Path=$Rule.Path; Reference=$Rule.Anchor; Target=$Rule.ArchiveRef; Lines=$null; Start=-1; End=-1; Segment='' }
  }
  $lines = @([System.IO.File]::ReadAllText($path) -split '\r?\n')
  $hits = @(for ($i=0; $i -lt $lines.Count; $i++) { if ($lines[$i].Contains($Rule.Anchor)) { $i } })
  if ($hits.Count -ne 1) {
    return [pscustomobject]@{ Ok=$false; Code="AMBIGUOUS-SOURCE:$($Rule.Id)"; Path=$Rule.Path; Reference=$Rule.Anchor; Target=$Rule.ArchiveRef; Lines=$lines; Start=-1; End=-1; Segment='' }
  }
  $start = [Math]::Max(0, $hits[0] - $Rule.Before)
  $end = [Math]::Min($lines.Count - 1, $hits[0] + $Rule.After)
  return [pscustomobject]@{ Ok=$true; Code='PRESENT'; Path=$Rule.Path; Reference=$Rule.ArchiveRef; Target=$Rule.ArchiveRef; Lines=$lines; Start=$start; End=$end; Segment=($lines[$start..$end] -join "`n") }
}
function Test-ArchivedCardReferenceSet([string]$Root, [object[]]$Rules) {
  foreach ($rule in $Rules) {
    $source = Get-ArchivedCardSourceSegment $Root $rule
    if (-not $source.Ok) { return $source }
    if ($source.Segment.Contains($rule.LiveRef)) {
      return [pscustomobject]@{ Ok=$false; Code="FORBIDDEN-LIVE-PATH:$($rule.Id)"; Path=$rule.Path; Reference=$rule.LiveRef; Target=$rule.ArchiveRef }
    }
    if (([regex]::Matches($source.Segment, [regex]::Escape($rule.ArchiveRef))).Count -ne 1) {
      return [pscustomobject]@{ Ok=$false; Code="MISSING-ARCHIVE-PATH:$($rule.Id)"; Path=$rule.Path; Reference=$rule.ArchiveRef; Target=$rule.ArchiveRef }
    }
    $targetPath = Join-Path $Root $rule.ArchiveRef
    $targetItem = Get-Item -LiteralPath $targetPath -Force -ErrorAction SilentlyContinue
    $isRegularFile = $targetItem -and -not $targetItem.PSIsContainer -and
      (($targetItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -eq 0)
    if (-not $isRegularFile) {
      return [pscustomobject]@{ Ok=$false; Code="UNRESOLVED-TARGET:$($rule.Id)"; Path=$rule.Path; Reference=$rule.ArchiveRef; Target=$rule.ArchiveRef }
    }
  }
  return [pscustomobject]@{ Ok=$true; Code='PRESENT'; Path=''; Reference=''; Target='' }
}

$archivedCardBase = Test-ArchivedCardReferenceSet $RepoRoot $archivedCardRefRules
if (-not $archivedCardBase.Ok) {
  Fail "[TD22-ARCHIVED-CARD-REF] code=$($archivedCardBase.Code) path=$($archivedCardBase.Path) reference=$($archivedCardBase.Reference) target=$($archivedCardBase.Target)"
} else {
  $archiveLifecycleRoot = Join-Path ([System.IO.Path]::GetTempPath()) "st17hh-archive-lifecycle-$PID"
  $archiveRefScratch = Join-Path ([System.IO.Path]::GetTempPath()) "st17hh-archive-refs-$PID"
  try {
    New-Item -ItemType Directory -Force (Join-Path $archiveLifecycleRoot 'specs/tasks'), (Join-Path $archiveLifecycleRoot 'docs') | Out-Null
    $fixtureTracker = @(
      '# TD22 fixture', '',
      '| id | 发现日 | 位置 | 偏离了什么（债） | 严重度 | 状态 | 偿还指针 |',
      '|---|---|---|---|---|---|---|',
      '| _示例_ | 2026-06-15 | `x/y` | 示例 | minor | open | — |'
    ) -join "`n"
    Set-Content -LiteralPath (Join-Path $archiveLifecycleRoot 'specs/tech-debt-tracker.md') -Value $fixtureTracker -Encoding utf8
    Set-Content -LiteralPath (Join-Path $archiveLifecycleRoot 'specs/tasks/TA1.md') -Value "---`nid: TA1`ntitle: lifecycle`nstatus: merged`n---" -Encoding utf8
    Set-Content -LiteralPath (Join-Path $archiveLifecycleRoot 'docs/inbound.md') -Value 'TA1 evidence: specs/tasks/TA1.md' -Encoding utf8
    $fixtureRule = @{ Id='fixture-ta1'; Path='docs/inbound.md'; Anchor='TA1 evidence:'; Before=0; After=0; LiveRef='specs/tasks/TA1.md'; ArchiveRef='specs/archive/tasks/TA1.md' }
    & pwsh -NoProfile -File (Join-Path $PSScriptRoot 'archive.ps1') -RepoRoot $archiveLifecycleRoot -Quiet *> $null
    $fixtureArchiveExit = $LASTEXITCODE
    $fixtureOld = Test-ArchivedCardReferenceSet $archiveLifecycleRoot @($fixtureRule)
    if ($fixtureArchiveExit -ne 0 -or -not (Test-Path -LiteralPath (Join-Path $archiveLifecycleRoot $fixtureRule.ArchiveRef) -PathType Leaf) -or (Test-Path -LiteralPath (Join-Path $archiveLifecycleRoot 'specs/tasks/TA1.md'))) {
      Fail "17hh(lifecycle)：archive.ps1 未把 merged TA1 从 live 目录移到 archive（exit=$fixtureArchiveExit）。"
    } elseif ($fixtureOld.Ok -or $fixtureOld.Code -ne 'FORBIDDEN-LIVE-PATH:fixture-ta1' -or $fixtureOld.Path -ne $fixtureRule.Path -or $fixtureOld.Reference -ne $fixtureRule.LiveRef -or $fixtureOld.Target -ne $fixtureRule.ArchiveRef) {
      Fail "17hh(lifecycle/old)：期望 code=FORBIDDEN-LIVE-PATH:fixture-ta1 path=$($fixtureRule.Path) reference=$($fixtureRule.LiveRef) target=$($fixtureRule.ArchiveRef)，实得 code=$($fixtureOld.Code) path=$($fixtureOld.Path) reference=$($fixtureOld.Reference) target=$($fixtureOld.Target)。"
    } else {
      $fixtureInbound = Join-Path $archiveLifecycleRoot $fixtureRule.Path
      [System.IO.File]::WriteAllText($fixtureInbound, ([System.IO.File]::ReadAllText($fixtureInbound).Replace($fixtureRule.LiveRef, $fixtureRule.ArchiveRef)), [Text.UTF8Encoding]::new($false))
      $fixtureFixed = Test-ArchivedCardReferenceSet $archiveLifecycleRoot @($fixtureRule)
      if (-not $fixtureFixed.Ok) {
        Fail "17hh(lifecycle/fixed)：改指 archive 后仍失败：code=$($fixtureFixed.Code) path=$($fixtureFixed.Path) reference=$($fixtureFixed.Reference) target=$($fixtureFixed.Target)。"
      } else { Write-Host '  17hh(lifecycle) merged TA1 移入 archive 后旧入站路径失败、archive 路径通过 OK' -ForegroundColor Green }
    }

    foreach ($rule in $archivedCardRefRules) {
      foreach ($rel in @($rule.Path, $rule.ArchiveRef)) {
        $dst = Join-Path $archiveRefScratch $rel
        New-Item -ItemType Directory -Force (Split-Path $dst -Parent) | Out-Null
        Copy-Item -LiteralPath (Join-Path $RepoRoot $rel) -Destination $dst -Force
      }
    }
    $scratchBase = Test-ArchivedCardReferenceSet $archiveRefScratch $archivedCardRefRules
    if (-not $scratchBase.Ok) {
      Fail "17hh(mut) 前置：scratch 基线失败 code=$($scratchBase.Code) path=$($scratchBase.Path) reference=$($scratchBase.Reference) target=$($scratchBase.Target)。"
    } else {
      $typeRule = $archivedCardRefRules[0]
      $typeTarget = Join-Path $archiveRefScratch $typeRule.ArchiveRef
      $typeTargetBytes = [System.IO.File]::ReadAllBytes($typeTarget)
      Remove-Item -LiteralPath $typeTarget -Force
      New-Item -ItemType Directory -Force $typeTarget | Out-Null
      $typeMutant = Test-ArchivedCardReferenceSet $archiveRefScratch $archivedCardRefRules
      Remove-Item -LiteralPath $typeTarget -Recurse -Force
      [System.IO.File]::WriteAllBytes($typeTarget, $typeTargetBytes)
      $expectedTypeCode = "UNRESOLVED-TARGET:$($typeRule.Id)"
      if ($typeMutant.Ok -or $typeMutant.Code -ne $expectedTypeCode -or $typeMutant.Path -ne $typeRule.Path -or $typeMutant.Reference -ne $typeRule.ArchiveRef -or $typeMutant.Target -ne $typeRule.ArchiveRef) {
        Fail "17hh(mut/target-type) 分类器：archive 目标变目录后期望 code=$expectedTypeCode path=$($typeRule.Path) reference=$($typeRule.ArchiveRef) target=$($typeRule.ArchiveRef)，实得 code=$($typeMutant.Code) path=$($typeMutant.Path) reference=$($typeMutant.Reference) target=$($typeMutant.Target)。"
      } else { Write-Host '  17hh(mut/target-type) archive 目标非普通文件时按 UNRESOLVED-TARGET 精确失败 OK' -ForegroundColor Green }

      foreach ($rule in $archivedCardRefRules) {
        $source = Get-ArchivedCardSourceSegment $archiveRefScratch $rule
        $target = Join-Path $archiveRefScratch $rule.Path
        $baselineBytes = [System.IO.File]::ReadAllBytes($target)
        $baselineHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($baselineBytes))
        $hits = ([regex]::Matches($source.Segment, [regex]::Escape($rule.ArchiveRef))).Count
        if ($hits -ne 1) {
          Fail "17hh(mut/$($rule.Id)) 前置：archive 路径在唯一锚定片段中出现 $hits 次，期望恰好 1 次。"
          continue
        }
        for ($lineIndex=$source.Start; $lineIndex -le $source.End; $lineIndex++) {
          $source.Lines[$lineIndex] = $source.Lines[$lineIndex].Replace($rule.ArchiveRef, $rule.LiveRef)
        }
        [System.IO.File]::WriteAllText($target, ($source.Lines -join "`n"), [Text.UTF8Encoding]::new($false))
        $mutant = Test-ArchivedCardReferenceSet $archiveRefScratch $archivedCardRefRules
        [System.IO.File]::WriteAllBytes($target, $baselineBytes)
        $restoredHash = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash
        $expectedCode = "FORBIDDEN-LIVE-PATH:$($rule.Id)"
        if ($restoredHash -ne $baselineHash) {
          Fail "17hh(mut/$($rule.Id)) 收尾：scratch 还原后 SHA256 不一致（前=$baselineHash，后=$restoredHash）。"
        } elseif ($mutant.Ok -or $mutant.Code -ne $expectedCode -or $mutant.Path -ne $rule.Path -or $mutant.Reference -ne $rule.LiveRef -or $mutant.Target -ne $rule.ArchiveRef) {
          Fail "17hh(mut/$($rule.Id)) 分类器：期望 code=$expectedCode path=$($rule.Path) reference=$($rule.LiveRef) target=$($rule.ArchiveRef)，实得 code=$($mutant.Code) path=$($mutant.Path) reference=$($mutant.Reference) target=$($mutant.Target)。"
        } else { Write-Host "  17hh(mut/$($rule.Id)) 旧 live 路径回归被精确分类，scratch SHA256 还原一致 OK" -ForegroundColor Green }
      }
      Write-Host '  17hh TD22 三个具名入站路径均指向非 reparse 的 archive 普通文件；三枚变异按 code/path/reference/target 分类击杀 OK' -ForegroundColor Green
    }
  } finally {
    Remove-Item -LiteralPath $archiveLifecycleRoot, $archiveRefScratch -Recurse -Force -ErrorAction SilentlyContinue
  }
}

# ── 收尾：真实生产文件全程未被写入（纵深防御，L196）——check-licenses.ps1 只曾在临时同目录副本上变异，
#    verify.ps1 与 docs/RELEASE-CHECKLIST.md 全程只读，三者 SHA256 理应与本闸开始前逐字不变。──
$realCLHashAfter = (Get-FileHash -LiteralPath $realCLPath -Algorithm SHA256).Hash
$realVfHashAfter = (Get-FileHash -LiteralPath $realVfPath -Algorithm SHA256).Hash
$realRcHashAfter = (Get-FileHash -LiteralPath $realRcPath -Algorithm SHA256).Hash
if ($realCLHashAfter -ne $realCLHashBefore) { Fail "17cc/17dd 收尾：真实 scripts/check-licenses.ps1 的 SHA256 在本闸前后不一致（前=$realCLHashBefore，后=$realCLHashAfter）——变异测试意外写到了生产文件本体，而非只碰临时副本（L196）。" }
elseif ($realVfHashAfter -ne $realVfHashBefore) { Fail "17cc/17dd 收尾：真实 scripts/verify.ps1 的 SHA256 在本闸前后不一致（前=$realVfHashBefore，后=$realVfHashAfter）——理应全程只读却被写入（L196）。" }
elseif ($realRcHashAfter -ne $realRcHashBefore) { Fail "17ee 收尾：真实 docs/RELEASE-CHECKLIST.md 的 SHA256 在本闸前后不一致（前=$realRcHashBefore，后=$realRcHashAfter）——理应全程只读却被写入（L196）。" }
else { Write-Host '  17cc/17dd/17ee 收尾：真实 check-licenses.ps1 / verify.ps1 / docs/RELEASE-CHECKLIST.md 三份生产文件 SHA256 全程未变 OK（L196 纵深防御）' -ForegroundColor Green }

[void]$executedGateGroups.Add('seeded:17-scanner')
}

}

$expectedGateGroups = @(switch ($Shard) {
  'core' { 'core:1-14'; 'core:16' }
  'workflow' { 'workflow:15' }
  'seeded' { 'seeded:17-git-pre'; 'seeded:17-git-main'; 'seeded:17-remote'; 'seeded:17-scanner' }
  'seeded-git' { 'seeded:17-git-pre'; 'seeded:17-git-main' }
  'seeded-remote' { 'seeded:17-remote' }
  'seeded-scanner' { 'seeded:17-scanner' }
})
if ($Shard -in @('seeded', 'seeded-git', 'seeded-remote', 'seeded-scanner')) {
  foreach ($disabledRegion in $expectedGateGroups) {
    $disabledReceipts = @($expectedGateGroups | Where-Object { $_ -cne $disabledRegion })
    if (Test-SelftestGateGroupCompletion -Actual $disabledReceipts -Expected $expectedGateGroups) {
      Fail "收据缺失变异存活：shard=$Shard region=$disabledRegion"
    }
  }
}
if (-not (Test-SelftestGateGroupCompletion -Actual $executedGateGroups -Expected $expectedGateGroups)) {
  Fail "分片收据错：shard=$Shard actual=$($executedGateGroups -join ',') expected=$($expectedGateGroups -join ',')"
} else { Write-Host "  分片执行组：$($expectedGateGroups -join ',') OK" -ForegroundColor Green }

Step "结论 [$Shard]"
$outcomeOverlap = @(Get-SelftestOutcomeOverlap -FailedGateIds $failedSelftestGateIds -SkippedRecords $skippedSelftestChecks)
if ($outcomeOverlap.Count -gt 0) { Fail "FAIL/SKIP outcome overlap: $($outcomeOverlap -join ',')" }
Write-Host (Format-SelftestSkipSummary -Shard $Shard -Records $skippedSelftestChecks) -ForegroundColor DarkGray
if ($fail) {
  Write-Host (Format-SelftestFailureSentinel -Shard $Shard -GateIds $failedSelftestGateIds) -ForegroundColor Red
  Write-Host 'selftest: FAIL' -ForegroundColor Red
  exit 1
}
Write-Host "selftest($Shard): PASS" -ForegroundColor Green
Write-Host 'selftest: PASS' -ForegroundColor Green
exit 0
